    /// 关闭态：一次 `Relaxed` 读 + 分支；启用时一次原子加。
    #[inline]
    pub(crate) fn bump(c: &AtomicU64) {
        if ENABLED.load(Ordering::Relaxed) {
            c.fetch_add(1, Ordering::Relaxed);
        }
    }

    #[inline]
    pub(crate) fn bump_by(c: &AtomicU64, n: u64) {
        if n > 0 && ENABLED.load(Ordering::Relaxed) {
            c.fetch_add(n, Ordering::Relaxed);
        }
    }

    /// 探针是否启用（调用方用于跳过取时钟等可选工作）。
    #[inline]
    pub(crate) fn enabled() -> bool {
        ENABLED.load(Ordering::Relaxed)
    }

    /// 消费端计数：`from_carry` = 该条来自结转槽（不是本轮从通道新取的）；
    /// 同时按 `GateEvent` 变体把 `drained` 拆成三类（只计数）。
    #[inline]
    pub(crate) fn note_inbound_drained(from_carry: bool, ev: &super::GateEvent) {
        if ENABLED.load(Ordering::Relaxed) {
            INBOUND_DRAINED.fetch_add(1, Ordering::Relaxed);
            if from_carry {
                INBOUND_CARRY.fetch_add(1, Ordering::Relaxed);
            }
            match ev {
                super::GateEvent::Command { .. } => {
                    DRAINED_COMMAND.fetch_add(1, Ordering::Relaxed);
                }
                super::GateEvent::Closed { .. } | super::GateEvent::CertificationPending { .. } => {
                    DRAINED_CLOSE.fetch_add(1, Ordering::Relaxed);
                }
                _ => {
                    DRAINED_CONTROL.fetch_add(1, Ordering::Relaxed);
                }
            }
        }
    }

    /// 区屏障等待记账：`us` = **该区本 tick 两道屏障等待之和**（微秒）。
    ///
    /// 关闭态纯 no-op；启用时 `region_barrier_us = max(各区的值)`、
    /// `region_barrier_total_us = Σ(各区的值)`（后者只对账）。
    ///
    /// **A36**：另记该区的区侧和（`zone_metrics.barrier_us[z]`，诊断用——判据仍看 max）。
    #[inline]
    pub(crate) fn note_region_barrier_us_for_zone(zone: usize, us: u64) {
        if ENABLED.load(Ordering::Relaxed) {
            REGION_BARRIER_US.fetch_max(us, Ordering::Relaxed);
            REGION_BARRIER_TOTAL_US.fetch_add(us, Ordering::Relaxed);
            if let Some(c) = REGION_BARRIER_US_BY_ZONE.get(zone) {
                c.fetch_max(us, Ordering::Relaxed);
            }
        }
    }

