    /// **A43h**：记一条事件的墙钟；只有比当前第 3 名更贵才进榜（插入排序，榜长 3）。
    #[inline]
    pub(crate) fn note_zonek_slow_ident(ident: u16, wall_us: u64) {
        if wall_us == 0 || !ENABLED.load(Ordering::Relaxed) {
            return;
        }
        let mut w = ZONEK_TOP_SLOW
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        // 按 ident 去重：每类只留最贵一条。
        match w.by_ident.iter_mut().find(|(id, _)| *id == ident) {
            Some((_, slot)) => {
                if wall_us > *slot {
                    *slot = wall_us;
                }
            }
            None => w.by_ident.push((ident, wall_us)),
        }
        // 最慢三条**事件**（同 ident 可重复）。
        if wall_us <= w.top[2].1 {
            return;
        }
        let mut i = 2;
        while i > 0 && w.top[i - 1].1 < wall_us {
            w.top[i] = w.top[i - 1];
            i -= 1;
        }
        w.top[i] = (ident, wall_us);
    }

    /// **A43h**：取走本 tick 的 top-3 并清零（写行时调用）。
    fn take_zonek_top_slow() -> [(u16, u64); 3] {
        let mut w = ZONEK_TOP_SLOW
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let out = w.top;
        w.top = [(u16::MAX, 0); 3];
        out
    }

    /// **A43h**：取走"按 ident 去重的最贵一条"表并序列化成 `ident:us,…`（us 降序前 5）。
    /// 空 ⇒ `"-"`（保持单列、无 tab/换行）。
    fn take_zonek_ident_slow() -> String {
        let mut w = ZONEK_TOP_SLOW
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let mut rows: Vec<(u16, u64)> = std::mem::take(&mut w.by_ident);
        rows.sort_unstable_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
        rows.truncate(5);
        if rows.is_empty() {
            return "-".to_string();
        }
        rows.iter()
            .map(|(id, us)| format!("{id}:{us}"))
            .collect::<Vec<_>>()
            .join(",")
    }

    /// **A43j**：由进程启动段调用一次（`MIR2_SLOW_EVENT_LOG_US`，缺省/非法 ⇒ 关）。
    pub(crate) fn set_slow_event_us_from_env() {
        let us = std::env::var("MIR2_SLOW_EVENT_LOG_US")
            .ok()
            .and_then(|v| v.trim().parse::<u64>().ok())
            .unwrap_or(0);
        SLOW_EVENT_US.store(us, Ordering::Relaxed);
    }

