    /// **M1b 第 3 步（r6）**：**5 个**派生列的**纯函数**（写行与单测共用同一份数学）。
    ///
    /// `ib = [inbound_drained(全事件), inbound_carry, inbound_budget_hit]`（区 0；派生列**不用**全事件 drained）、
    /// `dc` = 区 0 的**命令分量** `DRAINED_COMMAND`、`zk` = 6 个 `zonek_*`。返回 5 个 `*_all_zones`。
    ///
    /// **分母说明（写死）**：`inbound_drained_all_zones` = **区 0 命令分量 + Σ zonek**（区 k 只缓冲
    /// Command）⇒ **与 `inbound_drained`（全事件）不同分母，禁止并列比较**。
    /// **`inbound_carry_all_zones` 已删（r6）**：区 0 的 `inbound_carry` 按**事件**计、无命令分量列，
    /// 与区 k 的"只数命令"相加是**混合分母** ⇒ 不提供该派生列（单区 `inbound_carry` 原样保留）。
    pub(crate) fn zonek_derived_columns(ib: [u64; 3], dc: u64, zk: [u64; 6]) -> [u64; 5] {
        [dc + zk[0], ib[2] + zk[2], zk[3], zk[4], zk[5]]
    }

    pub(crate) fn init_with_path(path: &std::path::Path) -> std::io::Result<()> {
        let mut f = std::fs::File::create(path)?;
        writeln!(
            f,
            "tick\tactor_indexed\tchr_indexed\tactor_linear\tchr_linear\trefmsg_calls\trefmsg_targets\tsay_calls\tsay_recipients\tkick_scans\tinbound_enqueued\tinbound_drained\tinbound_carry\tinbound_budget_hit\tinbound_wall_us\tdrained_command\tdrained_close\tdrained_control\tmax_single_event_us\tmax_single_event_cpu_us\tmax_single_event_ident\tzone_router_overwrites\tzone_router_rejected_socket\tregion_barrier_us\tregion_barrier_total_us\tcross_recipient_refmsg\tcross_recipient_run_frames\tcross_recipient_npc_merchant\tcross_recipient_feature_changed\tcross_recipient_mountride\tcross_recipient_merchant_disappear\tcross_recipient_missing\tcross_recipient_depart_frames\tcross_recipient_seven_total\tcross_recipient_delivered\tcross_recipient_unroutable\tcross_frame_queue_overflow\tcross_frame_dup\tcross_frame_drop_closed\tcross_recipient_zone_unknown\tcross_enqueue_us\tcross_enqueue_events\tdepart_wrn_suppressed\tdepart_frames_mirror_suppressed\tzonek_inbound_drained\tzonek_inbound_carry\tzonek_inbound_budget_hit\tzonek_inbound_overflow_dropped\tzonek_inbound_pending_discarded\tzonek_inbound_unsupported\tzonek_control_defer_overflow\tzonek_control_wait_timeout\tzonek_control_mailbox_rejected\tzonek_control_shutdown_discarded\tzonek_control_zone_gone\tzonek_channel_enqueued\tzonek_channel_rejected\tzonek_channel_drained\tzonek_channel_recipients\tinbound_drained_all_zones\tinbound_budget_hit_all_zones\tinbound_overflow_dropped_all_zones\tinbound_pending_discarded_all_zones\tinbound_unsupported_all_zones\thandoff_offered\thandoff_accepted\thandoff_refused\thandoff_promoted\thandoff_inserted_fresh\tmirror_shadowed_by_local\tmirror_shadowed_static\tmirror_shadowed_handoff\thandoff_dup_dropped\tmirror_write_refused_cell\tmirror_write_refused_occupied\tzone_cmd_unsupported\thandoff_move_after_transfer_dropped\tmove_map_change_unsupported\tmirror_own_segment_ids\thandoff_fresh_own_segment\tscript_action_errors\tzone_selloff_sold_offline_seller\tzone_startup_lock_timeout\tzone_shutdown_lock_timeout\tzonek_exec_wall_hit\tzonek_exec_us_max\tzonek_exec_cpu_us\tzonek_top1_ident\tzonek_top1_us\tzonek_top2_ident\tzonek_top2_us\tzonek_top3_ident\tzonek_top3_us\tzonek_top_ident_slowest_us\tzone_metrics"
        )?;
        *WRITER.lock().unwrap_or_else(|p| p.into_inner()) = Some(f);
        *PATH.lock().unwrap_or_else(|p| p.into_inner()) = Some(path.to_path_buf());
        DATA_LINES.store(0, Ordering::Relaxed);
        ENABLED.store(true, Ordering::Relaxed);
        #[cfg(test)]
        {
            *TEST_WRITER_OWNER.lock().unwrap_or_else(|p| p.into_inner()) =
                Some(std::thread::current().id());
        }
        Ok(())
    }

    pub(crate) fn init_from_env() -> Result<bool, String> {
        match std::env::var("MIR2_PERF_COUNTERS") {
            Ok(p) if !p.trim().is_empty() => {
                init_with_path(std::path::Path::new(p.trim())).map_err(|e| {
                    format!("MIR2_PERF_COUNTERS={p} 打不开（探针 fail-closed）：{e}")
                })?;
                Ok(true)
            }
            _ => Ok(false),
        }
    }

    /// 每 tick 尾调用；关闭态在第一次原子读就返回（无分配/无锁）。
    pub(crate) fn write_tick() {
        if !ENABLED.load(Ordering::Relaxed) {
            return;
        }
        #[cfg(test)]
        {
            // 测试期：非 init 线程的写跳过（见 `TEST_WRITER_OWNER`）。
            let owner = *TEST_WRITER_OWNER.lock().unwrap_or_else(|p| p.into_inner());
            if owner != Some(std::thread::current().id()) {
                return;
            }
        }
        let tick = DATA_LINES.fetch_add(1, Ordering::Relaxed);
        let hd = handoff_deltas();
        // **M1b 第 3 步**：区 0 三列先取（派生列要 `区 0 + zonek`）；zonek 6 列同取。
        let host_enq = INBOUND_ENQUEUED.swap(0, Ordering::Relaxed);
        let ib = [
            INBOUND_DRAINED.swap(0, Ordering::Relaxed),
            INBOUND_CARRY.swap(0, Ordering::Relaxed),
            INBOUND_BUDGET_HIT.swap(0, Ordering::Relaxed),
        ];
        // 区 0 的 `inbound_drained` 计**全部 GateEvent**；`zonek_inbound_drained` 只计 **Command**
        // ⇒ 派生列用**区 0 的命令分量** `DRAINED_COMMAND`（不同分母，禁止与 `inbound_drained` 并列比较）。
        let dc = DRAINED_COMMAND.swap(0, Ordering::Relaxed);
        let zk = [
            ZONEK_INBOUND_DRAINED.swap(0, Ordering::Relaxed),
            ZONEK_INBOUND_CARRY.swap(0, Ordering::Relaxed),
            ZONEK_INBOUND_BUDGET_HIT.swap(0, Ordering::Relaxed),
            ZONEK_INBOUND_OVERFLOW_DROPPED.swap(0, Ordering::Relaxed),
            ZONEK_INBOUND_PENDING_DISCARDED.swap(0, Ordering::Relaxed),
            ZONEK_INBOUND_UNSUPPORTED.swap(0, Ordering::Relaxed),
        ];
        let dv = zonek_derived_columns(ib, dc, zk);
        let top_slow = take_zonek_top_slow();
        let cr = [
            CROSS_RECIPIENT_BY_SURFACE[0].swap(0, Ordering::Relaxed),
            CROSS_RECIPIENT_BY_SURFACE[1].swap(0, Ordering::Relaxed),
            CROSS_RECIPIENT_BY_SURFACE[2].swap(0, Ordering::Relaxed),
            CROSS_RECIPIENT_BY_SURFACE[3].swap(0, Ordering::Relaxed),
            CROSS_RECIPIENT_BY_SURFACE[4].swap(0, Ordering::Relaxed),
            CROSS_RECIPIENT_BY_SURFACE[5].swap(0, Ordering::Relaxed),
            CROSS_RECIPIENT_BY_SURFACE[6].swap(0, Ordering::Relaxed),
        ];
        let vals = [
            ACTOR_INDEXED.swap(0, Ordering::Relaxed),
            CHR_INDEXED.swap(0, Ordering::Relaxed),
            ACTOR_LINEAR.swap(0, Ordering::Relaxed),
            CHR_LINEAR.swap(0, Ordering::Relaxed),
            REFMSG_CALLS.swap(0, Ordering::Relaxed),
            REFMSG_TARGETS.swap(0, Ordering::Relaxed),
            SAY_CALLS.swap(0, Ordering::Relaxed),
            SAY_RECIPIENTS.swap(0, Ordering::Relaxed),
            KICK_SCANS.swap(0, Ordering::Relaxed),
            host_enq,
            ib[0],
            ib[1],
            ib[2],
            INBOUND_WALL_US.swap(0, Ordering::Relaxed),
            dc,
            DRAINED_CLOSE.swap(0, Ordering::Relaxed),
            DRAINED_CONTROL.swap(0, Ordering::Relaxed),
            SINGLE_EVENT_MAX_US.swap(0, Ordering::Relaxed),
            SINGLE_EVENT_MAX_CPU_US.swap(0, Ordering::Relaxed),
            u64::from(SINGLE_EVENT_MAX_IDENT.swap(0, Ordering::Relaxed)),
            ZONE_ROUTER_OVERWRITES.swap(0, Ordering::Relaxed),
            ZONE_ROUTER_REJECTED_SOCKET.swap(0, Ordering::Relaxed),
            REGION_BARRIER_US.swap(0, Ordering::Relaxed),
            REGION_BARRIER_TOTAL_US.swap(0, Ordering::Relaxed),
            // 六面逐面（历史列，顺序不变）。
            cr[0],
            cr[1],
            cr[2],
            cr[3],
            cr[4],
            cr[5],
            // 六面小计（**历史 10.004% 口径**；只求前 6 项，不能再 swap 一次）。
            cr[..6].iter().sum::<u64>(),
            // **L2-5 ⑦**：第七面 + 七面合计（七面合计 ≠ 历史 10.004% 口径）。
            cr[6],
            cr.iter().sum::<u64>(),
            // **L2-5 ⑤**：三桶 + canary/诊断（本 tick 增量；与七面合计同源构造）。
            CROSS_RECIPIENT_OUTCOME[0].swap(0, Ordering::Relaxed),
            CROSS_RECIPIENT_OUTCOME[1].swap(0, Ordering::Relaxed),
            CROSS_RECIPIENT_OUTCOME[2].swap(0, Ordering::Relaxed),
            CROSS_FRAME_DUP.swap(0, Ordering::Relaxed),
            CROSS_FRAME_DROP_CLOSED.swap(0, Ordering::Relaxed),
            CROSS_RECIPIENT_ZONE_UNKNOWN.swap(0, Ordering::Relaxed),
            CROSS_ENQUEUE_US.swap(0, Ordering::Relaxed),
            CROSS_ENQUEUE_EVENTS.swap(0, Ordering::Relaxed),
            // **L2-5 ⑦**：WRN 抑制数（本 tick 增量；与限流器同语义）。
            DEPART_WRN_SUPPRESSED.swap(0, Ordering::Relaxed),
            // **L2-5 follow-up**：镜像观察者被条件抑制的帧数（本 tick 增量；不进 ⑤ 账）。
            DEPART_FRAMES_MIRROR_SUPPRESSED.swap(0, Ordering::Relaxed),
            // **M1b 第 3 步**：区 k 6 列（仅 slicing；N=1 恒 0）。
            zk[0],
            zk[1],
            zk[2],
            zk[3],
            zk[4],
            zk[5],
            // **M1b 第 4 步（A6）+ M1c-2c 段 4**：5 列（三个降级 + 关服残留 + 区状态不在；
            // 仅区 k；N=1 恒 0；无派生列——按 A6 口径"区 0 无同名语义"）。
            ZONEK_CONTROL_DEFER_OVERFLOW.swap(0, Ordering::Relaxed),
            ZONEK_CONTROL_WAIT_TIMEOUT.swap(0, Ordering::Relaxed),
            ZONEK_CONTROL_MAILBOX_REJECTED.swap(0, Ordering::Relaxed),
            ZONEK_CONTROL_SHUTDOWN_DISCARDED.swap(0, Ordering::Relaxed),
            ZONEK_CONTROL_ZONE_GONE.swap(0, Ordering::Relaxed),
            // **A20 片 2**：频道四列（本 tick 增量；仅区 k 语义，N=1 恒 0）。
            ZONEK_CHANNEL_ENQUEUED.swap(0, Ordering::Relaxed),
            ZONEK_CHANNEL_REJECTED.swap(0, Ordering::Relaxed),
            ZONEK_CHANNEL_DRAINED.swap(0, Ordering::Relaxed),
            ZONEK_CHANNEL_RECIPIENTS.swap(0, Ordering::Relaxed),
            // **5 个**派生列（derived；数学见 [`zonek_derived_columns`]；不可与单区列混比）。
            // `inbound_carry_all_zones` 按 r6 已删（混合分母：区 0 按事件、区 k 按命令）。
            dv[0],
            dv[1],
            dv[2],
            dv[3],
            dv[4],
            // handoff 11（hd[0..=10]；表头顺序 offered..write_refused_occupied）。
            hd[0],
            hd[1],
            hd[2],
            hd[3],
            hd[4],
            hd[5],
            hd[6],
            hd[7],
            hd[8],
            hd[9],
            hd[10],
            // **L2-5 ④a**：区 k 命令接线 / ④b 缺口基线 / 区 k 换图帧降级（均为本 tick 增量）。
            ZONE_CMD_UNSUPPORTED.swap(0, Ordering::Relaxed),
            HANDOFF_MOVE_AFTER_TRANSFER_DROPPED.swap(0, Ordering::Relaxed),
            MOVE_MAP_CHANGE_UNSUPPORTED.swap(0, Ordering::Relaxed),
            // **L2-5 own-segment 修正**：信息性两列（表头在 zone-k 之后）。
            hd[11],
            hd[12],
            // **卡 A29**：脚本动作未实现错误次数（本 tick 增量）。
            SCRIPT_ACTION_ERRORS.swap(0, Ordering::Relaxed),
            // **A34 片 5**：卖方缺席（离线/别区）时成交数（oracle Flag=1 延期结算形态；
            // 本 tick 增量；**在 `zone_metrics` 之前**，A36 的末列契约不动）。
            ZONE_SELLOFF_SOLD_OFFLINE_SELLER.swap(0, Ordering::Relaxed),
            // **D6 P0**：跨区有界锁超时（本 tick 增量；**仍在 `zone_metrics` 之前**）。
            // 启动列在正常启动下恒 0（超时即 fail-closed 退出，写不到 TSV；计数器供测试）。
            ZONE_STARTUP_LOCK_TIMEOUT.swap(0, Ordering::Relaxed),
            ZONE_SHUTDOWN_LOCK_TIMEOUT.swap(0, Ordering::Relaxed),
            // **A43c**：执行段墙截断（仅墙）+ 执行段墙钟 max（**仍在 `zone_metrics` 之前**）。
            ZONEK_EXEC_WALL_HIT.swap(0, Ordering::Relaxed),
            ZONEK_EXEC_US_MAX.swap(0, Ordering::Relaxed),
            ZONEK_EXEC_CPU_US_MAX.swap(0, Ordering::Relaxed),
            // **A43h**：单条事件墙钟最贵 top-3（ident, us）；本列组是**跨区竞争**结果。
            u64::from(top_slow[0].0),
            top_slow[0].1,
            u64::from(top_slow[1].0),
            top_slow[1].1,
            u64::from(top_slow[2].0),
            top_slow[2].1,
        ];
        // **A36**：末列 `zone_metrics`（单列紧凑 JSON；无 tab/换行 ⇒ 不破坏 TSV 字段数）。
        let ident_slow = take_zonek_ident_slow();
        let zm = zone_metrics_json(host_enq, ib[0], ib[1], ib[2]);
        let mut guard = WRITER.lock().unwrap_or_else(|p| p.into_inner());
        if let Some(f) = guard.as_mut() {
            let line = format!(
                "{tick}\t{}\t{ident_slow}\t{zm}\n",
                vals.iter()
                    .map(u64::to_string)
                    .collect::<Vec<_>>()
                    .join("\t")
            );
            let _ = f.write_all(line.as_bytes());
        }
    }

    /// **A36**：`zone_metrics` 列的紧凑 JSON。
    ///
    /// - 无 tab/换行（TSV 单列；`zone_perf_parse.py` 的参差行判定依赖这一点）；
    /// - 键序固定（与 A36 契约示例一致：`v` → `barrier_us` → `inbound` → `landed` → `failures`；
    ///   内层按字典序）；
    /// - 每 tick 增量字段（barrier/inbound）在这里 `swap(0)`；累计字段（landed/failures）只读；
    /// - 区 0 的 inbound 用宿主列（`inbound_*` 口径，入参传入以免二次 swap）；区 k 用 per-zone
    ///   分桶（与 `zonek_inbound_*` 同宇宙：只计 Command）；
    /// - `failures.sampled` 按**代码事实**：只有 `router_unassigned` 的日志站点限流
    ///   （`n<=8 || n%1000`），其余三条逐次 glog ⇒ false。
    fn zone_metrics_json(
        host_enq: u64,
        host_drained: u64,
        host_carry: u64,
        host_budget_hit: u64,
    ) -> String {
        let zone_count = ZONE_COUNT.load(Ordering::Relaxed).min(ZONE_METRICS_CAP);
        let mut out = String::with_capacity(96 + zone_count * 96);
        out.push_str("{\"v\":1,\"barrier_us\":{");
        for (z, cell) in REGION_BARRIER_US_BY_ZONE
            .iter()
            .take(zone_count)
            .enumerate()
        {
            if z > 0 {
                out.push(',');
            }
            out.push('"');
            out.push_str(&z.to_string());
            out.push_str("\":");
            out.push_str(&cell.swap(0, Ordering::Relaxed).to_string());
        }
        out.push_str("},\"inbound\":{");
        for z in 0..zone_count {
            if z > 0 {
                out.push(',');
            }
            let (enq, drained, carry, budget_hit, overflow_drop, pending_discard) = if z == 0 {
                (host_enq, host_drained, host_carry, host_budget_hit, 0, 0)
            } else {
                (
                    ZONEK_ENQ_BY_ZONE[z].swap(0, Ordering::Relaxed),
                    ZONEK_DRAINED_BY_ZONE[z].swap(0, Ordering::Relaxed),
                    ZONEK_CARRY_BY_ZONE[z].swap(0, Ordering::Relaxed),
                    ZONEK_BUDGET_HIT_BY_ZONE[z].swap(0, Ordering::Relaxed),
                    ZONEK_OVERFLOW_DROP_BY_ZONE[z].swap(0, Ordering::Relaxed),
                    ZONEK_PENDING_DISCARD_BY_ZONE[z].swap(0, Ordering::Relaxed),
                )
            };
            out.push('"');
            out.push_str(&z.to_string());
            out.push_str("\":{\"budget_hit\":");
            out.push_str(&budget_hit.to_string());
            out.push_str(",\"carry\":");
            out.push_str(&carry.to_string());
            out.push_str(",\"drain\":");
            out.push_str(&drained.to_string());
            out.push_str(",\"enq\":");
            out.push_str(&enq.to_string());
            out.push_str(",\"overflow_drop\":");
            out.push_str(&overflow_drop.to_string());
            out.push_str(",\"pending_discard\":");
            out.push_str(&pending_discard.to_string());
            out.push('}');
        }
        out.push_str("},\"landed\":{");
        for (z, cell) in ZONE_LOGIN_LANDED.iter().take(zone_count).enumerate() {
            if z > 0 {
                out.push(',');
            }
            out.push('"');
            out.push_str(&z.to_string());
            out.push_str("\":");
            out.push_str(&cell.load(Ordering::Relaxed).to_string());
        }
        out.push_str("},\"failures\":{\"offzone\":");
        out.push_str(&ZONE_LOGIN_OFFZONE.load(Ordering::Relaxed).to_string());
        out.push_str(",\"router_unassigned\":");
        out.push_str(&ZONE_ROUTER_UNASSIGNED.load(Ordering::Relaxed).to_string());
        out.push_str(",\"sampled\":{\"offzone\":false,\"router_unassigned\":true,\"target_unavailable\":false,\"uncovered\":false}");
        out.push_str(",\"target_unavailable\":");
        out.push_str(&ZONE_TARGET_UNAVAILABLE.load(Ordering::Relaxed).to_string());
        out.push_str(",\"uncovered\":");
        out.push_str(&ZONE_LOGIN_UNCOVERED.load(Ordering::Relaxed).to_string());
        // **A35-b 导出（A36 接线）**：搬迁计数是**累计**值、与 failures 平级（不是失败语义）。
        out.push_str("},\"handoff\":{\"canceled_trades\":");
        out.push_str(
            &ZONE_HANDOFF_CANCELED_TRADES
                .load(Ordering::Relaxed)
                .to_string(),
        );
        out.push_str(",\"session_failed\":");
        out.push_str(
            &ZONE_HANDOFF_SESSION_FAILED
                .load(Ordering::Relaxed)
                .to_string(),
        );
        out.push_str(",\"session_moved\":");
        out.push_str(
            &ZONE_HANDOFF_SESSION_MOVED
                .load(Ordering::Relaxed)
                .to_string(),
        );
        out.push_str(",\"target_display_missing\":");
        out.push_str(
            &ZONE_HANDOFF_TARGET_DISPLAY_MISSING
                .load(Ordering::Relaxed)
                .to_string(),
        );
        out.push_str(",\"target_entity_released\":");
        out.push_str(
            &ZONE_HANDOFF_TARGET_ENTITY_RELEASED
                .load(Ordering::Relaxed)
                .to_string(),
        );
        out.push_str("}}");
        out
    }

    /// 收尾：启用却一条 tick 行都没有 ⇒ Err（调用方转 rc≠0）。
    pub(crate) fn finish() -> Result<(), String> {
        if !ENABLED.load(Ordering::Relaxed) {
            return Ok(());
        }
        if DATA_LINES.load(Ordering::Relaxed) == 0 {
            let p = PATH
                .lock()
                .unwrap_or_else(|e| e.into_inner())
                .clone()
                .unwrap_or_default();
            return Err(format!(
                "MIR2_PERF_COUNTERS={} 启用但 0 个 tick 行（探针 fail-closed）",
                p.display()
            ));
        }
        Ok(())
    }

    /// **D6 P0-②**：启动期静态装载「区状态锁有界获取超时」次数（该路径随后 fail-closed 退出；
    /// 计数器供测试/证据，TSV 列在正常启动下恒 0）。
    pub(crate) static ZONE_STARTUP_LOCK_TIMEOUT: AtomicU64 = AtomicU64::new(0);
    /// **D6 P0-①**：关服存档收集「区状态锁有界获取超时 ⇒ 跳过该区」次数（每 tick 增量进 TSV）。
    pub(crate) static ZONE_SHUTDOWN_LOCK_TIMEOUT: AtomicU64 = AtomicU64::new(0);

    #[cfg(test)]
    pub(crate) fn zone_startup_lock_timeout() -> u64 {
        ZONE_STARTUP_LOCK_TIMEOUT.load(Ordering::Relaxed)
    }

    #[cfg(test)]
    pub(crate) fn zone_shutdown_lock_timeout() -> u64 {
        ZONE_SHUTDOWN_LOCK_TIMEOUT.load(Ordering::Relaxed)
    }

    pub(crate) fn note_zone_startup_lock_timeout() -> u64 {
        ZONE_STARTUP_LOCK_TIMEOUT.fetch_add(1, Ordering::Relaxed) + 1
    }

    pub(crate) fn note_zone_shutdown_lock_timeout() -> u64 {
        ZONE_SHUTDOWN_LOCK_TIMEOUT.fetch_add(1, Ordering::Relaxed) + 1
    }

    /// **L2-5 ③ 1b**：登录落区计数。
    pub(crate) static ZONE_LOGIN_UNCOVERED: AtomicU64 = AtomicU64::new(0);
    /// 目标区不可用（线程已死/锁毒化）⇒ 拒登（不回落区 0）。
    pub(crate) static ZONE_TARGET_UNAVAILABLE: AtomicU64 = AtomicU64::new(0);
    /// `(line,socket)` 未 assign、回落区 0 的次数（发现即计）。
    pub(crate) static ZONE_ROUTER_UNASSIGNED: AtomicU64 = AtomicU64::new(0);
    /// 每区成功落区次数（下标 = 区号；上限 = [`crate::MAX_ZONE_COUNT`]）。
    ///
    /// 语义 = 「回执（`finish_login`）完成 **且** `ZoneRouter::assign` 成功」；区 0 计的是
    /// 「切片模式下按原路径处理完」的次数。世界进入是否成功不在此计（那是
    /// `telemetry::record_ok`/`record_attempt` 的口径）。
    static ZONE_LOGIN_LANDED: [AtomicU64; 512] = [const { AtomicU64::new(0) }; 512];
    /// **A34 片 5**：卖方缺席（离线/别区）时**成交**发生数（oracle `Sale.cs:303-317` 的 `Flag=1`
    /// 形态：买方照扣、物品照发、卖方未得元宝；oracle 单世界只可能是"离线"，本仓另含"别区"）。
    /// 每 tick 增量进 TSV；登录补偿见 `pay_selloff_on_login`。
    static ZONE_SELLOFF_SOLD_OFFLINE_SELLER: AtomicU64 = AtomicU64::new(0);
    /// 记一次「卖方缺席成交」；返回累计值（供 WRN 限速）。
    #[cfg(test)]
    pub(crate) fn zone_selloff_sold_offline_seller() -> u64 {
        ZONE_SELLOFF_SOLD_OFFLINE_SELLER.load(Ordering::Relaxed)
    }

    pub(crate) fn note_zone_selloff_sold_offline_seller() -> u64 {
        let n = ZONE_SELLOFF_SOLD_OFFLINE_SELLER.fetch_add(1, Ordering::Relaxed) + 1;
        if n <= 8 || n.is_multiple_of(1000) {
            glog!(
                "WRN",
                "元宝寄售：卖方缺席（离线/别区）成交 ⇒ 延期结算 flag=1 次数={n}（登录时补发，A34 片 5 登记）"
            );
        }
        n
    }
    // ---- **A36**：每区仪表（perf TSV 末列 `zone_metrics`）----
    /// 运行时区数（切片初始化时由 [`set_zone_count`] 写入；0 = 非切片 ⇒ per-zone 表为空）。
    static ZONE_COUNT: AtomicUsize = AtomicUsize::new(0);
    /// per-zone 表的固定上限（与 [`ZONE_LOGIN_LANDED`] 同口径；越界不记）。
    const ZONE_METRICS_CAP: usize = 512;
    /// 本 tick 各区「两道屏障等待之和」的**区侧和**（µs，`fetch_max`；写行即清零）。
    ///
    /// **诊断用，不是判据**：判据仍看进程列 `region_barrier_us` 的 **max**（各区 ≤ max ⇒
    /// max ≤20% 即各区 ≤20%）；本表只用于定位是哪一区慢。
    static REGION_BARRIER_US_BY_ZONE: [AtomicU64; ZONE_METRICS_CAP] =
        [const { AtomicU64::new(0) }; ZONE_METRICS_CAP];
    /// 区 k 入站：本 tick 投递成功（demux 目标区 `send` 成功；只计 `Command`，与 drained 同宇宙）。
    static ZONEK_ENQ_BY_ZONE: [AtomicU64; ZONE_METRICS_CAP] =
        [const { AtomicU64::new(0) }; ZONE_METRICS_CAP];
    /// 区 k 入站：本 tick 被消费并处置的 Command 条数（同 `zonek_inbound_drained` 口径）。
    static ZONEK_DRAINED_BY_ZONE: [AtomicU64; ZONE_METRICS_CAP] =
        [const { AtomicU64::new(0) }; ZONE_METRICS_CAP];
    /// 区 k 入站：其中来自结转槽的条数。
    static ZONEK_CARRY_BY_ZONE: [AtomicU64; ZONE_METRICS_CAP] =
        [const { AtomicU64::new(0) }; ZONE_METRICS_CAP];
    /// 区 k 入站：本 tick 预算命中（每 tick ≤1）。
    static ZONEK_BUDGET_HIT_BY_ZONE: [AtomicU64; ZONE_METRICS_CAP] =
        [const { AtomicU64::new(0) }; ZONE_METRICS_CAP];
    /// 区 k 入站：demux 丢新（`outstanding` 软上限）。
    static ZONEK_OVERFLOW_DROP_BY_ZONE: [AtomicU64; ZONE_METRICS_CAP] =
        [const { AtomicU64::new(0) }; ZONE_METRICS_CAP];
    /// 区 k 入站：线程尾丢弃的未执行命令（M1b 第 3 步「作废窗口」口径）。
    static ZONEK_PENDING_DISCARD_BY_ZONE: [AtomicU64; ZONE_METRICS_CAP] =
        [const { AtomicU64::new(0) }; ZONE_METRICS_CAP];
    /// **卡 A29**：脚本动作 `EngineError::NotImplemented`（`kind` 以 `action` 开头）被触发的次数。
    /// 进 perf TSV（表头末列 `script_action_errors`），每 tick 增量。
    static SCRIPT_ACTION_ERRORS: AtomicU64 = AtomicU64::new(0);
    /// 其中**实际打出**限速 WRN 的次数（同一 label+动作每分钟 ≤1 条；测试断言用，不进 TSV）。
    static SCRIPT_ACTION_ERROR_WRNS: AtomicU64 = AtomicU64::new(0);
    /// 落区后落点**不属于**判定区（墙格移位/死亡改写越过边界；只在切片模式计）。
    pub(crate) static ZONE_LOGIN_OFFZONE: AtomicU64 = AtomicU64::new(0);
    /// **L2-5 ③ 段 1c**：`Closed` 投到区 k 但**没有匹配在线项**（陈旧 `Closed` /
    /// 网关重登窗口 / 路由错投）而整臂早退的次数。段 1b 时本计数 = 被丢弃的
    /// 全部 `Closed`（当时的已知缺口）；1c 起 `Closed` 一律进 [`handle_zone_closed`]，
    /// **正常断线不再计入**，非 0 即说明 `(chr, gate, socket)` 与在线表不一致。
    pub(crate) static ZONE_DISCONNECT_DROPPED: AtomicU64 = AtomicU64::new(0);
    /// **L2-5 ④a**：区 k（切片区）命令派发里**未接线**的非移动命令次数。首 8 次与每 1000 次
    /// 各打一行 WRN（带 `ident`，即按命令类别采样）；非 0 = ④b 的余量清单，不是缺陷计数。
    /// 切片关 / N=1 恒 0（stub 路径与 N=1 不经过区 k 派发）。
    pub(crate) static ZONE_CMD_UNSUPPORTED: AtomicU64 = AtomicU64::new(0);
    /// **L2-5 ④a**：区 k 走位命令因「在线表有条目、世界里已无实体」被丢的次数。
    /// 当前唯一来源 = handoff 提升后源区不随迁（④b「会话/路由随迁」的缺口基线）；
    /// 正常稳态恒 0，迁完以后必须归零——用它证明缺口已补。
    pub(crate) static HANDOFF_MOVE_AFTER_TRANSFER_DROPPED: AtomicU64 = AtomicU64::new(0);
    /// **L2-5 ④a**：换图事件在**没有 `MapRegistry`** 时处理的次数（区 k 一律传 `None`：
    /// 帧仍发但降级——图名空 / flag 0 / 无 766·54）。区 0 有注册表 ⇒ 正常恒 0；
    /// ④b 补区 k 换图帧后应归零。
    pub(crate) static MOVE_MAP_CHANGE_UNSUPPORTED: AtomicU64 = AtomicU64::new(0);
    /// **A35-b**：跨区会话搬迁**成功**次数（源区摘 → 目标区插 → `router` 改指，三步都成）。
    pub(crate) static ZONE_HANDOFF_SESSION_MOVED: AtomicU64 = AtomicU64::new(0);
    /// **A35-b**：搬迁**失败并回滚**次数（目标区不可用/线程已退出/同 chr 冲突/router 失败）。
    pub(crate) static ZONE_HANDOFF_SESSION_FAILED: AtomicU64 = AtomicU64::new(0);
    /// **A35-b**：跨界前取消的交易/寄售次数（两族合计；跨区 = 离开范围 ⇒ 先取消）。
    pub(crate) static ZONE_HANDOFF_CANCELED_TRADES: AtomicU64 = AtomicU64::new(0);
    /// **A35-b**：目标区**缺该玩家展示项**的次数（fail-loud；不重建，出现帧可能缺项）。
    pub(crate) static ZONE_HANDOFF_TARGET_DISPLAY_MISSING: AtomicU64 = AtomicU64::new(0);
    /// **card/handoff-release-leak**：迁移失败回滚时，目标区**已提升为真实体**被释放的次数。
    /// 会话留源区而实体留目标区 ⇒ 无会话 PLAY 实体永久扫描，每条 hide 落 `missing_online`。
    pub(crate) static ZONE_HANDOFF_TARGET_ENTITY_RELEASED: AtomicU64 = AtomicU64::new(0);

    // ---- 卡 C27（openmir2-perfcounter-test-isolation）：`#[cfg(test)]` 线程级计数器实例 ----
    // 生产路径的 `note_zone_login_landed`/`note_zone_disconnect_dropped` 会从**其它并行用例**
    // 的线程写全局原子；直接读写计数器的用例因此会被插队（全量红、单跑绿）。这里给测试提供
    // 一个**本线程实例**：安装后本线程的读写/复位都走实例，全局原子不受影响、也看不到别人的写。
    #[cfg(test)]
    struct TestZoneCounters {
        login_uncovered: AtomicU64,
        target_unavailable: AtomicU64,
        router_unassigned: AtomicU64,
        login_offzone: AtomicU64,
        disconnect_dropped: AtomicU64,
        login_landed: [AtomicU64; 512],
        script_action_errors: AtomicU64,
        script_action_error_wrns: AtomicU64,
        handoff_session_moved: AtomicU64,
        handoff_session_failed: AtomicU64,
        handoff_canceled_trades: AtomicU64,
        handoff_target_display_missing: AtomicU64,
        handoff_target_entity_released: AtomicU64,
    }
    #[cfg(test)]
    impl TestZoneCounters {
        fn new() -> Self {
            Self {
                login_uncovered: AtomicU64::new(0),
                target_unavailable: AtomicU64::new(0),
                router_unassigned: AtomicU64::new(0),
                login_offzone: AtomicU64::new(0),
                disconnect_dropped: AtomicU64::new(0),
                login_landed: [const { AtomicU64::new(0) }; 512],
                script_action_errors: AtomicU64::new(0),
                script_action_error_wrns: AtomicU64::new(0),
                handoff_session_moved: AtomicU64::new(0),
                handoff_session_failed: AtomicU64::new(0),
                handoff_canceled_trades: AtomicU64::new(0),
                handoff_target_display_missing: AtomicU64::new(0),
                handoff_target_entity_released: AtomicU64::new(0),
            }
        }
    }
    #[cfg(test)]
    thread_local! {
        static TEST_ZONE_COUNTERS: std::cell::RefCell<Option<TestZoneCounters>> =
            const { std::cell::RefCell::new(None) };
    }
    /// 安装本线程计数器实例；`Drop` 时卸载（panic 也走 Drop，线程结束即失效）。
    #[cfg(test)]
    pub(crate) struct TestZoneCountersGuard;
    #[cfg(test)]
    impl Drop for TestZoneCountersGuard {
        fn drop(&mut self) {
            TEST_ZONE_COUNTERS.with(|c| *c.borrow_mut() = None);
        }
    }
    #[cfg(test)]
    pub(crate) fn test_zone_counters_scope() -> TestZoneCountersGuard {
        TEST_ZONE_COUNTERS.with(|c| *c.borrow_mut() = Some(TestZoneCounters::new()));
        TestZoneCountersGuard
    }
    #[cfg(test)]
    fn with_test_zone_counters<R>(f: impl FnOnce(&TestZoneCounters) -> R) -> Option<R> {
        TEST_ZONE_COUNTERS.with(|c| c.borrow().as_ref().map(f))
    }

    pub(crate) fn note_zone_login_uncovered() {
        #[cfg(test)]
        if with_test_zone_counters(|t| t.login_uncovered.fetch_add(1, Ordering::Relaxed)).is_some()
        {
            return;
        }
        ZONE_LOGIN_UNCOVERED.fetch_add(1, Ordering::Relaxed);
    }
    #[cfg(test)]
    pub(crate) fn zone_login_uncovered() -> u64 {
        #[cfg(test)]
        if let Some(v) = with_test_zone_counters(|t| t.login_uncovered.load(Ordering::Relaxed)) {
            return v;
        }
        ZONE_LOGIN_UNCOVERED.load(Ordering::Relaxed)
    }
