    /// **复验 Important 2**：会话的 `PlayObject.MNMval`（`SessionGround.mnm_val`）必须映射进
    /// 脚本侧 `NpcPlayer.mnmval`，脚本跑完再写回——oracle 里说词 `$STR(M*)`（`NormNpc.cs:1548`）
    /// 与 `<QUERYVAL>`（`PlayObject.Base.cs:3436`）读写的是**同一个** `PlayObject.MNMval`
    /// （`PlayObject.cs:543`）。
    ///
    /// 红检：删掉 `npc_player_from_session` 的 `mnm_val` seeding ⇒ 读断言红；
    /// 删掉 `write_back_player_mnmval` 调用/函数体 ⇒ 写回断言红。
    #[test]
    fn npc_player_maps_session_mnmval_both_ways() {
        use mir2_script::engine::ScriptPlayer as _;
        let mut sg = test_session_ground(7);
        sg.mnm_val[9] = 77;
        let vars = npc_vars_from(None, "SKY引擎", 10_000, 10_000_000);
        let catalog = game_svr::ability::StdItemCatalog::new();
        let mut rng = |_v: i32| 0;
        {
            let mut p = npc_player_from_session(&mut rng, "hero", &sg, "0", &catalog, &vars);
            assert_eq!(
                p.line_variable_text("<$STR(M9)>"),
                "77",
                "会话 MNMval[9] 必须映射进 NpcPlayer（$STR 300..399）"
            );
            // 脚本 `INC M9 1` 的落点。
            p.set_mnmval(9, 78);
            assert_eq!(p.line_variable_text("<$STR(M9)>"), "78");
            write_back_player_mnmval(&p, &mut sg);
        }
        assert_eq!(sg.mnm_val[9], 78, "脚本写回的 MNMval 必须回到会话");
    }

    /// **I-1（review `dd9f3223`）**：`user_account` 的唯一来源 = **会话**（登录时从角色记录
    /// `humData.Account` 装入）。商人 / 组队 / 固定 NPC / QFunction `@StdModeFunc*` 四条漏斗都经
    /// [`npc_player_from_session`] 取到同一个值（oracle 是同一个 `PlayObject.UserAccount`）。
    ///
    /// 牙：删掉 `p.user_account = sg.account.clone()` ⇒ 本用例红（`""` vs `"ua"`）。
    #[test]
    fn npc_player_from_session_injects_session_account_for_all_funnels() {
        use mir2_script::engine::ScriptPlayer as _;
        let mut sg = test_session_ground(7);
        sg.account = "ua".to_string();
        let vars = npc_vars_from(None, "SKY引擎", 10_000, 10_000_000);
        let catalog = game_svr::ability::StdItemCatalog::new();
        let mut rng = |_v: i32| 0;
        let p = npc_player_from_session(&mut rng, "hero", &sg, "0", &catalog, &vars);
        assert_eq!(p.user_account(), "ua", "会话账号必须进 NpcPlayer");
        // 未注入账号的会话 ⇒ 空串（fail-closed，不猜）。
        let sg2 = test_session_ground(7);
        let p2 = npc_player_from_session(&mut rng, "hero", &sg2, "0", &catalog, &vars);
        assert_eq!(p2.user_account(), "", "缺省空串");
    }

    /// **T-142 宿主会话接线**：`SaleDeal` / `PlayDiceLabel` / `GameGold` 在 oracle 里是
    /// 同一个 `PlayObject` 的字段（`PlayObject.cs:856/588`），跨 `GotoLable` 天然存活；
    /// 本仓每次 `GotoLable` 重建 `NpcPlayer` ⇒ 必须 seed + write-back，否则
    /// `OPENYBDEAL`（`ExecutionProcessingSys.cs:2345/2346`）/`PLAYDICE`（`:2032`）的副作用
    /// 会在本次调用结束时被丢弃。
    ///
    /// 红检：删掉 `write_back_player_gold_deal` 的 `SaleDeal`/`PlayDiceLabel`/`GameGold`
    /// 任一行（或 `seed_player_gold_deal` 的任一行）⇒ 对应断言红；同函数里 `PlayObject.Gold`
    /// 那一行的牙在 [`take_gold_persists_to_session_gold_through_production_path`]。
    #[test]
    fn t142_gold_deal_seed_and_write_back_round_trip() {
        use mir2_script::engine::ScriptPlayer as _;
        let mut sg = test_session_ground(1);
        sg.game_gold = 150;
        let mut session = ShopSession::default();
        let mut sell_off = game_svr::selloff::SellOffState::default();
        let catalog = game_svr::ability::StdItemCatalog::new();
        let vars = game_svr::npc::NpcVars::default();
        let mut rng = |_v: i32| 0;
        {
            let mut p = npc_player_from_session(&mut rng, "hero", &sg, "0", &catalog, &vars);
            // 脚本 `PLAYDICE ... @dice` / `OPENYBDEAL 100` 的落点。
            p.set_play_dice_label("@dice");
            p.set_sale_deal(true);
            p.set_game_gold(50);
            write_back_player_gold_deal(&p, &mut sg, &mut session, &mut sell_off);
        }
        assert!(sell_off.sale_deal, "SaleDeal 写回 `SellOffState`（真源）");
        assert_eq!(session.play_dice_label.as_deref(), Some("@dice"));
        assert_eq!(sg.game_gold, 50, "GameGold 写回会话（OPENYBDEAL 扣费）");
        // 反向：会话 → `NpcPlayer`（下一次 `GotoLable` 必须看到上一次的副作用）。
        let mut rng = |_v: i32| 0;
        let mut p = npc_player_from_session(&mut rng, "hero", &sg, "0", &catalog, &vars);
        seed_player_gold_deal(&mut p, &session, &sell_off);
        assert!(
            p.sale_deal(),
            "`ActionOfOpenSaleDeal` 的前置读必须看到已开通"
        );
        assert_eq!(p.play_dice_label(), Some("@dice".to_string()));
        assert_eq!(p.game_gold, 50);
    }

    /// **T-142 F1 夹具**：一条商人脚本动作（`n_cmd_code` = `codes.rs` 的 `field_index`
    /// = C# 枚举值：42 `PLAYDICE` / 191 `GAMEGOLD` / 342 `OPENYBDEAL`）。
    fn t142_act(code: i32, p1: &str, n1: i32, p2: &str) -> mir2_script::QuestActionInfo {
        mir2_script::QuestActionInfo {
            n_cmd_code: code,
            s_param1: p1.to_string(),
            n_param1: n1,
            s_param2: p2.to_string(),
            ..Default::default()
        }
    }

    /// 一个 label 的说词记录。**每个动作单独一条 procedure**：oracle
    /// `GotoLableQuestActionProcess` 对每个 process 只执行**第一个已注册动作**后返回
    /// （`Engine::run_actions` 的 1:1 移植），同一 `action_list` 里的后续动作不会执行。
    fn t142_record(
        label: &str,
        say: &str,
        actions: Vec<mir2_script::QuestActionInfo>,
    ) -> mir2_script::SayingRecord {
        let procedure_list = actions
            .into_iter()
            .enumerate()
            .map(|(i, a)| mir2_script::SayingProcedure {
                condition_list: Vec::new(),
                action_list: vec![a],
                else_action_list: Vec::new(),
                s_say_msg: if i == 0 {
                    say.to_string()
                } else {
                    String::new()
                },
                s_else_say_msg: String::new(),
            })
            .collect();
        mir2_script::SayingRecord {
            s_label: label.to_string(),
            procedure_list,
            bo_ext_jmp: false,
        }
    }

    /// **T-142 F1/F2 夹具**：世界（玩家 `hero` (10,10) + 商人 (11,10)，同图 ±15 内）、
    /// 会话（元宝 250、`GamePoint = 0x00010002`、`SoftVersionDateEx != 0`）、在线登记表、
    /// 网关下行缓冲与商店/寄售会话态。
    ///
    /// 这个夹具走的是**生产入口**（`handle_shop_cmd` / `handle_click_npc_cmd`），
    /// 直接调 `seed_player_gold_deal` 的往返用例（`t142_gold_deal_seed_and_write_back_round_trip`）
    /// 是辅助函数级假牙，删掉生产接线它不会红。
    struct T142Rig {
        world: mir2_world_bevy::World,
        merchant_id: i32,
        sessions: HashMap<String, SessionGround>,
        online: OnlineRegistry,
        gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>>,
        rx: mpsc::UnboundedReceiver<SimToGate>,
        shop_sessions: HashMap<String, ShopSession>,
        sell_off_sessions: HashMap<String, game_svr::selloff::SellOffState>,
        sell_off_book: game_svr::selloff::SellOffBook,
        book: game_svr::npc::MerchantScriptBook,
        npc_vars: game_svr::npc::NpcVars,
        catalog: game_svr::ability::StdItemCatalog,
        shop_cfg: ShopCfg,
        colors: MsgColors,
        item_number: std::sync::atomic::AtomicI32,
    }

    impl T142Rig {
        fn new(records: Vec<mir2_script::SayingRecord>) -> Self {
            let mut world = mir2_world_bevy::World::new(32, 32);
            let hero = world.add_entity({
                let mut e = mir2_world_bevy::EntitySpawn::new(1, "hero", 10, 10);
                e.race = mir2_world_bevy::ACTOR_RACE_PLAY;
                e
            });
            let merchant_id = world
                .insert_merchant(mir2_world_bevy::merchant::MerchantSpawn {
                    name: "商人".to_string(),
                    x: 11,
                    y: 10,
                    map_id: 0,
                    state: mir2_world_bevy::merchant::MerchantState::new(
                        "卫家店".to_string(),
                        "0".to_string(),
                        0,
                        0,
                        100,
                        false,
                        false,
                        0,
                        mir2_world_bevy::merchant::MerchantFlags {
                            is_buy: true,
                            ..Default::default()
                        },
                        vec![0, 5],
                        Vec::new(),
                        0,
                    ),
                })
                .expect("商人入世界");
            let mut book = game_svr::npc::MerchantScriptBook::new(30);
            book.insert(game_svr::npc::MerchantNpc {
                def: std::rc::Rc::new(game_svr::npc::NpcDef {
                    chr_name: "寄售商".to_string(),
                    file_path: "Market_Def".to_string(),
                    script_name: Some("寄售商-0103".to_string()),
                    is_hide: false,
                    is_quest: false,
                    scripts: vec![mir2_script::ScriptInfo {
                        is_quest: false,
                        quest_info: Default::default(),
                        record_list: records,
                        quest_count: 0,
                    }],
                    loaded: true,
                    actor_id: merchant_id,
                }),
                price_rate: 100,
                castle: None,
                map_name: "0".to_string(),
                curr_x: 11,
                curr_y: 10,

                envir_root: None,
            });
            let mut sg = test_session_ground(hero);
            sg.game_gold = 250;
            sg.game_point = 0x0001_0002;
            // 真冻结客户端的 `SoftVersionDateEx != 0`（同 `spell_session_ground`）。
            sg.soft_version_date = 120_020_522;
            let mut sessions: HashMap<String, SessionGround> = HashMap::new();
            sessions.insert("hero".to_string(), sg);
            let mut online: OnlineRegistry = OnlineRegistry::new();
            online_set(
                &mut online,
                OnlineEntry {
                    account: "ua".to_string(),
                    chr_name: "hero".to_string(),
                    session_id: 1,
                    gate_idx: 0,
                    socket: 901,
                    actor_id: hero,
                },
            );
            let (tx0, rx) = mpsc::unbounded_channel::<SimToGate>();
            let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
            gates.insert(0, tx0);
            Self {
                world,
                merchant_id,
                sessions,
                online,
                gates,
                rx,
                shop_sessions: HashMap::new(),
                sell_off_sessions: HashMap::new(),
                sell_off_book: game_svr::selloff::SellOffBook::default(),
                book,
                npc_vars: game_svr::npc::NpcVars::default(),
                catalog: game_svr::ability::StdItemCatalog::new(),
                shop_cfg: ShopCfg {
                    castle_member_price_rate: 100,
                    super_repair_price_rate: 100,
                    repair_item_dec_dura: 0,
                    make_durg_price: 100,
                    get_all_npc_tax: false,
                    human_max_gold: 10_000_000,
                    ..ShopCfg::default()
                },
                colors: MsgColors {
                    red_f: 255,
                    red_b: 56,
                    hear_f: 0,
                    hear_b: 255,
                    whisper_f: 0,
                    whisper_b: 0,
                    green_f: 0xDB,
                    green_b: 0xFF,
                    blue_f: 0xFF,
                    blue_b: 0xFC,
                },
                item_number: std::sync::atomic::AtomicI32::new(0),
            }
        }

        fn game_gold(&self) -> i32 {
            self.sessions["hero"].game_gold
        }

        /// 生产入口 ①：`CM_MERCHANTDLGSELECT`（`PlayObject.Operate.cs:114-128`）。
        fn dlg_select(&mut self, label: &str) {
            self.dlg_select_with_gm(label, None);
        }

        /// 同 [`Self::dlg_select`]，但把脚本 `GMEXECUTE` 的宿主跳线视图传进生产入口
        /// （卡 `openmir2-gm-script-exec-seams`）。
        fn dlg_select_with_gm(&mut self, label: &str, gm: Option<&ScriptGmEnv<'_>>) {
            self.dlg_select_with(label, gm, None);
        }

        /// 同 [`Self::dlg_select_with_gm`]，再装脚本世界副作用上下文
        /// （卡 `openmir2-clearmapmon-impl`；`CLEARMAPMON`/`MONGENEX` 走同一条动作序队列）。
        fn dlg_select_with_world(&mut self, label: &str, sw: &mut ScriptWorldCtx<'_>) {
            self.dlg_select_with(label, None, Some(sw));
        }

        fn dlg_select_with(
            &mut self,
            label: &str,
            gm: Option<&ScriptGmEnv<'_>>,
            script_world: Option<&mut ScriptWorldCtx<'_>>,
        ) {
            let trade: HashMap<String, game_svr::trade::DealState> = HashMap::new();
            handle_shop_cmd(
                game_svr::shop::CM_MERCHANTDLGSELECT,
                self.merchant_id,
                0,
                0,
                Some(label),
                "hero",
                901,
                &self.online,
                &mut self.sessions,
                &mut self.shop_sessions,
                &mut self.sell_off_sessions,
                &mut self.sell_off_book,
                &trade,
                &self.gates,
                &mut self.world,
                &self.catalog,
                &self.shop_cfg,
                &self.colors,
                None,
                &self.item_number,
                &self.book,
                &self.npc_vars,
                gm,
                script_world,
            );
        }

        /// 生产入口 ②：`CM_CLICKNPC`（`PlayObject.Message.cs:2071-2095` 的 `Click` 支）。
        fn click(&mut self) -> bool {
            self.click_with_gm(None)
        }

        /// 同 [`Self::click`]，但装脚本 `GMEXECUTE` 的宿主跳线（卡 `openmir2-gm-script-exec-seams`）。
        fn click_with_gm(&mut self, gm: Option<&ScriptGmEnv<'_>>) -> bool {
            self.click_with(gm, None)
        }

        /// 同 [`Self::click_with_gm`]，再装脚本世界副作用上下文
        /// （卡 `openmir2-clearmapmon-impl`；T118/Q001 的 `CLEARMAPMON → MONGENEX` 序列走此入口）。
        fn click_with_world(&mut self, sw: &mut ScriptWorldCtx<'_>) -> bool {
            self.click_with(None, Some(sw))
        }

        fn click_with(
            &mut self,
            gm: Option<&ScriptGmEnv<'_>>,
            script_world: Option<&mut ScriptWorldCtx<'_>>,
        ) -> bool {
            handle_click_npc_cmd(
                self.merchant_id,
                "hero",
                901,
                &self.online,
                &mut self.sessions,
                &mut self.world,
                &self.book,
                &mut self.shop_sessions,
                &mut self.sell_off_sessions,
                &self.npc_vars,
                &self.catalog,
                &self.item_number,
                &self.gates,
                gm,
                script_world,
            )
        }

        /// 生产入口 ③：`CM_USERREPAIRITEM`（`PlayObject.Operate.cs:1585`）。`MakeIndex = 0`
        /// ⇒ `repair_target_index` 走 BUG-REPLICA 的「回落最后一件」支。
        fn repair(&mut self) {
            let trade: HashMap<String, game_svr::trade::DealState> = HashMap::new();
            handle_shop_cmd(
                game_svr::shop::CM_USERREPAIRITEM,
                self.merchant_id,
                0,
                0,
                Some(""),
                "hero",
                901,
                &self.online,
                &mut self.sessions,
                &mut self.shop_sessions,
                &mut self.sell_off_sessions,
                &mut self.sell_off_book,
                &trade,
                &self.gates,
                &mut self.world,
                &self.catalog,
                &self.shop_cfg,
                &self.colors,
                None,
                &self.item_number,
                &self.book,
                &self.npc_vars,
                None,
                None,
            );
        }

        fn drain(&mut self) -> Vec<Vec<u8>> {
            drain_frames(&mut self.rx)
        }
    }

    /// **T-142 F1（Important，复核实证的假牙缺口）**：`CM_MERCHANTDLGSELECT` 的**生产路径**上，
    /// `PLAYDICE` 的 `PlayDiceLabel`、`OPENYBDEAL` 的 `SaleDeal`/`GameGold` 副作用必须跨
    /// `GotoLable` 存活（oracle 里它们是同一个 `PlayObject` 的字段，`PlayObject.cs:588/856`）。
    ///
    /// 夹具脚本三层：
    /// - `@main`：说词 `<开通/@open>` + `PLAY DICE 1 @dice`（`ExecutionProcessingSys.cs:2030-2034`）；
    /// - `@open`：说词 `<返回/@main>` + `OPENYBDEAL 100`（`:2329-2357`）；
    /// - `@dice`：说词 `<返回/@main>` + `OPENYBDEAL 100` + `GAMEGOLD + 10`。
    ///
    /// `@dice` **不出现在任何说词里** ⇒ 进入资格只能来自 `LableIsCanJmp` 第三支
    /// （`PlayObject.Base.cs:2824-2828`，命中即清 `string.Empty` ⇒ 一次性）。
    ///
    /// **卡 `openmir2-gm-script-exec-seams`（商家路）**：`CM_MERCHANTDLGSELECT` 送进
    /// `run_merchant_goto` 的脚本里写 `GMEXECUTE f`，必须与 `@Login`（T-210）
    /// 同口径产出**恰好一条** `SM_SYSMESSAGE(100)`（`@f` 缺参红帮助逐字节），
    /// 且抬权（`Permission 3 → 10`）在脚本结束后还原成进入前的 3。
    ///
    /// 载体选择（扫盲卡 `openmir2-gm-systemshare-null-sweep`）：原载体 `禁言` 真机零帧
    /// （`ShutupCommand.cs:30` 触 null 表 NRE ⇒ 红字回执不可达），故换 `@f`——
    /// 单条确定性红字、零副作用，`GMEXECUTE` 跳线属性不变。
    ///
    /// 牙：删 `run_merchant_goto` 的装桥块 ⇒ 本用例红（0 条 SysMsg：`process_user_line_msg`
    /// 回到 `ScriptPlayer` 缺省 no-op）；删块尾 `sg.gm = s` 的放回 ⇒ 会话 GM 态变默认值、
    /// permission 3 丢（断言红）。
    #[test]
    fn merchant_goto_gmexecute_emits_one_sysmsg_and_restores_permission() {
        let mut rig = T142Rig::new(vec![t142_record(
            "@main",
            "",
            vec![gmexec_act("f", "", "")],
        )]);
        rig.sessions.get_mut("hero").unwrap().gm.permission = 3;
        let guilds = mir2_world_bevy::GuildManager::new();
        let cfg = gmcmd::GmConfig::default();
        let pwd: HashMap<String, game_svr::inbound::PwdSession> = HashMap::new();
        let env = ScriptGmEnv {
            guilds: &guilds,
            maps: None,
            cfg: &cfg,
            pwd_sessions: &pwd,
            // 未装配宿主通道（退化兜底形态；卡 `openmir2-gmexe-bridge-channels` 前的行为）。
            host: ScriptGmHost::default(),
        };
        rig.dlg_select_with_gm("@main", Some(&env));
        let frames = rig.drain();
        let sys: Vec<&Vec<u8>> = frames
            .iter()
            .filter(|b| hdr(b.as_slice()).0 == mir2_protocol::messages::SM_SYSMESSAGE)
            .collect();
        assert_eq!(
            sys.len(),
            1,
            "脚本 GMEXECUTE ⇒ 恰好一条 SM_SYSMESSAGE；实得 {:?}",
            idents(&frames)
        );
        let text = gbk_decode(&mir2_protocol::edcode::decode(&sys[0][12..]));
        assert_eq!(text, "命令格式: @f 地图号", "`@f` 的 SysMsg 逐字节");
        assert_eq!(
            rig.sessions["hero"].gm.permission, 3,
            "抬权必须还回进入前的值（3），且会话 GM 态已原样放回"
        );
        // **无泄漏探针**（卡 seams 的判据 ④，与 T-210 同款）：同一 `GmSession` 上客户端直呼
        // perm-10 命令仍必须回 `权限不够!!!`。
        let mut sess = rig.sessions["hero"].gm.clone();
        let out = gmcmd::execute(
            &mut sess,
            &cfg,
            &gmcmd::GmWorld::new(&guilds),
            "@禁言 hero 10",
        );
        assert!(
            out.msgs.iter().any(|m| m.text.contains("权限不够")),
            "脚本抬权不得泄漏到客户端命令：{:?}",
            out.msgs
        );
    }

    /// 同卡的**点击路**：`CM_CLICKNPC(@main)`（`PlayObject.Base.cs:676` → `GotoLable("@main")`）
    /// 与对话框是同一个 [`run_merchant_goto`] ⇒ 装桥后脚本 `GMEXECUTE` 必须同样出帧
    /// （载体 `@f`，理由见上一用例——原载体 `禁言` 真机零帧）。
    ///
    /// 牙：把 `handle_click_npc_cmd` 里 `run_merchant_goto(...)` 的 `gm` 实参换回 `None` ⇒ 红。
    #[test]
    fn click_npc_gmexecute_produces_sysmsg() {
        let mut rig = T142Rig::new(vec![t142_record(
            "@main",
            "",
            vec![gmexec_act("f", "", "")],
        )]);
        let guilds = mir2_world_bevy::GuildManager::new();
        let cfg = gmcmd::GmConfig::default();
        let pwd: HashMap<String, game_svr::inbound::PwdSession> = HashMap::new();
        let env = ScriptGmEnv {
            guilds: &guilds,
            maps: None,
            cfg: &cfg,
            pwd_sessions: &pwd,
            // 未装配宿主通道（退化兜底形态；卡 `openmir2-gmexe-bridge-channels` 前的行为）。
            host: ScriptGmHost::default(),
        };
        assert!(rig.click_with_gm(Some(&env)), "点击必须命中商人");
        let frames = rig.drain();
        let sys: Vec<&Vec<u8>> = frames
            .iter()
            .filter(|b| hdr(b.as_slice()).0 == mir2_protocol::messages::SM_SYSMESSAGE)
            .collect();
        assert_eq!(
            sys.len(),
            1,
            "点击路 GMEXECUTE ⇒ 恰好一条 SM_SYSMESSAGE；实得 {:?}",
            idents(&frames)
        );
        assert_eq!(
            gbk_decode(&mir2_protocol::edcode::decode(&sys[0][12..])),
            "命令格式: @f 地图号"
        );
    }

    /// `GMEXECUTE`（`ExecutionCode.GmExecute = 229`）：`sParam1` 命令名、`sParam2` 目标、
    /// `sParam3` 参数（`ExecutionProcessingSys.cs:4925-4937`）。
    fn gmexec_act(p1: &str, p2: &str, p3: &str) -> mir2_script::QuestActionInfo {
        mir2_script::QuestActionInfo {
            n_cmd_code: 229,
            s_param1: p1.to_string(),
            s_param2: p2.to_string(),
            s_param3: p3.to_string(),
            ..Default::default()
        }
    }

    /// 牙（删生产接线必红）：删 `run_merchant_goto` 的 `seed_player_gold_deal` ⇒ 实测**先红在
    /// 第一次 `@dice` 的 `LableIsCanJmp` 断言**（`lib.rs` 的
    /// `assert_eq!(play_dice_label.as_deref(), Some(""))`：快照没 seed 到会话里的
    /// `PlayDiceLabel` ⇒ 第三支不放行 ⇒ `left: None, right: Some("")`，日志
    /// `LableIsCanJmp(@dice) == false`），根本到不了第③段的扣费分支（因此「160 变 60」只是
    /// 更后段的假设后果，不是首个失败点）；删其
    /// `write_back_player_gold_deal` ⇒ 第②段元宝不落会话（250 而非 150）。
    #[test]
    fn t142_merchant_dlg_select_openybdeal_and_playdice_through_production_path() {
        let mut rig = T142Rig::new(vec![
            t142_record(
                "@main",
                r"掷骰还是开通?\ <开通/@open>",
                vec![t142_act(42, "", 1, "@dice")],
            ),
            t142_record(
                "@open",
                r"开通寄售\ <返回/@main>",
                vec![t142_act(342, "100", 0, "")],
            ),
            t142_record(
                "@dice",
                r"骰子\ <返回/@main>",
                vec![t142_act(342, "100", 0, ""), t142_act(191, "+", 10, "10")],
            ),
        ]);

        // —— `@main`：`PLAY DICE 1 @dice` 只写标签（不涉元宝）。
        rig.dlg_select("@main");
        assert_eq!(rig.game_gold(), 250, "PLAYDICE 不扣元宝");
        assert_eq!(
            rig.shop_sessions["hero"].play_dice_label.as_deref(),
            Some("@dice"),
            "PLAYDICE 的 sParam2 必须经生产路径写回会话（否则客户端回跳必被拒）"
        );
        assert!(
            !rig.sell_off_sessions["hero"].sale_deal,
            "未 OPENYBDEAL 前 SaleDeal 必须为 false"
        );
        assert!(
            rig.drain()
                .iter()
                .any(|b| hdr(b).0 == mir2_protocol::messages::SM_MERCHANTSAY),
            "@main 说词必须下发"
        );

        // —— `@open`：经说词 `CanJmpScriptLableMap` 第二支放行；`OPENYBDEAL 100` 扣费 + 置 SaleDeal。
        rig.dlg_select("@open");
        assert_eq!(
            rig.game_gold(),
            150,
            "① OPENYBDEAL 100 必须经生产路径扣会话元宝（写回生效）"
        );
        assert!(
            rig.sell_off_sessions["hero"].sale_deal,
            "① SaleDeal 必须写回 `SellOffState`"
        );
        let _ = rig.drain();

        // —— 第一次 `@dice`：只能经 `LableIsCanJmp` 第三支（`@dice` 不在任何说词里）。
        rig.dlg_select("@dice");
        assert_eq!(
            rig.shop_sessions["hero"].play_dice_label.as_deref(),
            Some(""),
            "② 第三支命中即清成空串（一次性）"
        );
        assert_eq!(
            rig.game_gold(),
            160,
            "②③ 第三支放行 ⇒ 脚本执行：已开通支不扣费（150）+ GAMEGOLD +10 ⇒ 160（seed 生效）"
        );
        assert!(
            !rig.drain().is_empty(),
            "② 第三支放行 ⇒ 脚本执行（说词 + 元宝帧），不可能零帧"
        );

        // —— 第二次 `@dice`：第三支已被消费 ⇒ `LableIsCanJmp == false` ⇒ 零帧、零副作用。
        rig.dlg_select("@dice");
        assert!(
            rig.drain().is_empty(),
            "② 第三支只能放行一次（第二次被拒 ⇒ `GotoLable` 被 boExtJmp 挡下 ⇒ 零帧）"
        );
        assert_eq!(rig.game_gold(), 160, "② 被拒 ⇒ 脚本不执行，元宝不变");
    }

    /// 把部署脚本 `E:/MirServer/M2GameSvr/Envir/Market_Def/赌博NPC/赌场-B013.txt` 的
    /// `[@ya52]` 段（第 203-215 行）按 **GBK 原文** 写盘，再走生产解析器
    /// （`ScriptParsers::load_script_file`，`boFlag=true` = `Merchant.LoadScriptFile`）。
    ///
    /// `[@main]`/`[@ya5]` 只保留**可跳转链**（与 `tools/probe/scenarios/dice_chain*.json` 的
    /// `@ya5 → @ya52` 同形）；`[@ya52]` 段逐字照抄部署件：
    ///
    /// ```text
    /// [@ya52]
    /// #IF
    /// CHECKitem 筹码包 1
    /// #ACT
    /// take 筹码包 1
    /// movr d0 6
    /// inc d0 1
    /// playdice 1 @cube52
    /// #SAY
    /// 正在投骰子…………
    /// #ELSEACT
    /// MESSAGEBOX 请打开商铺兑换[筹码]后再来！
    /// break
    /// ```
    fn ya52_book(tag: &str, merchant_id: i32) -> game_svr::npc::MerchantScriptBook {
        const SRC: &str = r#"[@main]
<押1个筹码包/@ya5>\
[@ya5]
<大/@ya51>  <小/@ya52>\
[@ya52]
#IF
CHECKitem 筹码包 1
#ACT
take 筹码包 1
movr d0 6
inc d0 1
playdice 1 @cube52
#SAY
正在投骰子…………
#ELSEACT
MESSAGEBOX 请打开商铺兑换[筹码]后再来！
break
"#;
        let crlf = SRC.replace('\n', "\r\n");
        let bytes = encoding_rs::GBK.encode(&crlf).0.into_owned();
        let root = std::env::temp_dir().join(format!("gs-ya52-{tag}-{}", std::process::id()));
        let dir = root.join("Envir").join("Market_Def");
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("赌场-B013.txt"), bytes).unwrap();
        let parsers = mir2_script::ScriptParsers::new();
        let mut rename = |_min: i32, _max: i32| 1;
        let outcome = parsers
            .load_script_file(
                &mir2_script::LocalFs,
                &root.join("Envir"),
                "Market_Def",
                "赌场-B013",
                true,
                &mut rename,
            )
            .expect("解析不得 panic")
            .expect("脚本必须存在");
        std::fs::remove_dir_all(&root).ok();
        assert!(
            outcome.errors.is_empty(),
            "夹具脚本不得有解析错误：{:?}",
            outcome.errors
        );
        let mut book = game_svr::npc::MerchantScriptBook::new(30);
        book.insert(game_svr::npc::MerchantNpc {
            def: std::rc::Rc::new(game_svr::npc::NpcDef {
                chr_name: "赌场老板".to_string(),
                file_path: "Market_Def".to_string(),
                script_name: Some("赌场-B013".to_string()),
                is_hide: false,
                is_quest: false,
                scripts: outcome.scripts,
                loaded: true,
                actor_id: merchant_id,
            }),
            price_rate: 100,
            castle: None,
            map_name: "0".to_string(),
            curr_x: 11,
            curr_y: 10,

            envir_root: None,
        });
        book
    }

    /// `[@ya52]` 段的**生产链路**夹具：真实 GBK 脚本 → 解析器 → 商人脚本表。
    fn ya52_rig(tag: &str) -> T142Rig {
        let mut rig = T142Rig::new(Vec::new());
        rig.book = ya52_book(tag, rig.merchant_id);
        rig
    }

    /// 跑 `@main → @ya5 → @ya52`（与 dice_chain 场景同形）并返回最后一步的下行帧。
    fn ya52_run(rig: &mut T142Rig) -> Vec<Vec<u8>> {
        rig.dlg_select("@main");
        let _ = rig.drain();
        rig.dlg_select("@ya5");
        let _ = rig.drain();
        rig.dlg_select("@ya52");
        rig.drain()
    }

    fn idents(frames: &[Vec<u8>]) -> Vec<(u16, u16, u16, i32)> {
        frames.iter().map(|b| hdr(b.as_slice())).collect()
    }

    /// **T-193（卡 `openmir2-ya52-menu-ok-missing`）**：部署脚本 `[@ya52]` 的
    /// `CHECKitem` 不满足 ⇒ `#ELSEACT MESSAGEBOX ...` 必须下发**恰好一条** `SM_MENU_OK(767)`，
    /// 帧字节与 C# 真机金标准逐字节一致。
    ///
    /// oracle 推演（逐步）：
    /// 1. `ConditionOfCheckItem`（`ConditionProcessingSys.cs:4043-4056`）：
    ///    `playerActor.QuestCheckItem("筹码包")` 得 `n1C=0`，`0 < nParam2(1)` ⇒ `success=false`；
    /// 2. `ScriptEngine.GotoLable`（`ScriptEngine.cs:38-129`）条件假 ⇒ 走 `ElseActionList`；
    /// 3. `ActionOfMessageBox`（`ExecutionProcessingSys.cs:3416-3419`）：
    ///    `playerActor.SendMsg(normNpc, RM_MENU_OK, 0, playerActor.ActorId, 0, 0, text)`；
    /// 4. `PlayObject.Message.cs:1952-1953`：
    ///    `SendDefMessage(SM_MENU_OK, processMsg.nParam1, 0, 0, 0, processMsg.Msg)`
    ///    ⇒ `Recog` = **玩家** `ActorId`（`nParam1`）、`Param/Tag/Series` = 0、
    ///    尾 = `EDCode.EncodeString(GetLineVariableText(sParam1))`（cp936 原文）；
    /// 5. 动作循环在此 **return**：`GotoLableQuestActionProcess`
    ///    （`ScriptEngine.cs:887-895`）对**首个已注册动作**执行后立即 `return`
    ///    ⇒ `#ELSEACT` 里的 `break` **不可达**；可观测等价：
    ///    `ElseSayMsg` 为空 ⇒ 一样零 643。
    ///
    /// 真机金标准：`E:/tmp/conformance/runs/w24-csharp-dice-r1|r2/frames.ndjson` 的 `seq=35`
    /// （C# 2/2；同一场景 Rust 修复前 0/2）：`ident=767 / param=0 / tag=0 / series=0`、
    /// body 38 B、`body_sha256=e6d73c8e334a42ce701972b50e16e74624516dc309e321fd0b40ad30046cf15c`、
    /// `Recog` 为玩家 `ActorId`（r1=1833593529、r2=1882717309）。
    ///
    /// 牙（先备份 sha256，改完还原并核对）：
    /// ① 停用 `pickwire::script_frame` 的 `RM_MENU_OK` 支 ⇒ 本用例红（0 条 767）。
    ///    （T-194 起映射已**下沉进 `pickwire::script_frame`**，本卡原有的 `emit_script_frames`
    ///    直落旁路已删除；因此牙①的落点从「删 `emit_script_frames` 支」改为「停用统一映射」。）
    /// ② 把它提成「无条件发」⇒ [`ya52_checkitem_satisfied_sends_no_menu_ok`] 红。
    #[test]
    fn ya52_elseact_messagebox_emits_exactly_one_sm_menu_ok() {
        let mut rig = ya52_rig("pos");
        let frames = ya52_run(&mut rig);
        let menu: Vec<&Vec<u8>> = frames
            .iter()
            .filter(|b| hdr(b.as_slice()).0 == mir2_protocol::messages::SM_MENU_OK)
            .collect();
        assert_eq!(
            menu.len(),
            1,
            "命中 @ya52 的 ELSEACT ⇒ 恰好一条 SM_MENU_OK；实得 {:?}",
            idents(&frames)
        );
        let hero = rig.sessions["hero"].actor_id;
        assert_eq!(
            hdr(menu[0].as_slice()),
            (mir2_protocol::messages::SM_MENU_OK, 0, 0, hero),
            "767 的 Recog=玩家 ActorId，Param/Tag=0"
        );
        assert_eq!(
            u16::from_le_bytes([menu[0][10], menu[0][11]]),
            0,
            "Series 必须为 0（`SendDefMessage` 第 5 参）"
        );
        // 尾 = `EDCode.EncodeString(GBK 原文)`：与真机 C# 抓包逐字节相同。
        const GOLDEN_BODY: &str =
            "574f5445524342485554665054427a4e43437371434f6a584f7952405358715a54404b4a3d3f";
        let body_hex: String = menu[0][12..].iter().map(|b| format!("{b:02x}")).collect();
        assert_eq!(
            body_hex, GOLDEN_BODY,
            "767 尾必须与真机 C#（w24-csharp-dice-r1/r2 seq=35）逐字节相同"
        );
        // 尾部来源自证：消息原文的 cp936 字节 = 部署件 `赌场-B013.txt` 第 214 行
        // `MESSAGEBOX ` 之后的 28 B。
        const MSG_GBK: &[u8] = &[
            0xc7, 0xeb, 0xb4, 0xf2, 0xbf, 0xaa, 0xc9, 0xcc, 0xc6, 0xcc, 0xb6, 0xd2, 0xbb, 0xbb,
            0x5b, 0xb3, 0xef, 0xc2, 0xeb, 0x5d, 0xba, 0xf3, 0xd4, 0xd9, 0xc0, 0xb4, 0xa3, 0xa1,
        ];
        assert_eq!(
            menu[0][12..],
            mir2_protocol::edcode::encode(MSG_GBK)[..],
            "尾 = EDCode(请打开商铺兑换[筹码]后再来！) 的 cp936 原文"
        );
    }

    /// **T-193 反例（防「无条件发」）**：`CHECKitem 筹码包 1` **满足** ⇒ 走 `#ACT` 支 ⇒ **零** `SM_MENU_OK(767)`；
    /// 且 `#SAY`「正在投骰子…………」与 `take` 都真的发生（证明脚本确实进了段，不是零执行）。
    ///
    /// 注：C# `GotoLableQuestActionProcess` 对同一 `ActionList` **只执行第一个已注册动作**
    /// （`ScriptEngine.cs`；Rust `Engine::run_actions` 1:1）⇒ 本例只跑 `take`，
    /// `playdice` 不会到达（行为等价，不是本卡缺口）。
    #[test]
    fn ya52_checkitem_satisfied_sends_no_menu_ok() {
        let mut rig = ya52_rig("neg");
        rig.catalog.insert(
            1,
            mir2_data::StdItem {
                name: "筹码包".to_string(),
                dura_max: 5000,
                ..mir2_data::StdItem::default()
            },
        );
        rig.sessions
            .get_mut("hero")
            .unwrap()
            .state
            .item_list
            .push(game_svr::bag::BagItem::new(4201, 1));
        let frames = ya52_run(&mut rig);
        assert!(
            idents(&frames)
                .iter()
                .all(|h| h.0 != mir2_protocol::messages::SM_MENU_OK),
            "CHECKitem 满足 ⇒ 不得发 767（否则就是「无条件发」）；实得 {:?}",
            idents(&frames)
        );
        assert_eq!(
            idents(&frames)
                .iter()
                .filter(|h| h.0 == mir2_protocol::messages::SM_MERCHANTSAY)
                .count(),
            1,
            "#ACT 支必须真的执行（#SAY「正在投骰子…………」⇒ 恰好一条 SM_MERCHANTSAY）；实得 {:?}",
            idents(&frames)
        );
        assert!(
            rig.sessions["hero"].state.item_list.is_empty(),
            "`take 筹码包 1` 必须把物品从会话背包摘掉"
        );
    }

    /// `SETOFFLINE 时间 点数 踢号分钟`（`n_cmd_code = 337` = `ExecutionCode.OffLine`）：
    /// 三段参数都走 `sParam1..3`（`ScriptParsers.cs:554`）。
    fn setoffline_act(p1: &str, p2: &str, p3: &str) -> mir2_script::QuestActionInfo {
        mir2_script::QuestActionInfo {
            n_cmd_code: 337,
            s_param1: p1.to_string(),
            s_param2: p2.to_string(),
            s_param3: p3.to_string(),
            ..Default::default()
        }
    }

    /// **A-10/T-86（`SETOFFLINE`）生产入口**：`CM_MERCHANTDLGSELECT` → `run_merchant_goto`
    /// → `ActionOfOffLine`（code 337）→ `NpcPlayer::set_offline` → 会话写回，六字段逐项断言。
    ///
    /// oracle 锚（`ExecutionProcessingSys.cs:2723-2728`）：`AutoGetExpInSafeZone = true`、
    /// `AutoGetExpEnvir = playerActor.Envir`、`AutoGetExpTime = nTime * 1000`、
    /// `AutoGetExpPoint = nPoint`、`OffLineFlag = true`、
    /// `KickOffLineTick = HUtil32.GetTickCount() + nKickOffLine * 60 * 1000`。
    /// 宿主侧 `GetTickCount()` = `now_ms() as i32`（**与 P31 `host_now = now_ms()` 同域**）；
    /// 墙钟不可被夹具注入 ⇒ 用调用前后的两次取钟把基准钉在区间内。
    ///
    /// 牙①：删 `run_merchant_goto` 的 `write_back_player_offline` 调用 ⇒ 六条断言全红
    /// （会话仍是 false/None/0/0/0/0）。
    /// 牙②：删 `NpcPlayer::envir_map_name` / `tick_count` 覆写 ⇒ `envir` / `kick` 断言红。
    #[test]
    fn setoffline_writes_six_session_fields_through_production_path() {
        let mut rig = T142Rig::new(vec![t142_record(
            "@main",
            "挂机",
            vec![setoffline_act("3", "700", "15")],
        )]);
        let lo = now_ms() as i32;
        rig.dlg_select("@main");
        let hi = now_ms() as i32;
        let _ = rig.drain();
        let sg = &rig.sessions["hero"];
        assert!(sg.auto_get_exp_in_safe_zone, "InSafeZone = true（:2723）");
        assert_eq!(
            sg.auto_get_exp_envir.as_deref(),
            Some("0"),
            "Envir = playerActor.Envir 的地图名（:2724）"
        );
        assert_eq!(sg.auto_get_exp_time, 3_000, "nTime * 1000（:2725）");
        assert_eq!(sg.auto_get_exp_point, 700, "nPoint（:2726）");
        assert!(sg.off_line_flag, "OffLineFlag = true（:2727）");
        let base = sg.kick_off_line_tick.wrapping_sub(15 * 60_000);
        assert!(
            (lo..=hi).contains(&base),
            "KickOffLineTick = host_tick + nKick*60*1000（:2728）：base={base} not in [{lo},{hi}]"
        );
    }

    /// **M-1（商人路径 round-trip 恒等）**：`OffLineFlag`/`KickOffLineTick` 与 P31 四字段是
    /// oracle **同一个** `PlayObject` 的字段（`ExecutionProcessingSys.cs:2723-2728`）⇒ 商人
    /// `GotoLable` 未命中 `SETOFFLINE` 时，会话里已有的挂机面必须原样存活（脚本没写就不变）。
    ///
    /// 牙：删 `npc_player_from_session` 的挂机面 seed ⇒ 快照的缺省值
    /// （false/None/0/0/false/0）被写回 ⇒ 六条断言全红。
    #[test]
    fn merchant_goto_preserves_hang_state_round_trip() {
        let mut rig = T142Rig::new(vec![t142_record("@main", "欢迎", Vec::new())]);
        {
            let sg = rig.sessions.get_mut("hero").unwrap();
            sg.auto_get_exp_in_safe_zone = true;
            sg.auto_get_exp_envir = Some("0".to_string());
            sg.auto_get_exp_time = 7_000;
            sg.auto_get_exp_point = 900;
            sg.off_line_flag = true;
            sg.kick_off_line_tick = 42;
        }
        rig.dlg_select("@main");
        let _ = rig.drain();
        let sg = &rig.sessions["hero"];
        assert!(sg.auto_get_exp_in_safe_zone);
        assert_eq!(sg.auto_get_exp_envir.as_deref(), Some("0"));
        assert_eq!(sg.auto_get_exp_time, 7_000);
        assert_eq!(sg.auto_get_exp_point, 900);
        assert!(sg.off_line_flag, "挂机标志不得被商人脚本清零");
        assert_eq!(sg.kick_off_line_tick, 42, "踢号时限不得被商人脚本清零");
    }

    /// `CHANGEEXP`（`ExecutionCode.ChangeExp = 185`；`s_param1` = 运算符、`s_param2` = 数值）。
    fn changexp_act(op: &str, n: &str) -> mir2_script::QuestActionInfo {
        mir2_script::QuestActionInfo {
            n_cmd_code: 185,
            s_param1: op.to_string(),
            s_param2: n.to_string(),
            ..Default::default()
        }
    }

    /// **A-26/T-207（CHANGEEXP）**：脚本 `CHANGEEXP + 1000` 在**生产路径**（`CM_MERCHANTDLGSELECT`
    /// → `run_merchant_goto`）上必须：① 只发一条 `SM_WINEXP(44)`；② `Recog` = seed+1000（`Abil.Exp`
    /// 加完总量，`PlayObject.Message.cs:1666-1669`）；③ `Param/Tag` = 增量 1000 的 Lo/Hi、`Series=0`；
    /// ④ 会话 `state.wabil.exp` 与 `equip.abil.exp` 同步落 1500（存档与战斗侧同读）。
    ///
    /// 牙（删 `run_merchant_goto` 的 `write_back_player_abil_exp` ⇒ 本用例红）：
    /// `SM_WINEXP.Recog` 由 `emit_script_frames` 读会话 `state.wabil.exp` ⇒ 不写回时回到 seed(500)；
    /// 会话断言同时红（500 ≠ 1500）。
    #[test]
    fn changexp_plus_lands_one_sm_winexp_and_writes_back_session() {
        let mut rig = T142Rig::new(vec![t142_record(
            "@main",
            "",
            vec![changexp_act("+", "1000")],
        )]);
        {
            let sg = rig.sessions.get_mut("hero").unwrap();
            sg.equip.abil.exp = 500;
            sg.state.wabil.exp = 500;
        }
        rig.dlg_select("@main");
        let frames = rig.drain();
        let win: Vec<&Vec<u8>> = frames
            .iter()
            .filter(|b| hdr(b.as_slice()).0 == mir2_protocol::messages::SM_WINEXP)
            .collect();
        assert_eq!(
            win.len(),
            1,
            "CHANGEEXP + ⇒ 恰好一条 SM_WINEXP(44)；实得 {:?}",
            idents(&frames)
        );
        let (ident, param, tag, recog) = hdr(win[0].as_slice());
        assert_eq!(ident, mir2_protocol::messages::SM_WINEXP);
        assert_eq!(
            recog, 1500,
            "Recog = 加完后的 Abil.Exp 总量（seed 500 + 1000）"
        );
        assert_eq!((param, tag), (1000, 0), "Param/Tag = 增量 1000 的 Lo/Hi");
        assert_eq!(
            u16::from_le_bytes([win[0][10], win[0][11]]),
            0,
            "Series 必须为 0"
        );
        let sg = &rig.sessions["hero"];
        assert_eq!(sg.state.wabil.exp, 1500, "会话 wabil.exp 必须写回");
        assert_eq!(sg.equip.abil.exp, 1500, "会话 equip.abil.exp 必须同源写回");
    }

    /// **A-26/T-207 的 seed/写回面（牙的显式版）**：`npc_player_from_session` 必须把
    /// `sg.equip.abil.exp` seed 进 `NpcPlayer.abil_exp`（`$EXP` 与脚本读侧），
    /// `write_back_player_abil_exp` 必须把脚本增量落回会话**两个**同源字段；
    /// 不调用写回时会话保持 seed（这就是上一条用例的红条件）。
    #[test]
    fn changexp_seed_and_writeback_round_trip() {
        let mut rig = T142Rig::new(vec![t142_record("@main", "", Vec::new())]);
        // 目录从 rig 里择出来，避免「&rig.catalog（不可变借）」与「&mut rig.sessions」冲突。
        let catalog = std::mem::take(&mut rig.catalog);
        let vars = rig.npc_vars.clone();
        let mut sg = rig.sessions.remove("hero").unwrap();
        sg.equip.abil.exp = 500;
        sg.state.wabil.exp = 500;
        let mut rng = mir2_shared::rng::RandomNumber::with_seed(7);
        {
            let mut rngf = |v: i32| rng.random_below(v);
            let mut player = npc_player_from_session(&mut rngf, "hero", &sg, "0", &catalog, &vars);
            assert_eq!(player.abil_exp, 500, "seed：快照必须拿到会话经验");
            player.abil_exp += 1000;
            assert_eq!(
                sg.state.wabil.exp, 500,
                "未写回时会话仍是 seed（牙的红条件）"
            );
            write_back_player_abil_exp(&player, &mut sg);
        }
        assert_eq!(sg.state.wabil.exp, 1500, "写回后 wabil.exp = 脚本后总量");
        assert_eq!(sg.equip.abil.exp, 1500, "写回后 equip.abil.exp 同源");
        rig.sessions.insert("hero".to_string(), sg);
        rig.catalog = catalog;
    }

    /// `MOV`（`ExecutionCode.Mov = 23`）：`s_param1` = 目标变量名、`s_param2` = 取值文本。
    /// 走 `GetMovDataType` 的 4 号支（`s_param1` 是槽位名、`s_param2` 是 `<...>`）
    /// ⇒ `GetMovDataHumanInfoValue` 读 `$EXP`。
    fn mov_act(target: &str, value: &str) -> mir2_script::QuestActionInfo {
        mir2_script::QuestActionInfo {
            n_cmd_code: 23,
            s_param1: target.to_string(),
            s_param2: value.to_string(),
            ..Default::default()
        }
    }

    /// **A-26/T-207 ④**：`$EXP` 的**脚本读侧**（`ProcessingBase.cs:35-566` 的 switch）必须读
    /// 同一个 `Abil.Exp` ⇒ 脚本里 `CHANGEEXP + 1000` 之后 `MOV P0 <$EXP>` 的说词 `<$STR(P0)>`
    /// 展开成 seed+增量。
    ///
    /// 用例路径：一条 label 两个 procedure —— ①`CHANGEEXP + 1000` 然后 `MOV P0 <$EXP>`；
    /// ②说词 `<$STR(P0)>`。**先加后读**：把 `set_abil_exp` 写成 no-op（reviewer 的 N1 牙）
    /// 或只 seed 不写 `NpcPlayer` ⇒ 展开回 500 ⇒ 本用例红（旧版只钉 seed 读侧，写路径坏掉仍绿）。
    /// `Engine::goto_label` 把说词**累积**到所有 procedure 跑完后才 `line_variable_text` 展开
    /// （`crates/script/src/engine/mod.rs` 的尾段）⇒ 展开时 `P0` 已是脚本读到的值。
    ///
    /// 牙：把 `NpcPlayer::abil_exp` 改回缺省 `0`（或删 `npc_player_from_session` 的 seed）
    /// ⇒ 说词变成 `exp=0`，本用例红。
    #[test]
    fn changexp_exp_variable_reads_seeded_total_into_say_text() {
        let rec = mir2_script::SayingRecord {
            s_label: "@main".to_string(),
            procedure_list: vec![
                // `CHANGEEXP` 与 `MOV` 必须在**各自的 procedure** 里：oracle
                // `GotoLableQuestActionProcess` 的 `if (IsRegister) { Execute(...); return result; }`
                // 只执行一条动作表里的**第一个已注册动作**（`run_actions` 已 1:1 移植，见
                // `crates/script/src/engine/mod.rs:1420-1433`）⇒ 同表两条动作会静默丢掉后一条。
                mir2_script::SayingProcedure {
                    condition_list: Vec::new(),
                    action_list: vec![changexp_act("+", "1000")],
                    else_action_list: Vec::new(),
                    s_say_msg: String::new(),
                    s_else_say_msg: String::new(),
                },
                mir2_script::SayingProcedure {
                    condition_list: Vec::new(),
                    action_list: vec![mov_act("P0", "<$EXP>")],
                    else_action_list: Vec::new(),
                    s_say_msg: "exp=".to_string(),
                    s_else_say_msg: String::new(),
                },
                mir2_script::SayingProcedure {
                    condition_list: Vec::new(),
                    action_list: Vec::new(),
                    else_action_list: Vec::new(),
                    s_say_msg: "<$STR(P0)>".to_string(),
                    s_else_say_msg: String::new(),
                },
            ],
            bo_ext_jmp: false,
        };
        let mut rig = T142Rig::new(vec![rec]);
        {
            let sg = rig.sessions.get_mut("hero").unwrap();
            sg.equip.abil.exp = 500;
            sg.state.wabil.exp = 500;
        }
        rig.dlg_select("@main");
        let frames = rig.drain();
        let says: Vec<&Vec<u8>> = frames
            .iter()
            .filter(|b| hdr(b.as_slice()).0 == mir2_protocol::messages::SM_MERCHANTSAY)
            .collect();
        assert_eq!(
            says.len(),
            1,
            "累积说词只落一条 RM_MERCHANTSAY；实得 {:?}",
            idents(&frames)
        );
        let (_, _, _, recog) = hdr(says[0].as_slice());
        assert_eq!(
            recog, rig.merchant_id,
            "非 priority 说词的 Recog = NPC ActorId"
        );
        let text = gbk_decode(&mir2_protocol::edcode::decode(&says[0][12..]));
        assert_eq!(
            text, "寄售商/exp=1500",
            "`<$EXP>` 必须读到 seed(500) + CHANGEEXP 增量(1000) 后的 Abil.Exp
             （缺省会展开成 0；`set_abil_exp` 写丢时回 500 —— 两种都红）"
        );
    }

    /// **A-26/T-207 ⑤**：存档**字段级**——脚本改完经验后 `MakeSaveRcd` 的
    /// `data.abil.exp` 必须是写回后的总量（`build_save_record` 取 `base = &sg.equip.abil`
    /// 再 `exp: base.exp`），且经线上存档体编码/解码往返后仍是同一值。
    ///
    /// 牙：把 `write_back_player_abil_exp` 改成只写 `sg.state.wabil.exp`（漏 `equip.abil`）
    /// ⇒ 存档仍取 seed 500，本用例红（`SM_WINEXP` 那条用例的会话断言看不出来这一路）。
    #[test]
    fn changexp_writes_into_save_record_abil_exp() {
        use mir2_storage::MemPack;
        let mut rig = T142Rig::new(vec![t142_record(
            "@main",
            "",
            vec![changexp_act("+", "1000")],
        )]);
        {
            let sg = rig.sessions.get_mut("hero").unwrap();
            sg.equip.abil.exp = 500;
            sg.state.wabil.exp = 500;
        }
        rig.dlg_select("@main");
        let _ = rig.drain();
        let saved = SavedHuman {
            account: "ua".to_string(),
            record: record::PlayerRecord::default(),
            enter_map: "0".to_string(),
            derived: None,
        };
        let rec = build_save_record(&saved, "hero", &rig.world, &rig.sessions["hero"], None);
        assert_eq!(
            rec.data.abil.as_ref().expect("存档必须有 Abil").exp,
            1500,
            "保存记录的 data.abil.exp 必须取写回后的 equip.abil.exp"
        );
        let parsed = mir2_storage::SaveCharacterData::from_bytes(
            &record::encode_save_character_data(&saved.account, "hero", &rec),
        )
        .expect("DBSvr 侧必须能解存档体");
        let d = parsed.character_data.unwrap().data.unwrap();
        assert_eq!(
            d.abil.as_ref().expect("解码后必须有 Abil").exp,
            1500,
            "存档体逐字段往返后 exp 仍是写回值"
        );
    }

    /// **A-26/T-207 I-1（@Login 漏斗的持久化）**：QManage `[@Login]` 的 `CHANGEEXP + 1000`
    /// 必须 ① 改 `NpcPlayer.abil_exp`（帧与 `$EXP` 都读它）；② 由
    /// [`write_back_login_player_abil_exp`] 落进**角色记录** `saves.record.data.abil.exp`
    /// ——常态下会话已随进世界建好（`ground_sessions.insert` 在 @Login 之前），记录与会话两字段
    /// 同时落账；只有未建会话的分支（`data`/`ability_inputs` 缺失）才以记录为唯一载体
    /// （oracle 里 `@Login` 跑在活的 `PlayObject` 上，增量随后随存档落库）。
    ///
    /// 牙：删掉该函数的记录写回 ⇒ 记录仍是 seed 500 ⇒ 红。**帧侧断言看不出**——帧读的是
    /// `NpcPlayer`，这正是旧版「patch/status 声明写回、实际只 seed」漏掉的那半。
    #[test]
    fn login_changexp_persists_into_character_record() {
        let root = std::env::temp_dir().join(format!("gs-t207-login-{}", std::process::id()));
        let dir = root.join("Envir").join("MapQuest_def");
        std::fs::create_dir_all(&dir).unwrap();
        let script = concat!(
            "[@Login]
",
            "#ACT
",
            "CHANGEEXP + 1000
"
        );
        std::fs::write(dir.join("QManage.txt"), encoding_rs::GBK.encode(script).0).unwrap();
        let parsers = mir2_script::ScriptParsers::new();
        let mut rename = |_min: i32, _max: i32| 1;
        let outcome = parsers
            .load_script_file(
                &mir2_script::LocalFs,
                &root.join("Envir"),
                "MapQuest_def",
                "QManage",
                false,
                &mut rename,
            )
            .expect("解析不得 panic")
            .expect("脚本必须存在");
        std::fs::remove_dir_all(&root).ok();
        assert!(
            outcome.errors.is_empty(),
            "夹具脚本不得有解析错误：{:?}",
            outcome.errors
        );
        let host = game_svr::npc::NpcHost {
            envir_root: std::path::PathBuf::new(),
            defs: vec![std::rc::Rc::new(game_svr::npc::NpcDef {
                chr_name: "QManage".into(),
                file_path: "MapQuest_def".into(),
                script_name: Some("QManage".into()),
                is_hide: true,
                is_quest: false,
                loaded: true,
                actor_id: 0,
                scripts: outcome.scripts,
            })],
            failures: Vec::new(),
            goto_count_limit: 40,
        };
        let mut rng = |_v: i32| 0;
        let mut player = game_svr::npc::NpcPlayer::empty(&mut rng);
        player.actor_id = 7;
        player.chr_name = "hero".into();
        // seed：`sim_loop` 登录块用角色记录的 `Ability.Exp` 灌 `NpcPlayer.abil_exp`。
        player.abil_exp = 500;
        let _ = host.run_login(&mut player).expect("QManage 必须可加载");
        assert_eq!(
            player.abil_exp, 1500,
            "CHANGEEXP + 1000 必须改 NpcPlayer（帧与 $EXP 都读它）"
        );

        // 帧侧：SM_WINEXP.Recog = 加完后的总量（伴随断言；它读 NpcPlayer，抓不到持久化缺失）。
        let (tx, mut rx) = mpsc::unbounded_channel::<SimToGate>();
        let ground_sessions: HashMap<String, SessionGround> = HashMap::new();
        let _ = emit_login_script_frames(
            &tx,
            901,
            7,
            "hero",
            &ground_sessions,
            (player.gold, player.game_gold, player.game_point),
            player.abil_exp,
            &player.frames,
        );
        let mut win = None;
        while let Ok(ev) = rx.try_recv() {
            if let SimToGate::SendFrame { body, .. } = ev {
                if hdr(body.as_slice()).0 == mir2_protocol::messages::SM_WINEXP {
                    win = Some(body);
                }
            }
        }
        let win = win.expect("CHANGEEXP ⇒ 必须下发一条 SM_WINEXP(44)");
        assert_eq!(
            hdr(win.as_slice()).3,
            1500,
            "SM_WINEXP.Recog = 加完后的 Abil.Exp"
        );

        // 有会话（重登/断线重入）：记录 + 两个会话字段都必须落 1500。
        let mut saved = SavedHuman {
            account: "ua".to_string(),
            record: record::PlayerRecord::default(),
            enter_map: "0".to_string(),
            derived: None,
        };
        saved.record.data.abil = Some(record::Ability {
            exp: 500,
            ..Default::default()
        });
        let mut sg = test_session_ground(7);
        sg.state.wabil.exp = 500;
        sg.equip.abil.exp = 500;
        write_back_login_player_abil_exp(Some(&mut saved), Some(&mut sg), player.abil_exp);
        assert_eq!(
            saved
                .record
                .data
                .abil
                .as_ref()
                .expect("记录必须有 Abil")
                .exp,
            1500,
            "@Login 的增量必须落进角色记录（会话存在时两处同源；未建会话时记录是唯一载体）"
        );
        assert_eq!(sg.state.wabil.exp, 1500, "已有会话时 wabil.exp 同源写回");
        assert_eq!(
            sg.equip.abil.exp, 1500,
            "已有会话时 equip.abil.exp 同源写回"
        );

        // 未建会话形态（`data`/`ability_inputs` 缺失等分支：`sim_loop` 的
        // `ground_sessions.get_mut` 得 None）⇒ 角色记录是唯一持久载体。
        let mut saved = SavedHuman {
            account: "ua".to_string(),
            record: record::PlayerRecord::default(),
            enter_map: "0".to_string(),
            derived: None,
        };
        saved.record.data.abil = Some(record::Ability {
            exp: 500,
            ..Default::default()
        });
        write_back_login_player_abil_exp(Some(&mut saved), None, player.abil_exp);
        assert_eq!(
            saved
                .record
                .data
                .abil
                .as_ref()
                .expect("记录必须有 Abil")
                .exp,
            1500,
            "无会话（进世界之前）也必须持久化"
        );
    }

    /// `SETMPAMODE`（`ExecutionCode.SetMapMode = 216`；`sParam1..4` = 地图/分支/参数1/参数2）。
    fn setmapamode_act(map: &str, mode: &str, p1: &str, p2: &str) -> mir2_script::QuestActionInfo {
        mir2_script::QuestActionInfo {
            n_cmd_code: 216,
            s_param1: map.to_string(),
            s_param2: mode.to_string(),
            s_param3: p1.to_string(),
            s_param4: p2.to_string(),
            ..Default::default()
        }
    }

    /// `SENDMSG`（`ExecutionCode.SendMsg = 31`，`ActionOfLineMsg`）：`nParam1` = 分支号、
    /// `sParam2` = 文本（`ScriptParsers.cs:554`）。
    fn sendmsg_act(branch: i32, msg: &str) -> mir2_script::QuestActionInfo {
        mir2_script::QuestActionInfo {
            n_cmd_code: 31,
            n_param1: branch,
            s_param2: msg.to_string(),
            ..Default::default()
        }
    }

    /// **A-21/T-85（`SETMPAMODE DECHP`）生产入口**：`CM_MERCHANTDLGSELECT` → `run_merchant_goto`
    /// → `ActionOfSetMapMode`（code 216）→ `NpcPlayer::set_map_mode` 记录 → 宿主
    /// `flush_map_mode_writes` 落 `Envir.Flag` → P25 `drain_player_map_hp` 消费；同一条脚本里的
    /// `SENDMSG 5` 顺带钉住 `NpcPlayer::sys_msg` 的 `SM_SYSMESSAGE` **逐字节**。
    ///
    /// oracle 锚：
    /// - `ExecutionProcessingSys.cs:4429-4434`：`FindMap(sParam1) == null || sMapMode` 空 ⇒
    ///   `ScriptActionError`、**不写任何 Flag**；
    /// - `:4585-4596`：`DECHP` 在 `sParam3`/`sParam4` **都非空**时置
    ///   `boDECHP=true/nDECHPTIME=StrToInt(sParam3)/nDECHPPOINT=StrToInt(sParam4)`，否则只
    ///   `boDECHP=false`；
    /// - `PlayObject.Message.cs:569-578`：`boDECHP` 且 `now - DecHpTick > nDECHPTIME*1000`
    ///   ⇒ `HP -= nDECHPPOINT`（HP 不足则 0）+ `HealthSpellChanged()`；
    /// - `BaseObject.cs:1678` + `PlayObject.Message.cs:1715-1718`：`SysMsg(_, Red, Say)` ⇒
    ///   `SM_SYSMESSAGE(100)`、`Recog` = 玩家 `ActorId`、`Param = MakeWord(RedMsgFColor,
    ///   RedMsgBColor)`、`Series = 1`、尾 = `EncodeString`。
    ///
    /// 牙（删任一处 ⇒ 本用例红）：
    /// ① 删 `actions.rs` 的 `"ActionOfSetMapMode"` 支 ⇒ 无写队列 ⇒ `applied == 0`；
    /// ② 删 `map_mode::apply_set_map_mode` 的 `DECHP` 支 ⇒ `boDECHP` 仍 false（HP 不减）；
    /// ③ 删 `NpcPlayer::sys_msg` 覆写 ⇒ 帧列表为空；
    /// ④ 删 `pickwire::script_frame` 的 `RM_SYSMESSAGE` 支 ⇒ 帧被丢（T-142 ④ 口径）；
    /// ⑤ 删 `run_merchant_goto` 的 `pending_map_modes.extend` ⇒ 队列不达宿主。
    #[test]
    fn a21_setmpamode_dechp_lands_flag_frame_and_p25_consumes() {
        let mut rig = T142Rig::new(vec![t142_record(
            "@main",
            "",
            vec![
                setmapamode_act("A", "DECHP", "1", "10"),
                sendmsg_act(5, "中毒了"),
            ],
        )]);
        // `SystemShare.MapMgr` 的已装载图名表（`FindMap("A") != null` 门）+ 色词（缺省 oracle）。
        rig.npc_vars.map_names = vec!["A".to_string()];
        rig.npc_vars.sys_msg = game_svr::npc::SysMsgCfg::default();
        // 玩家 HP/MaxHP = 100/100，`DecHpTick` ctor = 0（进图后首次调用立即触发）。
        let hero = rig.sessions["hero"].actor_id;
        {
            let e = rig.world.entities.get_mut(hero).unwrap();
            e.vitals.hp = 100;
            e.vitals.max_hp = 100;
            let sg = rig.sessions.get_mut("hero").unwrap();
            sg.state.wabil.hp = 100;
            sg.state.wabil.max_hp = 100;
            sg.dec_hp_tick = 0;
        }

        rig.dlg_select("@main");

        // ① 帧：仅 `SENDMSG 5` 的一条 `SM_SYSMESSAGE`（`SETMPAMODE` 本身零帧）。
        let frames = rig.drain();
        let want = crate::smframe::sm_sysmessage(
            hero,
            0xFF,
            0x38,
            &mir2_script::cp936::encode_gb2312_dotnet("中毒了"),
        );
        assert_eq!(
            frames,
            vec![want],
            "SENDMSG 5 的红字必须逐字节 = SM_SYSMESSAGE(Recog=ActorId, Param=0x38FF, Series=1)"
        );

        // ② 落库：`flush_map_mode_writes` 把脚本队列写进注册表（= oracle 的 Envir.Flag）。
        let (mut registry, _dir) = pl3_registry("");
        let applied = flush_map_mode_writes(&mut rig.shop_sessions, Some(&mut registry));
        assert_eq!(applied, 1, "一条 SETMPAMODE 写必须落库");
        let flag = registry.flag_of(0).expect("图 A = id 0");
        assert!(
            flag.bo_dechp,
            "DECHP 两参数都非空 ⇒ boDECHP = true（:4587）"
        );
        assert_eq!(
            flag.n_dechptime, 1,
            "nDECHPTIME = StrToInt(sParam3)（:4588）"
        );
        assert_eq!(
            flag.n_dechppoint, 10,
            "nDECHPPOINT = StrToInt(sParam4)（:4589）"
        );

        // ③ 消费：P25 在 `now - DecHpTick > nDECHPTIME*1000` 时扣血并出 53。
        let mut run_frames = game_svr::run_frames::RunFrames::new();
        drain_player_map_hp(
            &mut rig.world,
            &mut rig.sessions,
            &rig.online,
            Some(&registry),
            1001,
            &mut run_frames,
        );
        assert_eq!(
            rig.world.entities.get(hero).unwrap().hp,
            90,
            "HP -= nDECHPPOINT（:572-574）"
        );
        assert_eq!(rig.sessions["hero"].state.wabil.hp, 90, "53 投影同步");
    }

    /// **`openmir2-setmapmode-map-refresh`（证伪/修复面）**：脚本动作 `SETMPAMODE FIGHT`
    /// 落库后，`world.maps` 必须与注册表 `Envir.Flag` 同步。
    ///
    /// oracle 只有**一份** `Envir.Flag`：`ExecutionProcessingSys.cs:4455-4462` 当场写
    /// `envir.Flag.FightZone`，所有读者立刻看到新值。本仓世界侧读者
    /// （`SetPkFlag` 的战区门、`DieDropItems`、`NEEDHOLE` 落地门、`EXPRATE`）读
    /// `world.maps`/`map_exp_rate` 镜像 ⇒ 必须回填。
    ///
    /// 判据全部直读状态（不靠日志/帧推断）：
    /// - 注册表 `flag_of(0).fight_zone`；
    /// - `world.maps[0].is_fight_zone()`；
    /// - `World::set_pk_flag` 的战区门（不置位、不产 RefNameColor 观察值）。
    #[test]
    fn setmpamode_fight_refreshes_world_map_flags_and_world_consumers() {
        let mut rig = T142Rig::new(vec![t142_record(
            "@main",
            "",
            vec![
                setmapamode_act("A", "FIGHT", "1", ""),
                // 另外三项世界镜像：只同步一项的变异必须被这条用例抓住。
                setmapamode_act("A", "NEEDHOLE", "1", ""),
                setmapamode_act("A", "NODROPITEM", "1", ""),
                setmapamode_act("A", "EXPRATE", "2", ""),
            ],
        )]);
        rig.npc_vars.map_names = vec!["A".to_string()];
        rig.npc_vars.sys_msg = game_svr::npc::SysMsgCfg::default();
        rig.dlg_select("@main");
        let (mut registry, _dir) = pl3_registry("");
        assert!(
            !registry.flag_of(0).unwrap().fight_zone,
            "前置：注册表未设 FIGHT"
        );
        assert!(!rig.world.maps[0].is_fight_zone(), "前置：world 未设 FIGHT");
        let applied = flush_map_mode_writes_into_world(
            &mut rig.shop_sessions,
            Some(&mut registry),
            &mut rig.world,
        );
        assert_eq!(applied, 4, "四条 SETMPAMODE 写必须落库");
        // **同 tick 两侧相等**（oracle 语义：脚本动作当场写同一份 `Envir.Flag`）——
        // 宿主侧读者 = 注册表、世界侧读者 = `world.maps`/`map_exp_rate` 镜像；
        // 任何一项只同步一半或少同步一项，这里都不等。
        // 先钉死宿主侧（注册表）四项的明确期望值。
        let reg = registry.flag_of(0).unwrap();
        assert!(
            reg.fight_zone && reg.bo_needhole && reg.no_drop_item && reg.bo_exprate,
            "注册表四项应均为新值：fight={} need_hole={} no_drop={} expr={}",
            reg.fight_zone,
            reg.bo_needhole,
            reg.no_drop_item,
            reg.bo_exprate
        );
        assert_eq!(reg.exp_rate, 2, "注册表 ExpRate = StrToInt(\"2\")");
        // 再钉死世界镜像的**明确期望值**：牙 C（只同步 FIGHT）时这一条把
        // need_hole / no_drop_item / exp_rate 三项的期望与实际一次打出。
        let w = &rig.world.maps[0];
        assert_eq!(
            (
                w.is_fight_zone(),
                w.need_hole(),
                w.no_drop_item(),
                rig.world.map_exp_rate[0]
            ),
            (true, true, true, Some(2)),
            "世界镜像的明确期望值（need_hole / no_drop_item / exp_rate 任一未同步即红）"
        );
        // 最终口径：同一 tick、未过下一 tick，宿主侧与世界侧**逐项相等**
        //（比"最终一致"严，正是 oracle 单对象语义）。
        assert_eq!(
            (
                w.is_fight_zone(),
                w.need_hole(),
                w.no_drop_item(),
                rig.world.map_exp_rate[0]
            ),
            (
                reg.fight_zone || reg.fight3_zone,
                reg.bo_needhole,
                reg.no_drop_item,
                reg.bo_exprate.then_some(reg.exp_rate)
            ),
            "同一 tick：宿主侧（注册表）与世界侧（world.maps/map_exp_rate）读取必须逐项相等"
        );
        // 世界侧消费者：战区门挡住 SetPkFlag（不置位、不产 RefNameColor 观察值）。
        let hero = rig.sessions["hero"].actor_id;
        let spy = rig.world.add_entity({
            let mut e = mir2_world_bevy::EntitySpawn::new(2, "spy".to_string(), 11, 10);
            e.race = mir2_world_bevy::ACTOR_RACE_PLAY;
            e
        });
        assert!(
            rig.world.set_pk_flag(hero, spy).is_none(),
            "FightZone 生效 ⇒ SetPkFlag 直接返回（PlayObject.cs:4331 的门）"
        );
        assert!(
            !rig.world.entities.get(spy).unwrap().pvp_flag,
            "攻击方不得被置位"
        );
    }

    /// `take`/`give` 的 **`nParam2`** 口径（`ScriptParsers.cs:554`：动作的件数在 **sParam2** ⇒
    /// `nParam2`；`sParam1` 是物品名，`nParam1` 留 0）。`take 筹码包 1` 的真实解析结果。
    fn t142_act_n2(code: i32, p1: &str, n2: i32) -> mir2_script::QuestActionInfo {
        mir2_script::QuestActionInfo {
            n_cmd_code: code,
            s_param1: p1.to_string(),
            n_param2: n2,
            ..Default::default()
        }
    }

    /// **线程卡 `openmir2-script-take-persist`（tier R）**：`take` 的副作用必须落到**会话背包**
    /// `SessionGround.state.item_list`（存档 `build_save_record` → `bag_items_for_save` 读它），
    /// 否则断线存档后 DB 里物品仍在（r9 真机现象）。
    ///
    /// oracle：`GotoLableTakeItem`（`ScriptEngine.cs:667`）**从尾往前**扫 `ItemList` 并
    /// `RemoveAt(i)`——同名多件时摘的是**最后几件**；本用例用
    /// `[筹码包(4201), 木剑(4202), 筹码包(4203)]` 钉住该顺序（摘 1 件必须摘 4203）。
    ///
    /// 牙（先备份 sha256，改完还原并核对）：
    /// ① 删 `run_merchant_goto` 里的 `write_back_player_bag` 调用 ⇒ 本用例红（背包仍 3 件）；
    /// ② 把回写摘除改成「从头往前」⇒ 4201 被摘 ⇒ 顺序断言红。
    #[test]
    fn take_removes_from_session_bag_through_production_path() {
        use game_svr::bag::BagItem;
        let mut rig = T142Rig::new(vec![
            t142_record(
                "@main",
                r"领筹码\ <领取/@ya52>",
                vec![t142_act(191, "+", 0, "")],
            ),
            t142_record("@ya52", "", vec![t142_act_n2(2, "筹码包", 1)]),
        ]);
        rig.catalog.insert(
            1,
            mir2_data::StdItem {
                name: "筹码包".to_string(),
                dura_max: 5000,
                ..mir2_data::StdItem::default()
            },
        );
        rig.catalog.insert(
            2,
            mir2_data::StdItem {
                name: "木剑".to_string(),
                dura_max: 10,
                ..mir2_data::StdItem::default()
            },
        );
        {
            let sg = rig.sessions.get_mut("hero").unwrap();
            sg.state.item_list = vec![
                BagItem {
                    make_index: 4201,
                    index: 1,
                    dura: 5000,
                    dura_max: 5000,
                    desc: [0; 14],
                },
                BagItem {
                    make_index: 4202,
                    index: 2,
                    dura: 10,
                    dura_max: 10,
                    desc: [0; 14],
                },
                BagItem {
                    make_index: 4203,
                    index: 1,
                    dura: 5000,
                    dura_max: 5000,
                    desc: [0; 14],
                },
            ];
        }
        // `@ya52` 的进入资格来自 `@main` 说词里的链接（`LableIsCanJmp` 第二支）。
        rig.dlg_select("@main");
        assert_eq!(
            rig.sessions["hero"].state.item_list.len(),
            3,
            "只跑 @main（无 take）⇒ 背包必须原样"
        );
        rig.dlg_select("@ya52");
        let bag = &rig.sessions["hero"].state.item_list;
        let remaining: Vec<i32> = bag.iter().map(|it| it.make_index).collect();
        assert_eq!(
            remaining,
            vec![4201, 4202],
            "`take 筹码包 1` 必须回写会话背包，且照 oracle 从**尾**摘（摘 4203，留 4201）"
        );
    }

    /// 同一张卡的金币半边：`take 金币 N` 走 `DecGold`（`ScriptEngine.cs:657-660`），改的是同一个
    /// `PlayObject.Gold` ⇒ 必须回写 `SessionGround.state.gold`（`build_save_record` 读它落库）。
    ///
    /// 牙：删 `write_back_player_gold_deal` 里的 `sg.state.gold = p.gold;` ⇒ 本用例红（仍 100）。
    #[test]
    fn take_gold_persists_to_session_gold_through_production_path() {
        let mut rig = T142Rig::new(vec![
            t142_record(
                "@main",
                r"交钱\ <交钱/@ya53>",
                vec![t142_act(191, "+", 0, "")],
            ),
            t142_record("@ya53", "", vec![t142_act_n2(2, "金币", 5)]),
        ]);
        rig.sessions.get_mut("hero").unwrap().state.gold = 100;
        rig.dlg_select("@main");
        assert_eq!(
            rig.sessions["hero"].state.gold, 100,
            "只跑 @main（无 take 金币）⇒ 金币必须原样"
        );
        rig.dlg_select("@ya53");
        assert_eq!(
            rig.sessions["hero"].state.gold, 95,
            "`take 金币 5` 必须回写会话金币（否则断线存档金币不减）"
        );
    }

    /// `give` 半边（同一次对账的「多出的件」）：照 `GotoLableGiveItem`（`ScriptEngine.cs:710-718`）
    /// ⇒ `CopyToUserItemFromName`：`Index` 按名查表、`Dura = DuraMax = tpl.DuraMax`、
    /// `MakeIndex = M2Share.GetItemNumber()`（生产 = sim 循环的 `item_number` 计数器）。
    ///
    /// 牙：删 `write_back_player_bag` 的「多出」分支 ⇒ 本用例红（背包 0 件）。
    /// **M1c-3b 牙（投递负例）`script_process_routes_to_zone0_mailbox`**：区 k 的 `CM_CLICKNPC`
    /// 与 `CM_MERCHANTDLGSELECT` 分类 **`Process`** ⇒ `a6_dispatch_local` 投
    /// `ControlRequest::ScriptProcess`（**完整 12B 字段**逐个搬入），执行体**未被调用**、
    /// `control_pending==1`、`first_tick` 置位。
    ///
    /// 变异：分类改回 `Unsupported`/`Local` ⇒ 分类断言红；投成 `GmSay` ⇒ 变体断言红。
    #[test]
    fn script_process_routes_to_zone0_mailbox() {
        for (ident, recog, param, tag, series, tail) in [
            (
                mir2_protocol::messages::CM_CLICKNPC,
                900_001,
                0u16,
                0u16,
                0u16,
                Some("x"),
            ),
            (
                game_svr::shop::CM_MERCHANTDLGSELECT,
                900_002,
                7u16,
                8u16,
                9u16,
                Some("@main"),
            ),
        ] {
            assert_eq!(
                zone_cmd_class(ident, tail),
                ZoneCmdClass::Process,
                "ident={ident} 必须整 ident Process（M1c-3b）"
            );
            let mut sessions = std::collections::HashMap::new();
            sessions.insert("hero".to_string(), test_session_ground(1));
            let inbox = std::sync::Mutex::new(std::collections::VecDeque::new());
            let mut pending = std::collections::BTreeMap::new();
            let mut executed = false;
            let mut exec =
                |_ev: &GateEvent, _s: &mut std::collections::HashMap<String, SessionGround>| {
                    executed = true;
                };
            let mut c = CommandMessage {
                recog: 0,
                ident,
                param: 0,
                tag: 0,
                series: 0,
            };
            c.recog = recog;
            c.param = param;
            c.tag = tag;
            c.series = series;
            let disp = a6_dispatch_local_test(
                SeqEvent {
                    seq: 1,
                    ev: GateEvent::Command {
                        line: 0,
                        index: 0,
                        chr_name: "hero".to_string(),
                        socket: 901,
                        cmd: c,
                        tail: tail.map(str::to_string),
                    },
                },
                ZoneCmdClass::Process,
                Some(&inbox),
                &mut sessions,
                &mut pending,
                zone::ZoneId::new(1),
                9,
                A6BatchBudget {
                    remaining_events: 10,
                    wall_ok: true,
                },
                &mut exec,
            );
            assert_eq!(
                disp,
                LocalDisposition::Drained,
                "ident={ident} 入邮箱即已处置"
            );
            assert!(!executed, "Process 支不得本地执行（ident={ident}）");
            {
                let q = inbox.lock().expect("inbox");
                assert_eq!(q.len(), 1, "ident={ident} 必须投 1 条");
                match &q[0] {
                    ControlRequest::ScriptProcess {
                        ident: got_ident,
                        recog: got_recog,
                        param: got_param,
                        tag: got_tag,
                        series: got_series,
                        tail: got_tail,
                        ..
                    } => {
                        assert_eq!(
                            (*got_ident, *got_recog, *got_param, *got_tag, *got_series),
                            (ident, recog, param, tag, series),
                            "12B 字段必须逐个搬入（ident={ident}）"
                        );
                        assert_eq!(got_tail.as_deref(), tail, "tail 必须原样搬入");
                    }
                    other => panic!("必须投 ScriptProcess 变体，实得 {other:?}"),
                }
            }
            assert_eq!(
                sessions["hero"].a6.control_pending, 1,
                "入邮箱必须置位 control_pending"
            );
            assert_eq!(sessions["hero"].a6.control_first_tick, Some(9));
        }
    }

    /// **M1c-3b 牙（行为正例）`script_process_click_executes_give_in_drain_path`**：drain 执行体
    /// `run_script_process_request` 对 `CM_CLICKNPC` **直调** `handle_click_npc_cmd`（同函数同实参）
    /// ⇒ 区 k 玩家点击的 `@main` 里 `GIVE 筹码包 2` 落到**会话背包**（+2 件、`MakeIndex` 由共享
    /// 计数器逐件分配）。
    ///
    /// **口径（whitelist T-157）**：脚本 `GIVE` 的 `SendAddItem` 线上帧在本宿主**未建模**
    /// （T-157 登记）⇒ 本牙断言**会话/落库面**（`SessionGround.item_list` + 说词帧），
    /// **不**断言 `SM_ADDITEM` 帧；不得把"没有 200 帧"当失败。
    /// 变异：seam 的 click 分支不调用 handler ⇒ 背包 0 件 ⇒ 红。
    #[test]
    fn script_process_click_executes_give_in_drain_path() {
        let mut rig = T142Rig::new(vec![t142_record(
            "@main",
            "点我给筹码 <给/@ya54>",
            vec![t142_act_n2(3, "筹码包", 2)],
        )]);
        rig.catalog.insert(
            1,
            mir2_data::StdItem {
                name: "筹码包".to_string(),
                dura_max: 5000,
                ..mir2_data::StdItem::default()
            },
        );
        let trade: std::collections::HashMap<String, game_svr::trade::DealState> =
            std::collections::HashMap::new();
        run_script_process_request(
            mir2_protocol::messages::CM_CLICKNPC,
            rig.merchant_id,
            0,
            0,
            None,
            "hero",
            901,
            &rig.online,
            &mut rig.sessions,
            &mut rig.shop_sessions,
            &mut rig.sell_off_sessions,
            &trade,
            &mut rig.world,
            &rig.gates,
            &rig.catalog,
            &rig.shop_cfg,
            &rig.colors,
            None,
            &rig.item_number,
            ScriptProcessEnv {
                merchant_book: &rig.book,
                npc_vars: &rig.npc_vars,
                sell_off_book: &mut rig.sell_off_book,
                gm: None,
                script_world: None,
            },
        );
        let bag = &rig.sessions["hero"].state.item_list;
        assert_eq!(
            bag.len(),
            2,
            "click 的 `@main` 里 `GIVE 筹码包 2` 必须落到会话背包"
        );
        assert!(
            bag.iter().all(|it| it.index == 1 && it.make_index > 0),
            "件模板与 MakeIndex 必须正确：{bag:?}"
        );
        let mk: Vec<i32> = bag.iter().map(|it| it.make_index).collect();
        assert_eq!(mk, vec![1, 2], "MakeIndex 从夹具计数器 0 起逐件 +1");
        let mut says = 0;
        while let Ok(SimToGate::SendFrame { body, .. }) = rig.rx.try_recv() {
            if CommandMessage::from_bytes(&body)
                .is_some_and(|m| m.ident == mir2_protocol::messages::SM_MERCHANTSAY)
            {
                says += 1;
            }
        }
        assert!(says > 0, "`@main` 的说词必须下发（SM_MERCHANTSAY）");
    }

    /// **M1c-3b 牙 `script_process_dlgselect_route_gate_kept`**：drain 执行体的 1011 route 门
    /// （**只此一处**）——`NotMerchant`（recog 是玩家 actor）⇒ **零帧、零副作用**；
    /// `Shop`（recog 是商人 actor + 脚本 label）⇒ 脚本执行（`@main` 的 `GIVE` 落包）。
    /// `GuildOfficial` 按 **T-140** 构造不可达（seam 静态面钉 `DlgSelectRoute::GuildOfficial` 显式零帧）。
    ///
    /// 变异：删 route 门（直接进 `handle_shop_cmd`）⇒ 静态面红（`dlgselect_route_for(` 消失）。
    #[test]
    fn script_process_dlgselect_route_gate_kept() {
        let mut rig = T142Rig::new(vec![t142_record(
            "@main",
            "欢迎 <给/@ya54>",
            vec![t142_act_n2(3, "筹码包", 2)],
        )]);
        rig.catalog.insert(
            1,
            mir2_data::StdItem {
                name: "筹码包".to_string(),
                dura_max: 5000,
                ..mir2_data::StdItem::default()
            },
        );
        rig.sessions
            .get_mut("hero")
            .expect("hero 会话")
            .state
            .item_list
            .clear();
        let trade: std::collections::HashMap<String, game_svr::trade::DealState> =
            std::collections::HashMap::new();
        let hero_actor = {
            let e = rig.online.find_by_chr("hero").expect("hero 在线");
            e.actor_id
        };
        let merchant_id = rig.merchant_id;
        // ① NotMerchant（recog = 玩家自己）⇒ route 非 Shop ⇒ 零帧零副作用。
        run_script_process_request(
            game_svr::shop::CM_MERCHANTDLGSELECT,
            hero_actor,
            0,
            0,
            Some("@main"),
            "hero",
            901,
            &rig.online,
            &mut rig.sessions,
            &mut rig.shop_sessions,
            &mut rig.sell_off_sessions,
            &trade,
            &mut rig.world,
            &rig.gates,
            &rig.catalog,
            &rig.shop_cfg,
            &rig.colors,
            None,
            &rig.item_number,
            ScriptProcessEnv {
                merchant_book: &rig.book,
                npc_vars: &rig.npc_vars,
                sell_off_book: &mut rig.sell_off_book,
                gm: None,
                script_world: None,
            },
        );
        assert!(
            rig.sessions["hero"].state.item_list.is_empty(),
            "NotMerchant ⇒ 不得执行脚本（背包不变）"
        );
        assert!(rig.rx.try_recv().is_err(), "NotMerchant ⇒ 零帧");
        // ② Shop（recog = 商人）⇒ 脚本执行。
        run_script_process_request(
            game_svr::shop::CM_MERCHANTDLGSELECT,
            merchant_id,
            0,
            0,
            Some("@main"),
            "hero",
            901,
            &rig.online,
            &mut rig.sessions,
            &mut rig.shop_sessions,
            &mut rig.sell_off_sessions,
            &trade,
            &mut rig.world,
            &rig.gates,
            &rig.catalog,
            &rig.shop_cfg,
            &rig.colors,
            None,
            &rig.item_number,
            ScriptProcessEnv {
                merchant_book: &rig.book,
                npc_vars: &rig.npc_vars,
                sell_off_book: &mut rig.sell_off_book,
                gm: None,
                script_world: None,
            },
        );
        assert_eq!(
            rig.sessions["hero"].state.item_list.len(),
            2,
            "Shop ⇒ 脚本执行（`@main` 的 GIVE 落包）"
        );
        // ③ 静态面：route 门在 seam 内、且先于 `handle_shop_cmd`。
        let src = include_str!("lib.rs");
        let start = src
            .find("fn run_script_process_request(")
            .expect("seam 定义");
        let end = src[start..]
            .find("\n}\n")
            .map_or(src.len(), |k| start + k + 3);
        let body = &src[start..end];
        let gate = body
            .find("dlgselect_route_for(")
            .expect("route 门必须在 seam 内");
        let shop = body
            .find("handle_shop_cmd(")
            .expect("Shop 支必须执行 handle_shop_cmd");
        assert!(gate < shop, "route 门必须先于 handle_shop_cmd");
        assert!(
            body.contains("DlgSelectRoute::GuildOfficial"),
            "GuildOfficial 支必须显式零帧（T-140）"
        );
    }

    /// **M1c-3b 静态牙 `click_drain_calls_same_handler_not_p0`**：seam 对 `CM_CLICKNPC` 必须
    /// 出现 `handle_click_npc_cmd(`，且**不得**出现 `dispatch_inbound_p0(`——p0 批要 `&mut guilds`
    /// （`GuildDisconnect`），与 `ScriptGmEnv` 要借的 `&guilds` 冲突（区 0 tick click 臂因此单独接管）。
    #[test]
    fn click_drain_calls_same_handler_not_p0() {
        let src = include_str!("lib.rs");
        let start = src
            .find("fn run_script_process_request(")
            .expect("seam 定义");
        let end = src[start..]
            .find("\n}\n")
            .map_or(src.len(), |k| start + k + 3);
        let body = &src[start..end];
        assert!(
            body.contains("handle_click_npc_cmd("),
            "seam 必须直调 handle_click_npc_cmd（与区 0 click 臂同函数）"
        );
        assert!(
            !body.contains("dispatch_inbound_p0("),
            "seam 不得走 dispatch_inbound_p0（`&mut guilds` 冲突）"
        );
    }

