    /// **卡 `openmir2-gm-impl-kick`**：GM 命令登记的踢人目标在宿主 tick 内并入 `kick_pending`，
    /// 并沿既有 `drain_kicks` 落地（先 `SM_OUTOFCONNECTION(528)`、再 `KickUser` + 清槽）。
    ///
    /// 牙：把 `collect_gm_kick_pending` 的 `pending_kick.take()` 换成只读 ⇒ 本用例红（目标不收口）。
    #[test]
    fn gm_pending_kick_is_collected_and_landed_with_sm_outofconnection() {
        use mir2_protocol::frame::CommandMessage;
        use std::collections::HashMap;
        let mut world = mir2_world_bevy::World::with_maps(vec![(64, 64)]);
        let victim = world.add_entity(mir2_world_bevy::EntitySpawn::new(0, "victim", 5, 5));
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut sg = test_session_ground(victim);
        sg.gm.pending_kick = Some("victim".to_string());
        sessions.insert("victim".to_string(), sg);
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("a", "victim", 1, 0, 901, victim));
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut kick_pending: Vec<String> = Vec::new();
        assert_eq!(
            collect_gm_kick_pending(&mut sessions, &mut kick_pending),
            1,
            "会话缓冲里的目标必须并入本 tick 的 kick_pending"
        );
        assert_eq!(kick_pending, vec!["victim".to_string()]);
        assert!(
            sessions["victim"].gm.pending_kick.is_none(),
            "缓冲必须被取走（一次性）"
        );
        // 幂等：再收一次不得重复入列。
        assert_eq!(collect_gm_kick_pending(&mut sessions, &mut kick_pending), 0);
        drain_kicks(
            &mut world,
            &gates,
            &mut online,
            &mut kick_pending,
            &mut None,
            &mut load::FrontEngine::new(),
            &mut HashMap::new(),
            &mut sessions,
            &mut std::collections::HashMap::new(),
            &mut std::collections::HashMap::new(),
            &mut std::collections::HashMap::new(),
            &mut downlink::DisplayTable::new(),
            None,
            &mut mir2_world_bevy::GuildManager::new(),
            None,
            &mir2_data::guild::GuildFileSections::oracle_defaults(),
            &guild_runtime::GuildMsgCfg::from_config(
                &mir2_world_bevy::GuildConfig::default(),
                false,
                "",
            ),
            0,
        );
        assert!(kick_pending.is_empty(), "待踢名单被消费");
        let frames = drain_frames(&mut rx0);
        assert_eq!(frames.len(), 1, "只有一条帧：SM_OUTOFCONNECTION");
        assert_eq!(
            CommandMessage::from_bytes(&frames[0])
                .expect("12B 头")
                .ident,
            mir2_protocol::messages::SM_OUTOFCONNECTION,
            "`BoKickFlag` 支先发 528（`PlayObject.Message.cs:376-377`）"
        );
        assert!(
            online.iter().all(|e| e.chr_name != "victim"),
            "目标已离开在线登记（MakeGhost 的宿主等价物）"
        );
    }

    /// **卡 `openmir2-gm-impl-kick`（复审 important-1）**：命令行目标的大小写与实体规范名不同
    /// （`@VV踢人 ViCtIm` → 实体 `victim`）时，命令体必须登记**实体规范名** ⇒ 宿主
    /// `online_take`（`e.chr_name == chr` 精确匹配）才找得到并落地 528。
    ///
    /// 牙：把 `kick_human` 改回 `Some(name.to_string())`（存输入串）⇒ 本用例红：`collect` 入列
    /// `ViCtIm`，`drain_kicks` 在在线表里找不到 `ViCtIm` ⇒ 只留 WRN、无 528。
    #[test]
    fn gm_pending_kick_canonicalizes_mixed_case_target_and_lands_528() {
        use mir2_protocol::frame::CommandMessage;
        use std::collections::HashMap;
        let mut world = mir2_world_bevy::World::with_maps(vec![(64, 64)]);
        let mut ev = mir2_world_bevy::EntitySpawn::new(0, "victim", 5, 5);
        ev.race = mir2_world_bevy::ACTOR_RACE_PLAY;
        let victim = world.add_entity(ev);
        let mut eg = mir2_world_bevy::EntitySpawn::new(0, "gm", 5, 5);
        eg.race = mir2_world_bevy::ACTOR_RACE_PLAY;
        let gm_actor = world.add_entity(eg);
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut sg = test_session_ground(gm_actor);
        sg.gm.permission = 10; // `[Permission] Kick=10`（脚本 GMEXECUTE 抬到 10 后的会话态）
        let guilds = mir2_world_bevy::GuildManager::new();
        let cfg = gmcmd::GmConfig::default();
        {
            let view = gmcmd::GmWorld::new(&guilds)
                .with_world(&world)
                .with_speaker("gm");
            let r = gmcmd::execute(&mut sg.gm, &cfg, &view, "@VV踢人 ViCtIm");
            assert!(r.msgs.is_empty(), "命中目标 ⇒ 命令无回帧");
        }
        assert_eq!(
            sg.gm.pending_kick.as_deref(),
            Some("victim"),
            "命令体必须存实体规范名（存输入串 `ViCtIm` 会让宿主精确匹配落空）"
        );
        sessions.insert("gm".to_string(), sg);
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("a", "victim", 1, 0, 901, victim));
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut kick_pending: Vec<String> = Vec::new();
        assert_eq!(collect_gm_kick_pending(&mut sessions, &mut kick_pending), 1);
        drain_kicks(
            &mut world,
            &gates,
            &mut online,
            &mut kick_pending,
            &mut None,
            &mut load::FrontEngine::new(),
            &mut HashMap::new(),
            &mut sessions,
            &mut std::collections::HashMap::new(),
            &mut std::collections::HashMap::new(),
            &mut std::collections::HashMap::new(),
            &mut downlink::DisplayTable::new(),
            None,
            &mut mir2_world_bevy::GuildManager::new(),
            None,
            &mir2_data::guild::GuildFileSections::oracle_defaults(),
            &guild_runtime::GuildMsgCfg::from_config(
                &mir2_world_bevy::GuildConfig::default(),
                false,
                "",
            ),
            0,
        );
        let frames = drain_frames(&mut rx0);
        assert_eq!(
            frames.len(),
            1,
            "混合大小写目标也必须落地 528（不是只留 WRN）"
        );
        assert_eq!(
            CommandMessage::from_bytes(&frames[0])
                .expect("12B 头")
                .ident,
            mir2_protocol::messages::SM_OUTOFCONNECTION,
        );
        assert!(
            online.iter().all(|e| e.chr_name != "victim"),
            "目标已离开在线登记"
        );
    }

    fn entry(account: &str, chr: &str, sid: i32, gate: i32, sock: i32, actor: i32) -> OnlineEntry {
        OnlineEntry {
            account: account.to_string(),
            chr_name: chr.to_string(),
            session_id: sid,
            gate_idx: gate,
            socket: sock,
            actor_id: actor,
        }
    }

    /// **`openmir2-channel-chat`**：`handle_say` 的宿主上下文夹具（生产入参收敛后的形状）。
    struct TestChatCtx {
        guilds: mir2_world_bevy::GuildManager,
        guild_msg_cfg: guild_runtime::GuildMsgCfg,
        party_cfg: mir2_world_bevy::PartyConfig,
        strings: crate::strings::StringConf,
        can_shout_level: i32,
        /// `SystemShare.FilterWord` 全局位（部署启动 true；`@DisableFilter` 翻转）。
        filter_word: std::cell::Cell<bool>,
        /// **族 X2**：全局任务目标四元与 `SpiritMutinyTick`（@Mission/@祈祷生效/@停止叛变）。
        mission: std::cell::RefCell<gmcmd::GmMissionState>,
        spirit_mutiny_tick: std::cell::Cell<i64>,
        /// **族 X2**：展示表（`@vv杀死` 面对面支的 pose 解析）。
        displays: downlink::DisplayTable,
        /// **T-277**：物品目录（`@OnHorse` 把背包 `StdIndex` 解析成 `mount_id`）。
        catalog: game_svr::ability::StdItemCatalog,
        /// **A20 重构回归**：`Envir.Flag` 来源（`boQUIZ` 喊话门；`None` ⇒ false，与生产 S1 同）。
        registry: Option<mir2_envir::MapRegistry>,
    }

    impl TestChatCtx {
        fn new() -> Self {
            Self {
                guilds: mir2_world_bevy::GuildManager::new(),
                guild_msg_cfg: guild_runtime::GuildMsgCfg {
                    show_pre_fix_msg: false,
                    prefix: String::new(),
                    f_color: 0,
                    b_color: 0,
                },
                party_cfg: mir2_world_bevy::PartyConfig::default(),
                strings: crate::strings::StringConf::defaults(),
                can_shout_level: 0,
                filter_word: std::cell::Cell::new(true),
                mission: std::cell::RefCell::new(gmcmd::GmMissionState::default()),
                spirit_mutiny_tick: std::cell::Cell::new(0),
                displays: downlink::DisplayTable::new(),
                catalog: game_svr::ability::StdItemCatalog::new(),
                registry: None,
            }
        }

        fn host<'a>(
            &'a self,
            online: &'a OnlineRegistry,
            world: &'a mir2_world_bevy::World,
            gates: &'a std::collections::HashMap<u8, mpsc::UnboundedSender<SimToGate>>,
            colors: &'a MsgColors,
        ) -> ChatHost<'a> {
            ChatHost {
                online,
                world,
                gates,
                guilds: &self.guilds,
                guild_msg_cfg: &self.guild_msg_cfg,
                party_cfg: &self.party_cfg,
                strings: &self.strings,
                colors,
                gm_cfg: gmcmd::GmConfig::default(),
                can_shout_level: self.can_shout_level,
                registry: self.registry.as_ref(),
                filter_word: &self.filter_word,
                mission: &self.mission,
                spirit_mutiny_tick: &self.spirit_mutiny_tick,
                displays: &self.displays,
                catalog: &self.catalog,
            }
        }
    }

    /// **GM 命令第一批（G1）**：`@` 命令面的**生产入口**夹具（`handle_say` ⇒ [`gmcmd`]）。
    ///
    /// 一个说话者（`aaa` / socket 901 / gate 0）+ 一条网关通道；颜色取部署值
    /// （Red 255/56、Green 219/255、Blue 251/252，`M2GameSvr/Server.conf:600-605`）。
    struct GmRig {
        gates: std::collections::HashMap<u8, mpsc::UnboundedSender<SimToGate>>,
        rx: mpsc::UnboundedReceiver<SimToGate>,
        world: mir2_world_bevy::World,
        online: OnlineRegistry,
        sessions: std::collections::HashMap<String, SessionGround>,
        actor: i32,
        /// `@改属性` 的 `SendUpdateItem` 需要物品模板（`GetStdItem`）。
        catalog: game_svr::ability::StdItemCatalog,
        /// `@Level0` 的 `MaxExp = GetLevelExp(level)` 数据源（`Exps.conf`；这里用常量表）。
        need_exps: Vec<i32>,
        /// **族 X2**：展示表（`@vv杀死` 面对面支 pose 解析用；测试默认空）。
        displays: downlink::DisplayTable,
        /// **族 F**：会话任务态运行时真身（`saves.record.data.quest_*`，oracle 不落库的
        /// 内存 `CharacterData`）。`handle_say` 派发前据此建只读快照，命令后由
        /// `apply_pending_gm_target_ops` 把调用者的写落回这里。
        saves: std::collections::HashMap<String, SavedHuman>,
    }

    impl GmRig {
        fn new() -> Self {
            let (tx, rx) = mpsc::unbounded_channel::<SimToGate>();
            let mut gates = std::collections::HashMap::new();
            gates.insert(0, tx);
            let mut world = mir2_world_bevy::World::new(64, 64);
            let mut e = mir2_world_bevy::EntitySpawn::new(0, "aaa".to_string(), 10, 10);
            e.race = mir2_world_bevy::ACTOR_RACE_PLAY;
            let actor = world.add_entity(e);
            let mut online: OnlineRegistry = OnlineRegistry::new();
            online_set(&mut online, entry("a", "aaa", 1, 0, 901, actor));
            let mut sessions = std::collections::HashMap::new();
            sessions.insert("aaa".to_string(), test_session_ground(actor));
            let mut saves: std::collections::HashMap<String, SavedHuman> =
                std::collections::HashMap::new();
            saves.insert(
                "aaa".to_string(),
                SavedHuman {
                    account: "a".into(),
                    record: record::PlayerRecord::default(),
                    enter_map: "0".into(),
                    derived: None,
                },
            );
            Self {
                gates,
                rx,
                world,
                online,
                sessions,
                actor,
                catalog: game_svr::ability::StdItemCatalog::new(),
                // `GetLevelExp` 的索引上界是 255（`Grobal2.MaxLevel = byte.MaxValue`），
                // 这里给 256 项常量表 ⇒ `level=255` 时取 `need_exps[255]`（不触发越界支）。
                need_exps: vec![10i32; 256],
                displays: downlink::DisplayTable::new(),
                saves,
            }
        }

        /// 按 **GM 权限 10** 发一条。oracle 现网 `Permission` 恒 0（设计件 §2），31 条本批命令
        /// 全部不可达；这里显式构造，只为把「命令体命中时」的帧面钉住。
        fn say_gm(&mut self, line: &str) -> Vec<Vec<u8>> {
            self.sessions
                .get_mut("aaa")
                .expect("GmRig 恒有 aaa 会话")
                .gm
                .permission = 10;
            self.say(line)
        }

        /// 走**生产入口** [`handle_say`]（不是直接调 `gmcmd::execute`），收集本 tick 发出的帧。
        fn say(&mut self, line: &str) -> Vec<Vec<u8>> {
            let colors = MsgColors {
                red_f: 255,
                red_b: 56,
                hear_f: 0,
                hear_b: 255,
                whisper_f: 0,
                whisper_b: 0,
                green_f: 219,
                green_b: 255,
                blue_f: 251,
                blue_b: 252,
            };
            let ctx = TestChatCtx {
                // **T-277**：把夹具目录交给 ChatHost（`@OnHorse` 用它解析马牌 Shape）。
                catalog: self.catalog.clone(),
                ..TestChatCtx::new()
            };
            let host = ctx.host(&self.online, &self.world, &self.gates, &colors);
            let (deferred, gm_frames) = handle_say_with_saves(
                &host,
                &mut self.sessions,
                &self.saves,
                "aaa",
                901,
                Some(line),
            );
            // 与生产 `sim_loop` 的 `CM_SAY` 支同一步：命令体装填的权威写在**同一事件内**
            // 落到 `Entity`（卡 `openmir2-gm-admin-mode-entity-seam`）。
            apply_pending_gm_entity(&mut self.sessions, "aaa", &mut self.world);
            // 与生产 `sim_loop` 的 `CM_SAY` 支同一步（卡 `openmir2-gm-target-state-write`）：
            // `@Level0` 的 `HasLevelUp(1)` 语义在同一事件内落地并发 45/52/752。
            apply_pending_level_up(
                &mut self.sessions,
                "aaa",
                &self.catalog,
                &self.need_exps,
                &mut self.world,
                &self.online,
                &self.gates,
            );
            // 卡 `openmir2-gm-impl-smake`（复审 important-2）：`SM_UPDATEITEM(203)` 先发
            // （oracle `SendDefMessage` 立即），GM 的蓝字 `SM_SYSMESSAGE(100)` 后发。
            if let Some(body) = apply_pending_gm_use_item(
                &mut self.sessions,
                "aaa",
                &mut self.world,
                &self.catalog,
                &self.online,
                &self.gates,
            ) {
                if let Some(tx) = self.gates.get(&0) {
                    let _ = tx.send(SimToGate::SendFrame { socket: 901, body });
                }
            }
            // 与生产 `sim_loop` 的 `CM_SAY` 支同一步（卡 `openmir2-gm-family-t-toggle-horse`）：
            // `@OnHorse`/`@OffHorse` 的 `FeatureChanged()` 视距广播 `SM_FEATURECHANGED(41)`。
            apply_pending_gm_feature_changed(
                &mut self.sessions,
                "aaa",
                &self.catalog,
                &self.world,
                &self.online,
                &self.gates,
                chat::send_ref_msg_range(),
            );
            // **T-277**：独立骑乘帧 `SM_MOUNTRIDE(1118)`（与生产 CM_SAY 支同一步）。
            apply_pending_gm_mountride(
                &mut self.sessions,
                "aaa",
                &self.world,
                &self.online,
                &self.gates,
                &mut self.displays,
                chat::send_ref_msg_range(),
            );
            // 族 X2（review F3）：@Reconnection 与 sim_loop 同一步——推入 ReconnectPending
            // ⇒ 唯一排水点 drain_reconnects（先置 BoReconnection=true 再发 SM_RECONNECT）。
            let mut reconnect_pending: Vec<ReconnectPending> = Vec::new();
            if let Some(addr) = self
                .sessions
                .get_mut("aaa")
                .and_then(|sg| sg.gm.pending_reconnect.take())
            {
                reconnect_pending.push(ReconnectPending {
                    gate_idx: 0,
                    socket: 901,
                    chr_name: "aaa".to_string(),
                    msg: addr.into_bytes(),
                });
            }
            drain_reconnects(&mut reconnect_pending, &mut self.sessions, &self.gates);
            // 族 X2 批 B：目标侧副作用收口（与 sim_loop CM_SAY 支同一步；pwd/saves/魔表用空表，
            // displays 空 ⇒ pose 恒 None——面对面支与删技能的线上承载在 lib 层专用用例覆盖）。
            let mut pwd_sessions: std::collections::HashMap<String, game_svr::inbound::PwdSession> =
                std::collections::HashMap::new();
            let empty_magic_table = magics::MagicTable::default();
            let gm_magic_cfg = MagicCfg {
                table: &empty_magic_table,
                fire_ball_skill: "火球术",
                heal_skill: "治愈术",
            };
            apply_pending_gm_target_ops(
                &mut self.sessions,
                &mut pwd_sessions,
                &mut self.saves,
                &mut self.world,
                &self.catalog,
                gm_magic_cfg,
                &self.displays,
                &self.online,
                &self.gates,
                &colors,
                chat::send_ref_msg_range(),
                "aaa",
            );
            if !deferred.is_empty() || !gm_frames.is_empty() {
                let speaker = self
                    .online
                    .iter()
                    .find(|e| e.chr_name == "aaa")
                    .expect("GmRig 恒有 aaa 在线");
                for (f, b, text) in &deferred {
                    send_gm_sysmsg(&self.gates, speaker, *f, *b, text);
                }
                for body in gm_frames {
                    if let Some(tx) = self.gates.get(&0) {
                        let _ = tx.send(SimToGate::SendFrame { socket: 901, body });
                    }
                }
            }
            let mut out = Vec::new();
            while let Ok(msg) = self.rx.try_recv() {
                match msg {
                    SimToGate::SendFrame { socket, body } => {
                        assert_eq!(socket, 901);
                        out.push(body);
                    }
                    other => panic!("GM 命令不应产生非帧消息: {other:?}"),
                }
            }
            out
        }
    }

    /// `SM_SYSMESSAGE(100)` 的 `(Param, 正文)`；同时钉 `Ident`/`Series`/`Recog`。
    fn sysmsg_of(rig: &GmRig, body: &[u8]) -> (u16, String) {
        assert!(body.len() > 12, "12B 头 + 尾");
        assert_eq!(
            i32::from_le_bytes([body[0], body[1], body[2], body[3]]),
            rig.actor,
            "Recog = 说话者自己的 ActorId"
        );
        assert_eq!(
            u16::from_le_bytes([body[4], body[5]]),
            mir2_protocol::messages::SM_SYSMESSAGE,
            "Ident = SM_SYSMESSAGE(100)"
        );
        assert_eq!(u16::from_le_bytes([body[8], body[9]]), 0, "Tag=0");
        assert_eq!(u16::from_le_bytes([body[10], body[11]]), 1, "Series=1");
        let param = u16::from_le_bytes([body[6], body[7]]);
        let text = gbk_decode(&mir2_protocol::edcode::decode(&body[12..]));
        (param, text)
    }

    /// **R1 牙**：排水门严格 `starts_with('@')`（与 handle_say 同口径）——前导空格的
    /// 「 @…」是普通聊天，不得排水；非 @ 与 None 同样不放行。
    /// 变异红：改 `trim_start().starts_with('@')` ⇒ 本用例红。
    #[test]
    fn gm_drain_gate_is_strict_at_prefix() {
        assert!(gm_drain_gate(Some("@Reconnection 1.2.3.4 7200")));
        assert!(
            !gm_drain_gate(Some(" @Reconnection 1.2.3.4 7200")),
            "前导空格 ⇒ 普通聊天"
        );
        assert!(!gm_drain_gate(Some("hello")));
        assert!(!gm_drain_gate(None));
    }

    /// **R3 牙（F3 bo 置位顺序）**：`drain_reconnects` 必须**先置 `BoReconnection=true` 再
    /// 尝试发帧**（oracle `PlayObject.Message.cs:1989-1990` 同序）——用「会话在、gates 空
    /// （路由必败）」构造：bo 仍为 true 证明置位先于/独立于发送。
    /// 变异红：把 `sg.bo_reconnection = true;` 挪到 `route_to_gate` 失败 `continue` 之后
    /// （或删掉）⇒ 本用例红。
    #[test]
    fn drain_reconnects_sets_bo_before_send() {
        use std::collections::HashMap;
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut sg = test_session_ground(7);
        sg.bo_reconnection = false;
        sessions.insert("hero".into(), sg);
        let empty_gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        let mut pending = vec![ReconnectPending {
            gate_idx: 0,
            socket: 901,
            chr_name: "hero".to_string(),
            msg: b"1.2.3.4/7200".to_vec(),
        }];
        drain_reconnects(&mut pending, &mut sessions, &empty_gates);
        assert!(
            sessions["hero"].bo_reconnection,
            "BoReconnection 必须置位（先置后发；路由失败也不回滚）"
        );
        assert!(pending.is_empty(), "队列取尽");
    }

    /// **族 X2 批 B 宿主落地牙**：`apply_pending_gm_target_ops` 五条副作用——
    /// 复活（death=false + HP=MaxHP + SM_ABILITY(52) 投给调用者）/ VV给予权限（目标会话
    /// permission 写）/ 清除仓库密码（pwd 三字段清）/ ClearCopyItem（**误删调用者背包**
    /// 怪癖照抄 + 目标列表不动 + 越界异常停止）/ vv杀死（World::kill 入队 ⇒ tick 后 death）。
    /// 变异红：M-B1..M-B5（每条副作用删/改向）⇒ 对应用例红。
    #[test]
    fn gm_target_ops_apply_state_and_quirk() {
        use mir2_world_bevy::World;
        use std::collections::HashMap;
        let mut world = World::new(32, 32);
        let hero_id = world.add_entity(mir2_world_bevy::EntitySpawn::new(0, "hero", 10, 10));
        let mut victim_e = mir2_world_bevy::EntitySpawn::new(0, "victim", 11, 11);
        victim_e.death = true;
        victim_e.death_settled = true; // 已结算过的尸体：复活必须清闩锁（F2 牙敏感点）
        victim_e.hp = 1;
        victim_e.max_hp = 100;
        let victim_id = world.add_entity(victim_e);
        let mut catalog = game_svr::ability::StdItemCatalog::new();
        catalog.insert(
            10,
            mir2_data::StdItem {
                name: "木剑".into(),
                ..Default::default()
            },
        );
        catalog.insert(
            11,
            mir2_data::StdItem {
                name: "铁剑".into(),
                ..Default::default()
            },
        );
        let item = |make_index: i32, index: u16| game_svr::bag::BagItem {
            make_index,
            index,
            dura: 0,
            dura_max: 0,
            desc: [0; 14],
        };
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut hero_sg = test_session_ground(hero_id);
        hero_sg.state.item_list = vec![item(100, 10), item(101, 11)];
        hero_sg.storage.items = vec![item(200, 11)];
        hero_sg.gm.pending_gm_revive = Some("victim".into());
        hero_sg.gm.pending_set_permission = Some(("victim".into(), 7));
        hero_sg.gm.pending_clear_password = Some("victim".into());
        hero_sg.gm.pending_clear_copy = Some("victim".into());
        sessions.insert("hero".into(), hero_sg);
        let mut victim_sg = test_session_ground(victim_id);
        // 目标背包两把同名同 MakeIndex 的剑 ⇒ 一次命中；目标仓库同样。
        victim_sg.state.item_list = vec![item(500, 10), item(500, 10)];
        victim_sg.storage.items = vec![item(600, 11), item(600, 11)];
        sessions.insert("victim".into(), victim_sg);
        let mut pwd_sessions: HashMap<String, game_svr::inbound::PwdSession> = HashMap::new();
        pwd_sessions.insert(
            "victim".into(),
            game_svr::inbound::PwdSession {
                state: game_svr::inbound::StoragePwdState {
                    storage_pwd: "abcd".into(),
                    is_password_locked: true,
                    is_un_lock_storage_pwd: true,
                    ..Default::default()
                },
                locks: game_svr::inbound::ActionLocks::default(),
            },
        );
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "a".into(),
                chr_name: "hero".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: hero_id,
            },
        );
        // F1：被复活者本人在线（有自己的 socket）——SM_ABILITY 收件人 = 被复活者。
        online_set(
            &mut online,
            OnlineEntry {
                account: "v".into(),
                chr_name: "victim".into(),
                session_id: 2,
                gate_idx: 0,
                socket: 902,
                actor_id: victim_id,
            },
        );
        // F2-R1 牙敏感点：视野内有一个 **Ghost** 观察者（online 仍含它）——SM_ALIVE 不得发它。
        let mut ghost_e = mir2_world_bevy::EntitySpawn::new(0, "watcher", 12, 12);
        ghost_e.ghost = true;
        let watcher_id = world.add_entity(ghost_e);
        online_set(
            &mut online,
            OnlineEntry {
                account: "w".into(),
                chr_name: "watcher".into(),
                session_id: 3,
                gate_idx: 0,
                socket: 903,
                actor_id: watcher_id,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let colors = MsgColors {
            red_f: 255,
            red_b: 56,
            hear_f: 0,
            hear_b: 255,
            whisper_f: 0,
            whisper_b: 0,
            green_f: 0xDB,
            green_b: 0xFF,
            blue_f: 0xFF,
            blue_b: 0xFC,
        };
        let mut saves: HashMap<String, SavedHuman> = HashMap::new();
        let empty_magic = magics::MagicTable::default();
        let displays = downlink::DisplayTable::new();
        apply_pending_gm_target_ops(
            &mut sessions,
            &mut pwd_sessions,
            &mut saves,
            &mut world,
            &catalog,
            MagicCfg {
                table: &empty_magic,
                fire_ball_skill: "火球术",
                heal_skill: "治愈术",
            },
            &displays,
            &online,
            &gates,
            &colors,
            12,
            "hero",
        );
        // ① 复活：death=false + death_settled 清零 + HP=MaxHP + wabil 同步（F2）。
        {
            let e = world.entities.get(victim_id).unwrap();
            assert!(!e.death, "ReAlive ⇒ death=false");
            assert!(
                !e.death_settled,
                "F2：death_settled 必须清零（否则复活即免死）"
            );
            assert_eq!(e.hp, 100, "HP=MaxHP");
        }
        assert_eq!(sessions["victim"].state.wabil.hp, 100, "wabil.hp 同步");
        assert_eq!(
            sessions["victim"].state.wabil.max_hp, 100,
            "wabil.max_hp 同步"
        );
        // F1：SM_ABILITY(52) 投**被复活者本人**（socket 902），不是调用者 901；
        // F2c：SM_ALIVE(27) 视距广播（观察者 901 + 自己 902）。
        let frames: Vec<(i32, u16)> = std::iter::from_fn(|| rx0.try_recv().ok())
            .filter_map(|m| match m {
                SimToGate::SendFrame { socket, body } => {
                    Some((socket, u16::from_le_bytes([body[4], body[5]])))
                }
                _ => None,
            })
            .collect();
        assert!(
            frames.contains(&(902, mir2_protocol::messages::SM_ABILITY)),
            "SM_ABILITY 必须投被复活者 902；实得 {frames:?}"
        );
        assert!(
            !frames.contains(&(901, mir2_protocol::messages::SM_ABILITY)),
            "调用者 901 不得收到 SM_ABILITY（F1 纠错向）"
        );
        assert!(
            frames.contains(&(901, mir2_protocol::messages::SM_ALIVE)),
            "SM_ALIVE 广播到观察者 901；实得 {frames:?}"
        );
        assert!(
            frames.contains(&(902, mir2_protocol::messages::SM_ALIVE)),
            "SM_ALIVE 广播含自己 902"
        );
        assert!(
            !frames.contains(&(903, mir2_protocol::messages::SM_ALIVE)),
            "F2-R1：Ghost 观察者 903 不得收 SM_ALIVE（hear_targets 的 !Ghost 过滤）"
        );
        // ② VV给予权限：目标会话运行时 permission 写。
        assert_eq!(sessions["victim"].gm.permission, 7);
        // ③ 清除仓库密码：三字段清零。
        {
            let p = &pwd_sessions["victim"].state;
            assert!(!p.is_password_locked && !p.is_un_lock_storage_pwd && p.storage_pwd.is_empty());
        }
        // ④ ClearCopyItem 怪癖：删**调用者**背包[0] 与仓库[0]；目标两列表不变。
        assert_eq!(
            sessions["hero"].state.item_list.len(),
            1,
            "调用者背包被误删"
        );
        assert_eq!(sessions["hero"].state.item_list[0].make_index, 101);
        assert_eq!(sessions["hero"].storage.items.len(), 0, "调用者仓库被误删");
        assert_eq!(sessions["victim"].state.item_list.len(), 2, "目标背包不动");
        assert_eq!(sessions["victim"].storage.items.len(), 2, "目标仓库不动");
        // ⑤ pending 全清（一次性）。
        let gm = &sessions["hero"].gm;
        assert!(
            gm.pending_gm_die.is_none()
                && gm.pending_gm_revive.is_none()
                && gm.pending_set_permission.is_none()
                && gm.pending_clear_copy.is_none()
                && gm.pending_clear_password.is_none()
                && gm.pending_del_skill.is_none()
        );
        // ⑥ vv杀死：单独一例（World::kill 入队 ⇒ tick 后 death）。
        sessions.get_mut("hero").unwrap().gm.pending_gm_die = Some("victim".into());
        apply_pending_gm_target_ops(
            &mut sessions,
            &mut pwd_sessions,
            &mut saves,
            &mut world,
            &catalog,
            MagicCfg {
                table: &empty_magic,
                fire_ball_skill: "火球术",
                heal_skill: "治愈术",
            },
            &displays,
            &online,
            &gates,
            &colors,
            12,
            "hero",
        );
        while rx0.try_recv().is_ok() {}
        for _ in 0..3 {
            world.tick();
        }
        assert!(
            world.entities.get(victim_id).unwrap().death,
            "World::kill ⇒ tick 后死亡结算"
        );
    }

    /// **F4 牙（review b6a3962b / d7a57cd0 F3-R3 / 27f360af F1-R3）**：`@删除技能` 宿主真实
    /// 实现——MagicList 在 `saves`；按名（**Desc** 语义，夹具 desc≠magic_name）命中 ⇒
    /// `SM_DELMAGIC(212)` 投**目标 socket=902** + 审计 `RecalcAbilitys` 的 210/212（**同为
    /// 目标 socket、SendSocket 立即**）+ 目标绿/调用者绿（**队尾**，排审计帧之后）+ 列表移除；
    /// `All` ⇒ 清空且不发帧不发字。逐 socket 帧序断言（212(命令) → 212(审计) → 100(绿字)），
    /// 审计帧各恰一条。
    /// 变异红：M-T1 绿字回 canon / M-T2 自写收件人（ghost 收 ALIVE）/ M-T3 recalc 传 None /
    /// M-T4 pose 注入恒 None / M-T5 SM_ABILITY 回发调用者 / M-T6 审计帧投 901 /
    /// M-T7 查找键 desc→magic_name / M-T8 绿字先于审计帧。
    #[test]
    fn gm_del_skill_host_apply_emits_212_and_greens() {
        use std::collections::HashMap;
        let mut world = mir2_world_bevy::World::new(32, 32);
        let hero_id = world.add_entity(mir2_world_bevy::EntitySpawn::new(0, "hero", 10, 10));
        let victim_id = world.add_entity(mir2_world_bevy::EntitySpawn::new(0, "victim", 11, 11));
        // **657（`#11`）**：victim 的两名观察者（hero@(10,10) 本来就在范围内）+ 一名超 range 玩家；
        // 四人 `hit_speed` 互异（5/7/9/11），用于断言 `Series` 逐收件人取值。
        let obs_id = world.add_entity(mir2_world_bevy::EntitySpawn::new(0, "obs", 12, 11));
        let far_id = world.add_entity(mir2_world_bevy::EntitySpawn::new(0, "far", 24, 11));
        let mag = |mag_idx: u16| {
            Some(record::MagicRcd {
                mag_idx,
                level: 1,
                magic_key: 0,
                tran_point: 0,
            })
        };
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut hero_sg = test_session_ground(hero_id);
        hero_sg.gm.pending_del_skill = Some(("victim".into(), "烈火球".into())); // Desc
        sessions.insert("hero".into(), hero_sg);
        let mut victim_sg = test_session_ground(victim_id);
        victim_sg.equip.job = 2; // TAOIST：审计保治愈术（主案例确定性）
                                 // 让 `RecalcAbilitys` 产出**非 0** 的落地 HitSpeed（657 自见副本的 Series 取它；
                                 // oracle handler 读 `this.HitSpeed` = 重算后的落地值，不是插入前的实体旧值）。
        victim_sg.equip.bonus_tick_hit = 20;
        victim_sg.equip.bonus_tick_speed = 35;
        // 装备一把 StdMode 5 武器：`AddAbil.HitSpeed` 由物品 `MAC` 高字节派生（`apply_item_parameters`）
        // ⇒ 重算后的**落地** `hit_speed` 非 0（防退化区间）。
        victim_sg.use_items[game_svr::ability::SLOT_WEAPON] = Some(game_svr::bag::BagItem {
            make_index: 1,
            index: 77,
            dura: 1000,
            dura_max: 1000,
            desc: [0; 14],
        });
        sessions.insert("victim".into(), victim_sg);
        let mut saves: HashMap<String, SavedHuman> = HashMap::new();
        saves.insert(
            "victim".into(),
            SavedHuman {
                account: "v".into(),
                record: record::PlayerRecord::default(),
                enter_map: "0".into(),
                derived: None,
            },
        );
        magic_list_mut(saves.get_mut("victim").unwrap()).extend([mag(1), mag(2)]);
        // F2-R3 牙敏感点：目标带生效中的 ExtraAbil[0]（AttPowerUp DC 高字节 +3）——
        // 重算仍按实体活跃值传 `Some(&e.extra_abil)`（状态面照传）；但**不得**折进 `WAbil`
        //（oracle `:2899-2906` 覆盖 `:2818-2846`，见 F2-R3 的修正）。
        world.entities.get_mut(victim_id).unwrap().buff.extra_abil[0] = 3;
        for (id, hs) in [(victim_id, 5u16), (hero_id, 7), (obs_id, 9), (far_id, 11)] {
            world.entities.get_mut(id).unwrap().vitals.hit_speed = hs;
        }
        // F3-R3：**desc ≠ magic_name**——命令按 Desc 匹配（oracle :60），审计按 MagicName 查找
        // （`magicaudit::delete_name_skill` 用 magic_name）。把命令查找改成 magic_name ⇒ 本用例红。
        let magic_table = magics::MagicTable::new(vec![
            mir2_data::MagicInfo {
                magic_id: 1,
                magic_name: "火球术".into(),
                desc: "烈火球".into(),
                ..Default::default()
            },
            mir2_data::MagicInfo {
                magic_id: 2,
                magic_name: "治愈术".into(),
                desc: "回春术".into(),
                ..Default::default()
            },
        ]);
        let mut pwd_sessions: HashMap<String, game_svr::inbound::PwdSession> = HashMap::new();
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "a".into(),
                chr_name: "hero".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: hero_id,
            },
        );
        online_set(
            &mut online,
            OnlineEntry {
                account: "v".into(),
                chr_name: "victim".into(),
                session_id: 2,
                gate_idx: 0,
                socket: 902,
                actor_id: victim_id,
            },
        );
        online_set(
            &mut online,
            OnlineEntry {
                account: "o".into(),
                chr_name: "obs".into(),
                session_id: 3,
                gate_idx: 0,
                socket: 903,
                actor_id: obs_id,
            },
        );
        online_set(
            &mut online,
            OnlineEntry {
                account: "f".into(),
                chr_name: "far".into(),
                session_id: 4,
                gate_idx: 0,
                socket: 904,
                actor_id: far_id,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let colors = MsgColors {
            red_f: 255,
            red_b: 56,
            hear_f: 0,
            hear_b: 255,
            whisper_f: 0,
            whisper_b: 0,
            green_f: 0xDB,
            green_b: 0xFF,
            blue_f: 0xFF,
            blue_b: 0xFC,
        };
        let displays = downlink::DisplayTable::new();
        let mut catalog = game_svr::ability::StdItemCatalog::new();
        catalog.insert(
            77,
            mir2_data::StdItem {
                name: "提速剑".into(),
                std_mode: 5,
                mac: 0x0500,
                dura_max: 1000,
                ..mir2_data::StdItem::default()
            },
        );
        let collect =
            |rx: &mut mpsc::UnboundedReceiver<SimToGate>| -> Vec<(i32, u16, i32, String, u16)> {
                std::iter::from_fn(|| rx.try_recv().ok())
                    .filter_map(|m| match m {
                        SimToGate::SendFrame { socket, body } => Some((
                            socket,
                            u16::from_le_bytes([body[4], body[5]]),
                            i32::from_le_bytes([body[0], body[1], body[2], body[3]]),
                            if body.len() > 12 {
                                gbk_decode(&mir2_protocol::edcode::decode(&body[12..]))
                            } else {
                                String::new()
                            },
                            u16::from_le_bytes([body[10], body[11]]),
                        )),
                        _ => None,
                    })
                    .collect()
            };
        // ---- 主案例：job=TAOIST，按 Desc("烈火球") 删 mag1 ----
        apply_pending_gm_target_ops(
            &mut sessions,
            &mut pwd_sessions,
            &mut saves,
            &mut world,
            &catalog,
            MagicCfg {
                table: &magic_table,
                fire_ball_skill: "火球术",
                heal_skill: "治愈术",
            },
            &displays,
            &online,
            &gates,
            &colors,
            12,
            "hero",
        );
        let list = saves["victim"].record.data.magic.as_ref().unwrap();
        assert_eq!(list.len(), 1, "只删命中项（按 Desc）");
        assert_eq!(list[0].as_ref().unwrap().mag_idx, 2);
        // **F2-R3（2026-11-20 修正：旧期望编码了错误行为）**：`ExtraAbil[0]=3` **不得**进 `WAbil`——
        // oracle `RecalcAbilitys` 的折算段（`PlayObject.cs:2818-2846`）必被 `:2899-2906` 的
        // `WAbil.DC = MakeWord(MIN(255,Lo(Add)+Lo(Abil)), MIN(255,Hi+Hi))` 整体覆盖 ⇒ 只能 `0x0100`。
        // 旧期望 `0x0400`（Hi 1+3）是把"被覆盖值"当成最终值的被测错误。
        assert_eq!(
            sessions["victim"].state.wabil.dc, 0x0100,
            "ExtraAbil 不进 WAbil（oracle :2899-2906 覆盖 :2818-2846）"
        );
        assert!(
            !world.entities.get(victim_id).unwrap().flame_ring,
            "无 Sticky FlameRing（flame_ring_in=false 路径）"
        );
        let frames = collect(&mut rx0);
        // 902 帧序：212(命令删除) → 100(目标绿)；审计在本例无事件（火球已删/治愈 job 门）。
        let s902: Vec<u16> = frames
            .iter()
            .filter(|(s, ..)| *s == 902)
            .map(|(_, id, ..)| *id)
            .collect();
        assert_eq!(
            s902,
            vec![
                mir2_protocol::messages::SM_DELMAGIC,
                mir2_protocol::messages::SM_CHARSTATUSCHANGED,
                mir2_protocol::messages::SM_SYSMESSAGE
            ],
            "目标 socket 序 212 → 657×1 → 100（155 成队首被 SendUpdateMsg 去重）；实得 {frames:?}"
        );
        let del: Vec<&(i32, u16, i32, String, u16)> = frames
            .iter()
            .filter(|(_, id, ..)| *id == mir2_protocol::messages::SM_DELMAGIC)
            .collect();
        assert_eq!(del.len(), 1, "恰一条 SM_DELMAGIC；实得 {frames:?}");
        assert_eq!(del[0].0, 902, "212 投目标");
        assert_eq!(del[0].2, 1, "212 Recog = MagIdx");
        assert!(
            frames.iter().any(|(s, id, _, t, _)| *s == 902
                && *id == mir2_protocol::messages::SM_SYSMESSAGE
                && t == "技能烈火球已删除。"),
            "目标绿字；实得 {frames:?}"
        );
        assert!(
            frames.iter().any(|(s, id, _, t, _)| *s == 901
                && *id == mir2_protocol::messages::SM_SYSMESSAGE
                && t == "victim的技能烈火球已删除。"),
            "调用者绿字；实得 {frames:?}"
        );
        // **657（`#11`）逐 socket 计数 + `Series` 逐收件人**（§47：只断计数与同 socket 内序，
        // 不断跨 socket、不断两条 self 的先后）。
        let cs657 = |sock: i32| -> Vec<u16> {
            frames
                .iter()
                .filter(|(s, id, ..)| {
                    *s == sock && *id == mir2_protocol::messages::SM_CHARSTATUSCHANGED
                })
                .map(|(_, _, _, _, series)| *series)
                .collect()
        };
        let c902 = cs657(902);
        assert_eq!(
            c902.len(),
            1,
            "目标自见 657 = 1 条（155 成队首 ⇒ SendUpdateMsg 去重弹掉再入）"
        );
        // 自见副本的 `Series` = **重算后的落地 `sg.hit_speed`**（oracle handler 读 `this.HitSpeed`），
        // 不是插入前实体上的旧值。
        // `Series` 源 = **实体**（oracle `this.HitSpeed`；本路径上游 `apply_ability_to_entity`
        // 已把重算后的值镜像进实体）。
        let want_self = world.entities.get(victim_id).map_or(0, |e| e.hit_speed);
        assert_ne!(want_self, 0, "本用例要求非 0 落地 HitSpeed（防退化区间）");
        // **65531 = -5 的 `u16` 回绕结果**：武器 `mac=0x0500` ⇒ `hi_byte=5` ⇒
        // `real_attack_speed(5) = -5` ⇒ `AddAbil.HitSpeed` 逐次 `u16` 回绕。oracle 的
        // `AddAbil.HitSpeed` 同为 `ushort`，预期同样回绕，但**本值未经 oracle 侧实测对照**——
        // 若日后发现 oracle 用的是别的宽度/符号，本断言要跟着改。
        assert_eq!(want_self, 65531, "落地 HitSpeed = -5 的 u16 回绕");
        assert!(
            c902.iter().all(|s| *s == want_self),
            "自见 Series = 实体落地 hit_speed({want_self})；实得 {c902:?}"
        );
        assert_eq!(
            cs657(901),
            vec![7],
            "调用者（观察者）恰 1 条，Series = 自己 7"
        );
        assert_eq!(cs657(903), vec![9], "观察者 obs 恰 1 条，Series = 自己 9");
        assert!(cs657(904).is_empty(), "超 range（far）零 657");
        // 同 socket 内：657 在 212/210 之后、绿字 100 之前。
        let idx_of = |sock: i32, id: u16| -> Vec<usize> {
            frames
                .iter()
                .enumerate()
                .filter(|(_, (s, i, ..))| *s == sock && *i == id)
                .map(|(k, _)| k)
                .collect()
        };
        let i657 = idx_of(902, mir2_protocol::messages::SM_CHARSTATUSCHANGED);
        let mut before: Vec<usize> = idx_of(902, mir2_protocol::messages::SM_DELMAGIC);
        before.extend(idx_of(902, mir2_protocol::messages::SM_ADDMAGIC));
        let i100 = idx_of(902, mir2_protocol::messages::SM_SYSMESSAGE);
        if let (Some(a), Some(b)) = (i657.iter().min(), before.iter().max()) {
            assert!(a > b, "657 必须在 212/210 之后");
        }
        if let (Some(a), Some(b)) = (i657.iter().max(), i100.iter().min()) {
            assert!(a < b, "657 必须在绿字(100)之前");
        }

        // ---- All 支：清空且不发帧不发字 ----
        while rx0.try_recv().is_ok() {}
        magic_list_mut(saves.get_mut("victim").unwrap()).extend([mag(1), mag(2)]);
        sessions.get_mut("hero").unwrap().gm.pending_del_skill =
            Some(("victim".into(), "All".into()));
        apply_pending_gm_target_ops(
            &mut sessions,
            &mut pwd_sessions,
            &mut saves,
            &mut world,
            &catalog,
            MagicCfg {
                table: &magic_table,
                fire_ball_skill: "火球术",
                heal_skill: "治愈术",
            },
            &displays,
            &online,
            &gates,
            &colors,
            12,
            "hero",
        );
        assert!(
            saves["victim"]
                .record
                .data
                .magic
                .as_ref()
                .unwrap()
                .is_empty(),
            "All ⇒ 全部删除"
        );
        // `All` 支：**不发** 212/绿字（`DelSkillCommand.cs:49-52`），但 :71 的 `RecalcAbilitys()`
        // **照样执行** ⇒ 有 657（自见**净 1 条**：队首去重，`BaseObject.Message.cs:283-304`）。
        let all_frames = collect(&mut rx0);
        assert!(
            all_frames
                .iter()
                .all(|(_, id, ..)| *id == mir2_protocol::messages::SM_CHARSTATUSCHANGED),
            "All 支只允许 657；实得 {all_frames:?}"
        );
        let all657 = all_frames
            .iter()
            .filter(|(s, id, ..)| *s == 902 && *id == mir2_protocol::messages::SM_CHARSTATUSCHANGED)
            .count();
        assert_eq!(
            all657, 1,
            "All 支的 RecalcAbilitys 自见净 1 条 657（队首去重）"
        );
        // ---- 审计案例：job=WARRIOR，按 Desc("回春术") 删 mag2；审计按 MagicName("火球术")
        //      删 mag1 并出第二条 212 —— 目标 socket 序 212(2) → 212(1) → 100 ----
        magic_list_mut(saves.get_mut("victim").unwrap()).extend([mag(1), mag(2)]);
        sessions.get_mut("victim").unwrap().equip.job = 0;
        sessions.get_mut("hero").unwrap().gm.pending_del_skill =
            Some(("victim".into(), "回春术".into()));
        apply_pending_gm_target_ops(
            &mut sessions,
            &mut pwd_sessions,
            &mut saves,
            &mut world,
            &catalog,
            MagicCfg {
                table: &magic_table,
                fire_ball_skill: "火球术",
                heal_skill: "治愈术",
            },
            &displays,
            &online,
            &gates,
            &colors,
            12,
            "hero",
        );
        let frames = collect(&mut rx0);
        let s902: Vec<u16> = frames
            .iter()
            .filter(|(s, ..)| *s == 902)
            .map(|(_, id, ..)| *id)
            .collect();
        assert_eq!(
            s902,
            vec![
                mir2_protocol::messages::SM_DELMAGIC,
                mir2_protocol::messages::SM_DELMAGIC,
                mir2_protocol::messages::SM_CHARSTATUSCHANGED,
                mir2_protocol::messages::SM_SYSMESSAGE
            ],
            "帧序：212(命令) → 212(审计) → 657×1 → 100(目标绿，队尾)；实得 {frames:?}"
        );
        let dels: Vec<(i32, i32)> = frames
            .iter()
            .filter(|(_, id, ..)| *id == mir2_protocol::messages::SM_DELMAGIC)
            .map(|(s, _, recog, _, _)| (*s, *recog))
            .collect();
        assert_eq!(
            dels,
            vec![(902, 2), (902, 1)],
            "命令删除(2)+审计删除(1)各恰一条且都投目标 902；实得 {frames:?}"
        );
        assert!(
            saves["victim"]
                .record
                .data
                .magic
                .as_ref()
                .unwrap()
                .iter()
                .all(|m| m.is_none() || m.as_ref().unwrap().mag_idx != 1),
            "审计已删火球术"
        );
        // ---- F4-R1：调用者绿字回显**原始参数拼写**（大写 VICTIM ≠ 实体名 victim）----
        magic_list_mut(saves.get_mut("victim").unwrap()).push(mag(1));
        sessions.get_mut("victim").unwrap().equip.job = 2;
        sessions.get_mut("hero").unwrap().gm.pending_del_skill =
            Some(("VICTIM".into(), "烈火球".into()));
        apply_pending_gm_target_ops(
            &mut sessions,
            &mut pwd_sessions,
            &mut saves,
            &mut world,
            &catalog,
            MagicCfg {
                table: &magic_table,
                fire_ball_skill: "火球术",
                heal_skill: "治愈术",
            },
            &displays,
            &online,
            &gates,
            &colors,
            12,
            "hero",
        );
        let frames = collect(&mut rx0);
        assert!(
            frames.iter().any(|(s, id, _, t, _)| *s == 901
                && *id == mir2_protocol::messages::SM_SYSMESSAGE
                && t == "VICTIM的技能烈火球已删除。"),
            "F4-R1：调用者绿字用原始参数拼写；实得 {frames:?}"
        );
    }

    /// **657（`#12`）第二臂：目标有会话但**无 `saves` 记录**（`(Some(tsg), None)` 分支）。
    ///
    /// oracle `DelSkillCommand.cs:60-71`：`mIPlayerActor` 存在才继续；`MagicList` 在 **PlayObject** 上
    /// （本仓投影在 `saves`），无记录 ⇒ 循环无命中、无 212/绿字，但 `:71` 的 `RecalcAbilitys()`
    /// **照样执行** ⇒ 只有 657（自见 2 + 观察者各 1，`Series` 逐收件人）。
    /// 红检：把 657 只挂在"有 saves"的臂上 ⇒ 本例零 657；删 657 ⇒ 计数红。
    #[test]
    fn gm_del_skill_without_saves_arm_emits_657() {
        use std::collections::HashMap;
        let mut world = mir2_world_bevy::World::new(32, 32);
        let hero_id = world.add_entity(mir2_world_bevy::EntitySpawn::new(0, "hero", 10, 10));
        let victim_id = world.add_entity(mir2_world_bevy::EntitySpawn::new(0, "victim", 11, 11));
        let obs_id = world.add_entity(mir2_world_bevy::EntitySpawn::new(0, "obs", 12, 11));
        let far_id = world.add_entity(mir2_world_bevy::EntitySpawn::new(0, "far", 24, 11));
        for (id, hs) in [(hero_id, 7u16), (obs_id, 9), (far_id, 11)] {
            world.entities.get_mut(id).unwrap().vitals.hit_speed = hs;
        }
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut hero_sg = test_session_ground(hero_id);
        hero_sg.gm.pending_del_skill = Some(("victim".into(), "烈火球".into()));
        sessions.insert("hero".into(), hero_sg);
        let mut victim_sg = test_session_ground(victim_id);
        victim_sg.equip.bonus_tick_hit = 20;
        victim_sg.equip.bonus_tick_speed = 35;
        victim_sg.use_items[game_svr::ability::SLOT_WEAPON] = Some(game_svr::bag::BagItem {
            make_index: 1,
            index: 77,
            dura: 1000,
            dura_max: 1000,
            desc: [0; 14],
        });
        sessions.insert("victim".into(), victim_sg);
        let mut saves: HashMap<String, SavedHuman> = HashMap::new(); // **无 victim 记录** ⇒ 第二臂
        let mut catalog = game_svr::ability::StdItemCatalog::new();
        catalog.insert(
            77,
            mir2_data::StdItem {
                name: "提速剑".into(),
                std_mode: 5,
                mac: 0x0500,
                dura_max: 1000,
                ..mir2_data::StdItem::default()
            },
        );
        let magic_table = magics::MagicTable::new(vec![]);
        let mut pwd_sessions: HashMap<String, game_svr::inbound::PwdSession> = HashMap::new();
        let mut online: OnlineRegistry = OnlineRegistry::new();
        for (name, sock, id, sid) in [
            ("hero", 901i32, hero_id, 1),
            ("victim", 902, victim_id, 2),
            ("obs", 903, obs_id, 3),
            ("far", 904, far_id, 4),
        ] {
            online_set(
                &mut online,
                OnlineEntry {
                    account: name.into(),
                    chr_name: name.into(),
                    session_id: sid,
                    gate_idx: 0,
                    socket: sock,
                    actor_id: id,
                },
            );
        }
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let colors = MsgColors {
            red_f: 255,
            red_b: 56,
            hear_f: 0,
            hear_b: 255,
            whisper_f: 0,
            whisper_b: 0,
            green_f: 0xDB,
            green_b: 0xFF,
            blue_f: 0xFF,
            blue_b: 0xFC,
        };
        let displays = downlink::DisplayTable::new();
        apply_pending_gm_target_ops(
            &mut sessions,
            &mut pwd_sessions,
            &mut saves,
            &mut world,
            &catalog,
            MagicCfg {
                table: &magic_table,
                fire_ball_skill: "火球术",
                heal_skill: "治愈术",
            },
            &displays,
            &online,
            &gates,
            &colors,
            12,
            "hero",
        );
        let frames: Vec<(i32, u16, u16)> = std::iter::from_fn(|| rx0.try_recv().ok())
            .filter_map(|m| match m {
                SimToGate::SendFrame { socket, body } => Some((
                    socket,
                    u16::from_le_bytes([body[4], body[5]]),
                    u16::from_le_bytes([body[10], body[11]]),
                )),
                _ => None,
            })
            .collect();
        let cs = |sock: i32| -> Vec<u16> {
            frames
                .iter()
                .filter(|(s, id, _)| {
                    *s == sock && *id == mir2_protocol::messages::SM_CHARSTATUSCHANGED
                })
                .map(|(_, _, series)| *series)
                .collect()
        };
        // `Series` 源 = **实体**（同上：重算后已镜像；oracle `this.HitSpeed`）。
        let want_self = world.entities.get(victim_id).map_or(0, |e| e.hit_speed);
        assert_ne!(want_self, 0, "要求非 0 落地 HitSpeed（防退化区间）");
        // 65531 的来历与"未经 oracle 实测对照"的限定同第一臂。
        assert_eq!(want_self, 65531, "落地 HitSpeed = -5 的 u16 回绕");
        assert_eq!(cs(902), vec![want_self], "目标自见净 1 条（队首去重）");
        assert_eq!(cs(901), vec![7], "观察者 hero 1 条，Series = 自己");
        assert_eq!(cs(903), vec![9], "观察者 obs 1 条，Series = 自己");
        assert!(cs(904).is_empty(), "超 range 零 657");
        assert!(
            frames
                .iter()
                .all(|(_, id, _)| { *id == mir2_protocol::messages::SM_CHARSTATUSCHANGED }),
            "第二臂无 212/绿字，只允许 657；实得 {frames:?}"
        );
    }

    /// **M1 牙（review b6a3962b）**：`@ClearCopyItem` 调用者==目标时按**活表**迭代——
    /// oracle 内层删除正在遍历的同一张表（后续 i 读到移位后的元素）。
    /// 夹具 `[A1(m1), A2(m2), A3(m1)]`：活表结果 `[A2, A3]`（2 件）；快照实现会给 `[A3]`（1 件）。
    #[test]
    fn gm_clear_copy_self_target_uses_live_table() {
        use std::collections::HashMap;
        let mut world = mir2_world_bevy::World::new(32, 32);
        let hero_id = world.add_entity(mir2_world_bevy::EntitySpawn::new(0, "hero", 10, 10));
        let mut catalog = game_svr::ability::StdItemCatalog::new();
        catalog.insert(
            10,
            mir2_data::StdItem {
                name: "木剑".into(),
                ..Default::default()
            },
        );
        catalog.insert(
            11,
            mir2_data::StdItem {
                name: "铁剑".into(),
                ..Default::default()
            },
        );
        let item = |make_index: i32, index: u16| game_svr::bag::BagItem {
            make_index,
            index,
            dura: 0,
            dura_max: 0,
            desc: [0; 14],
        };
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut hero_sg = test_session_ground(hero_id);
        // 区分活表 vs 快照的夹具（5 件同名木剑）：活表结果 makes=[1,2]；快照会给 [2,2]。
        hero_sg.state.item_list = vec![
            item(1, 10),
            item(2, 10),
            item(2, 10),
            item(1, 10),
            item(2, 10),
        ];
        hero_sg.gm.pending_clear_copy = Some("hero".into());
        sessions.insert("hero".into(), hero_sg);
        let mut pwd_sessions: HashMap<String, game_svr::inbound::PwdSession> = HashMap::new();
        let mut saves: HashMap<String, SavedHuman> = HashMap::new();
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "a".into(),
                chr_name: "hero".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: hero_id,
            },
        );
        let (tx0, _rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let colors = MsgColors {
            red_f: 255,
            red_b: 56,
            hear_f: 0,
            hear_b: 255,
            whisper_f: 0,
            whisper_b: 0,
            green_f: 0xDB,
            green_b: 0xFF,
            blue_f: 0xFF,
            blue_b: 0xFC,
        };
        let displays = downlink::DisplayTable::new();
        let magic_table = magics::MagicTable::default();
        apply_pending_gm_target_ops(
            &mut sessions,
            &mut pwd_sessions,
            &mut saves,
            &mut world,
            &catalog,
            MagicCfg {
                table: &magic_table,
                fire_ball_skill: "火球术",
                heal_skill: "治愈术",
            },
            &displays,
            &online,
            &gates,
            &colors,
            12,
            "hero",
        );
        let list = &sessions["hero"].state.item_list;
        assert_eq!(list.len(), 2, "活表结果 2 件");
        let makes: Vec<i32> = list.iter().map(|it| it.make_index).collect();
        assert_eq!(
            makes,
            vec![1, 2],
            "活表语义（oracle 外层次次读移位后的元素）；快照实现会给 [2, 2]"
        );
    }

