    /// 封禁名单族 9 条（权限 10）：可达支文本逐字节 + 触表支零帧（扫盲卡
    /// `openmir2-gm-systemshare-null-sweep`，review F1 同款运行层真相——Del/Show 六命令的
    /// 循环/Count 读 SystemShare.Deny*List 声明即 null（SystemShare.cs:135/:139/:143）⇒
    /// NRE 被 Chat.cs:402 顶层 catch 吞 ⇒ 零帧；+jid 三条只调 Save 方法（全注释体）⇒
    /// 绿字可达不变；4 参 `@params[3]` 越界零帧不变）。
    #[test]
    fn gm_batch2_deny_family_through_handle_say() {
        let mut rig = GmRig::new();
        let cases: &[(&str, u16, &str)] = &[
            ("@-jid", 0x38FF, "命令格式: @-jid 登录帐号"),
            (
                "@DelDenyChrNameLogon",
                0x38FF,
                "命令格式: @DelDenyChrNameLogon 人物名称",
            ),
            ("@-jip", 0x38FF, "命令格式: @-jip IP地址"),
            ("@+jid", 0x38FF, "命令格式: @+jid 登录帐号 是否永久封(0,1)"),
            ("@+jid acct 1", 0xFFDB, "acct已加入禁止登录帐号列表"),
            ("@+jid acct 0", 0xFFDB, "acct已加入临时禁止登录帐号列表"),
            (
                "@DenyChrNameLogon",
                0x38FF,
                "命令格式: @DenyChrNameLogon 人物名称 是否永久封(0,1)",
            ),
            ("@DenyChrNameLogon 张三 1", 0xFFDB, "张三已加入禁止人物列表"),
            ("@+jip", 0x38FF, "命令格式: @+jip IP地址 是否永久封(0,1)"),
            ("@+jip 1.2.3.4", 0xFFDB, "1.2.3.4已加入临时禁止登录IP列表"),
            // 4 参才轮到 `@params[3]`。
            ("@+jip 1.2.3.4 a b 1", 0xFFDB, "1.2.3.4已加入禁止登录IP列表"),
        ];
        for (line, param, text) in cases {
            let frames = rig.say_gm(line);
            assert_eq!(frames.len(), 1, "{line} 一帧");
            let (got_param, got_text) = sysmsg_of(&rig, &frames[0]);
            assert_eq!(got_param, *param, "{line}");
            assert_eq!(&got_text, text, "{line}");
        }
        // 触表六命令：真机 NRE ⇒ 零帧 + log_note（SYSTEMSHARE_NULL_TABLE）。
        for line in [
            "@-jid acct",
            "@DelDenyChrNameLogon 张三",
            "@-jip 1.2.3.4",
            "@+-jid",
            "@ShowDenyCharNameLogon",
            "@+-jip",
        ] {
            let frames = rig.say_gm(line);
            assert!(frames.is_empty(), "{line} 应零帧");
        }
        // 2/3 参 ⇒ `@params[3]` 越界（catch 吞）⇒ 零帧。
        for line in ["@+jip 1.2.3.4 a", "@+jip 1.2.3.4 a b"] {
            assert!(rig.say_gm(line).is_empty(), "{line} 应零帧");
        }
        assert!(rig
            .sessions
            .get("aaa")
            .expect("rig 恒有 aaa")
            .gm
            .pending_clear_bag
            .is_none());
    }

    /// 重载/管理族 14 条（权限 10）：文本逐字节 + 零帧项。
    #[test]
    fn gm_batch2_reload_family_through_handle_say() {
        let mut rig = GmRig::new();
        let cases: &[(&str, u16, &str)] = &[
            ("@LoadAdmin", 0xFFDB, "管理员列表重新加载成功..."),
            ("@重读GM", 0xFFDB, "管理员列表重新加载成功..."),
            ("@ReloadGuildAll", 0x38FF, "重新加载行会信息完成."),
            ("@ReloadItemDB", 0xFFDB, "物品数据库重新加载完成。"),
            ("@ReloadMagicDB", 0xFFDB, "魔法数据库重新加载完成。"),
            ("@ReloadGuild", 0x38FF, "命令格式: @ReloadGuild 行会名称"),
            ("@ReloadGuild 血盟", 0x38FF, "未找到行会血盟!!!"),
            ("@重读公告", 0xFFDB, "重新加载公告设置信息完成。"),
            ("@重读爆率", 0xFFDB, "怪物爆物品列表重加载完成..."),
            ("@重读机器人脚本", 0xFFDB, "重新加载机器人配置完成..."),
            ("@重读机器人配置", 0xFFDB, "重新加载机器人专用脚本完成..."),
        ];
        for (line, param, text) in cases {
            let frames = rig.say_gm(line);
            assert_eq!(frames.len(), 1, "{line} 一帧");
            let (got_param, got_text) = sysmsg_of(&rig, &frames[0]);
            assert_eq!(got_param, *param, "{line}");
            assert_eq!(&got_text, text, "{line}");
        }
        // `@重读登陆`：两条 Green，顺序固定（登录脚本 → 功能脚本）。
        let frames = rig.say_gm("@重读登陆");
        assert_eq!(frames.len(), 2);
        let (param, text) = sysmsg_of(&rig, &frames[0]);
        assert_eq!(param, 0xFFDB);
        assert_eq!(text, "重新加载登录脚本完成...");
        let (param, text) = sysmsg_of(&rig, &frames[1]);
        assert_eq!(param, 0xFFDB);
        assert_eq!(text, "重新加载功能脚本完成...");
        // 零帧：空体 / 整段注释。
        for line in ["@ReloadAbuse", "@NpcScript", "@重读商人"] {
            assert!(rig.say_gm(line).is_empty(), "{line} 应零帧");
        }
    }

    /// 桩/测试族 7 条（权限 10）：文本逐字节、翻转副作用、数组越界零帧。
    #[test]
    fn gm_batch2_stub_family_through_handle_say() {
        let mut rig = GmRig::new();
        // `@TestGetBagItems`：`string.Format` 无 `{n}` 占位符 ⇒ 原文照发（Blue）。
        let frames = rig.say_gm("@TestGetBagItems");
        assert_eq!(frames.len(), 1);
        let (param, text) = sysmsg_of(&rig, &frames[0]);
        assert_eq!(param, 0xFCFB, "Blue = MakeWord(251,252)");
        assert_eq!(text, "DC:%d SC:%d MC:%d DURA:%d");
        // `@TestSpeedMode`：翻转 + Red。
        let frames = rig.say_gm("@TestSpeedMode");
        assert_eq!(
            sysmsg_of(&rig, &frames[0]),
            (0x38FF, "开启速度测试模式".into())
        );
        assert!(rig.sessions["aaa"].gm.test_speed_mode);
        let frames = rig.say_gm("@TestSpeedMode");
        assert_eq!(
            sysmsg_of(&rig, &frames[0]),
            (0x38FF, "关闭速度测试模式".into())
        );
        assert!(!rig.sessions["aaa"].gm.test_speed_mode);
        // `@TestStatus`：合法下标一帧；越界零帧。
        let frames = rig.say_gm("@TestStatus 3 60");
        assert_eq!(frames.len(), 1);
        let (param, text) = sysmsg_of(&rig, &frames[0]);
        assert_eq!(param, 0xFFDB);
        assert_eq!(text, "状态编号:3 时间长度: 60 秒");
        for line in ["@TestStatus 15 1", "@TestStatus -1 1"] {
            assert!(rig.say_gm(line).is_empty(), "{line} 应零帧（数组越界）");
        }
        // `@FireBurn`：任一参数 0 ⇒ Red 帮助（Help 为 null ⇒ 尾随空格）。
        let frames = rig.say_gm("@FireBurn 1 0 1");
        assert_eq!(frames.len(), 1);
        let (param, text) = sysmsg_of(&rig, &frames[0]);
        assert_eq!(param, 0x38FF);
        assert_eq!(text, "命令格式: @FireBurn ");
        // 零帧：事件队列宿主 / 空体。
        for line in [
            "@TestFire 3 1 5 10",
            "@UserCmd anylabel",
            "@Backstep 3 5",
            "@FireBurn 1 1 1",
        ] {
            assert!(rig.say_gm(line).is_empty(), "{line} 应零帧");
        }
    }

    /// 在线登记在**进世界成功**时落坐标，断线/踢旧时被 `online_take` 拿走（名字精确匹配）。
    #[test]
    fn online_registry_set_and_take() {
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("a", "lb1a", 1, 0, 901, 5));
        online_set(&mut online, entry("a", "lb1a", 1, 2, 903, 5)); // 同名刷新（重进世界）只有一条
        assert_eq!(online.len(), 1);
        assert_eq!(online_take(&mut online, "lb1a").unwrap().socket, 903);
        assert!(online_take(&mut online, "lb1a").is_none());
        assert!(online.is_empty());
    }

    /// **登记序**：`OnlineRegistry` 是 `Vec`，广播/可见集/顶号都依赖**插入序**。
    /// 保序索引（`Vec` + `HashMap<_, usize>`）改造后，本断言必须仍然绿。
    ///
    /// 红检（结构改错）：把迭代改成走 `HashMap` 键序 ⇒ 本用例必红。
    #[test]
    fn online_registry_preserves_registration_order() {
        let mut online: OnlineRegistry = OnlineRegistry::new();
        // actor_id 故意**非单调**：若实现偷偷按 id 排序或走哈希序，序列会变。
        online_set(&mut online, entry("a", "ca", 1, 0, 901, 30));
        online_set(&mut online, entry("b", "cb", 2, 0, 902, 10));
        online_set(&mut online, entry("c", "cc", 3, 1, 903, 20));
        let order: Vec<i32> = online.iter().map(|e| e.actor_id).collect();
        assert_eq!(
            order,
            vec![30, 10, 20],
            "登记序必须等于插入序（保序索引不得改变遍历序）"
        );
    }

    /// **摘除保序**：`online_take` 必须用 `Vec::remove`（搬移其余元素），**不能** `swap_remove`。
    ///
    /// **为什么必须 4 个元素**：3 个元素取中间时 `Vec::remove` 与 `swap_remove` 的结果**相同**
    /// （`[30,10,20]` 取 10 都得 `[30,20]`）⇒ 用例会假绿；4 个元素才能区分
    /// （期望 `[30,20,40]`，`swap_remove` 会给 `[30,40,20]`）。**不要把人简化回 3 个元素。**
    ///
    /// 红检：把 `online_take` 的 `Vec::remove` 换成 `swap_remove` ⇒ 本用例必红。
    #[test]
    fn online_take_keeps_order() {
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("a", "t30", 1, 0, 901, 30));
        online_set(&mut online, entry("b", "t10", 2, 0, 902, 10));
        online_set(&mut online, entry("c", "t20", 3, 0, 903, 20));
        online_set(&mut online, entry("d", "t40", 4, 0, 904, 40));
        let taken = online_take(&mut online, "t10").expect("中间那条必须取得到");
        assert_eq!(taken.actor_id, 10);
        let order: Vec<i32> = online.iter().map(|e| e.actor_id).collect();
        assert_eq!(
            order,
            vec![30, 20, 40],
            "摘除中间元素后其余必须保持原序（swap_remove 会得到 [30,40,20]）"
        );
    }

    /// **顶号取最小下标**（O-3 裁决语义）：同一账号在某网关上的多条登记，`online_find_for_kick`
    /// 必须返回该网关**登记序首个**（= 最小下标），且**按网关分桶**、桶内仍按登记序。
    ///
    /// 红检：改成"取最后一个"或"全局首个/无序"⇒ 本用例必红。
    #[test]
    fn online_kick_prefers_first_registered() {
        let mut online: OnlineRegistry = OnlineRegistry::new();
        // 同账号、同网关两条（不同 chr_name 才不会被子刷掉），后登记者 socket 更大。
        online_set(&mut online, entry("k", "k1", 1, 0, 901, 1));
        online_set(&mut online, entry("k", "k2", 2, 0, 902, 2));
        let t = online_find_for_kick(&online, "k", 1);
        assert_eq!(t.len(), 1, "同一网关只踢第一个");
        assert_eq!(t[0].socket, 901, "必须是**先登记**的那条（最小下标）");
        // 桶隔离：另一网关也要各返回自己的首个，且整体按登记序。
        online_set(&mut online, entry("k", "k3", 3, 1, 903, 3));
        let t2 = online_find_for_kick(&online, "k", 1);
        let socks: Vec<i32> = t2.iter().map(|e| e.socket).collect();
        assert_eq!(
            socks,
            vec![901, 903],
            "每网关各一条、按登记序（gate0 先于 gate1）"
        );
    }

    /// **OnlineRegistry 索引模型对账**：随机 `set`/`take` 序列 2000 步，**每一步之后**把
    /// `by_actor`/`by_chr` 与 `entries` 逐项对账——这是「索引与 Vec 永远一致」这条不变量的
    /// 可执行版本（不是注释）。
    ///
    /// 红检（索引同步缺失）：删掉 `OnlineRegistry::take` 里的 `self.rebuild();` ⇒
    /// 第一次 `take` 之后两个 map 的长度/下标立即与 Vec 不符 ⇒ 本用例红。
    #[test]
    fn online_index_matches_vec_under_random_set_take() {
        fn assert_same(online: &OnlineRegistry) {
            assert_eq!(
                online.by_chr.len(),
                online.entries.len(),
                "by_chr 与 entries 条数不等"
            );
            assert_eq!(
                online.by_actor.len(),
                online.entries.len(),
                "by_actor 与 entries 条数不等"
            );
            for (pos, e) in online.entries.iter().enumerate() {
                assert_eq!(
                    online.by_chr.get(&e.chr_name),
                    Some(&pos),
                    "by_chr[{:?}] 下标不符",
                    e.chr_name
                );
                assert_eq!(
                    online.by_actor.get(&i64::from(e.actor_id)),
                    Some(&pos),
                    "by_actor[{}] 下标不符",
                    e.actor_id
                );
            }
        }
        let mut online = OnlineRegistry::new();
        let mut state: u64 = 0x9e37_79b9_7f4a_7c15;
        let mut next = || {
            state = state
                .wrapping_mul(6364136223846793005)
                .wrapping_add(1442695040888963407);
            (state >> 33) as u32
        };
        for step in 0..2000u32 {
            // chr 与 actor_id 一一对应（1000+n），保证两个 map 的条数可逐项对账；chr 序故意
            // 随机（非单调），换名/随机取都覆盖。
            let n = next() % 40;
            let chr = format!("ridx{n}");
            if next() % 3 != 0 {
                online.set(entry("acct", &chr, 1, 0, 900 + n as i32, 1000 + n as i32));
            } else {
                let expected = online
                    .entries
                    .iter()
                    .position(|e| e.chr_name == chr)
                    .map(|pos| online.entries[pos].clone());
                let got = online.take(&chr);
                assert_eq!(
                    got, expected,
                    "第 {step} 步 take({chr}) 返回值与线性 position 不等"
                );
            }
            assert_same(&online);
        }
        // 收尾：索引查找必须与线性查找逐项一致（含未命中）。
        for n in 0..40 {
            let chr = format!("ridx{n}");
            assert_eq!(
                online.find_by_chr(&chr).map(|e| e.actor_id),
                online
                    .entries
                    .iter()
                    .find(|e| e.chr_name == chr)
                    .map(|e| e.actor_id),
                "find_by_chr({chr}) 与线性不等"
            );
            assert_eq!(
                online.find_by_actor(1000 + n).map(|e| e.chr_name.clone()),
                online
                    .entries
                    .iter()
                    .find(|e| e.actor_id == 1000 + n)
                    .map(|e| e.chr_name.clone()),
                "find_by_actor({}) 与线性不等",
                1000 + n
            );
        }
    }

    /// **同名 `set` 必须把 `by_chr` 指向被替换后的条目**（不是残留旧下标）。随机对账测试可能
    /// 覆盖也可能没覆盖这条路径；本用例是**具名**的，失败信息直接可读。
    #[test]
    fn online_set_same_chr_repoints_index_to_replaced_entry() {
        let mut online = OnlineRegistry::new();
        online.set(entry("a", "same", 1, 0, 901, 10));
        online.set(entry("a", "same", 1, 2, 902, 20)); // 同名刷新（重进世界）
        assert_eq!(online.entries.len(), 1, "同名只保留一条");
        assert_eq!(online.entries[0].socket, 902, "保留后写的那条");
        assert_eq!(
            online.by_chr.get("same"),
            Some(&0),
            "by_chr 必须指向被替换后的唯一条目"
        );
        assert_eq!(
            online.find_by_chr("same").map(|e| e.actor_id),
            Some(20),
            "find_by_chr 必须命中新条目"
        );
        assert_eq!(
            online.find_by_actor(20).map(|e| e.socket),
            Some(902),
            "新 actor_id 必须可查"
        );
        assert!(
            online.find_by_actor(10).is_none(),
            "旧 actor_id 不得残留可查（索引必须重指）"
        );
    }

    /// **`take` 未命中是零副作用**：返回 `None`，`entries` 与两个索引（长度、下标、条目）全不变。
    /// 专防"rebuild 后恰好一样"式的假正确：这里要求**未命中路径根本不触碰索引**。
    #[test]
    fn online_take_absent_key_is_noop_for_entries_and_indexes() {
        let mut online = OnlineRegistry::new();
        for (i, chr) in ["t1", "t2", "t3", "t4"].iter().enumerate() {
            online.set(entry("acct", chr, 1, 0, 900 + i as i32, 100 + i as i32));
        }
        let entries_before = online.entries.clone();
        let by_actor_before = online.by_actor.clone();
        let by_chr_before = online.by_chr.clone();
        assert_eq!(online.take("no-such-chr"), None, "未命中必须返回 None");
        assert_eq!(online.entries, entries_before, "entries 不得被改动");
        assert_eq!(online.by_actor, by_actor_before, "by_actor 不得被改动");
        assert_eq!(online.by_chr, by_chr_before, "by_chr 不得被改动");
    }

    /// **探针 fail-closed**：`MIR2_PERF_COUNTERS` 设了但一个 tick 行都没写 ⇒ `finish()` Err
    /// （`sim_loop` 把它转成 rc≠0）；写一条后 Ok。默认关闭时 `bump` 必须是纯 no-op。
    #[test]
    fn perf_counters_fail_closed_and_disabled_noop() {
        // 与 `zone_router` 的计数器用例共用一把锁：两边都开关全局 `ENABLED`。
        let _g = crate::perf_counters::TEST_LOCK
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        use std::sync::atomic::Ordering;

        let dir = std::env::temp_dir();
        let p = dir.join(format!("d8_perf_counters_{}.tsv", std::process::id()));
        let _ = std::fs::remove_file(&p);

        // 1) 默认关闭：bump 是 no-op（不分配、不加计数）。
        let before = crate::perf_counters::ACTOR_INDEXED.load(Ordering::Relaxed);
        crate::perf_counters::bump(&crate::perf_counters::ACTOR_INDEXED);
        assert_eq!(
            before,
            crate::perf_counters::ACTOR_INDEXED.load(Ordering::Relaxed),
            "关闭态 bump 必须 no-op"
        );

        // 2) 打不开的路径 ⇒ Err（启动 fail-closed 的来源）。
        let bad = dir.join("d8_probe_no_such_dir").join("x.tsv");
        assert!(
            crate::perf_counters::init_with_path(&bad).is_err(),
            "不可写路径必须报错"
        );

        // 3) env 设了但 0 tick 行 ⇒ finish Err（rc≠0 的来源）。
        std::env::set_var("MIR2_PERF_COUNTERS", &p);
        assert!(
            crate::perf_counters::init_from_env().expect("env 路径可建"),
            "env 设了应启用"
        );
        let err = crate::perf_counters::finish().expect_err("0 tick 行必须 fail-closed");
        assert!(
            err.contains("0 个 tick 行"),
            "错误必须点名 fail-closed：{err}"
        );

        // 4) 写一条 tick ⇒ Ok；文件 = 表头 + 1 行。
        crate::perf_counters::write_tick();
        crate::perf_counters::finish().expect("有 tick 行应通过");
        let text = std::fs::read_to_string(&p).expect("探针文件可读");
        assert_eq!(text.lines().count(), 2, "表头 + 1 行 tick：{text:?}");

        std::env::remove_var("MIR2_PERF_COUNTERS");
        crate::perf_counters::reset_for_tests();
        let _ = std::fs::remove_file(&p);
    }

    /// **follow-up 牙**：TSV 表头新增 `depart_frames_mirror_suppressed` 后，表头与每行的
    /// **列数必须一致**，且计数落在**同名列**上（防「表头/值错位」复发；2026-11-23 之前踩过）。
    ///
    /// 变异：只加表头不加值（或反之）⇒ 列数不等 ⇒ 红；值写错位置 ⇒ 同名列断言红。
    #[test]
    fn perf_tsv_header_matches_values_with_new_column() {
        let _g = crate::perf_counters::TEST_LOCK
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let dir = std::env::temp_dir();
        let p = dir.join(format!("d8_perf_cols_{}.tsv", std::process::id()));
        let _ = std::fs::remove_file(&p);
        std::env::set_var("MIR2_PERF_COUNTERS", &p);
        crate::perf_counters::init_from_env().expect("env 路径可建");
        crate::perf_counters::note_depart_frames_mirror_suppressed();
        crate::perf_counters::note_depart_frames_mirror_suppressed();
        crate::perf_counters::write_tick();
        crate::perf_counters::finish().expect("有 tick 行应通过");
        std::env::remove_var("MIR2_PERF_COUNTERS");
        let text = std::fs::read_to_string(&p).expect("探针文件可读");
        let mut lines = text.lines();
        let header: Vec<&str> = lines.next().expect("表头").split('\t').collect();
        let values: Vec<&str> = lines.next().expect("tick 行").split('\t').collect();
        assert_eq!(header.len(), values.len(), "表头/值列数必须相等：{text:?}");
        let idx = header
            .iter()
            .position(|h| *h == "depart_frames_mirror_suppressed")
            .expect("表头必须含新列 depart_frames_mirror_suppressed");
        assert_eq!(
            values[idx],
            "2",
            "新列值必须落在同名列上（bump 2 次）；实际列={:?}",
            values.get(idx)
        );
        crate::perf_counters::reset_for_tests();
        let _ = std::fs::remove_file(&p);
    }

    /// **MP-1 微基准（算法级证据，不是端到端收益）**：`OnlineRegistry` 线性查找 vs 旁挂索引。
    ///
    /// 只测「单次查找」的复杂度：n ∈ {986, 2800}、命中/未命中各半、各 1e5 次查找，median-3。
    /// **不证明 tick 收益**——端到端需要「真实 `sim_loop` 每 tick 调用次数 × 单次耗时」探针（另立卡）。
    /// 另：`simmonsterai_bench_tiers` **不经过** `OnlineRegistry`（该文件无 `online` 引用），
    /// 不能拿它当收益证据（见 `docs/issues/single-thread-lookup-inventory-20261121.md` §5）。
    ///
    /// 红检：索引臂若未比线性快 ≥5× ⇒ panic（结构改了但没吃上索引 / 索引退化成线性）。
    #[test]
    #[ignore = "微基准：需 MIR2_PERF_MICRO=1 + --ignored --nocapture"]
    fn online_lookup_micro_index_vs_linear() {
        use std::hint::black_box;

        if std::env::var("MIR2_PERF_MICRO").ok().as_deref() != Some("1") {
            eprintln!("MIR2_PERF_MICRO != 1 不跑微基准");
            return;
        }
        const ITERS: u64 = 100_000;
        const REPEATS: usize = 3;
        const MIN_SPEEDUP: f64 = 5.0;

        fn build(n: usize) -> OnlineRegistry {
            let mut r = OnlineRegistry::new();
            for i in 0..n {
                r.set(entry(
                    "acct",
                    &format!("m{i}"),
                    1,
                    0,
                    900 + (i % 100) as i32,
                    10_000 + i as i32,
                ));
            }
            r
        }

        fn median3(mut v: [u128; REPEATS]) -> u128 {
            v.sort_unstable();
            v[REPEATS / 2]
        }

        fn time<F: FnOnce() -> u64>(f: F) -> u128 {
            let t = std::time::Instant::now();
            black_box(f());
            t.elapsed().as_nanos()
        }

        // 探针开销 A/B：`MIR2_PERF_COUNTERS` 设了就在测量期间启用（只影响本次 ignored 测试）。
        let probe_on = std::env::var("MIR2_PERF_COUNTERS")
            .map(|v| !v.trim().is_empty())
            .unwrap_or(false);
        if probe_on {
            crate::perf_counters::init_from_env().expect("探针启用失败");
            println!("# PROBE_ENABLED=1（本次 ns 含计数开销）");
        }
        println!("# online_lookup_micro iters={ITERS}（命中/未命中各半）repeats={REPEATS}");
        let mut failures: Vec<String> = Vec::new();
        for &n in &[986usize, 2_800usize] {
            let r = build(n);
            // **键预构造**：format! 不放进计时循环（否则测的是分配器，不是查找）。
            // 偶数下标是命中键（m{i} / actor 10_000+i），奇数下标是未命中键。
            let keys: Vec<(i32, String)> = (0..n)
                .map(|i| {
                    if i % 2 == 0 {
                        (10_000 + i as i32, format!("m{i}"))
                    } else {
                        (-1 - i as i32, format!("miss{i}"))
                    }
                })
                .collect();

            let lin_actor: [u128; REPEATS] = std::array::from_fn(|_| {
                time(|| {
                    let mut sum = 0u64;
                    for k in 0..ITERS as usize {
                        let (aid, _) = &keys[k % n];
                        sum += r
                            .entries
                            .iter()
                            .find(|e| e.actor_id == *aid)
                            .map_or(0, |e| e.socket as u64);
                    }
                    sum
                })
            });
            let idx_actor: [u128; REPEATS] = std::array::from_fn(|_| {
                time(|| {
                    let mut sum = 0u64;
                    for k in 0..ITERS as usize {
                        let (aid, _) = &keys[k % n];
                        sum += r.find_by_actor(*aid).map_or(0, |e| e.socket as u64);
                    }
                    sum
                })
            });
            let lin_chr: [u128; REPEATS] = std::array::from_fn(|_| {
                time(|| {
                    let mut sum = 0u64;
                    for k in 0..ITERS as usize {
                        let (_, chr) = &keys[k % n];
                        sum += r
                            .entries
                            .iter()
                            .find(|e| e.chr_name == *chr)
                            .map_or(0, |e| e.socket as u64);
                    }
                    sum
                })
            });
            let idx_chr: [u128; REPEATS] = std::array::from_fn(|_| {
                time(|| {
                    let mut sum = 0u64;
                    for k in 0..ITERS as usize {
                        let (_, chr) = &keys[k % n];
                        sum += r.find_by_chr(chr).map_or(0, |e| e.socket as u64);
                    }
                    sum
                })
            });

            let (la, ia) = (median3(lin_actor), median3(idx_actor));
            let (lc, ic) = (median3(lin_chr), median3(idx_chr));
            let per = |total: u128| total as f64 / ITERS as f64;
            let sp_actor = la as f64 / ia.max(1) as f64;
            let sp_chr = lc as f64 / ic.max(1) as f64;
            println!(
                "n={n}: actor linear={:.2} ns/lookup index={:.2} ns/lookup speedup={:.1}x；                 chr linear={:.2} ns/lookup index={:.2} ns/lookup speedup={:.1}x",
                per(la),
                per(ia),
                sp_actor,
                per(lc),
                per(ic),
                sp_chr
            );
            println!(
                "        总量 median-3：actor linear={la} ns index={ia} ns；chr linear={lc} ns index={ic} ns"
            );
            if sp_actor < MIN_SPEEDUP {
                failures.push(format!(
                    "n={n} actor 加速仅 {sp_actor:.2}x < {MIN_SPEEDUP}x（linear {la} ns / index {ia} ns，{ITERS} 次）"
                ));
            }
            if sp_chr < MIN_SPEEDUP {
                failures.push(format!(
                    "n={n} chr 加速仅 {sp_chr:.2}x < {MIN_SPEEDUP}x（linear {lc} ns / index {ic} ns，{ITERS} 次）"
                ));
            }
        }
        assert!(
            failures.is_empty(),
            "索引臂未达到 ≥{MIN_SPEEDUP}x（结构改了但没吃上索引？）：\n{}",
            failures.join("\n")
        );
        if probe_on {
            crate::perf_counters::reset_for_tests();
        }
    }

    /// **探针自身开销**：`write_tick` 关闭态 vs 启用态（启用 = format + 写一行到文件）。
    /// 只在 `MIR2_PERF_MICRO=1` 时跑；输出 ns/tick。
    #[test]
    #[ignore = "微基准：需 MIR2_PERF_MICRO=1 + --ignored --nocapture"]
    fn perf_counters_write_tick_cost() {
        use std::hint::black_box;

        if std::env::var("MIR2_PERF_MICRO").ok().as_deref() != Some("1") {
            eprintln!("MIR2_PERF_MICRO != 1 不跑微基准");
            return;
        }
        // 关闭态：1e6 次（每次 = 一次原子读 + 分支）。
        let t = std::time::Instant::now();
        for _ in 0..1_000_000u32 {
            crate::perf_counters::write_tick();
            black_box(());
        }
        let off_ns = t.elapsed().as_nanos() as f64 / 1_000_000.0;
        // 启用态：1e4 次真实写入（含 format + write_all）。
        let p = std::env::temp_dir().join(format!("d8_write_tick_cost_{}.tsv", std::process::id()));
        let _ = std::fs::remove_file(&p);
        crate::perf_counters::init_with_path(&p).expect("探针文件可建");
        let t = std::time::Instant::now();
        for _ in 0..10_000u32 {
            crate::perf_counters::write_tick();
        }
        let on_ns = t.elapsed().as_nanos() as f64 / 10_000.0;
        crate::perf_counters::reset_for_tests();
        let _ = std::fs::remove_file(&p);
        println!(
            "# write_tick disabled={off_ns:.2} ns/call enabled={on_ns:.0} ns/call（1 行/tick）"
        );
    }

    /// **`CM_SAY` 普通说话**：与 oracle `SendRefMsg`（`BaseObject.Message.cs:395-440`）同集合 ——
    /// ±`SendRefMsgRange`(12) 格内、同图、`Race==Play && !Ghost` 的 actor，**含说话者自己**。
    /// 帧 = 12B 头（`Recog=说话者 ActorId`、`Ident=SM_HEAR(40)`、`Param=MakeWord(F,B)`、`Tag=0`、
    /// `Series=1`）+ 尾 `EncodeString("aaa:hi")`。
    ///
    /// 红检：把 `chat::hear_targets` 的"含自己"去掉（或把 `sm_hear` 的 `Series` 改 0 / `Ident` 改错）
    /// ⇒ 本用例必红。
    #[test]
    fn say_broadcasts_hear_to_self_and_near_players_only() {
        use std::collections::HashMap;
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let (tx1, mut rx1) = mpsc::unbounded_channel::<SimToGate>();
        let (tx2, mut rx2) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        gates.insert(1, tx1);
        gates.insert(2, tx2);

        let mut world = mir2_world_bevy::World::with_maps(vec![(64, 64), (64, 64)]);
        let mut mk = |name: &str, x: i32, y: i32, map_id: usize| {
            let mut e = mir2_world_bevy::EntitySpawn::new(0, name.to_string(), x, y);
            e.race = mir2_world_bevy::ACTOR_RACE_PLAY;
            e.map_id = map_id;
            world.add_entity(e)
        };
        let a = mk("aaa", 10, 10, 0); // 说话者
        let b = mk("bbb", 12, 12, 0); // dx=dy=12 ⇒ 边界内
        let c = mk("ccc", 11, 11, 1); // 另一张图 ⇒ 不收

        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("a", "aaa", 1, 0, 901, a));
        online_set(&mut online, entry("b", "bbb", 2, 1, 902, b));
        online_set(&mut online, entry("c", "ccc", 3, 2, 903, c));

        let colors = MsgColors {
            red_f: 0xFF,
            red_b: 0x38,
            hear_f: 0x00,
            hear_b: 0xFF,
            whisper_f: 0,
            whisper_b: 0,
            green_f: 0xDB,
            green_b: 0xFF,
            blue_f: 0xFF,
            blue_b: 0xFC,
        };
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        for (name, id) in [("aaa", a), ("bbb", b), ("ccc", c)] {
            sessions.insert(name.to_string(), test_session_ground(id));
        }
        let ctx = TestChatCtx::new();
        let host = ctx.host(&online, &world, &gates, &colors);
        handle_say(&host, &mut sessions, "aaa", 901, Some("hi"));

        let check =
            |rx: &mut mpsc::UnboundedReceiver<SimToGate>, want_sock: i32| match rx.try_recv() {
                Ok(SimToGate::SendFrame { socket, body }) => {
                    assert_eq!(socket, want_sock);
                    assert_eq!(body.len(), 12 + 8, "12B 头 + Encode(\"aaa:hi\")(8)");
                    assert_eq!(
                        i32::from_le_bytes([body[0], body[1], body[2], body[3]]),
                        a,
                        "Recog = 说话者 ActorId（BaseObject.Message.cs:154）"
                    );
                    assert_eq!(
                        u16::from_le_bytes([body[4], body[5]]),
                        mir2_protocol::messages::SM_HEAR,
                        "Ident = SM_HEAR(40)"
                    );
                    assert_eq!(
                        u16::from_le_bytes([body[6], body[7]]),
                        0xFF00,
                        "Param = MakeWord(FColor=0x00, BColor=0xFF)"
                    );
                    assert_eq!(u16::from_le_bytes([body[8], body[9]]), 0, "Tag=0");
                    assert_eq!(u16::from_le_bytes([body[10], body[11]]), 1, "Series=1");
                    assert_eq!(
                        mir2_protocol::edcode::decode(&body[12..]),
                        b"aaa:hi".to_vec(),
                        "尾 = EncodeString(ChrName + ':' + sMsg)"
                    );
                }
                _ => panic!("socket={want_sock} 未收到 SM_HEAR"),
            };
        check(&mut rx0, 901); // 自己（客户端靠这条回声渲染自己发的话）
        check(&mut rx1, 902); // 边界内近邻
        assert!(rx2.try_recv().is_err(), "另一张图的角色不该收到普通说话");
    }

    /// **卡 `openmir2-sendrefmsg-range-config` 判据②（生产路径）**：`[Setup] SendRefMsgRange=15`
    /// ⇒ `CM_SAY` 的 `SendRefMsg(RM_HEAR)` 收件人集合按 **15** 格算：12 格外、15 格内的玩家
    /// **能收到**，16 格不收。配置值经 `config::load` 真读文件（不是常量 12），再经生产安装点
    /// `sim_loop` 的 `chat::install_send_ref_msg_range(enter_cfg.ref_msg_range)` →
    /// `chat::send_ref_msg_range()`（所有生产广播消费点读它）。
    ///
    /// 本用例用 [`chat::with_send_ref_msg_range`] 注入**同一来源**的配置值（线程本地，避免并行
    /// 串扰）；`config::load` 已把「文件 → 15」这步钉住（缺键 ③ 面见
    /// `chat::send_ref_msg_range_defaults_to_oracle_default_12`）。
    ///
    /// 齿说明：本用例走线程本地覆盖（不碰进程全局）；「安装值被忽略」这一面由独立进程的集成用例
    /// `tests/sendrefmsg_range_config.rs` 咬住（把 `chat::send_ref_msg_range()` 改回常量
    /// `SEND_REF_MSG_RANGE`=12 ⇒ 该用例红）。本用例钉的是**生产消费点**真的读生效值。
    #[test]
    fn say_recipients_follow_configured_send_ref_msg_range() {
        use std::collections::HashMap;
        // ① 真读配置：部署同款键 `[Setup] SendRefMsgRange=15`（**不是**常量 12）。
        let dir = std::env::temp_dir().join(format!("gs-srmr-{}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("临时目录");
        let p = dir.join("Server.conf");
        std::fs::write(
            &p,
            "[Server]
GateAddr=127.0.0.1
GatePort=5000
CheckBlock=12288
             IDSAddr=127.0.0.1
IDSPort=5600
DBAddr=127.0.0.1
DBPort=6000
             [Setup]
SendRefMsgRange=15
",
        )
        .expect("写临时 Server.conf");
        let cfg = crate::config::load(&p).expect("解析 Server.conf");
        assert_eq!(
            cfg.send_ref_msg_range, 15,
            "[Setup] SendRefMsgRange=15 必须解析为 15"
        );
        let range = i32::from(cfg.send_ref_msg_range);

        // ② 生产路径：说话者 a（10,10）+ 13/15/16 格邻居。
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let (tx1, mut rx1) = mpsc::unbounded_channel::<SimToGate>();
        let (tx2, mut rx2) = mpsc::unbounded_channel::<SimToGate>();
        let (tx3, mut rx3) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        gates.insert(1, tx1);
        gates.insert(2, tx2);
        gates.insert(3, tx3);

        let mut world = mir2_world_bevy::World::new(64, 64);
        let mut mk = |name: &str, x: i32, y: i32| {
            let mut e = mir2_world_bevy::EntitySpawn::new(0, name.to_string(), x, y);
            e.race = mir2_world_bevy::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        let a = mk("aaa", 10, 10);
        let d13 = mk("d13", 23, 10);
        let d15 = mk("d15", 25, 10);
        let d16 = mk("d16", 26, 10);

        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("a", "aaa", 1, 0, 901, a));
        online_set(&mut online, entry("b", "d13", 2, 1, 902, d13));
        online_set(&mut online, entry("c", "d15", 3, 2, 903, d15));
        online_set(&mut online, entry("d", "d16", 4, 3, 904, d16));

        let colors = MsgColors {
            red_f: 0xFF,
            red_b: 0x38,
            hear_f: 0x00,
            hear_b: 0xFF,
            whisper_f: 0,
            whisper_b: 0,
            green_f: 0xDB,
            green_b: 0xFF,
            blue_f: 0xFF,
            blue_b: 0xFC,
        };
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        for (name, id) in [("aaa", a), ("d13", d13), ("d15", d15), ("d16", d16)] {
            sessions.insert(name.to_string(), test_session_ground(id));
        }
        let ctx = TestChatCtx::new();
        let host = ctx.host(&online, &world, &gates, &colors);
        chat::with_send_ref_msg_range(range, || {
            handle_say(&host, &mut sessions, "aaa", 901, Some("hi"));
        });

        let want_hear = |rx: &mut mpsc::UnboundedReceiver<SimToGate>, sock: i32, what: &str| {
            match rx.try_recv() {
                Ok(SimToGate::SendFrame { socket, body }) => {
                    assert_eq!(socket, sock, "{what}");
                    assert_eq!(
                        u16::from_le_bytes([body[4], body[5]]),
                        mir2_protocol::messages::SM_HEAR,
                        "{what}"
                    );
                }
                _ => panic!("{what}：socket={sock} 必须收到 SM_HEAR"),
            }
        };
        want_hear(&mut rx0, 901, "说话者自己（echo）");
        want_hear(&mut rx1, 902, "13 格邻居（15 > 13）");
        want_hear(&mut rx2, 903, "15 格邻居（恰在边界）");
        assert!(rx3.try_recv().is_err(), "16 格邻居（15 < 16）不得收到");
        assert!(
            rx0.try_recv().is_err() && rx1.try_recv().is_err() && rx2.try_recv().is_err(),
            "每个收件人恰一条 SM_HEAR"
        );
        std::fs::remove_dir_all(&dir).ok();
    }

    /// **I-1（review `d8519c00`）接线点保鲜门**：`[Setup] SendRefMsgRange` 的**生产安装行**
    /// ——`sim_loop` 启动处的 `chat::install_send_ref_msg_range(enter_cfg.ref_msg_range)`——
    /// 必须仍在且**未被注释**，且其配置来源 `EnterConfig` 的装配行
    /// `ref_msg_range: i32::from(cfg.send_ref_msg_range)`（`run_inner` 构造 `EnterConfig` 处）
    /// 不得被删/改回常量。
    ///
    /// 背景（复审自造牙，实测）：把 `sim_loop` 里的安装行注释掉，全测试套件**无一变红**
    /// （`sim_loop` 需真机/DB 才能驱到，进程内用例无法直达其函数体）⇒ 本卡要消灭的
    /// 「改配置静默分叉」在「安装行被删」这条路径上仍成立。本用例用 [`include_str!`]
    /// 把本文件源码嵌入，对该调用点、其位置（`sim_loop` 体内、首个消费点之前）与
    /// 装配行形状做锚点保鲜断言（口径同 `login_tail_production_call_is_wired_after_aoi` /
    /// `drain_deal_tick_production_call_is_wired_in_sim_loop`）。**非行为覆盖**——行为面
    /// 由 `say_recipients_follow_configured_send_ref_msg_range` 与集成进程
    /// `tests/sendrefmsg_range_config.rs` 承担。
    ///
    /// 红检（**实测**）：把安装行用 `//` 注释 ⇒ 本用例红（调用行 trim 不再相等）；
    /// 把装配行改回字面量 `12` ⇒ 红（trim 行缺失）；复原 ⇒ 绿。
    #[test]
    fn sendrefmsg_range_install_call_is_wired_in_sim_loop() {
        let src = include_str!("lib.rs");
        let lines: Vec<&str> = src.lines().collect();
        // ① 生产安装行（trim 恰等 ⇒ `//`/`/*` 注释、改实参都会脱靶）。
        let install: Vec<usize> = lines
            .iter()
            .enumerate()
            .filter(|(_, l)| {
                l.trim() == "chat::install_send_ref_msg_range(enter_cfg.ref_msg_range);"
            })
            .map(|(i, _)| i)
            .collect();
        assert_eq!(
            install.len(),
            1,
            "sim_loop 的 SendRefMsgRange 生产安装行必须恰 1 处且未被注释"
        );
        // ② 位置：必须在 `sim_loop` 函数体内（签名之后）、首个配置消费点 `npc_vars_from` 之前。
        let sim_loop = lines
            .iter()
            .position(|l| l.trim_start().starts_with("fn sim_loop("))
            .expect("sim_loop 定义");
        let first_consumer = lines
            .iter()
            .position(|l| l.contains("let mut npc_vars_base = npc_vars_from("))
            .expect("sim_loop 内首个配置消费点");
        assert!(
            sim_loop < install[0] && install[0] < first_consumer,
            "安装行必须落在 sim_loop 启动段（签名之后、首个配置消费点之前），实得 {}（sim_loop={} consumer={}）",
            install[0] + 1,
            sim_loop + 1,
            first_consumer + 1
        );
        // ③ 配置来源装配行（`EnterConfig.ref_msg_range` ← `[Setup] SendRefMsgRange`）。
        //    `ShopCfg.send_ref_msg_range` 的行 trim 后带 `send_` 前缀 ⇒ 不会误命中。
        let wired: Vec<usize> = lines
            .iter()
            .enumerate()
            .filter(|(_, l)| l.trim() == "ref_msg_range: i32::from(cfg.send_ref_msg_range),")
            .map(|(i, _)| i)
            .collect();
        assert_eq!(
            wired.len(),
            1,
            "EnterConfig.ref_msg_range 必须从 cfg.send_ref_msg_range 装配（恰 1 处、未改回常量）"
        );
        assert!(
            wired[0] < sim_loop,
            "装配行应属于 run_inner 构造 EnterConfig（在 sim_loop 定义之前）"
        );
    }

    /// **orphan 编码器接线首批**：`/目标名 正文` 私聊 ⇒ `SM_WHISPER(103)`
    /// （oracle `PlayObject.Chat.cs:57` 的非 GM 支）。
    ///
    /// 帧 = 12B 头（`Recog` = **收件人** ActorId、`Ident = SM_WHISPER(103)`、
    /// `Param = MakeWord(WhisperFColor, WhisperBColor)`、`Tag = 0`、`Series = 1`）
    /// + 尾 `EncodeString("<说话者>=> <正文>")`；**只发收件人**（oracle 不回声给说话者）。
    ///
    /// 红检：把 [`handle_whisper`] 的收件人改成说话者、或把 [`chat::whisper_text`] 的 `"=> "` 去掉
    /// ⇒ 本用例必红。
    #[test]
    fn whisper_slash_line_sends_sm_whisper_to_target_only() {
        use std::collections::HashMap;
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let (tx1, mut rx1) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        gates.insert(1, tx1);

        let mut world = mir2_world_bevy::World::new(64, 64);
        world.open_session("aaa");
        let a = world
            .enter_map(
                "aaa",
                mir2_world_bevy::EntitySpawn::new(0, "aaa".to_string(), 10, 10),
                0,
            )
            .expect("说话者进图");
        world.open_session("bbb");
        let b = world
            .enter_map(
                "bbb",
                mir2_world_bevy::EntitySpawn::new(0, "bbb".to_string(), 30, 30),
                0,
            )
            .expect("目标进图");

        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("a", "aaa", 1, 0, 901, a));
        online_set(&mut online, entry("b", "bbb", 2, 1, 902, b));

        let colors = MsgColors {
            red_f: 0,
            red_b: 0,
            hear_f: 0,
            hear_b: 0,
            whisper_f: 0xFC,
            whisper_b: 0xFF,
            green_f: 0xDB,
            green_b: 0xFF,
            blue_f: 0xFF,
            blue_b: 0xFC,
        };
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("aaa".to_string(), test_session_ground(a));
        sessions.insert("bbb".to_string(), test_session_ground(b));
        let ctx = TestChatCtx::new();
        let host = ctx.host(&online, &world, &gates, &colors);
        handle_say(&host, &mut sessions, "aaa", 901, Some("/bbb 你好呀"));

        assert!(
            rx0.try_recv().is_err(),
            "说话者不收私聊回声（oracle 只发收件人）"
        );
        match rx1.try_recv().expect("目标应收到 SM_WHISPER") {
            SimToGate::SendFrame { socket, body } => {
                assert_eq!(socket, 902);
                assert_eq!(
                    i32::from_le_bytes([body[0], body[1], body[2], body[3]]),
                    b,
                    "Recog = 收件人 ActorId（BaseObject.Message.cs:143）"
                );
                assert_eq!(
                    u16::from_le_bytes([body[4], body[5]]),
                    mir2_protocol::messages::SM_WHISPER,
                    "Ident = SM_WHISPER(103)"
                );
                assert_eq!(
                    u16::from_le_bytes([body[6], body[7]]),
                    0xFFFC,
                    "Param = MakeWord(WhisperFColor=0xFC, WhisperBColor=0xFF)"
                );
                assert_eq!(u16::from_le_bytes([body[8], body[9]]), 0, "Tag=0");
                assert_eq!(u16::from_le_bytes([body[10], body[11]]), 1, "Series=1");
                let mut want = b"aaa=> ".to_vec();
                want.extend_from_slice(&encoding_rs::GBK.encode("你好呀").0);
                assert_eq!(
                    mir2_protocol::edcode::decode(&body[12..]),
                    want,
                    "尾 = EncodeString(\"aaa=> 你好呀\")"
                );
            }
            other => panic!("目标应收到 SendFrame，实收 {other:?}"),
        }
    }

    /// **`openmir2-channel-chat` 判据①**：`!!正文` ⇒ `SendGroupText(ChrName + ": " + sText)`
    /// （`PlayObject.Chat.cs:167-169` + `PlayObject.cs:5185-5197`）⇒ 逐成员 `SM_SYSMESSAGE(100)`：
    /// `Recog` = **说话者** ActorId、`Param` = `MakeWord(GroupMsgFColor, GroupMsgBColor)`、
    /// `Series=1`、尾 = `EncodeString("〖组队〗aaa: hello")`；非组员不收。
    ///
    /// 牙：把 `!!` 落回喊话/普通说话 ⇒ ident 变成 `SM_HEAR(40)` ⇒ 必红；把 recog 改成收件人 ⇒ 必红。
    #[test]
    fn group_say_sends_sm_sysmessage_to_each_party_member() {
        use std::collections::HashMap;
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let (tx1, mut rx1) = mpsc::unbounded_channel::<SimToGate>();
        let (tx2, mut rx2) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        gates.insert(1, tx1);
        gates.insert(2, tx2);

        let mut world = mir2_world_bevy::World::new(64, 64);
        let mut mk = |name: &str, x: i32, y: i32| {
            let mut e = mir2_world_bevy::EntitySpawn::new(0, name.to_string(), x, y);
            e.race = mir2_world_bevy::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        let a = mk("aaa", 10, 10);
        let b = mk("bbb", 11, 10);
        let outsider = mk("ccc", 50, 50);
        // 团长 a 的成员表 = [a, b]；b 的 GroupOwner = a（oracle Operate.cs:834-835/875）。
        world.entities.get_mut(a).unwrap().group.group_owner = a;
        world.entities.get_mut(a).unwrap().group.group_members = vec![a, b];
        world.entities.get_mut(b).unwrap().group.group_owner = a;

        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("a", "aaa", 1, 0, 901, a));
        online_set(&mut online, entry("b", "bbb", 2, 1, 902, b));
        online_set(&mut online, entry("c", "ccc", 3, 2, 903, outsider));

        let colors = MsgColors {
            red_f: 0xFF,
            red_b: 0x38,
            hear_f: 0,
            hear_b: 0,
            whisper_f: 0,
            whisper_b: 0,
            green_f: 0xDB,
            green_b: 0xFF,
            blue_f: 0xFF,
            blue_b: 0xFC,
        };
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        for (name, id) in [("aaa", a), ("bbb", b), ("ccc", outsider)] {
            sessions.insert(name.to_string(), test_session_ground(id));
        }
        let ctx = TestChatCtx::new();
        let host = ctx.host(&online, &world, &gates, &colors);
        handle_say(&host, &mut sessions, "aaa", 901, Some("!!hello"));

        let check = |rx: &mut mpsc::UnboundedReceiver<SimToGate>, sock: i32| match rx.try_recv() {
            Ok(SimToGate::SendFrame { socket, body }) => {
                assert_eq!(socket, sock);
                assert_eq!(
                    i32::from_le_bytes([body[0], body[1], body[2], body[3]]),
                    a,
                    "Recog = 说话者 ActorId（RM_GROUPMESSAGE 的 SendMsg(this, …)）"
                );
                assert_eq!(
                    u16::from_le_bytes([body[4], body[5]]),
                    mir2_protocol::messages::SM_SYSMESSAGE,
                    "Ident = SM_SYSMESSAGE(100)"
                );
                assert_eq!(
                    u16::from_le_bytes([body[6], body[7]]),
                    0xFFC4,
                    "Param = MakeWord(GroupMsgFColor=0xC4, GroupMsgBColor=0xFF)"
                );
                assert_eq!(u16::from_le_bytes([body[8], body[9]]), 0, "Tag=0");
                assert_eq!(u16::from_le_bytes([body[10], body[11]]), 1, "Series=1");
                assert_eq!(
                    mir2_protocol::edcode::decode(&body[12..]),
                    encoding_rs::GBK.encode("〖组队〗aaa: hello").0.to_vec(),
                    "尾 = EncodeString(GroupMsgPreFix + ChrName + ': ' + sText)"
                );
            }
            other => panic!("socket={sock} 应收到组队 SM_SYSMESSAGE，实收 {other:?}"),
        };
        check(&mut rx0, 901); // 说话者自己也在 GroupMembers 里（oracle 不排除 self）
        check(&mut rx1, 902); // 组员
        assert!(rx2.try_recv().is_err(), "非组员不收组队消息");
    }

    /// **判据②**：`!~正文`（有行会）⇒ `MyGuild.SendGuildMsg(ChrName + ": " + sText)`
    /// （`PlayObject.Chat.cs:171-176` + `GuildInfo.cs:431-456`）⇒ 逐成员 `SM_GUILDMESSAGE(104)`：
