    /// **判据⑥**：等级门 `Abil.Level <= CanShoutMsgLevel`（`<=`，不是 `<`）——等于也拒，
    /// 提示 `CanShoutMsgLevel + 1`。
    ///
    /// 牙：把 `<=` 改成 `<` ⇒ level=34 时误放行 ⇒ 必红；提示文案用错参数 ⇒ 必红。
    #[test]
    fn shout_level_gate_is_inclusive_at_configured_level() {
        use std::collections::HashMap;
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);

        let mut world = mir2_world_bevy::World::new(64, 64);
        let mut e = mir2_world_bevy::EntitySpawn::new(0, "aaa".to_string(), 10, 10);
        e.race = mir2_world_bevy::ACTOR_RACE_PLAY;
        let a = world.add_entity(e);
        world.clock_ms = 20_000;
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("a", "aaa", 1, 0, 901, a));

        let colors = MsgColors {
            red_f: 0xFF,
            red_b: 0x38,
            hear_f: 0,
            hear_b: 0,
            whisper_f: 0,
            whisper_b: 0,
            green_f: 0xDB,
            green_b: 0xFF,
            blue_f: 0xFF,
            blue_b: 0xFC,
        };
        let mut sg = test_session_ground(a);
        sg.equip.abil.level = 34; // == CanShoutMsgLevel ⇒ 拒
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("aaa".into(), sg);
        let mut ctx = TestChatCtx::new();
        ctx.can_shout_level = 34;
        {
            let host = ctx.host(&online, &world, &gates, &colors);
            handle_say(&host, &mut sessions, "aaa", 901, Some("!hi"));
        }
        match rx0.try_recv().expect("等级不足应收到提示") {
            SimToGate::SendFrame { body, .. } => {
                assert_eq!(
                    u16::from_le_bytes([body[4], body[5]]),
                    mir2_protocol::messages::SM_SYSMESSAGE
                );
                assert_eq!(
                    mir2_protocol::edcode::decode(&body[12..]),
                    encoding_rs::GBK
                        .encode("你的等级要在35级以上才能用此功能!!!")
                        .0
                        .to_vec()
                );
            }
            other => panic!("应收到等级提示帧，实收 {other:?}"),
        }
        assert_eq!(sessions["aaa"].shout_msg_tick, 0, "被等级门拒绝不写 tick");

        sessions.get_mut("aaa").unwrap().equip.abil.level = 35;
        {
            let host = ctx.host(&online, &world, &gates, &colors);
            handle_say(&host, &mut sessions, "aaa", 901, Some("!hi"));
        }
        assert!(
            rx0.try_recv().is_err(),
            "level=35 > 34 放行 ⇒ 成功喊话零帧（oracle NRE 搬运）"
        );
        assert_eq!(
            sessions["aaa"].shout_msg_tick, 20_000,
            "放行后写 ShoutMsgTick（证明过了等级门）"
        );
    }

    /// **判据⑦（G1 起）**：`@` 行走命令派发（[`gmcmd`]）——**不得**产生聊天帧（`SM_HEAR`）；
    /// 未命中命令表 ⇒ 恰好两条 `SM_SYSMESSAGE`（`未知命令: …` + `@此命令不正确…`）。
    ///
    /// 牙：把 `@` 行落进喊话/普通说话 ⇒ 会多一条 `SM_HEAR`，本用例必红。
    #[test]
    fn at_command_line_produces_no_chat_frame() {
        use std::collections::HashMap;
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);

        let mut world = mir2_world_bevy::World::new(64, 64);
        let mut e = mir2_world_bevy::EntitySpawn::new(0, "aaa".to_string(), 10, 10);
        e.race = mir2_world_bevy::ACTOR_RACE_PLAY;
        let a = world.add_entity(e);
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("a", "aaa", 1, 0, 901, a));

        let colors = MsgColors {
            red_f: 0xFF,
            red_b: 0x38,
            hear_f: 0,
            hear_b: 0,
            whisper_f: 0,
            whisper_b: 0,
            green_f: 0xDB,
            green_b: 0xFF,
            blue_f: 0xFF,
            blue_b: 0xFC,
        };
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("aaa".into(), test_session_ground(a));
        let ctx = TestChatCtx::new();
        let host = ctx.host(&online, &world, &gates, &colors);
        let (deferred, direct) = handle_say(&host, &mut sessions, "aaa", 901, Some("@move 1 1"));
        let speaker = online
            .iter()
            .find(|e| e.chr_name == "aaa")
            .expect("aaa 在线");
        for (f, b, text) in &deferred {
            send_gm_sysmsg(&gates, speaker, *f, *b, text);
        }
        for body in direct {
            if let Some(tx) = gates.get(&0) {
                let _ = tx.send(SimToGate::SendFrame { socket: 901, body });
            }
        }
        let mut frames = Vec::new();
        while let Ok(SimToGate::SendFrame { body, .. }) = rx0.try_recv() {
            frames.push(body);
        }
        assert_eq!(
            frames.len(),
            2,
            "未知命令 = CommandSystem 一条 + Chat 回落一条（oracle 恒两条）"
        );
        for body in &frames {
            assert_eq!(
                u16::from_le_bytes([body[4], body[5]]),
                mir2_protocol::messages::SM_SYSMESSAGE,
                "`@` 命令不得被当成聊天广播（必须是 SM_SYSMESSAGE，不是 SM_HEAR）"
            );
        }
        assert_eq!(
            gbk_decode(&mir2_protocol::edcode::decode(&frames[0][12..])),
            "未知命令: move 1 1"
        );
        assert_eq!(
            gbk_decode(&mir2_protocol::edcode::decode(&frames[1][12..])),
            "@此命令不正确，或没有足够的权限!!!"
        );
    }

