    /// **Lane A 缺口 1/2 的接线牙**（评审员更正要求）：`sim_loop` 的内联接线在仓内用例里
    /// 从不执行 ⇒ 用源码锚点钉住生产位置。红检：把并入调用挪到 `let data = full.as_ref()`
    /// 之后、恢复旧 late `add_newbie_items`、或删掉 `refresh_login_max_exp` 调用 ⇒ 必红。
    #[test]
    fn login_numeric_gap_wiring_is_anchored() {
        let src = include_str!("lib.rs");
        let lines: Vec<&str> = src.lines().collect();
        let tests_start = lines
            .iter()
            .position(|l| l.trim() == "mod tests {")
            .expect("`mod tests {` 行");
        let prod = &lines[..tests_start];
        let pos = |needle: &str| -> Vec<usize> {
            prod.iter()
                .enumerate()
                .filter(|(_, l)| l.trim() == needle)
                .map(|(i, _)| i)
                .collect()
        };
        let merge = pos("let warns = merge_newbie_items_into_record(");
        assert_eq!(merge.len(), 1, "并入调用必须恰一处：{merge:?}");
        let data = prod
            .iter()
            .position(|l| l.trim() == "let data = full.as_ref().map(|r| &r.data);")
            .expect("`let data = full.as_ref()` 行");
        assert!(
            merge[0] < data,
            "并入必须在 `let data = full.as_ref()`（52/752 输入）之前"
        );
        let newh = prod
            .iter()
            .position(|l| l.trim() == "if is_new_human {")
            .expect("`if is_new_human {` 块");
        assert!(merge[0] > newh, "并入必须在 `if is_new_human` 块内");
        assert!(
            !prod
                .iter()
                .any(|l| l.contains("for w in add_newbie_items(")),
            "旧 late `add_newbie_items`（写会话 item_list，不同源）必须已删除"
        );
        let refresh: Vec<usize> = prod
            .iter()
            .enumerate()
            .filter(|(_, l)| l.trim().starts_with("refresh_login_max_exp("))
            .map(|(i, _)| i)
            .collect();
        assert_eq!(refresh.len(), 1, "登录 MaxExp 刷新必须恰一处：{refresh:?}");
        assert!(
            refresh[0] < data,
            "MaxExp 刷新必须在 `let data` 之前（所有角色）"
        );
        let exp = pos("e.exp = wabil.exp;");
        let max_exp = pos("e.max_exp = wabil.max_exp;");
        assert_eq!(exp.len(), 1, "实体 Exp 必须恰一处：{exp:?}");
        assert_eq!(max_exp.len(), 1, "实体 MaxExp 必须恰一处：{max_exp:?}");
        assert_eq!(
            max_exp[0],
            exp[0] + 1,
            "两行相邻落在 `apply_ability_to_entity`（生产登录点调用它）"
        );
    }

    /// **Important-2（reviewer-3 第 1 轮）**：登录把 DB 列 `AllowGroupReCall` 装进实体。
    ///
    /// oracle `WorldServer.cs:1159`：`playObject.AllowGroupReCall = humData.AllowGroupReCall;`
    /// ——该列是唯一初值来源，之后只由 `@允许天地合一` 翻转（`AllowGroupReCallCommand.cs:15`）。
    /// 生产入口 = [`apply_login_record_scalars`]（登录实体构造点唯一调用；`sim_loop` 的内联段
    /// 不在仓内用例里执行，故另用源码锚点钉住接线）。
    ///
    /// 红检：删掉登录点的 `apply_login_record_scalars(&mut ent, …)`（或把
    /// `allow_group_re_call` 写死 false）⇒ 源码锚点/断言必红。
    #[test]
    fn login_loads_allow_group_re_call_from_record() {
        let mut ent = new_player_entity("hero".to_string(), 10, 10);
        assert!(!ent.allow_group_re_call, "`EntitySpawn::new` 缺省 false");
        let mut rec = record::CharacterData {
            dir: 3,
            ..record::CharacterData::default()
        };
        apply_login_record_scalars(&mut ent, Some(&rec));
        assert!(!ent.allow_group_re_call, "DB 列 false ⇒ 实体 false");
        assert_eq!(ent.ai.dir, 3, "`Dir` 同一入口装载（G-09）");
        rec.allow_group_re_call = true;
        apply_login_record_scalars(&mut ent, Some(&rec));
        assert!(ent.allow_group_re_call, "DB 列 true ⇒ 实体 true");
        // 无角色记录（`full == None`，oracle 不进 `GetHumData`）⇒ 不置位。
        let mut ent2 = new_player_entity("hero2".to_string(), 10, 10);
        ent2.allow_group_re_call = true;
        apply_login_record_scalars(&mut ent2, None);
        assert!(!ent2.allow_group_re_call);
        assert_eq!(ent2.ai.dir, 0);

        // 源码锚点：登录构造点必须**恰一处**调用，且在 `enter_map` 之前。
        let src = include_str!("lib.rs");
        let lines: Vec<&str> = src.lines().collect();
        let tests_start = lines
            .iter()
            .position(|l| l.trim() == "mod tests {")
            .expect("`mod tests {` 行");
        let prod = &lines[..tests_start];
        let calls: Vec<usize> = prod
            .iter()
            .enumerate()
            .filter(|(_, l)| l.trim().starts_with("apply_login_record_scalars("))
            .map(|(i, _)| i)
            .collect();
        assert_eq!(calls.len(), 1, "登录装载必须恰一处：{calls:?}");
        let enter = prod
            .iter()
            .position(|l| l.contains("world.enter_map_at("))
            .expect("登录 `enter_map` 行");
        assert!(calls[0] < enter, "装载必须在 `enter_map` 之前");
        assert!(
            prod.iter()
                .all(|l| !l.contains("ent.ai.dir = full.as_ref()")),
            "旧的嵌入式 `Dir` 赋值必须已并入生产入口"
        );
    }

    // ---------------------------------------------------------------------
    // 进图/死亡改写（`rewrite_enter_position`）的**生产路径**判据
    // ---------------------------------------------------------------------

    /// 带一座「战时 + 皇宫在 map_id=0」的城：任何进图/死亡都命中城堡改写臂。
    fn rewrite_test_world_with_castle() -> mir2_world_bevy::World {
        let mut world = mir2_world_bevy::World::with_maps(vec![(20, 20)]);
        let mut castle = mir2_world_bevy::castle::UserCastle::new(
            "沙巴克",
            mir2_world_bevy::castle::CastleSiegeConfig::default(),
        );
        castle.map_name = Some("3".to_string());
        castle.palace_map_id = Some(0);
        castle.under_war = true;
        castle.home_map = "3".to_string();
        castle.home_x = 644;
        castle.home_y = 290;
        world.castles.push(castle);
        world
    }

    /// 记录 Home 与 `Server.conf [Setup]` Home（部署 3/839/668）**故意不同**：
    /// 落点若取 `[Setup]` ⇒ map_name 变 `"3"`、坐标在 837..841 / 666..670。
    fn rewrite_test_record() -> record::PlayerRecord {
        record::PlayerRecord {
            chr_name: Some("hero".to_string()),
            header: record::RecordHeader::default(),
            data: record::CharacterData {
                home_map: Some("recordHome".to_string()),
                home_x: 100,
                home_y: 200,
                abil: Some(record::Ability {
                    level: 30,
                    hp: 40,
                    mp: 20,
                    max_hp: 60,
                    max_mp: 30,
                    ..record::Ability::default()
                }),
                ..record::CharacterData::default()
            },
        }
    }

    /// **Critical 宿主接线级判据**：进图改写必须用**角色记录**的 `HomeMap/HomeX/HomeY`
    /// （oracle `WorldServer.cs` 的 `playObject.HomeMap` 来自 `GetHumData`），
    /// 不是 `Server.conf [Setup]`（部署 3/839/668）。
    ///
    /// 牙：把 `EnterRelocateInput` 的 `home_*` 改回 `enter_cfg.home.*` ⇒ 落点变
    /// `"3"`/837..841 ⇒ 本用例红。
    #[test]
    fn enter_rewrite_uses_record_home_not_setup_home() {
        let world = rewrite_test_world_with_castle();
        let mut rec = rewrite_test_record();
        let mut rng = mir2_shared::rng::RandomNumber::with_seed(20261021);
        let (map_name, map_id, x, y, die) = rewrite_enter_position(
            &world,
            &mut rng,
            &mut rec,
            "3",
            0,
            1,
            1,
            None,
            false,
            false,
            None,
            &mir2_world_bevy::castle::RedDieHome::default(),
        );
        assert_eq!(
            map_name, "recordHome",
            "进图落点必须用记录 HomeMap（不是 [Setup] 的 3）"
        );
        assert_eq!(map_id, 0);
        assert!((98..=102).contains(&x), "x 以记录 HomeX=100 为基准：{x}");
        assert!((198..=202).contains(&y), "y 以记录 HomeY=200 为基准：{y}");
        assert!(!die, "非 Fight3Zone ⇒ DieInFight3Zone=false");
    }

    /// **Critical + Important 2 宿主接线级判据（死亡臂）**：记录 `HP<=0` ⇒ 死亡三臂的
    /// 非成员支用**记录** `HomeMap/HomeX/HomeY`，并在改写后写回记录 `HP=14`
    /// （oracle `WorldServer.cs` 的 `playObject.Abil.HP = 14`；该记录随后进入 52 帧）。
    ///
    /// 牙：Home 改回 `[Setup]` ⇒ map_name/坐标红；删掉 `abil.hp = 14` 写回 ⇒ HP=0 红。
    #[test]
    fn death_rewrite_uses_record_home_and_writes_hp_14() {
        let world = rewrite_test_world_with_castle();
        let mut rec = rewrite_test_record();
        rec.data.abil.as_mut().unwrap().hp = 0;
        let mut rng = mir2_shared::rng::RandomNumber::with_seed(20261021);
        let (map_name, _, x, y, die) = rewrite_enter_position(
            &world,
            &mut rng,
            &mut rec,
            "3",
            0,
            1,
            1,
            None,
            false,
            false,
            None,
            &mir2_world_bevy::castle::RedDieHome::default(),
        );
        assert_eq!(map_name, "recordHome", "死亡落点必须用记录 HomeMap");
        assert!((98..=102).contains(&x), "x 以记录 HomeX=100 为基准：{x}");
        assert!((198..=202).contains(&y), "y 以记录 HomeY=200 为基准：{y}");
        assert!(!die);
        assert_eq!(
            rec.data.abil.as_ref().unwrap().hp,
            14,
            "oracle 死亡改写后无条件 Abil.HP=14，写回记录（后续 52 帧的 cur_hp）"
        );
    }

    /// **Important 2**：Fight3Zone 恢复支写记录 `HP=MaxHP、MP=MaxMP` 并置
    /// `DieInFight3Zone=true`（oracle `WorldServer.cs`），不进入死亡 `HP=14` 分支。
    ///
    /// 牙：只改局部 `hp` 不写回记录 ⇒ HP/MP 仍是 0 红；不置位 ⇒ `die` false 红。
    #[test]
    fn fight3_zone_recovery_writes_record_hp_mp_and_die_bit() {
        let mut world = mir2_world_bevy::World::with_maps(vec![(20, 20)]);
        let mut rec = rewrite_test_record();
        {
            let a = rec.data.abil.as_mut().unwrap();
            a.hp = 0;
            a.mp = 0;
        }
        let mut rng = mir2_shared::rng::RandomNumber::with_seed(20261021);
        let (_, _, _, _, die) = rewrite_enter_position(
            &world,
            &mut rng,
            &mut rec,
            "3",
            0,
            640,
            300,
            None,
            false,
            true,
            None,
            &mir2_world_bevy::castle::RedDieHome::default(),
        );
        let a = rec.data.abil.as_ref().unwrap();
        assert_eq!((a.hp, a.mp), (60, 30), "HP=MaxHP、MP=MaxMP 写回记录");
        assert!(die, "DieInFight3Zone=true（oracle WorldServer.cs:290）");
        assert_ne!(a.hp, 14, "HP>0 ⇒ 不进死亡改写支");
        let _ = &mut world;
    }

    /// **Important 2（else 支）**：Fight3Zone 且不满足恢复条件 ⇒ 清记录
    /// `FightZoneDieCount=0`（oracle 的 else 分支），HP/MP 不动。
    #[test]
    fn fight3_zone_else_resets_fight_zone_die_count() {
        let world = mir2_world_bevy::World::with_maps(vec![(20, 20)]);
        let mut rec = rewrite_test_record();
        rec.data.fight_zone_die_count = 2;
        let mut rng = mir2_shared::rng::RandomNumber::with_seed(20261021);
        let (_, _, _, _, die) = rewrite_enter_position(
            &world,
            &mut rng,
            &mut rec,
            "3",
            0,
            640,
            300,
            None,
            false,
            true,
            None,
            &mir2_world_bevy::castle::RedDieHome::default(),
        );
        assert_eq!(rec.data.fight_zone_die_count, 0, "else 支清记录计数");
        assert_eq!(rec.data.abil.as_ref().unwrap().hp, 40, "HP>0 不动");
        assert!(!die);
    }

    /// **Critical 的源码牙**：生产面不得再把 `[Setup]` Home 喂给落点改写；
    /// 地形移位回落（oracle `WorldServer.cs:389-393`）仍必须用 `[Setup]` Home。
    #[test]
    fn enter_rewrite_home_source_is_record_anchored() {
        let src = include_str!("lib.rs");
        let tests = src
            .find("#[cfg(test)]\nmod tests {")
            .expect("`#[cfg(test)] mod tests` 起点");
        let prod = &src[..tests];
        assert!(
            !prod.contains("home_map: &enter_cfg.home.home_map"),
            "进图/死亡改写的 Home 必须取角色记录，不是 Server.conf [Setup]"
        );
        assert!(
            prod.contains("home_map: rec.data.home_map.as_deref().unwrap_or(\"\")"),
            "两臂都必须从记录取 HomeMap"
        );
        assert!(
            prod.contains("map_name: &enter_cfg.home.home_map"),
            "地形移位回落（oracle 389-393）仍按 oracle 用 [Setup] HomeMap"
        );
    }

    fn exps_table() -> Vec<i32> {
        let mut t = vec![0i32; 300];
        t[1] = 10;
        t[10] = 300;
        t
    }

    fn zero_bonus_abil() -> game_svr::ability::NakedAbility {
        game_svr::ability::NakedAbility {
            dc: 0,
            mc: 0,
            sc: 0,
            ac: 0,
            mac: 0,
            hp: 0,
            mp: 0,
            hit: 0,
            speed: 0,
            reserved: 0,
        }
    }

    /// **Lane A 缺口 2**：登录记录侧 `Abil.MaxExp = GetLevelExp(Level)`（oracle :1310）。
    /// 牙：删掉记录侧赋值 ⇒ 保持 100/1，必红。
    #[test]
    fn login_max_exp_uses_exps_table() {
        let need_exps = exps_table();
        let mut rec = record::CharacterData {
            abil: Some(record::Ability {
                level: 1,
                max_exp: 100,
                ..record::Ability::default()
            }),
            ..record::CharacterData::default()
        };
        refresh_login_max_exp(&mut rec, &need_exps);
        assert_eq!(
            rec.abil.as_ref().unwrap().max_exp,
            10,
            "Level1 = Exps[1]（现网 10，不是记录/新号缺省 100）"
        );
        let a = rec.abil.as_mut().unwrap();
        a.level = 10;
        a.max_exp = 1;
        refresh_login_max_exp(&mut rec, &need_exps);
        assert_eq!(
            rec.abil.as_ref().unwrap().max_exp,
            300,
            "Level10 = Exps[10]（记录旧值 1 被覆盖）"
        );
    }

    /// **Lane A 缺口 2**：52/752 的 MaxExp 与登录记录值一致（两种布局都断言）。
    /// 牙：记录不刷新 ⇒ `recalc_abilitys` 只 `..base` 复制 ⇒ 100，必红。
    #[test]
    fn frame52_max_exp_equals_login_value() {
        let need_exps = exps_table();
        let unrefreshed = new_human_ability(); // max_exp = 100
        let mut rec = record::CharacterData {
            abil: Some(unrefreshed.clone()),
            ..record::CharacterData::default()
        };
        refresh_login_max_exp(&mut rec, &need_exps);
        let abil = rec.abil.clone().unwrap();
        let bonus = zero_bonus_abil();
        let catalog = newbie_catalog();
        let a = enter::AbilityInputs {
            catalog: &catalog,
            abil: &abil,
            bonus_abil: &bonus,
            bonus_tick_hit: 1,
            bonus_tick_speed: 1,
            use_items: None,
            bag_items: None,
            magics: None,
            magic_table: None,
            gold: 0,
            client_ability_layout: false,
        };
        let out = enter::recalc_for_session(&a, 0);
        assert_eq!(out.wabil.max_exp, 10, "52 帧尾取登录后的 MaxExp");
        let b = record::encode_ability(&out.wabil);
        assert_eq!(b.len(), 40, "oracle 40B 体");
        assert_eq!(
            i32::from_le_bytes([b[28], b[29], b[30], b[31]]),
            10,
            "MaxExp@28（40B 布局）"
        );
        let c = record::encode_ability_client(&out.wabil);
        assert_eq!(c.len(), 58, "冻结客户端 58B");
        assert_eq!(
            i32::from_le_bytes([c[42], c[43], c[44], c[45]]),
            10,
            "MaxExp@42（client-58）"
        );
        // 对照（牙）：未刷新的记录值原样复制。
        let u = enter::AbilityInputs {
            abil: &unrefreshed,
            ..a
        };
        assert_eq!(
            enter::recalc_for_session(&u, 0).wabil.max_exp,
            100,
            "对照：不刷新 ⇒ 100（证明本判据有牙）"
        );
    }

    /// **Lane A 缺口 2**：实体 `exp/max_exp` 必须随登录装载——否则 `win_exp` 的
    /// `exp >= max_exp` 在 `0/0` 下恒真，登录后首杀必然伪升级（等级 +1、`exp -= 0`）。
    /// 牙：删掉 `apply_ability_to_entity` 的两行 ⇒ 对照段 `1 >= 0` 必红为真。
    #[test]
    fn login_seeds_entity_exp_and_max_exp() {
        let need_exps = exps_table();
        let mut abil = new_human_ability(); // exp = 0 / max_exp = 100
        abil.max_exp = mir2_formula::exp::get_level_exp(
            &need_exps,
            mir2_data::models::MAX_LEVEL,
            i32::from(abil.level),
        );
        let bonus = zero_bonus_abil();
        let catalog = newbie_catalog();
        let a = enter::AbilityInputs {
            catalog: &catalog,
            abil: &abil,
            bonus_abil: &bonus,
            bonus_tick_hit: 1,
            bonus_tick_speed: 1,
            use_items: None,
            bag_items: None,
            magics: None,
            magic_table: None,
            gold: 0,
            client_ability_layout: false,
        };
        let out = enter::recalc_for_session(&a, 0);
        let mut e = new_player_entity("hero".to_string(), 10, 10);
        apply_ability_to_spawn(&mut e, &out.wabil, &out.sub, out.hit_speed);
        assert_eq!(e.exp, 0, "实体 Exp = WAbil.Exp（记录值）");
        assert_eq!(e.max_exp, 10, "实体 MaxExp = Exps[1]");
        // 首杀：1 点经验 < 10 ⇒ 不得升级。
        let (_, leveled, _) = mir2_world_bevy::combat::win_exp(
            &mut e,
            1,
            &need_exps,
            &mir2_world_bevy::combat::CombatConfig::default(),
            None,
        );
        assert!(!leveled, "登录后首杀不得伪升级（exp=1 < max_exp=10）");
        assert_eq!(e.level, 1, "等级保持不变");
        // 对照（牙）：max_exp 未装载（0）⇒ `1 >= 0` 恒真。
        let mut d = new_player_entity("hero2".to_string(), 10, 10);
        d.exp = 0;
        d.max_exp = 0;
        let (_, bogus, _) = mir2_world_bevy::combat::win_exp(
            &mut d,
            1,
            &need_exps,
            &mir2_world_bevy::combat::CombatConfig::default(),
            None,
        );
        assert!(bogus, "对照：0/0 ⇒ 首杀伪升级（证明本判据有牙）");
    }

    /// **Lane A 缺口 2**：装备/卸下重算只 `..base` 复制 `MaxExp/Exp`，登录值不得被记录旧值覆盖。
    #[test]
    fn equip_recalc_preserves_login_max_exp() {
        let catalog = newbie_catalog();
        let mut sg = test_session_ground(1);
        sg.equip.abil.max_exp = 10;
        sg.equip.abil.exp = 3;
        sg.state.wabil.max_exp = 10;
        let _ = recalc_session_ability(&mut sg, &catalog, None, None, None);
        assert_eq!(sg.state.wabil.max_exp, 10, "重算保留登录 MaxExp");
        assert_eq!(sg.state.wabil.exp, 3, "重算保留 Exp");
    }

