    /// `CM_QUERYVAL(1065)`：`ValType` 0 ⇒ 写 `MNSval[ValLabel]`；1 ⇒ 写 `MNMval[ValLabel]`；
    /// 两路之后都清空 `GotoNpcLabel`；`Ghost` 时 `sRefMsg` 落空串。
    ///
    /// 红检：把 `val_type` 的两支对调（0 写 `mnm_val`）⇒ 断言必红；把 `s_ref_msg` 的 `!ghost` 门删掉
    /// ⇒ ③ 的 Ghost 断言必红；删 `goto_npc_label.clear()` ⇒ 断言必红。
    #[test]
    fn query_val_writes_mns_or_mnm_and_clears_label() {
        use std::collections::HashMap;
        let mut world = mir2_world_bevy::World::with_maps(vec![(40, 40)]);
        world.open_session("hero");
        let hero = world
            .enter_map(
                "hero",
                mir2_world_bevy::EntitySpawn::new(0, "hero", 10, 10),
                0,
            )
            .unwrap();
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("hero".into(), test_session_ground(hero));
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("ua", "hero", 1, 0, 901, hero));

        // ① ValType=0（串）：写 MNSval[3]=tail，且 GotoNpcLabel 被清。
        {
            let sg = sessions.get_mut("hero").unwrap();
            sg.val_type = 0;
            sg.val_label = 3;
            sg.goto_npc_label = "@x".into();
        }
        assert!(handle_query_val_cmd(
            0,
            Some("hello"),
            "hero",
            901,
            &online,
            &mut sessions,
            &world
        ));
        let sg = sessions.get("hero").unwrap();
        assert_eq!(sg.mns_val[3], "hello", "ValType=0 ⇒ MNSval[3]=sRefMsg");
        assert!(sg.goto_npc_label.is_empty(), "末尾清空 GotoNpcLabel");

        // ② ValType=1（整）：写 MNMval[5]=StrToInt(tail)。
        {
            let sg = sessions.get_mut("hero").unwrap();
            sg.val_type = 1;
            sg.val_label = 5;
            sg.goto_npc_label = "@y".into();
        }
        assert!(handle_query_val_cmd(
            0,
            Some(" 42 "),
            "hero",
            901,
            &online,
            &mut sessions,
            &world
        ));
        let sg = sessions.get("hero").unwrap();
        assert_eq!(sg.mnm_val[5], 42, "ValType=1 ⇒ MNMval[5]=StrToInt('42')");
        assert_eq!(sg.mns_val[3], "hello", "ValType=1 不得动 MNSval");

        // ③ Ghost ⇒ sRefMsg 落空串（门 `!Ghost && GotoNpcLabel != ""`）。
        {
            let sg = sessions.get_mut("hero").unwrap();
            sg.val_type = 0;
            sg.val_label = 7;
            sg.goto_npc_label = "@z".into();
        }
        world.entities.get_mut(hero).unwrap().life_cycle.ghost = true;
        assert!(handle_query_val_cmd(
            0,
            Some("ignored"),
            "hero",
            901,
            &online,
            &mut sessions,
            &world
        ));
        let sg = sessions.get("hero").unwrap();
        assert_eq!(sg.mns_val[7], "", "Ghost ⇒ sRefMsg 空串");
    }

    /// `CM_SOFTCLOSE(1009)`：置 `BoReconnection`/`BoSoftClose`；`wParam==1` 追加 `BoEmergencyClose`；
    /// 并离开世界（`world.session.stage == Left`、`soft_close_count += 1`）。
    ///
    /// 红检：删 `if emergency { bo_emergency_close = true }` ⇒ ① 的 emergency 断言必红；
    /// 删 `world.soft_close(chr_name)` ⇒ 「stage=Left / count=1」断言必红。
    #[test]
    fn soft_close_sets_flags_and_leaves_world() {
        use std::collections::HashMap;
        let mut world = mir2_world_bevy::World::with_maps(vec![(40, 40)]);
        world.open_session("hero");
        let hero = world
            .enter_map(
                "hero",
                mir2_world_bevy::EntitySpawn::new(0, "hero", 10, 10),
                0,
            )
            .unwrap();
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("hero".into(), test_session_ground(hero));
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("ua", "hero", 1, 0, 901, hero));

        // ① wParam=1 ⇒ 三标志全置真 + 离开世界。
        handle_soft_close_cmd(
            1,
            "hero",
            901,
            &online,
            &mut sessions,
            &mut world,
            None,
            &mut HashMap::new(),
        );
        let sg = sessions.get("hero").unwrap();
        assert!(sg.bo_reconnection, "BoReconnection=true");
        assert!(sg.bo_soft_close, "BoSoftClose=true");
        assert!(sg.bo_emergency_close, "wParam==1 ⇒ BoEmergencyClose=true");
        assert_eq!(
            world.session("hero").unwrap().stage,
            mir2_world_bevy::WorldStage::Left,
            "BoSoftClose 支 ⇒ MakeGhost（离开世界）"
        );
        assert_eq!(world.session("hero").unwrap().soft_close_count, 1);
        // M-3：`MakeGhost` 不销毁对象 ⇒ 实体仍在且 `ghost=true`，`actor_id` 保留。
        assert!(
            world.entities.get(hero).is_some_and(|e| e.ghost),
            "soft_close ⇒ 实体保留且 ghost=true（oracle MakeGhost）"
        );
        assert_eq!(
            world.session("hero").unwrap().actor_id,
            Some(hero),
            "A2：stage=Left 与 actor_id=Some 并存"
        );

        // ② 再进世界后 wParam=0 ⇒ 不置 emergency（旧的 emergency 需先清）。
        let hero2 = world
            .enter_map(
                "hero",
                mir2_world_bevy::EntitySpawn::new(0, "hero", 12, 12),
                0,
            )
            .unwrap();
        sessions.get_mut("hero").unwrap().actor_id = hero2;
        sessions.get_mut("hero").unwrap().bo_emergency_close = false;
        handle_soft_close_cmd(
            0,
            "hero",
            901,
            &online,
            &mut sessions,
            &mut world,
            None,
            &mut HashMap::new(),
        );
        let sg = sessions.get("hero").unwrap();
        assert!(sg.bo_reconnection && sg.bo_soft_close);
        assert!(!sg.bo_emergency_close, "wParam==0 ⇒ 不置 BoEmergencyClose");
        assert_eq!(world.session("hero").unwrap().soft_close_count, 2);
    }

    /// 源码锚点断言的**去注释**视图：逐行删掉整行注释（`// ...`）。
    ///
    /// 不做这一步时「把调用注释掉」仍能通过文本断言（红检会假绿）——本卡的两条牙齿
    /// 用例统一走这里。
    fn strip_comment_lines(src: &str) -> String {
        src.lines()
            .map(|l| {
                if l.trim_start().starts_with("//") {
                    ""
                } else {
                    l
                }
            })
            .collect::<Vec<_>>()
            .join("\n")
    }

    /// **T-202 判据①**：登录跨服分支（oracle `WorldServer.cs:352-368` 的
    /// `GetMapInfo(ServerIndex, MapName) == null` 支）⇒ **恰好一条** `SM_RECONNECT`：
    /// 载荷 `"{ip}/{port}"`、头四字段全 0、尾 `EncodeString(Msg)`、单投 `[GateIdx, Socket]`。
    ///
    /// 红检：删 `try_cross_server_redirect` 里的 `pending.push(..)`，或删 `sim_loop` 的
    /// `drain_reconnects(..)` 调用 ⇒ 「恰好一条」必红（见 `sm_reconnect_production_calls_are_wired_in_sim_loop`）。
    #[test]
    fn login_cross_server_redirect_emits_exactly_one_sm_reconnect() {
        // 真机 `!servertable.txt` 的内容（`0 127.0.0.1 127.0.0.1 7200`）。
        let table = parse_server_table("0 127.0.0.1 127.0.0.1 7200\n");
        assert_eq!(table.len(), 1);
        assert_eq!(table[0].server_idx, 0);
        assert_eq!(table[0].game_gate_ips, vec!["127.0.0.1".to_string()]);
        assert_eq!(table[0].game_gate_ports, vec![7200], "GateCount=1");

        let mut world = mir2_world_bevy::World::new(16, 16);
        let mut pending: Vec<ReconnectPending> = Vec::new();
        assert!(
            try_cross_server_redirect(
                &table,
                &mut world.rng,
                None,
                "本服没有的图",
                0,
                901,
                &mut pending
            ),
            "有路由 ⇒ 必须转服（oracle GetMultiServerAddrPort == true）"
        );
        assert_eq!(pending.len(), 1, "恰好一条待发");
        assert_eq!(pending[0].msg, b"127.0.0.1/7200".to_vec());

        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        drain_reconnects(&mut pending, &mut sessions, &gates);
        assert!(pending.is_empty(), "排水后队列清空（不得重发）");

        let mut frames = Vec::new();
        while let Ok(SimToGate::SendFrame { socket, body }) = rx0.try_recv() {
            frames.push((socket, body));
        }
        assert_eq!(frames.len(), 1, "恰好一条 SM_RECONNECT");
        assert_eq!(frames[0].0, 901, "收件人 = 登录 socket");
        assert_eq!(
            frames[0].1,
            smframe_ext::sm_reconnect(b"127.0.0.1/7200"),
            "逐字节 = 既有编码器（头全 0 + 尾 EncodeString）"
        );
        let cm = mir2_protocol::frame::CommandMessage::from_bytes(&frames[0].1).expect("12B 头");
        assert_eq!(cm.recog, 0);
        assert_eq!(cm.ident, mir2_protocol::messages::SM_RECONNECT);
        assert_eq!((cm.param, cm.tag, cm.series), (0, 0, 0));

        // 无路由 ⇒ oracle `GetMultiServerAddrPort == false` ⇒ **不发帧**（也不消耗进图）。
        let empty = parse_server_table("1 10.0.0.1 10.0.0.1 7100\n");
        let mut pending2: Vec<ReconnectPending> = Vec::new();
        assert!(
            !try_cross_server_redirect(
                &empty,
                &mut world.rng,
                None,
                "本服没有的图",
                0,
                901,
                &mut pending2
            ),
            "ServerIdx 不匹配 ⇒ 无路由"
        );
        assert!(pending2.is_empty());
    }

    /// **T-202 判据②**：软关链（`CM_SOFTCLOSE`）**零条** `SM_RECONNECT` —— 两条链
    /// **只共享 `BoReconnection` 标志、不共享帧**（审计 §5 ①）。
    ///
    /// 红检：把软关与重连混成一条（在 `handle_soft_close_cmd` 里 push 重连队列）⇒
    /// 本用例的「零条」与 `soft_close_body_does_not_share_the_reconnect_channel` **同时**必红。
    #[test]
    fn soft_close_sets_flag_without_any_sm_reconnect() {
        let mut world = mir2_world_bevy::World::with_maps(vec![(40, 40)]);
        world.open_session("hero");
        let hero = world
            .enter_map(
                "hero",
                mir2_world_bevy::EntitySpawn::new(0, "hero", 10, 10),
                0,
            )
            .unwrap();
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("hero".into(), test_session_ground(hero));
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("ua", "hero", 1, 0, 901, hero));
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);

        handle_soft_close_cmd(
            0,
            "hero",
            901,
            &online,
            &mut sessions,
            &mut world,
            None,
            &mut HashMap::new(),
        );
        assert!(
            sessions["hero"].bo_reconnection,
            "软关照样置 BoReconnection（两链共享的**唯一**东西）"
        );

        let mut reconnects = 0usize;
        while let Ok(SimToGate::SendFrame { body, .. }) = rx0.try_recv() {
            let cm = mir2_protocol::frame::CommandMessage::from_bytes(&body).expect("12B 头");
            if cm.ident == mir2_protocol::messages::SM_RECONNECT {
                reconnects += 1;
            }
        }
        assert_eq!(reconnects, 0, "软关 ⇒ 零条 SM_RECONNECT（不共享帧）");
    }

    /// **T-202 牙②（静态）**：软关链**不得**接入重连通道 —— `handle_soft_close_cmd` 函数体里
    /// 出现 `reconnect_pending` / `drain_reconnects` / `try_cross_server_redirect` 即红。
    #[test]
    fn soft_close_body_does_not_share_the_reconnect_channel() {
        let src = strip_comment_lines(include_str!("lib.rs"));
        let start = src.find("fn handle_soft_close_cmd(").expect("定义行");
        let end = src[start..]
            .find("\n}\n")
            .map(|i| start + i)
            .expect("函数结束行");
        let body = &src[start..end];
        for banned in [
            "reconnect_pending",
            "drain_reconnects",
            "try_cross_server_redirect",
            "SM_RECONNECT",
        ] {
            assert!(
                !body.contains(banned),
                "软关链与重连链只共享标志，函数体不得含 {banned}"
            );
        }
    }

    /// **T-202 判据③**：直发路径（`WorldServer.cs:606-610` + `:1066-1075` `SendChangeServer`）的
    /// **时机与收件人**：`SwitchDataSended` 严格 `> 100ms` 才发；帧只给该玩家自己
    /// （`SendDefMessage` 单投，不广播、不抄送观察者）；`GetMultiServerAddrPort` 失败 ⇒ 不发。
    #[test]
    fn switch_data_poll_sends_change_server_only_to_the_player() {
        // 同一路由两对网关 ⇒ `GetRandpmRoute` 的 `Random(2)` 抽一对（oracle `GameShare.cs:83-85`）。
        let table = parse_server_table("0 10.1.1.1 10.1.1.1 7001 10.1.1.1 7002\n");
        assert_eq!(
            table[0].game_gate_ports,
            vec![7001, 7002],
            "GateCount=2（两对 ip/port）"
        );

        let mut world = mir2_world_bevy::World::new(16, 16);
        let hero = world.add_entity({
            let mut e = mir2_world_bevy::EntitySpawn::new(1, "hero", 10, 10);
            e.race = mir2_world_bevy::ACTOR_RACE_PLAY;
            e
        });
        let other = world.add_entity({
            let mut e = mir2_world_bevy::EntitySpawn::new(2, "other", 12, 10);
            e.race = mir2_world_bevy::ACTOR_RACE_PLAY;
            e
        });
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("hero".into(), test_session_ground(hero));
        sessions.insert("other".into(), test_session_ground(other));
        sessions.get_mut("hero").unwrap().switch_state.switch_data = true;
        sessions.get_mut("hero").unwrap().switch_state.rcd_saved = true;
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("ua", "hero", 1, 0, 901, hero));
        online_set(&mut online, entry("ub", "other", 1, 0, 902, other));
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);

        let mut pending: Vec<ReconnectPending> = Vec::new();
        // 2_000ms：SendSwitchData 成功 ⇒ 进入 100ms 窗口，本轮不发。
        process_switch_data(
            &mut sessions,
            2_000,
            |_, _| true,
            |st, name| {
                switch_data_send_change_server(
                    st,
                    name,
                    &mut world,
                    &online,
                    None,
                    &table,
                    &mut pending,
                );
            },
        );
        assert!(pending.is_empty(), "刚进入窗口（0ms）不得 SendChangeServer");
        // 2_100ms：oracle 是严格 `>` ⇒ 恰好 100ms 仍不发。
        process_switch_data(
            &mut sessions,
            2_100,
            |_, _| true,
            |st, name| {
                switch_data_send_change_server(
                    st,
                    name,
                    &mut world,
                    &online,
                    None,
                    &table,
                    &mut pending,
                );
            },
        );
        assert!(pending.is_empty(), "恰好 100ms 不得发（严格 > 100）");
        // 2_101ms ⇒ 发一条。
        process_switch_data(
            &mut sessions,
            2_101,
            |_, _| true,
            |st, name| {
                switch_data_send_change_server(
                    st,
                    name,
                    &mut world,
                    &online,
                    None,
                    &table,
                    &mut pending,
                );
            },
        );
        assert_eq!(pending.len(), 1, "101ms 后恰好一条");
        assert_eq!(pending[0].socket, 901);
        assert_eq!(pending[0].chr_name, "hero");
        let msg = String::from_utf8(pending[0].msg.clone()).expect("ASCII");
        assert!(
            msg == "10.1.1.1/7001" || msg == "10.1.1.1/7002",
            "载荷必须来自本路由的两对网关之一：{msg}"
        );

        drain_reconnects(&mut pending, &mut sessions, &gates);
        let mut sockets = Vec::new();
        while let Ok(SimToGate::SendFrame { socket, .. }) = rx0.try_recv() {
            sockets.push(socket);
        }
        assert_eq!(
            sockets,
            vec![901],
            "只投给该玩家，不广播（观察者 902 一条都没有）"
        );
        assert!(
            sessions["hero"].bo_reconnection,
            "SendChangeServer 先置 BoReconnection 再发帧"
        );
        assert!(!sessions["other"].bo_reconnection, "旁观者不受影响");
    }

    /// **B4 #6（`process_switch_data`）行为牙**：换服轮询的**跨会话推进序**必须严格等于
    /// 名字升序——两段排水都要成立：① 循环内 `SendSwitchData` 回调的调用序；② 回调把待发项推进
    /// `reconnect_pending: Vec` 后，`drain_reconnects` 按 Vec 序发出的 `SM_RECONNECT` 帧序。
    ///
    /// 构造：8 个会话全部 `switch_data=RcdSaved=true`，名字按「升序 ≠ 插入序」插入。
    /// 第一轮（now=2000）进入 100ms 窗口；第二轮（now=2101）过严格 `>` 门，逐会话触发
    /// `SendChangeServer`。断言 ①回调序、②帧 socket 序都 = 名字升序。
    ///
    /// 牙：删 `process_switch_data` 里的 `names.sort_unstable();` ⇒ 两段都退化为 `HashMap` 迭代序 ⇒ 必红。
    #[test]
    fn switch_data_iteration_order_is_name_ascending_with_unordered_sessions() {
        use std::collections::HashMap;
        let names = [
            "kilo", "alpha", "mike", "bravo", "november", "charlie", "oscar", "delta",
        ];
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut socket_by_name: HashMap<&str, i32> = HashMap::new();
        for (i, name) in names.iter().enumerate() {
            let name: &str = name;
            let mut sg = test_session_ground(i as i32 + 1);
            sg.switch_state.switch_data = true;
            sg.switch_state.rcd_saved = true;
            sessions.insert(name.to_string(), sg);
            socket_by_name.insert(name, 901 + i as i32);
        }
        let mut sorted_names: Vec<&str> = names.to_vec();
        sorted_names.sort_unstable();

        // ① 第一轮：SendSwitchData 的调用序。
        let mut writes: Vec<String> = Vec::new();
        process_switch_data(
            &mut sessions,
            2_000,
            |_, name| {
                writes.push(name.to_string());
                true
            },
            |_, _| panic!("刚进入窗口（0ms）不得 SendChangeServer"),
        );
        let want_names: Vec<String> = sorted_names.iter().map(|n| (*n).to_string()).collect();
        assert_eq!(
            writes, want_names,
            "SendSwitchData 的跨会话调用序必须 = 名字升序"
        );

        // ② 第二轮：SendChangeServer 推进 Vec，排水帧序也必须 = 名字升序。
        let mut pending: Vec<ReconnectPending> = Vec::new();
        process_switch_data(
            &mut sessions,
            2_101,
            |_, _| true,
            |_, name| {
                pending.push(ReconnectPending {
                    gate_idx: 0,
                    socket: socket_by_name[name],
                    chr_name: name.to_string(),
                    msg: b"10.0.0.1/7000".to_vec(),
                });
            },
        );
        assert_eq!(pending.len(), names.len(), "101ms 后每会话恰一条");
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        drain_reconnects(&mut pending, &mut sessions, &gates);
        let mut got: Vec<i32> = Vec::new();
        while let Ok(SimToGate::SendFrame { socket, body }) = rx0.try_recv() {
            assert_eq!(
                u16::from_le_bytes([body[4], body[5]]),
                mir2_protocol::messages::SM_RECONNECT,
                "排水帧 = SM_RECONNECT"
            );
            got.push(socket);
        }
        let want_sockets: Vec<i32> = sorted_names.iter().map(|n| socket_by_name[n]).collect();
        assert_eq!(
            got, want_sockets,
            "二次排水的 SM_RECONNECT 帧序必须 = 名字升序（两次排水之间契约成立）"
        );
    }

    /// **T-202 牙①**：撤发射点 ⇒ 红。生产编排里的接线必须在位且在正确的段落：
    /// `sim_loop` 体内 登录跨服调 `try_cross_server_redirect(`、换服门轮询 `process_switch_data(`
    /// **之后**调 `drain_reconnects(`（oracle `:609` 的 `SendChangeServer` 在该轮询内同步发帧）。
    #[test]
    fn sm_reconnect_production_calls_are_wired_in_sim_loop() {
        let src = strip_comment_lines(include_str!("lib.rs"));
        // **只看生产源码**：本模块自身就含 `drain_reconnects(` 等**字符串字面量**，
        // 不切掉 `mod tests {` 会自指假绿（首次实现踩过，红检 A 实测）。
        let prod_end = src.find("\nmod tests {").expect("测试模块起点");
        let prod = &src[..prod_end];
        let sim_loop = prod.find("fn sim_loop(").expect("`fn sim_loop(` 定义行");
        // L2-5 ③ 段 1a：登录块搬进 `finish_login`（在 sim_loop 之前）⇒ 扫描从它起。
        let body_start = prod
            .find("fn finish_login(")
            .map_or(sim_loop, |f| f.min(sim_loop));
        let body = &prod[body_start..];
        let login = body
            .find("try_cross_server_redirect(")
            .expect("登录跨服分支必须调 try_cross_server_redirect(");
        let poll = body
            .find("switch_data_send_change_server(")
            .expect("换服门轮询的生产闭包必须调 switch_data_send_change_server(");
        let drain = body
            .find("drain_reconnects(")
            .expect("sim_loop 必须排水 SM_RECONNECT");
        // 定义行都在 sim_loop 之前（不在 body 里），body 里首次命中即**调用点**。
        assert!(
            login < poll,
            "登录跨服分支在换服门轮询之前（本文件的实际次序）"
        );
        assert!(drain > poll, "SM_RECONNECT 排水必须在换服门轮询之后");
    }

    /// **T-202 牙③（复审 `513c571a` I-1）**：`GateCount==1` 也必须**真实消耗一次**
    /// `Next(max)` 采样 —— oracle `RandomNumber.Random(value)`（`RandomNumber.cs:93-100`）在
    /// `value=1` 时同样调 `random.Next(1)` 消耗一次，且 `GetRandpmRoute`（`GameShare.cs:81-86`）
    /// 的 `RandomNumber.GetInstance()` 与 `M2Share.RandomNumber` 是**同一单例** ⇒ 这一次抽样
    /// 就在世界 RNG 流里。若未来有人把 `random_below(gate_count)`「优化」成
    /// `if gate_count > 1 { … } else { 0 }`（部署 `!servertable.txt` 恰好只有 1 对网关：
    /// `0 127.0.0.1 127.0.0.1 7200`），世界流会**静默少消耗一次** ⇒ 之后所有抽数整体错位
    /// （对拍全面 flaky）——本用例即红。
    ///
    /// 手法 = 复审建议的备选「金种子序列对比」：同一种子三路对照 —— A 走生产路径；B 手抽一次
    /// `random_below(1)`（= oracle `Next(1)` 的等价消耗）；C 不抽。断言 `A ≡ B ≠ C`：
    /// 「恰好一次」由 `A=B` 钉住（少抽 ⇒ `A=C` 红；多抽 ⇒ `A` 与 `B` 的流位置错开一次，也红），
    /// 「不是零次空转」由 `A≠C` 钉住。**不用** `rng_trace::enable`：那是进程级 `OnceLock`
    /// 全局开关，并行测试下会被别的用例占住 ⇒ trace 落不到本用例的文件。
    #[test]
    fn multi_server_route_draws_once_even_with_a_single_gate() {
        let table = parse_server_table("0 127.0.0.1 127.0.0.1 7200\n");
        assert_eq!(
            table[0].game_gate_ips.len(),
            1,
            "GateCount=1（与部署 !servertable.txt 同形）"
        );

        // A：生产路径（get_multi_server_addr_port 内部的抽数）。
        let mut a = mir2_shared::rng::RandomNumber::with_seed(20_261_023);
        let got = get_multi_server_addr_port(&table, 0, &mut a);
        assert_eq!(
            got,
            Some(("127.0.0.1".to_string(), 7200)),
            "路由命中：载荷 = 第一对（唯一一对）网关"
        );
        let mark_a = a.random();

        // B：金序列 —— 手抽一次 `random_below(1)`（= oracle `Next(1)`，返回恒 0 但消耗一次）。
        let mut b = mir2_shared::rng::RandomNumber::with_seed(20_261_023);
        assert_eq!(b.random_below(1), 0, "Next(1) 返回恒 0（但消耗一次采样）");
        let mark_b = b.random();
        assert_eq!(
            mark_a, mark_b,
            "GateCount==1 必须恰好消耗一次采样（少抽/多抽 ⇒ 世界流错位）"
        );

        // C：零次对照 —— 不抽直接取下一个值；与 A 不同 ⇒ 证明 A 确实消耗了（不是空转）。
        let mut c = mir2_shared::rng::RandomNumber::with_seed(20_261_023);
        let mark_c = c.random();
        assert_ne!(
            mark_a, mark_c,
            "GateCount==1 不得跳过抽样（跳过 ⇒ 世界流静默少消耗一次）"
        );
    }

    /// `CM_CLICKNPC(1010)`：`IsCanDeal` 门、`Death`/`Ghost` 门、`ClickNpcTime` 限频门、
    /// `FindMerchant` 解析、同图/±15 距离门——全过才返回 `true`（走到 `Click` 点）。
    ///
    /// 红检：把 `is_can_deal` 门删掉 ⇒ ① 断言必红；把 `<= 15` 放宽到 `<= 20` ⇒ ③ 断言必红；
    /// 把限频门（`<= CLICK_NPC_TIME_MS`）删掉 ⇒ ④ 断言必红。
    #[test]
    fn click_npc_guards_and_reach_click_point() {
        use std::collections::HashMap;
        let mut world = mir2_world_bevy::World::new(32, 32);
        let hero = world.add_entity({
            let mut e = mir2_world_bevy::EntitySpawn::new(1, "hero", 10, 10);
            e.race = mir2_world_bevy::ACTOR_RACE_PLAY;
            e
        });
        let mid = world
            .insert_merchant(mir2_world_bevy::merchant::MerchantSpawn {
                name: "商人".to_string(),
                x: 11,
                y: 10,
                map_id: 0,
                state: mir2_world_bevy::merchant::MerchantState::new(
                    "卫家店".to_string(),
                    "0".to_string(),
                    0,
                    0,
                    100,
                    false,
                    false,
                    0,
                    mir2_world_bevy::merchant::MerchantFlags {
                        is_buy: true,
                        ..Default::default()
                    },
                    vec![0, 5],
                    Vec::new(),
                    0,
                ),
            })
            .expect("商人入世界");
        world.tick();

        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("hero".into(), test_session_ground(hero));
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("ua", "hero", 1, 0, 901, hero));
        let gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();

        // ① IsCanDeal=false ⇒ 走到 !IsCanDeal 支，返回 false（不点）。
        sessions.get_mut("hero").unwrap().is_can_deal = false;
        assert!(
            !handle_click_npc_cmd(
                mid,
                "hero",
                901,
                &online,
                &mut sessions,
                &mut world,
                &game_svr::npc::MerchantScriptBook::default(),
                &mut HashMap::new(),
                &mut HashMap::new(),
                &game_svr::npc::NpcVars::default(),
                &game_svr::ability::StdItemCatalog::new(),
                &std::sync::atomic::AtomicI32::new(0),
                &gates,
                None,
                None,
            ),
            "IsCanDeal=false ⇒ 不点"
        );
        sessions.get_mut("hero").unwrap().is_can_deal = true;

        // ② 全过：商人 (11,10) 在 ±15 ⇒ 返回 true。
        assert!(
            handle_click_npc_cmd(
                mid,
                "hero",
                901,
                &online,
                &mut sessions,
                &mut world,
                &game_svr::npc::MerchantScriptBook::default(),
                &mut HashMap::new(),
                &mut HashMap::new(),
                &game_svr::npc::NpcVars::default(),
                &game_svr::ability::StdItemCatalog::new(),
                &std::sync::atomic::AtomicI32::new(0),
                &gates,
                None,
                None,
            ),
            "商人在 ±15 ⇒ 到达 Click 点"
        );

        // ③ 商人太远（挪到 (30,30)）⇒ false。
        if let Some(m) = world.entities.transform_mut(mid) {
            m.x = 30;
            m.y = 30;
        }
        sessions.get_mut("hero").unwrap().click_npc_time = None; // 复位限频
        assert!(
            !handle_click_npc_cmd(
                mid,
                "hero",
                901,
                &online,
                &mut sessions,
                &mut world,
                &game_svr::npc::MerchantScriptBook::default(),
                &mut HashMap::new(),
                &mut HashMap::new(),
                &game_svr::npc::NpcVars::default(),
                &game_svr::ability::StdItemCatalog::new(),
                &std::sync::atomic::AtomicI32::new(0),
                &gates,
                None,
                None,
            ),
            "NPC 超 ±15 ⇒ 不点"
        );

        // ④ 限频：刚点过（同 tick）⇒ false。
        if let Some(m) = world.entities.transform_mut(mid) {
            m.x = 11;
            m.y = 10;
        }
        world.clock_ms = 100_000;
        sessions.get_mut("hero").unwrap().click_npc_time = Some(100_000);
        assert!(
            !handle_click_npc_cmd(
                mid,
                "hero",
                901,
                &online,
                &mut sessions,
                &mut world,
                &game_svr::npc::MerchantScriptBook::default(),
                &mut HashMap::new(),
                &mut HashMap::new(),
                &game_svr::npc::NpcVars::default(),
                &game_svr::ability::StdItemCatalog::new(),
                &std::sync::atomic::AtomicI32::new(0),
                &gates,
                None,
                None,
            ),
            "限频内 ⇒ 不点"
        );
        // 过了一个限频窗 ⇒ 再点成功。
        world.clock_ms = 100_000 + i64::from(CLICK_NPC_TIME_MS) + 1;
        assert!(
            handle_click_npc_cmd(
                mid,
                "hero",
                901,
                &online,
                &mut sessions,
                &mut world,
                &game_svr::npc::MerchantScriptBook::default(),
                &mut HashMap::new(),
                &mut HashMap::new(),
                &game_svr::npc::NpcVars::default(),
                &game_svr::ability::StdItemCatalog::new(),
                &std::sync::atomic::AtomicI32::new(0),
                &gates,
                None,
                None,
            ),
            "超出限频窗 ⇒ 可点"
        );
    }

    // ===================== 入站派发 P0 批：**派发级**用例 =====================
    //
    // 上面 6 条直调 `handle_*`（handler 级）；下面这组走**派发入口** [`dispatch_inbound_p0`]：
    // 构造 12B 帧（含 EDCode 尾）→ `CommandMessage::from_bytes`（= `dispatch()` 的解析口径）
    // → `dispatch_inbound_p0` → 断言出帧/副作用。牙住「ident→handler」与「线缆字段→形参」的映射
    // （这正是对抗验证 v5 判阻塞的那一层：直调 `handle_*` 检不出「去派发 / Param-Tag 互换」）。

    /// 构造 12B 命令帧（小端），形态与网关→sim 的入站帧头一致。
    fn p0_frame(ident: u16, recog: i32, param: u16, tag: u16, series: u16) -> Vec<u8> {
        let mut b = vec![0u8; COMMAND_MESSAGE_SIZE];
        b[0..4].copy_from_slice(&recog.to_le_bytes());
        b[4..6].copy_from_slice(&ident.to_le_bytes());
        b[6..8].copy_from_slice(&param.to_le_bytes());
        b[8..10].copy_from_slice(&tag.to_le_bytes());
        b[10..12].copy_from_slice(&series.to_le_bytes());
        b
    }

    /// 按 `dispatch()` 的口径把入站帧解成 `(cmd, tail)`：
    /// `len == 12 ⇒ tail=None`，否则 `EDCode.DeCodeString(body[12..len-1])`（再 GBK 解码）。
    fn p0_parse(body: Vec<u8>) -> (CommandMessage, Option<String>) {
        let cmd = CommandMessage::from_bytes(&body).expect(">=12B");
        let tail = if body.len() == COMMAND_MESSAGE_SIZE {
            None
        } else {
            Some(gbk_decode(&mir2_protocol::edcode::decode(
                &body[COMMAND_MESSAGE_SIZE..body.len() - 1],
            )))
        };
        (cmd, tail)
    }

    /// **派发级**：`CM_SOFTCLOSE(1009)` 经 `dispatch_inbound_p0` —— `Series`(=wParam) 0/1 分别只置
    /// `BoSoftClose` / 追加 `BoEmergencyClose`，并离开世界（`soft_close`）。
    ///
    /// 红检（实测见 fixtures）：把 `dispatch_inbound_p0` 的 `CM_SOFTCLOSE` 分支整条删掉 ⇒ 派发不再匹配
    /// （返回 `false`、不置位）⇒ ① 断言必红；把 `handle_soft_close_cmd(cmd.series, …)` 的实参换成 `0`
    /// ⇒ ① 的 emergency 断言必红。
    #[test]
    fn p0_dispatch_softclose_series_0_1_sets_flags() {
        use std::collections::HashMap;
        let mut world = mir2_world_bevy::World::with_maps(vec![(40, 40)]);
        world.open_session("hero");
        let hero = world
            .enter_map(
                "hero",
                mir2_world_bevy::EntitySpawn::new(0, "hero", 10, 10),
                0,
            )
            .unwrap();
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("hero".into(), test_session_ground(hero));
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("ua", "hero", 1, 0, 901, hero));
        let displays = downlink::DisplayTable::new();
        let gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        let catalog = game_svr::ability::StdItemCatalog::new();

        // ① Series=1 ⇒ 两标志置真 + 离开世界；派发对 P0 ident 返回 true。
        let (cmd, tail) = p0_parse(p0_frame(mir2_protocol::messages::CM_SOFTCLOSE, 0, 0, 0, 1));
        assert!(
            dispatch_inbound_p0(
                &cmd,
                tail.as_deref(),
                "hero",
                901,
                &online,
                &mut sessions,
                &mut world,
                &displays,
                &gates,
                &catalog,
                None,
                &mut HashMap::new(),
            ),
            "CM_SOFTCLOSE 属 P0 批 ⇒ 派发返回 true"
        );
        let sg = sessions.get("hero").unwrap();
        assert!(sg.bo_soft_close, "BoSoftClose=true");
        assert!(sg.bo_emergency_close, "Series=1 ⇒ BoEmergencyClose=true");
        assert_eq!(
            world.session("hero").unwrap().stage,
            mir2_world_bevy::WorldStage::Left,
            "BoSoftClose 支 ⇒ 离开世界"
        );

        // ② 再进世界、Series=0 ⇒ 不置 emergency（先清旧值）。
        let hero2 = world
            .enter_map(
                "hero",
                mir2_world_bevy::EntitySpawn::new(0, "hero", 12, 12),
                0,
            )
            .unwrap();
        {
            let sg = sessions.get_mut("hero").unwrap();
            sg.actor_id = hero2;
            sg.bo_emergency_close = false;
        }
        let (cmd, tail) = p0_parse(p0_frame(mir2_protocol::messages::CM_SOFTCLOSE, 0, 0, 0, 0));
        assert!(
            dispatch_inbound_p0(
                &cmd,
                tail.as_deref(),
                "hero",
                901,
                &online,
                &mut sessions,
                &mut world,
                &displays,
                &gates,
                &catalog,
                None,
                &mut HashMap::new(),
            ),
            "CM_SOFTCLOSE 属 P0 批 ⇒ 派发返回 true"
        );
        let sg = sessions.get("hero").unwrap();
        assert!(
            sg.bo_soft_close && !sg.bo_emergency_close,
            "Series=0 ⇒ 不置 BoEmergencyClose"
        );
    }

    /// **派发级**：`CM_QUERYUSERNAME(80)` 经 `dispatch_inbound_p0` —— `Param`→x、`Tag`→y 的线缆映射
    /// 在出窗时原样回带进 `SM_GHOST` 的 `Param`/`Tag`；近窗时出 `SM_USERNAME`。
    ///
    /// 用 `Param != Tag` 的请求（7/22）⇒ 一旦映射互换即被检出。
    ///
    /// 红检（实测见 fixtures）：把派发分支里 `handle_query_user_name_cmd(cmd.recog, cmd.param, cmd.tag, …)`
    /// 的 `cmd.param, cmd.tag` 对调 ⇒ ① 的 `(Param,Tag)==(7,22)` 断言必红。
    #[test]
    fn p0_dispatch_queryuser_name_param_tag_map_to_ghost_xy() {
        use std::collections::HashMap;
        let mut world = mir2_world_bevy::World::with_maps(vec![(40, 40)]);
        world.open_session("hero");
        let hero = world
            .enter_map(
                "hero",
                mir2_world_bevy::EntitySpawn::new(0, "hero", 10, 10),
                0,
            )
            .unwrap();
        world.open_session("tgt");
        let tgt = world
            .enter_map(
                "tgt",
                mir2_world_bevy::EntitySpawn::new(0, "tgt", 11, 10),
                0,
            )
            .unwrap();
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("hero".into(), test_session_ground(hero));
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("ua", "hero", 1, 0, 901, hero));
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            tgt,
            downlink::ActorDisplay::new(0, 0, 0, 0, 0, 255, b"TGT-SHOWN".to_vec()),
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let catalog = game_svr::ability::StdItemCatalog::new();

        // ① 出窗请求（x=7,y=22）：Param/Tag 取不同值 ⇒ 对调必被检出。
        let (cmd, tail) = p0_parse(p0_frame(
            mir2_protocol::messages::CM_QUERYUSERNAME,
            tgt,
            7,
            22,
            0,
        ));
        assert!(
            dispatch_inbound_p0(
                &cmd,
                tail.as_deref(),
                "hero",
                901,
                &online,
                &mut sessions,
                &mut world,
                &displays,
                &gates,
                &catalog,
                None,
                &mut HashMap::new(),
            ),
            "CM_QUERYUSERNAME 属 P0 批"
        );
        let frames = drain_frames(&mut rx0);
        assert_eq!(frames.len(), 1, "出窗 ⇒ 恰好一帧 SM_GHOST");
        let (ident, param, tag, recog) = hdr(&frames[0]);
        assert_eq!(ident, mir2_protocol::messages::SM_GHOST, "ident=803");
        assert_eq!(recog, tgt, "SM_GHOST 的 Recog=targetId");
        assert_eq!(
            (param, tag),
            (7, 22),
            "SM_GHOST 的 Param/Tag = 请求 x/y（Param→x、Tag→y，不互换）"
        );
        assert_eq!(frames[0].len(), 12, "SM_GHOST 无尾");

        // ② 近窗请求（x=10,y=10）⇒ SM_USERNAME(42)，尾 = EncodeString(showName)。
        let (cmd, tail) = p0_parse(p0_frame(
            mir2_protocol::messages::CM_QUERYUSERNAME,
            tgt,
            10,
            10,
            0,
        ));
        assert!(dispatch_inbound_p0(
            &cmd,
            tail.as_deref(),
            "hero",
            901,
            &online,
            &mut sessions,
            &mut world,
            &displays,
            &gates,
            &catalog,
            None,
            &mut HashMap::new(),
        ));
        let frames = drain_frames(&mut rx0);
        assert_eq!(frames.len(), 1, "近窗 ⇒ 恰好一帧 SM_USERNAME");
        let (ident, param, tag, recog) = hdr(&frames[0]);
        assert_eq!(ident, mir2_protocol::messages::SM_USERNAME, "ident=42");
        assert_eq!(
            (recog, param, tag),
            (tgt, 255, 0),
            "SM_USERNAME 头（Param=NameColor）"
        );
        assert_eq!(
            mir2_protocol::edcode::decode(&frames[0][12..]),
            b"TGT-SHOWN",
            "尾 = EncodeString(GetShowName())"
        );
    }

    /// **派发级**：`CM_QUERYUSERSTATE(82)` 经 `dispatch_inbound_p0` —— 线缆 `Param`→`nX`、`Tag`→`nY`
    /// 的映射进 `cetin_near_xy` 窗口命中判定；命中 ⇒ `SM_SENDUSERSTATE`（`Recog=0`），尾 =
    /// `EncodeBuffer(UserStateInfo)`（`PlayObject.Message.cs:795-797` →
    /// `ClientQueryUserInformation(nParam1,nParam2,nParam3)`；线缆即 `WorldServer.cs:793-794` 的
    /// `nParam1=Recog`、`nParam2=Param`、`nParam3=Tag`）。
    ///
    /// 用 `Param != Tag`（10/9）且**只在一侧命中**的请求 ⇒ 一旦 `cmd.param, cmd.tag` 对调，
    /// `cetin_near_xy` 的窗口不再含目标 ⇒ ① 的「恰好一帧」断言必红。
    ///
    /// 红检（实测见 fixtures）：删 `dispatch_inbound_p0` 的 `CM_QUERYUSERSTATE` 分支 ⇒ 派发返回
    /// `false` 且不再出帧 ⇒ ① 必红；把 `handle_query_user_state_cmd(cmd.recog, cmd.param, cmd.tag, …)`
    /// 的 `cmd.param, cmd.tag` 对调 ⇒ 请求 `(10,9)` 变 `(9,10)`、目标 `(11,10)` 出窗 ⇒ ① 必红。
    #[test]
    fn p0_dispatch_queryuser_state_param_tag_map_to_nx_ny() {
        use std::collections::HashMap;
        let mut world = mir2_world_bevy::World::with_maps(vec![(40, 40)]);
        world.open_session("hero");
        let hero = world
            .enter_map(
                "hero",
                mir2_world_bevy::EntitySpawn::new(0, "hero", 10, 10),
                0,
            )
            .unwrap();
        world.open_session("tgt");
        let tgt = world
            .enter_map(
                "tgt",
                mir2_world_bevy::EntitySpawn::new(0, "tgt", 11, 10),
                0,
            )
            .unwrap();
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("hero".into(), test_session_ground(hero));
        sessions.insert("tgt".into(), test_session_ground(tgt));
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("ua", "hero", 1, 0, 901, hero));
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let displays = downlink::DisplayTable::new();
        let catalog = game_svr::ability::StdItemCatalog::new();

        // 目标 tgt 在 (11,10)：窗口心 (10,9) 命中，心 (9,10) 不命中 ⇒ Param(10)/Tag(9) 只在一侧命中。
        let (cmd, tail) = p0_parse(p0_frame(
            mir2_protocol::messages::CM_QUERYUSERSTATE,
            tgt,
            10,
            9,
            0,
        ));
        assert!(
            dispatch_inbound_p0(
                &cmd,
                tail.as_deref(),
                "hero",
                901,
                &online,
                &mut sessions,
                &mut world,
                &displays,
                &gates,
                &catalog,
                None,
                &mut HashMap::new(),
            ),
            "CM_QUERYUSERSTATE 属 P0 批 ⇒ 派发返回 true"
        );
        let frames = drain_frames(&mut rx0);
        assert_eq!(
            frames.len(),
            1,
            "近窗玩家 ⇒ 恰好一帧 SM_SENDUSERSTATE（Param/Tag 互换 ⇒ 目标出窗 ⇒ 零帧）"
        );
        let (ident, _, _, recog) = hdr(&frames[0]);
        assert_eq!(
            ident,
            mir2_protocol::messages::SM_SENDUSERSTATE,
            "ident=751"
        );
        assert_eq!(recog, 0, "SM_SENDUSERSTATE 的 Recog=0");
        // 尾 = EncodeBuffer(UserStateInfo)；UserName @4 = target.Name。
        let user_state = mir2_protocol::edcode::decode(&frames[0][12..]);
        assert_eq!(user_state[4], 3, "UserName='tgt' 长度=3 @4");
        assert_eq!(&user_state[5..8], b"tgt", "UserName 内容");
    }

    /// **派发级契约（卡 `openmir2-p0-clicknpc-unit-branch`）**：`CM_CLICKNPC(1010)` **不属于 P0 批**
    /// —— 生产路径由 `sim_loop` 在调 `dispatch_inbound_p0` **之前**直调 `handle_click_npc_cmd`
    ///（那里能同时借 `&mut guilds` 给 GM 跳线与脚本宿主；p0 的 `guild` 参数与它冲突）。
    /// 本用例钉住三条：① 派发返回 `false`（交后续分支，**不得静默兜底执行 click**）；
    /// ② 会话侧 `click_npc_time` 保持 `None`（p0 确实没执行半截 click）；
    /// ③ 若有人把 `CM_CLICKNPC` 臂加回 p0（返回 `true` / 置 `ClickNpcTime`）⇒ 本用例红。
    ///
    /// 点击语义本身（IsCanDeal/Death/限频/距离门）由 `click_npc_guards_and_reach_click_point`
    /// 在 handler 级覆盖；生产直达路径由 M1c-3b 的 drain/seam 用例覆盖。
    #[test]
    fn p0_dispatch_does_not_handle_clicknpc() {
        use std::collections::HashMap;
        let mut world = mir2_world_bevy::World::new(32, 32);
        let hero = world.add_entity({
            let mut e = mir2_world_bevy::EntitySpawn::new(1, "hero", 10, 10);
            e.race = mir2_world_bevy::ACTOR_RACE_PLAY;
            e
        });
        let mid = world
            .insert_merchant(mir2_world_bevy::merchant::MerchantSpawn {
                name: "商人".to_string(),
                x: 11,
                y: 10,
                map_id: 0,
                state: mir2_world_bevy::merchant::MerchantState::new(
                    "卫家店".to_string(),
                    "0".to_string(),
                    0,
                    0,
                    100,
                    false,
                    false,
                    0,
                    mir2_world_bevy::merchant::MerchantFlags {
                        is_buy: true,
                        ..Default::default()
                    },
                    vec![0, 5],
                    Vec::new(),
                    0,
                ),
            })
            .expect("商人入世界");
        world.tick();

        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("hero".into(), test_session_ground(hero));
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("ua", "hero", 1, 0, 901, hero));
        let displays = downlink::DisplayTable::new();
        let gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        let catalog = game_svr::ability::StdItemCatalog::new();

        assert!(
            sessions.get("hero").unwrap().click_npc_time.is_none(),
            "前置：未点过（ClickNpcTime 空）"
        );
        // 线缆 Recog=npcActorId=mid；商人在 (11,10)、hero 在 (10,10) ⇒ ±15 命中。
        let (cmd, tail) = p0_parse(p0_frame(mir2_protocol::messages::CM_CLICKNPC, mid, 0, 0, 0));
        assert!(
            !dispatch_inbound_p0(
                &cmd,
                tail.as_deref(),
                "hero",
                901,
                &online,
                &mut sessions,
                &mut world,
                &displays,
                &gates,
                &catalog,
                None,
                &mut HashMap::new(),
            ),
            "CM_CLICKNPC 不属 P0 批 ⇒ 派发返回 false（生产由 sim_loop 直调 handler）"
        );
        assert!(
            sessions.get("hero").unwrap().click_npc_time.is_none(),
            "p0 不得执行 click 的任何副作用（ClickNpcTime 必须保持空）"
        );
    }

    /// **派发级**：`dispatch_inbound_p0` 的批成员判定 + `CM_QUERYVAL(1065)` 尾透传。
    /// - 非 P0 ident（`CM_SAY`）⇒ 返回 `false`（交后续分支，不属本批）；
    /// - `CM_QUERYUSERSET` ⇒ 返回 `true`、无副作用（oracle 函数体空）；
    /// - `CM_QUERYVAL` 带 EDCode 尾 ⇒ 返回 `true`，尾按 oracle 落 `MNSval[ValLabel]` 并清 `GotoNpcLabel`。
    ///
    /// 红检（实测见 fixtures）：删 `CM_QUERYUSERSET` 分支 ⇒ ② 的返回 `true` 断言必红；
    /// 删 `CM_QUERYVAL` 分支 ⇒ ③ 的 `MNSval[3]=="hello"` 断言必红。
    #[test]
    fn p0_dispatch_membership_and_queryval_tail() {
        use std::collections::HashMap;
        let mut world = mir2_world_bevy::World::with_maps(vec![(40, 40)]);
        world.open_session("hero");
        let hero = world
            .enter_map(
                "hero",
                mir2_world_bevy::EntitySpawn::new(0, "hero", 10, 10),
                0,
            )
            .unwrap();
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("hero".into(), test_session_ground(hero));
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("ua", "hero", 1, 0, 901, hero));
        let displays = downlink::DisplayTable::new();
        let gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        let catalog = game_svr::ability::StdItemCatalog::new();

        // ① 非 P0（CM_SAY=3030）⇒ false（不属本批，交后续分支）。
        let (cmd, tail) = p0_parse(p0_frame(game_svr::chat::CM_SAY, 0, 0, 0, 0));
        assert!(
            !dispatch_inbound_p0(
                &cmd,
                tail.as_deref(),
                "hero",
                901,
                &online,
                &mut sessions,
                &mut world,
                &displays,
                &gates,
                &catalog,
                None,
                &mut HashMap::new(),
            ),
            "非 P0 ident ⇒ 返回 false"
        );

        // ② CM_QUERYUSERSET ⇒ true、不改会话态。
        let (cmd, tail) = p0_parse(p0_frame(
            mir2_protocol::messages::CM_QUERYUSERSET,
            0,
            0,
            0,
            0,
        ));
        assert!(dispatch_inbound_p0(
            &cmd,
            tail.as_deref(),
            "hero",
            901,
            &online,
            &mut sessions,
            &mut world,
            &displays,
            &gates,
            &catalog,
            None,
            &mut HashMap::new(),
        ));
        assert_eq!(
            sessions.get("hero").unwrap().mns_val[3],
            "",
            "CM_QUERYUSERSET 不改会话态"
        );

        // ③ CM_QUERYVAL 带 EDCode 尾：ValType=0/ValLabel=3/GotoNpcLabel 非空 ⇒ MNSval[3]=尾串。
        {
            let sg = sessions.get_mut("hero").unwrap();
            sg.val_type = 0;
            sg.val_label = 3;
            sg.goto_npc_label = "@ask".into();
        }
        let mut body = p0_frame(mir2_protocol::messages::CM_QUERYVAL, 0, 0, 0, 0);
        body.extend_from_slice(&mir2_protocol::edcode::encode(&gbk_encode("hello")));
        body.push(0);
        let (cmd, tail) = p0_parse(body);
        assert!(dispatch_inbound_p0(
            &cmd,
            tail.as_deref(),
            "hero",
            901,
            &online,
            &mut sessions,
            &mut world,
            &displays,
            &gates,
            &catalog,
            None,
            &mut HashMap::new(),
        ));
        let sg = sessions.get("hero").unwrap();
        assert_eq!(sg.mns_val[3], "hello", "CM_QUERYVAL 尾经派发落 MNSval[3]");
        assert!(sg.goto_npc_label.is_empty(), "末尾清空 GotoNpcLabel");
    }
    // ======================= 接线批 A（TransMap 簇 + 会话/门）端到端 =======================

    /// **接线批 A 端到端（TransMap 簇）**：`World::switch_map_space` 成功 ⇒ `SessionRegistry` 记一条
    /// `MapChange` ⇒ `drain_map_change` 按 oracle 序出
    /// `SM_CLEAROBJECTS(633)` → `SM_CHANGEMAP(634)`（`SendMsg`，只发自己）→
    /// `SM_SPACEMOVE_SHOW(801)`（`SendRefMsg`，±`SendRefMsgRange` 格内 `Race==Play && !Ghost`，含自己）。
    ///
    /// **观察者集合**：SHOW 只到 hero（自己）+ peer（近邻）；far（远）与 mon（怪物）不收。
    /// **红检 1**：把 `map_change_frames` 里 CLEAROBJECTS/CHANGEMAP 两条对调 ⇒ 帧序断言必红。
    /// **红检 3**：把 SHOW 的 `route` 从 `Ref` 改成 `SelfOnly` ⇒ 观察者断言必红。
    #[test]
    fn drain_map_change_emits_transmap_cluster_and_ref_observers() {
        use mir2_protocol::messages;
        use std::collections::HashMap;
        // `World::new` 只建 0 号图 ⇒ 手工加 1 号图供换图落地。
        let mut world = mir2_world_bevy::World::new(64, 64);
        world.maps.push(mir2_world_bevy::map::MapGrid::new(64, 64));
        world.open_session("hero");
        let hero = world
            .enter_map("hero", new_player_entity("hero".to_string(), 5, 5), 0)
            .expect("hero 进图");
        // 观察者们在**目标图**（1 号图）上，落点 (7,9) 的 ±12 格内。
        world.open_session("peer");
        let peer = world
            .enter_map("peer", new_player_entity("peer".to_string(), 8, 9), 1)
            .expect("peer 进图");
        world.open_session("far");
        let far = world
            .enter_map("far", new_player_entity("far".to_string(), 40, 40), 1)
            .expect("far 进图");
        // 近处怪物（Race != Play）⇒ 不该收 SHOW。
        world.add_entity({
            let mut e = mir2_world_bevy::EntitySpawn::new(0, "mon", 8, 9);
            e.race = mir2_world_bevy::ACTOR_RACE_MONSTER;
            e.map_id = 1;
            e
        });
        let mut displays = downlink::DisplayTable::new();
        for id in [hero, peer, far] {
            displays.set(
                id,
                downlink::ActorDisplay::new(2, 6, 111, 0, 0, 255, b"n".to_vec()),
            );
        }
        let mut online: OnlineRegistry = OnlineRegistry::new();
        for (acct, nm, sid, sock, id) in [
            ("a", "hero", 1, 901, hero),
            ("b", "peer", 2, 902, peer),
            ("c", "far", 3, 903, far),
        ] {
            online_set(
                &mut online,
                OnlineEntry {
                    account: acct.into(),
                    chr_name: nm.into(),
                    session_id: sid,
                    gate_idx: 0,
                    socket: sock,
                    actor_id: id,
                },
            );
        }
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);

        // SpaceMove 支（`nInt != 1` ⇒ `SM_SPACEMOVE_SHOW(801)`）。
        world
            .switch_map_space("hero", 1, 7, 9, false)
            .expect("换图落地");
        assert_eq!(
            world.sessions.map_changes().len(),
            1,
            "落地记一条 MapChange"
        );

        drain_map_change(&mut world, &online, &gates, &displays, None);
        assert!(
            world.sessions.map_changes().is_empty(),
            "drain 后事件清空（不重复出帧）"
        );

        let mut seq: Vec<(i32, u16)> = Vec::new();
        while let Ok(SimToGate::SendFrame { socket, body }) = rx0.try_recv() {
            seq.push((socket, u16::from_le_bytes([body[4], body[5]])));
        }
        // ① hero 自己收 CLEAROBJECTS + CHANGEMAP（`SendMsg`）。
        assert!(
            seq.contains(&(901, messages::SM_CLEAROBJECTS)),
            "hero 收 633"
        );
        assert!(seq.contains(&(901, messages::SM_CHANGEMAP)), "hero 收 634");
        // ② SHOW(801) 到 hero + peer（近邻），不到 far（远）/ mon（非玩家）。
        assert!(
            seq.contains(&(901, messages::SM_SPACEMOVE_SHOW)),
            "hero(自己) 收 801"
        );
        assert!(
            seq.contains(&(902, messages::SM_SPACEMOVE_SHOW)),
            "peer(近邻) 收 801"
        );
        assert!(
            !seq.iter()
                .any(|(sk, id)| *sk == 903 && *id == messages::SM_SPACEMOVE_SHOW),
            "far(40,40) 超出 SendRefMsgRange ⇒ 不收 801"
        );
        // ③ CLEAROBJECTS/CHANGEMAP 是 SendMsg ⇒ peer 不收这两条。
        assert!(
            !seq.iter().any(|(sk, id)| *sk == 902
                && (*id == messages::SM_CLEAROBJECTS || *id == messages::SM_CHANGEMAP)),
            "peer 不收 SendMsg 帧（633/634）"
        );
        // ④ 帧序（hero 的 socket 上）：CLEAROBJECTS 必须先于 CHANGEMAP。
        let hero_ids: Vec<u16> = seq
            .iter()
            .filter(|(sk, _)| *sk == 901)
            .map(|(_, id)| *id)
            .collect();
        let pos_clear = hero_ids
            .iter()
            .position(|id| *id == messages::SM_CLEAROBJECTS)
            .unwrap();
        let pos_map = hero_ids
            .iter()
            .position(|id| *id == messages::SM_CHANGEMAP)
            .unwrap();
        assert!(
            pos_clear < pos_map,
            "oracle 序：CLEAROBJECTS(633) 先于 CHANGEMAP(634)"
        );
    }

    /// **接线批 A 端到端（EnterAnotherMap 支）**：无 `space_move_show` ⇒ 只出 2 帧（不出 `SM_SPACEMOVE_SHOW`）。
    #[test]
    fn drain_map_change_enter_another_map_has_no_show_frame() {
        use mir2_protocol::messages;
        use std::collections::HashMap;
        let mut world = mir2_world_bevy::World::new(64, 64);
        world.maps.push(mir2_world_bevy::map::MapGrid::new(64, 64));
        world.open_session("hero");
        let hero = world
            .enter_map("hero", new_player_entity("hero".to_string(), 5, 5), 0)
            .expect("进图");
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            hero,
            downlink::ActorDisplay::new(2, 6, 111, 0, 0, 255, b"n".to_vec()),
        );
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "a".into(),
                chr_name: "hero".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: hero,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        world.switch_map("hero", 1, 7, 9).expect("换图落地");
        drain_map_change(&mut world, &online, &gates, &displays, None);
        let mut ids = Vec::new();
        while let Ok(SimToGate::SendFrame { body, .. }) = rx0.try_recv() {
            ids.push(u16::from_le_bytes([body[4], body[5]]));
        }
        assert_eq!(
            ids,
            vec![messages::SM_CLEAROBJECTS, messages::SM_CHANGEMAP],
            "EnterAnotherMap 支：无 SM_SPACEMOVE_SHOW"
        );
    }

    /// **`CM_WANTMINIMAP(1033)` 生产入口端到端**（卡 `openmir2-minimap-consumer-wire`，tier=L）：
    /// 会话当前 `map_id` → `MapRegistry::name_of` → `MiniMapRegistry::get` = oracle
    /// `Envirnoment.MinMap`（`MapManager.cs:92-95`）→ `ClientGetMinMap`
    /// （`PlayObject.Operate.cs:1204-1214`）⇒ `SM_READMINIMAP_OK(710, recog 0, param MinMap, 0, 0)`。
    ///
    /// 逐字节断言 12B 命令头（无尾）：`Recog=0, Ident=710(0x02C6), Param=7, Tag=0, Series=0`。
    /// 第二支（注册表里没有该图）⇒ `SM_READMINIMAP_FAIL(711, 0, 0, 0, 0)`。
    ///
    /// **牙**：删掉 `handle_inbound_cmd` 的 `CM_WANTMINIMAP` 臂 ⇒ 一支帧都没有 ⇒ 本例必红；
    /// 把 `session_min_map` 写死 0（旧接线）⇒ 第一支出 711 ⇒ 本例必红。
    #[test]
    fn cm_wantminimap_emits_ok_with_session_map_minmap() {
        use mir2_protocol::messages;
        use std::collections::HashMap;
        use std::sync::atomic::{AtomicU32, Ordering};

        // ① Envir 注册表：`MapInfo.txt` 逻辑名 `map` ↔ `0.map`（20×20 全 0 格）⇒ map_id 0。
        static COUNTER: AtomicU32 = AtomicU32::new(0);
        let base = std::env::temp_dir().join(format!(
            "gs-minimap-want-{}-{}",
            std::process::id(),
            COUNTER.fetch_add(1, Ordering::Relaxed)
        ));
        let _ = std::fs::remove_dir_all(&base);
        std::fs::create_dir_all(base.join("Map")).unwrap();
        let (w, h) = (20_i16, 20_i16);
        let mut bytes = vec![0u8; mir2_envir::HEADER_BYTES];
        bytes[0..2].copy_from_slice(&w.to_le_bytes());
        bytes[2..4].copy_from_slice(&h.to_le_bytes());
        bytes.resize(
            mir2_envir::HEADER_BYTES
                + usize::try_from(w).unwrap()
                    * usize::try_from(h).unwrap()
                    * mir2_envir::CELL_BYTES,
            0,
        );
        std::fs::write(base.join("Map").join("0.map"), &bytes).unwrap();
        let registry = mir2_envir::MapRegistry::from_entries(
            mir2_envir::MapLoader::new(base.clone(), "Map", "Envir"),
            vec![mir2_envir::MapInfoEntry {
                map_name: "map".to_string(),
                map_file_name: "0".to_string(),
                desc: String::new(),
                server_index: 0,
                flag: mir2_envir::MapInfoFlag::default(),
            }],
        );
        assert_eq!(registry.name_of(0), Some("map"));

        // ② `MiniMap.txt`：`map 7` ⇒ `MiniMapList["map"] = 7`。
        let (minimap, dups) = mir2_envir::load_minimap("map 7\n");
        assert!(dups.is_empty());
        assert_eq!(minimap.get("map"), Some(7));

        // ③ 世界：hero 进 0 号图（map_id 0）。
        let mut world = mir2_world_bevy::World::with_maps(vec![(20, 20)]);
        world.open_session("hero");
        let hero = world
            .enter_map(
                "hero",
                mir2_world_bevy::EntitySpawn::new(0, "hero", 5, 5),
                0,
            )
            .unwrap();
        assert_eq!(world.session("hero").unwrap().map_id, 0);

        let online: OnlineRegistry = OnlineRegistry::from(vec![OnlineEntry {
            account: "a".into(),
            chr_name: "hero".into(),
            session_id: 1,
            gate_idx: 0,
            socket: 901,
            actor_id: hero,
        }]);
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut pwd_sessions: HashMap<String, game_svr::inbound::PwdSession> = HashMap::new();
        let cfg = GroundCfg {
            human_max_gold: 10_000_000,
            floor_item_can_pick_up_time: 120_000,
            control_drop_item: false,
            in_safe_disable_drop: false,
            can_drop_price: 500,
            can_drop_gold: 1000,
            drop_item_rage: 3,
        };
        let displays = downlink::DisplayTable::new();
        let cmd = CommandMessage {
            recog: 0,
            ident: messages::CM_WANTMINIMAP,
            param: 0,
            tag: 0,
            series: 0,
        };

        // ① OK 支：`Envir.MinMap = 7 > 0` ⇒ SM_READMINIMAP_OK(710), Param = 7。
        handle_inbound_cmd(
            &cmd,
            None,
            "hero",
            901,
            &online,
            &mut world,
            &mut sessions,
            &gates,
            Some(&registry),
            Some(&minimap),
            &mut pwd_sessions,
            &cfg,
            &displays,
            // 测试用：空物品目录 + oracle 布局 + 红 253/0。
            &test_frames_ctx(&game_svr::ability::StdItemCatalog::new()),
        );
        let frames = drain_frames(&mut rx0);
        assert_eq!(frames.len(), 1, "收 1033 ⇒ 恰好一帧 SM_READMINIMAP_*");
        assert_eq!(
            frames[0],
            vec![0, 0, 0, 0, 0xC6, 0x02, 0x07, 0x00, 0, 0, 0, 0],
            "SM_READMINIMAP_OK：Recog=0, Ident=710, Param=MinMap=7, Tag=0, Series=0"
        );

        // ② FAIL 支：同一会话，但 `MiniMap.txt` 里没有该图名 ⇒ `Envir.MinMap` 保持初值 0。
        let (other_minimap, _) = mir2_envir::load_minimap("somewhere 9\n");
        handle_inbound_cmd(
            &cmd,
            None,
            "hero",
            901,
            &online,
            &mut world,
            &mut sessions,
            &gates,
            Some(&registry),
            Some(&other_minimap),
            &mut pwd_sessions,
            &cfg,
            &displays,
            // 测试用：空物品目录 + oracle 布局 + 红 253/0。
            &test_frames_ctx(&game_svr::ability::StdItemCatalog::new()),
        );
        let frames = drain_frames(&mut rx0);
        assert_eq!(frames.len(), 1);
        assert_eq!(
            frames[0],
            vec![0, 0, 0, 0, 0xC7, 0x02, 0, 0, 0, 0, 0, 0],
            "SM_READMINIMAP_FAIL(711, 0, 0, 0, 0)"
        );

        // ③ 无 `MiniMap.txt`（注册表 None）⇒ 同上 FAIL 支。
        handle_inbound_cmd(
            &cmd,
            None,
            "hero",
            901,
            &online,
            &mut world,
            &mut sessions,
            &gates,
            Some(&registry),
            None,
            &mut pwd_sessions,
            &cfg,
            &displays,
            // 测试用：空物品目录 + oracle 布局 + 红 253/0。
            &test_frames_ctx(&game_svr::ability::StdItemCatalog::new()),
        );
        let frames = drain_frames(&mut rx0);
        assert_eq!(frames.len(), 1);
        assert_eq!(u16::from_le_bytes([frames[0][4], frames[0][5]]), 711);

        let _ = std::fs::remove_dir_all(&base);
    }

    // ─────────────────── CM_ADJUST_BONUS(1043) 端到端（卡 `openmir2-cm-adjust-bonus`） ───────────────────

    /// `CM_ADJUST_BONUS(1043)` 的用例骨架：一条进世界的 hero + 会话（`BonusPoint` 可设）+ 网关通道。
    ///
    /// 会话侧的 `WAbil`/`SubAbility` 用**入图同一实现**（[`recalc_session_ability`]）先算一遍
    /// ⇒ 用例里的「重算前真值」= oracle 进世界时 `RecalcAbilitys()` 的产物；装备槽装一把木剑
    /// （`newbie_catalog` 的 3 号，`std_mode 5`、`weight 5`）让 52 的载荷不是全零。
    struct AdjustBonusFix {
        world: mir2_world_bevy::World,
        online: OnlineRegistry,
        sessions: HashMap<String, SessionGround>,
        gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>>,
        rx: mpsc::UnboundedReceiver<SimToGate>,
        catalog: game_svr::ability::StdItemCatalog,
        actor: i32,
    }

    impl AdjustBonusFix {
        fn new(bonus_point: i32) -> Self {
            let mut world = mir2_world_bevy::World::with_maps(vec![(20, 20)]);
            world.open_session("hero");
            let actor = world
                .enter_map(
                    "hero",
                    mir2_world_bevy::EntitySpawn::new(0, "hero", 5, 5),
                    0,
                )
                .unwrap();
            let online: OnlineRegistry = OnlineRegistry::from(vec![OnlineEntry {
                account: "a".into(),
                chr_name: "hero".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: actor,
            }]);
            let (tx0, rx) = mpsc::unbounded_channel::<SimToGate>();
            let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
            gates.insert(0, tx0);
            let catalog = newbie_catalog();
            let mut sg = test_session_ground(actor);
            sg.bonus_point = bonus_point;
            sg.use_items[game_svr::ability::SLOT_WEAPON] = Some(game_svr::bag::BagItem {
                make_index: 1,
                index: 3,
                dura: 20,
                dura_max: 20,
                desc: [0u8; 14],
            });
            // 背包放一根蜡烛（1 号，`weight 1`）⇒ `WAbil.Weight`（`RecalcBagWeight`）非零。
            sg.state.item_list = vec![game_svr::bag::BagItem {
                make_index: 2,
                index: 1,
                dura: 20,
                dura_max: 20,
                desc: [0u8; 14],
            }];
            let _ = recalc_session_ability(&mut sg, &catalog, None, None, None);
            if let Some(mut e) = world.entities.get_mut(actor) {
                apply_ability_to_entity(&mut e, &sg.state.wabil, &sg.sub, sg.hit_speed);
            }
            let mut sessions = HashMap::new();
            sessions.insert("hero".to_string(), sg);
            Self {
                world,
                online,
                sessions,
                gates,
                rx,
                catalog,
                actor,
            }
        }

        /// 发一条 `CM_ADJUST_BONUS`（`nPoint` 在 `Recog`，见 `WorldServer.cs:827-829`）并取走本批帧。
        fn send(&mut self, n_point: i32) -> Vec<Vec<u8>> {
            let cmd = CommandMessage {
                recog: n_point,
                ident: mir2_protocol::messages::CM_ADJUST_BONUS,
                param: 0,
                tag: 0,
                series: 0,
            };
            let cfg = GroundCfg {
                human_max_gold: 10_000_000,
                floor_item_can_pick_up_time: 120_000,
                control_drop_item: false,
                in_safe_disable_drop: false,
                can_drop_price: 500,
                can_drop_gold: 1000,
                drop_item_rage: 3,
            };
            let displays = downlink::DisplayTable::new();
            let mut pwd_sessions: HashMap<String, game_svr::inbound::PwdSession> = HashMap::new();
            handle_inbound_cmd(
                &cmd,
                None,
                "hero",
                901,
                &self.online,
                &mut self.world,
                &mut self.sessions,
                &self.gates,
                None,
                None,
                &mut pwd_sessions,
                &cfg,
                &displays,
                &test_frames_ctx(&self.catalog),
            );
            drain_frames(&mut self.rx)
        }
    }

    /// **`CM_ADJUST_BONUS` ①（合法支）**：`nPoint == BonusPoint` ⇒ `BonusPoint = nPoint`（**等值**，
    /// 门是 `nPoint + 0 == BonusPoint`）、真跑 `RecalcAbilitys()`、线上
    /// **`752 → 52 → 657`（各 1 条）**——优先级 `RM_SUBABILITY=62 < RM_ABILITY=67 <
    /// RM_CHARSTATUSCHANGED=155`；657 之所以只 1 条是 `SendUpdateMsg` 的**头-only 去重**
    /// （`BaseObject.Message.cs:283-303`）删掉了 `StatusChanged()` 刚入的那条。
    ///
    /// 红检（复审 `124fe49e` I-1/I-2 的证伪牙）：改成「源码序 52→752」或「657×2」⇒ 本用例红。
    ///
    /// **牙 1「撤会话态」**：把派发臂的 `sg.bonus_point` 换回常量 0（旧缺陷）⇒ 本用例
    /// （`BonusPoint=3`、`nPoint=3`）落到非法支 ⇒ 帧面与属性断言全红。
    #[test]
    fn adjust_bonus_valid_equal_point_emits_752_52_and_one_657() {
        let mut fix = AdjustBonusFix::new(3);
        let (wabil0, sub0, hit0) = {
            let sg = &fix.sessions["hero"];
            (sg.state.wabil.clone(), sg.sub, sg.hit_speed)
        };
        let frames = fix.send(3);
        let ids: Vec<u16> = frames.iter().map(|f| hdr(f).0).collect();
        assert_eq!(
            ids,
            vec![
                mir2_protocol::messages::SM_SUBABILITY,
                mir2_protocol::messages::SM_ABILITY,
                mir2_protocol::messages::SM_CHARSTATUSCHANGED,
            ],
            "oracle 出队序：RM_SUBABILITY(62) → RM_ABILITY(67) → RM_CHARSTATUSCHANGED(155)，657 仅 1 条"
        );
        // `BonusPoint = nPoint`（等值赋值 ⇒ 会话值不变；`BonusAbil.* += 0` 同理，BUG-REPLICA 3）。
        assert_eq!(fix.sessions["hero"].bonus_point, 3);
        assert_eq!(
            fix.sessions["hero"].state.wabil, wabil0,
            "输入不变 ⇒ WAbil 逐字段不变"
        );
        assert_eq!(fix.sessions["hero"].sub, sub0, "SubAbility 逐字段不变");
        // 657：`(Recog=ActorId, Param=LoWord(CharStatus), Tag=HiWord(CharStatus), Series=HitSpeed)`。
        let (ident, param, tag, recog) = hdr(&frames[2]);
        assert_eq!(ident, mir2_protocol::messages::SM_CHARSTATUSCHANGED);
        assert_eq!((param, tag), (0, 0), "CharStatus = 0（无 buff）");
        assert_eq!(recog, fix.actor);
        assert_eq!(
            u16::from_le_bytes([frames[2][10], frames[2][11]]),
            hit0,
            "Series = 重算后的 HitSpeed"
        );
        assert_eq!(
            frames.len(),
            3,
            "657 必须只有 1 条（SendUpdateMsg 头-only 去重；登录的 2 条是另一种队列形态）"
        );
        // 实体侧（战斗权威值）与 52 的载荷同源。
        let e = fix.world.entities.get(fix.actor).unwrap();
        assert_eq!(e.max_hp, fix.sessions["hero"].state.wabil.max_hp);
        assert_eq!(e.max_mp, fix.sessions["hero"].state.wabil.max_mp);
        assert_eq!(e.ac, i32::from(fix.sessions["hero"].state.wabil.ac));
    }

    /// **`CM_ADJUST_BONUS` ②（失败支）**：`nPoint != BonusPoint` ⇒ **零** 52/752/657，只有一条
    /// 红色 `SysMsg("非法数据调整!!!", Red, Hint)`（`PlayObject.Base.cs:1177-1179`）；`BonusPoint`
    /// 与会话属性都不动。
    ///
    /// **牙 2「门写反」**：把 [`game_svr::inbound::client_adjust_bonus`] 的 `==` 写成 `!=` ⇒ 本用例的
    /// 三个 `nPoint` 全部被接受（出 4 帧）⇒ 必红；用例①的 `nPoint==BonusPoint` 反被拒 ⇒ 也红。
    #[test]
    fn adjust_bonus_mismatched_point_emits_only_red_sysmsg() {
        let mut fix = AdjustBonusFix::new(3);
        let (wabil0, sub0) = {
            let sg = &fix.sessions["hero"];
            (sg.state.wabil.clone(), sg.sub)
        };
        let expected = game_svr::smframe::sm_sysmessage(
            fix.actor,
            253,
            0,
            &gbk_encode(ADJUST_BONUS_INVALID_MSG),
        );
        for n in [0, 7, -1] {
            let frames = fix.send(n);
            assert_eq!(
                frames.len(),
                1,
                "nPoint={n} ≠ BonusPoint=3 ⇒ 只有一条 SysMsg"
            );
            assert_eq!(
                frames[0], expected,
                "SM_SYSMESSAGE(252)：红 253/0 + GBK 原文"
            );
            let (ident, param, tag, recog) = hdr(&frames[0]);
            assert_eq!(ident, mir2_protocol::messages::SM_SYSMESSAGE);
            assert_eq!(recog, fix.actor, "Recog = 自己的 ActorId");
            assert_eq!(
                param, 253,
                "Param = MakeWord(RedMsgFColor=253, RedMsgBColor=0)"
            );
            assert_eq!(tag, 0);
            assert_eq!(
                u16::from_le_bytes([frames[0][10], frames[0][11]]),
                1,
                "Series 恒 1"
            );
            assert_eq!(fix.sessions["hero"].bonus_point, 3, "失败支不动 BonusPoint");
            assert_eq!(fix.sessions["hero"].state.wabil, wabil0, "失败支不重算");
            assert_eq!(fix.sessions["hero"].sub, sub0);
        }
    }

    /// **`CM_ADJUST_BONUS` ③（重算口径）**：成功支的 52 载荷 `MaxHP/MaxMP/AC/MAC/DC/MC/SC` 与
    /// `RecalcAbilitys()` 的 oracle 口径一致——期望值用**字面量**钉住（等级 1 战士 + 木剑 `weight 5`），
    /// 再用同一份 `wabil` 独立重建 52/752 帧做逐字节比对。
    ///
    /// 牙：漏掉会话装备（`use_items`）⇒ `Weight`/`WearWeight`/`MaxWeight` 变；把 `prior` 传成
    /// `SubAbility::first_call()`（重复调用的 T-18 口径）⇒ `SubAbility` 的 recover 项变 ⇒ 752 红。
    #[test]
    fn adjust_bonus_recalc_matches_oracle_pinned_ability() {
        let mut fix = AdjustBonusFix::new(0);
        let frames = fix.send(0);
        assert_eq!(frames.len(), 3, "合法支出 752/52/657");
        let w = &fix.sessions["hero"].state.wabil;
        assert_eq!(
            (
                w.max_hp,
                w.max_mp,
                w.ac,
                w.mac,
                w.dc,
                w.mc,
                w.sc,
                w.weight,
                w.wear_weight,
                w.hand_weight,
                w.max_weight,
            ),
            (19u16, 15u16, 0u16, 0u16, 257u16, 0u16, 0u16, 1u16, 0u8, 5u8, 50u16),
            "oracle 口径：等级 1 战士裸装 + 木剑"
        );
        assert_eq!(
            frames[1],
            game_svr::smframe::sm_ability(0, 0, 0, &record::encode_ability(w)),
            "52 帧尾 = Encode(40B TAbility)，载荷逐字段来自 RecalcAbilitys"
        );
        let sb = fix.sessions["hero"].sub.to_frame_bytes();
        assert_eq!(
            frames[0],
            game_svr::smframe::sm_subability(
                sb[0],
                u8::try_from(sb[1]).unwrap_or(0),
                u8::try_from(sb[2]).unwrap_or(0),
                u8::try_from(sb[3]).unwrap_or(0),
                u8::try_from(sb[4]).unwrap_or(0),
                u8::try_from(sb[5]).unwrap_or(0),
                u8::try_from(sb[6]).unwrap_or(0),
            ),
            "752 帧 = SubAbility 的 7 项（AntiMagic/HitPoint/SpeedPoint/…）"
        );
    }

    /// **接线批 A 端到端（SM_PASSWORD）**：`CM_PASSWORD` 命中 `ProcessClientPassword` 的重设支
    /// （`IsSetStoragePwd=true` + 4-7 位密码）⇒ 出 `SM_PASSWORD(5009)`，且状态迁到 `IsReConfigPwd`。
    ///
    /// **红检 2**：把 `CM_PASSWORD` 分支改回「只记日志」（不出帧）⇒ 本用例必红。
    #[test]
    fn cm_password_emits_sm_password_on_reset_branch() {
        use mir2_protocol::messages;
        use std::collections::HashMap;
        let mut world = mir2_world_bevy::World::new(32, 32);
        let displays = downlink::DisplayTable::new();
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "a".into(),
                chr_name: "hero".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: 1,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut pwd_sessions: HashMap<String, game_svr::inbound::PwdSession> = HashMap::new();
        pwd_sessions.insert(
            "hero".into(),
            game_svr::inbound::PwdSession {
                state: game_svr::inbound::StoragePwdState {
                    is_set_storage_pwd: true,
                    ..Default::default()
                },
                locks: Default::default(),
            },
        );
        let cfg = GroundCfg {
            human_max_gold: 10_000_000,
            floor_item_can_pick_up_time: 120_000,
            control_drop_item: false,
            in_safe_disable_drop: false,
            can_drop_price: 500,
            can_drop_gold: 1000,
            drop_item_rage: 3,
        };
        let cmd = CommandMessage {
            recog: 0,
            ident: messages::CM_PASSWORD,
            param: 1,
            tag: 0,
            series: 0,
        };
        handle_inbound_cmd(
            &cmd,
            Some("abcd"),
            "hero",
            901,
            &online,
            &mut world,
            &mut sessions,
            &gates,
            None,
            None,
            &mut pwd_sessions,
            &cfg,
            &displays,
            // 测试用：空物品目录 + oracle 布局 + 红 253/0。
            &test_frames_ctx(&game_svr::ability::StdItemCatalog::new()),
        );
        let mut ids = Vec::new();
        while let Ok(SimToGate::SendFrame { body, .. }) = rx0.try_recv() {
            ids.push(u16::from_le_bytes([body[4], body[5]]));
        }
        assert_eq!(
            ids,
            vec![messages::SM_PASSWORD],
            "重设支 ⇒ 只出 SM_PASSWORD(5009)"
        );
        assert!(
            pwd_sessions.get("hero").unwrap().state.is_re_config_pwd,
            "状态机迁到 IsReConfigPwd"
        );
        assert!(
            pwd_sessions.get("hero").unwrap().state.ms_temp_pwd == "abcd",
            "临时密码写回会话"
        );
    }

