    /// **接线批 A 端到端（SM_CHANGELIGHT）**：卸下一件 `Light>0` 的装备 ⇒ `RecalcAbilitys` 的
    /// `oldlight != Light` 支 ⇒ `SM_CHANGELIGHT(654)` 广播给 ±`SendRefMsgRange` 格内的玩家（含自己）。
    ///
    /// 造：actor 42 在世界上；`UseItems[Dress]` 放一件 `Light=5` 的衣；展示表 `light=5`
    /// （进世界时的 `GetMyLight`）；卸下后 `my_light` 回落到 0 ⇒ 出帧。
    /// **红检**：删掉 `handle_bag_cmd` 里的 `changelight_frame` 广播 ⇒ 本用例必红。
    #[test]
    fn bag_takeoff_emits_changelight_when_light_drops() {
        use std::collections::HashMap;
        let mut catalog = game_svr::ability::StdItemCatalog::new();
        catalog.insert(
            1,
            mir2_data::StdItem {
                name: "布衣".into(),
                std_mode: 5,
                light: 5,
                ..Default::default()
            },
        );
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut sg = test_session_ground(42);
        sg.use_items[0] = Some(game_svr::bag::BagItem {
            make_index: 60001,
            index: 1,
            dura: 10,
            dura_max: 10,
            desc: [0u8; 14],
        });
        sessions.insert("hero".into(), sg);
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "ua".into(),
                chr_name: "hero".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: 42,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut world = mir2_world_bevy::World::new(8, 8);
        world.add_entity(mir2_world_bevy::EntitySpawn::new(42, "hero", 3, 3));
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            42,
            downlink::ActorDisplay::new(2, 5, 111, 0, 0, 255, b"hero".to_vec()),
        );
        handle_bag_cmd(
            game_svr::bag::CM_TAKEOFFITEM,
            60001,
            0,
            0,
            Some("布衣"),
            "hero",
            901,
            &online,
            &mut sessions,
            &gates,
            &catalog,
            &mut world,
            &mut displays,
            12,
            false,
            true,
        );
        let mut ids = Vec::new();
        while let Ok(SimToGate::SendFrame { socket, body }) = rx0.try_recv() {
            assert_eq!(socket, 901, "回帧发给该用户 socket");
            ids.push(u16::from_le_bytes([body[4], body[5]]));
        }
        assert!(
            ids.contains(&mir2_protocol::messages::SM_CHANGELIGHT),
            "卸下 Light=5 装备 ⇒ 出 SM_CHANGELIGHT(654)；实得 idents {ids:?}"
        );
        assert_eq!(
            displays.get(42).unwrap().light,
            0,
            "重算后展示表 Light 回落到 0"
        );
    }

    /// **L1 TransMap 端到端 + 帧序**：玩家走一格踩中 `MapRoute` ⇒ `handle_move_cmd` 先冲换图簇
    /// （`SM_CLEAROBJECTS(633)` → `SM_CHANGEMAP(634)`，`SendMsg` 只发 hero），再广播移动帧
    /// （`SM_WALK` 给**换图后新图**近邻 obs）——oracle 序：簇先、移动帧后
    /// （`PlayObject.Walk` 尾段才 `SendRefMsg(nIdent,…)`）。
    ///
    /// **帧序回归牙**：去掉 `handle_move_cmd` 里 `if outcome.changed_map { drain_map_change(...) }`
    /// ⇒ 633/634 只剩 tick 尾的 drain（本测不调 tick）⇒ 帧序断言（633 先于 SM_WALK）必红。
    #[test]
    fn move_cmd_route_emits_transmap_cluster_before_move_frame() {
        use mir2_protocol::messages::{CM_WALK, SM_CHANGEMAP, SM_CLEAROBJECTS, SM_WALK};
        use std::collections::HashMap;
        let mut world = mir2_world_bevy::World::new(64, 64);
        world.maps.push(mir2_world_bevy::map::MapGrid::new(64, 64));
        world.open_session("hero");
        let hero = world
            .enter_map("hero", new_player_entity("hero".to_string(), 5, 4), 0)
            .expect("hero 进图");
        // obs 在目标图 (7,9) ±12 格内 ⇒ 收移动帧（oracle 用换图后新坐标广播）。
        world.open_session("obs");
        let obs = world
            .enter_map("obs", new_player_entity("obs".to_string(), 8, 9), 1)
            .expect("obs 进图");
        // map0 (5,5) → map1 (7,9)
        assert_eq!(
            world.add_map_routes(vec![mir2_world_bevy::map::MapRouteSpec {
                map_id: 0,
                x: 5,
                y: 5,
                route_id: 1,
                hop: mir2_world_bevy::map::RouteHop {
                    dst_map_id: 1,
                    dst_x: 7,
                    dst_y: 9,
                },
            }]),
            1
        );
        let mut displays = downlink::DisplayTable::new();
        for id in [hero, obs] {
            displays.set(
                id,
                downlink::ActorDisplay::new(0, 0, 111, 0, 0, 255, b"n".to_vec()),
            );
        }
        let mut online: OnlineRegistry = OnlineRegistry::new();
        for (acct, nm, sid, sock, id) in [("a", "hero", 1, 901, hero), ("b", "obs", 2, 902, obs)] {
            online_set(
                &mut online,
                OnlineEntry {
                    account: acct.into(),
                    chr_name: nm.into(),
                    session_id: sid,
                    gate_idx: 0,
                    socket: sock,
                    actor_id: id,
                },
            );
        }
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);

        // 目标 = (5,5)（hero 当前格正下方）⇒ 方向 Down，走一格踩中 route。
        handle_move_cmd(
            CM_WALK,
            game_svr::feature::make_long(5, 5),
            0,
            "hero",
            901,
            &online,
            &mut HashMap::new(),
            &mut world,
            &mut displays,
            &gates,
            None,
        );

        // 换图落地：hero 在 map1 (7,9)。
        let he = world.entities.get(hero).unwrap();
        assert_eq!((he.map_id, he.x, he.y), (1, 7, 9));

        // 同一 gate 0 通道，保序收集出帧。
        let mut seq: Vec<(i32, u16)> = Vec::new();
        while let Ok(SimToGate::SendFrame { socket, body }) = rx0.try_recv() {
            seq.push((socket, u16::from_le_bytes([body[4], body[5]])));
        }
        assert!(seq.contains(&(901, SM_CLEAROBJECTS)), "hero 收 633");
        assert!(seq.contains(&(901, SM_CHANGEMAP)), "hero 收 634");
        assert!(
            seq.iter().any(|(sk, id)| *sk == 902 && *id == SM_WALK),
            "obs 收移动帧 SM_WALK"
        );
        let i_clear = seq
            .iter()
            .position(|(_, id)| *id == SM_CLEAROBJECTS)
            .unwrap();
        let i_walk = seq.iter().position(|(_, id)| *id == SM_WALK).unwrap();
        assert!(
            i_clear < i_walk,
            "oracle 序：换图簇(633) 先于移动帧(SM_WALK)，实际 {seq:?}"
        );
    }

    // ==========================================================================
    // 片 `openmir2-default-arm-spell-surface`（帧面）：`DoSpell` **无条件** `RM_SPELL` 的牙
    // ==========================================================================
    //
    // 界定件 `tests/parity/m3/design-default-arm-spell-frames-20261017.md` §5.1（J1–J8）；
    // 范围 = 编排侧**宽口径**裁决（卡上 comment `e6d8e8353ebb6f9a64013a1ec88110c450b10a7d`）。
    // 全部走**生产入口** `handle_spell_cmd`（不直调 `World::cast_*`、不碰派生路径）。

    /// 帧面片的共用夹具：施法者 `caster`(10,10)/socket 911、若干观察者（名, x, y, Ghost, socket）、
    /// 存档里学会的魔号、魔法模板表（逐 `(魔号, Effect)`），以及 `ArmRingl` 槽里的护身符
    /// （`dura = 600` ⇒ `Round(600/100) = 6`，满足 `CheckAmulet` 三档需求 1/5/2）。
    /// **MG-57 / B29（`DEV-MG57-RIG-MAP-BASELINE`）**：把真 `0.map` 载成 `MapGrid` 并做
    /// size/sha/直方图三重断言（细节见 [`spacemove_rig_inputs`] 的说明）。8/37 推挤类支在
    /// `Fixture.real_map=true` 时用它，使两侧 `CanWalk` 读**同一张冻结地图**。
    ///
    /// 返回 `(地图目录, 网格, 文件)`：`spacemove` 还要用目录+文件建 `MapRegistry`。
    fn real_map_grid_and_file(
        stem: &str,
        label: &str,
    ) -> (
        std::path::PathBuf,
        mir2_world_bevy::map::MapGrid,
        mir2_envir::MapFile,
    ) {
        let dir = std::env::var("MAGICGOLDEN_MAP_DIR")
            .map(std::path::PathBuf::from)
            .unwrap_or_else(|_| std::path::PathBuf::from(r"E:\MirServer\M2GameSvr\Map"));
        assert!(
            dir.is_dir(),
            "[{stem}/{label}] MAP_DIR_MISSING 地图目录不存在: {}",
            dir.display()
        );
        let path = dir.join("0.map");
        assert!(
            path.is_file(),
            "[{stem}/{label}] MAP_FILE_MISSING 地图目录里没有 0.map: {}",
            path.display()
        );
        // 图身份：golden 的 `Fixture.map_file_size`（缺键同样 panic —— 不能落成 0 静默通过）
        let g = golden_case_for(stem, label);
        let want_size = g["Fixture"]["map_file_size"].as_i64().unwrap_or_else(|| {
            panic!("[{stem}/{label}] golden 缺 Fixture.map_file_size，先重出 golden")
        });
        let got_size = std::fs::metadata(&path)
            .map(|m| m.len() as i64)
            .unwrap_or(-1);
        assert_eq!(
            got_size,
            want_size,
            "[{stem}/{label}] MAP_SIZE_MISMATCH golden={want_size} 磁盘={got_size}（{}）",
            path.display()
        );
        // 光比 size 抓不到"同尺寸换了一张图" ⇒ 必须比内容摘要。
        let want_sha = g["Fixture"]["map_file_sha256"].as_str().unwrap_or_else(|| {
            panic!("[{stem}/{label}] golden 缺 Fixture.map_file_sha256，先重出 golden")
        });
        let bytes_map = std::fs::read(&path).unwrap_or_else(|e| {
            panic!("[{stem}/{label}] 读 0.map 失败: {e}（{}）", path.display())
        });
        use sha2::Digest;
        let got_sha = format!("{:x}", sha2::Sha256::digest(&bytes_map));
        assert_eq!(
            got_sha,
            want_sha,
            "[{stem}/{label}] MAP_SHA_MISMATCH golden={want_sha} 磁盘={got_sha}（{}）",
            path.display()
        );
        let loader = mir2_envir::MapLoader::new(&dir, "", "");
        let mf = loader
            .load("0")
            .unwrap_or_else(|e| panic!("[{stem}/{label}] 0.map 解析失败: {e:?}"));
        let mut grid = mir2_world_bevy::map::MapGrid::new(mf.width, mf.height);
        let written = game_svr::mapwire::apply_map_file_cells(&mf, &mut grid);
        let expect = (mf.width as usize) * (mf.height as usize);
        assert_eq!(
            written, expect,
            "[{stem}/{label}] 格属性写入数 {written} != 期望 {expect}（尺寸不符会 fail-closed）"
        );
        // 直方图交叉核：写入数相等但属性错位（行列转置）只有这里抓得到
        assert_eq!(
            grid.walk_count(),
            mf.walk_count(),
            "[{stem}/{label}] 可走格直方图不一致（grid={} file={}）",
            grid.walk_count(),
            mf.walk_count()
        );
        // 只比 walk 抓不到"高墙↔低墙互换"（写入数同、walk 数也同）⇒ 另两档也核。
        assert_eq!(
            grid.high_wall_count(),
            mf.high_count(),
            "[{stem}/{label}] 高墙直方图不一致（grid={} file={}）",
            grid.high_wall_count(),
            mf.high_count()
        );
        assert_eq!(
            grid.low_wall_count(),
            mf.low_count(),
            "[{stem}/{label}] 低墙直方图不一致（grid={} file={}）",
            grid.low_wall_count(),
            mf.low_count()
        );
        (dir, grid, mf)
    }

    /// [`real_map_grid_and_file`] 的网格版（8/37 的 rig 只需要图）。
    fn real_map_grid_for(stem: &str, label: &str) -> mir2_world_bevy::map::MapGrid {
        real_map_grid_and_file(stem, label).1
    }

    /// **MG-35（21 瞬息移动）驱动的 rig 输入**：真图（`MAGICGOLDEN_MAP_DIR`）+ 真 `MapRegistry`。
    ///
    /// **与旧先例的差异（勿复用）**：`cast_slave` 为 `name_of(map_id)` 写过 200×200 全 0 的临时图，
    /// 那是"只给 name↔id"用的、可走性仍用 World 图。本支**不能**沿用那个口径：
    /// `SpaceMoveGetRandXY`（`src/M2Server/Actor/BaseObject.cs:1040`）是带 `CanWalk` 的**移位环**，
    /// 不可走会继续抽 `Random(Width)`/`Random(Height)`（至多 201 轮，超限则整段换图不发生）。
    /// 用全 `Walk` 合成图会让移位环**零轮** ⇒ 系统性少抽 RNG（"帧对、抽数错"的典型假对拍）。
    ///
    /// 三档具名 panic（不静默）：`MAP_DIR_MISSING` / `MAP_FILE_MISSING` / `MAP_SIZE_MISMATCH`。
    fn spacemove_rig_inputs(
        stem: &str,
        label: &str,
    ) -> (mir2_world_bevy::map::MapGrid, mir2_envir::MapRegistry) {
        let (dir, grid, _mf) = real_map_grid_and_file(stem, label);
        let g = golden_case_for(stem, label);
        let registry = mir2_envir::MapRegistry::from_entries(
            mir2_envir::MapLoader::new(&dir, "", ""),
            vec![mir2_envir::MapInfoEntry {
                map_name: "0".to_string(),
                map_file_name: "0".to_string(),
                // **`desc` 为什么是空串，以及为什么空串是对的**（三条一起看）：
                // ① `54 SM_MAPDESCRIPTION` 的尾串取 `Envir.MapDesc`（`src/M2Server/Player/PlayObject.Base.cs:894`）；
                // ② C# 装置只调 `env.LoadMapData("0.map")`，**不读 MapInfo.txt**
                //    （且部署的 `MapInfo.txt` 在 `M2GameSvr/Envir/` 而不是 Map 目录，装置根本没看到它）；
                // ③ 实测 golden 的 `54`/`766` 两条 `tail` 都是 `''` ⇒ 与"装置没读 MapInfo"一致。
                // ⇒ 这里填 `""` 是**与 golden 同源**，不是"漏读配置"；将来若装置开始读 MapInfo，
                //    本处要同步改成同一个来源，否则 54 的尾串会与 golden 比不过。
                desc: String::new(),
                server_index: 0,
                flag: mir2_envir::mapinfo::MapInfoFlag::default(),
            }],
        );
        // **注册表自检**：`HomeMap="0"` 靠 `registry.id_of("0")` 解析；查不到就会静默"不移动"
        // ⇒ 在这里就红，并打出注册项名字，省掉"跑完没动再回头查"的一轮。
        assert_eq!(
            registry.id_of("0"),
            Some(0),
            "[{stem}/{label}] MapRegistry 里查不到 map_name=\"0\"（注册项 = [\"0\"]）⇒ HomeMap 解析 None，本支会退化"
        );
        // 卡 `openmir2-changemap-missing-serverconfig` §10：`SM_SERVERCONFIG(11029)` 的
        // `ClientConf` 原文来自**部署 `Server.conf` 的 `[Setup]` 客户端段**（与 C# 装置同源：
        // `SystemShare.Config.ClientConf`）。先核 golden 记录的 `Fixture.server_conf_sha256`
        // （生成源一改即红），再 `GameSvrConf::load` 取 `client_conf.to_bytes()`，装进
        // **线程本地**测试覆盖（只影响本测试线程，`--lib` 并行测试互不污染）。
        {
            let conf_path = std::env::var("MAGICGOLDEN_SERVERCONF")
                .map(std::path::PathBuf::from)
                .unwrap_or_else(|_| {
                    std::path::PathBuf::from(r"E:\MirServer\M2GameSvr\Server.conf")
                });
            assert!(
                conf_path.is_file(),
                "[{stem}/{label}] SERVERCONF_MISSING（{}）",
                conf_path.display()
            );
            let bytes = std::fs::read(&conf_path)
                .unwrap_or_else(|e| panic!("[{stem}/{label}] Server.conf 读失败：{e}"));
            let want_sha = g["Fixture"]["server_conf_sha256"]
                .as_str()
                .unwrap_or_else(|| panic!("[{stem}/{label}] golden 缺 Fixture.server_conf_sha256"));
            use sha2::Digest;
            let got_sha = format!("{:x}", sha2::Sha256::digest(&bytes));
            assert_eq!(
                got_sha, want_sha,
                "[{stem}/{label}] SERVERCONF_SHA_MISMATCH golden={want_sha} 磁盘={got_sha}"
            );
            let conf = mir2_envir::GameSvrConf::from_bytes(&bytes);
            set_test_client_conf(Some(conf.client_conf.to_bytes()));
        }
        (grid, registry)
    }

    struct SpellFrameRig {
        world: mir2_world_bevy::World,
        caster: i32,
        online: OnlineRegistry,
        saves: std::collections::HashMap<String, SavedHuman>,
        ground_sessions: std::collections::HashMap<String, SessionGround>,
        magic_table: magics::MagicTable,
        displays: downlink::DisplayTable,
        gates: std::collections::HashMap<u8, mpsc::UnboundedSender<SimToGate>>,
        rx: mpsc::UnboundedReceiver<SimToGate>,
        /// **P3-B2**：`[Setup]` 三个 AoE 半径（缺省 = oracle `GameSvrConf.cs:1770-1772`）。
        fire_boom_rage: i32,
        snow_wind_range: i32,
        elec_blizzard_range: i32,
        /// 护身符 `StdItem.Shape`（施毒 6/48 走 `CheckAmulet(1,2)`，要求 ≤2；缺省 5 = nType=1 组）。
        amulet_shape: u8,
        /// **MG-35（21 瞬息移动）**：驱动可注入的真 `MapRegistry`（解析 `HomeMap`）。
        /// 缺省 `None` ⇒ 回落历史行为（空注册表 ⇒ `id_of` 恒 `None` ⇒ 不移动）。
        /// **测试装置专用**；产品路径由 `main` 注入，不在 `handle_spell_cmd` 里加测试缝。
        registry: Option<mir2_envir::MapRegistry>,
        /// **(ii) pilot**：上一 tick 未放行的 657（per-viewer 延迟；随 `deliver` 步进放行）。
        pending_657: Vec<(i32, u8, Vec<u8>)>,
    }

    impl SpellFrameRig {
        fn new(
            learned: u16,
            table: &[(u16, u8)],
            observers: &[(&str, i32, i32, bool, i32)],
        ) -> Self {
            Self::new_layout(64, 64, 0, 10, 10, learned, table, observers)
        }

        /// **卡 `openmir2-magic-parity` §22**：可指定世界尺寸、施法者起点与实体 id 段的构造器。
        ///
        /// `id_base == 0` ⇒ 由 `World::add_entity` 分配（与原 `new` 逐字节同行为）；
        /// `id_base > 0` ⇒ caster = `id_base + 1`、第 i 个观察者 = `id_base + 2 + i`
        /// （对齐 C# golden 的 ActorId 分段 1001/2001/3001——ActorId 会进 `SM_MAGICFIRE` 尾串，
        /// 必须**构造时就同值**，不做落盘改名）。
        ///
        /// 世界尺寸/坐标是**行为输入**：`MagCanHitTarget` 沿格走位受 `get_next_position` 边界钳制
        /// （施法者 (100,100) 朝 +x 走一步要求 `width >= 102`）；golden 用真实 `Map/0.map`，
        /// 合成图必须至少覆盖 golden 几何 + 行走步长。
        #[allow(clippy::too_many_arguments)]
        fn new_layout(
            width: i32,
            height: i32,
            id_base: i32,
            caster_x: i32,
            caster_y: i32,
            learned: u16,
            table: &[(u16, u8)],
            observers: &[(&str, i32, i32, bool, i32)],
        ) -> Self {
            use std::collections::HashMap;
            let mut world = mir2_world_bevy::World::new(width, height);
            let mut caster_spawn = new_player_entity("caster".to_string(), caster_x, caster_y);
            if id_base > 0 {
                caster_spawn.id = id_base + 1;
            }
            let caster = world.add_entity(caster_spawn);
            let mut displays = downlink::DisplayTable::new();
            displays.set(
                caster,
                downlink::ActorDisplay::new(4, 0, 111, 0, 0, 255, b"caster".to_vec()),
            );
            let mut online: OnlineRegistry = OnlineRegistry::new();
            online_set(
                &mut online,
                OnlineEntry {
                    account: "uc".into(),
                    chr_name: "caster".into(),
                    session_id: 1,
                    gate_idx: 0,
                    socket: 911,
                    actor_id: caster,
                },
            );
            for (i, o) in observers.iter().enumerate() {
                let (name, x, y, ghost, socket): (&str, i32, i32, bool, i32) = *o;
                let mut spawn = new_player_entity(name.to_string(), x, y);
                if id_base > 0 {
                    spawn.id = id_base + 2 + i32::try_from(i).unwrap_or(0);
                }
                let id = world.add_entity(spawn);
                if ghost {
                    world.entities.get_mut(id).unwrap().life_cycle.ghost = true;
                }
                displays.set(
                    id,
                    downlink::ActorDisplay::new(
                        4,
                        0,
                        112 + i32::try_from(i).unwrap_or(0),
                        0,
                        0,
                        255,
                        enter::gbk(name),
                    ),
                );
                online_set(
                    &mut online,
                    OnlineEntry {
                        account: format!("u{i}"),
                        chr_name: name.to_string(),
                        session_id: 10 + i32::try_from(i).unwrap_or(0),
                        gate_idx: 0,
                        socket,
                        actor_id: id,
                    },
                );
            }
            world.tick();
            let (tx0, rx) = mpsc::unbounded_channel::<SimToGate>();
            let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
            gates.insert(0, tx0);
            let mut record = stage6_record();
            record.data.magic = Some(vec![Some(record::MagicRcd {
                mag_idx: learned,
                level: 1,
                magic_key: u16::from(b'm'),
                tran_point: 0,
            })]);
            let mut saves: HashMap<String, SavedHuman> = HashMap::new();
            saves.insert(
                "caster".into(),
                SavedHuman {
                    account: "uc".into(),
                    record,
                    enter_map: "0".into(),
                    derived: None,
                },
            );
            let mut ground_sessions: HashMap<String, SessionGround> = HashMap::new();
            let mut sg = spell_session_ground(caster);
            sg.use_items[game_svr::ability::SLOT_ARMRING_L] = Some(game_svr::bag::BagItem {
                make_index: 1,
                index: 1,
                dura: 600,
                dura_max: 1000,
                desc: [0; 14],
            });
            ground_sessions.insert("caster".into(), sg);
            let magic_table = magics::MagicTable::new(
                table
                    .iter()
                    .map(|(id, eff)| mir2_data::MagicInfo {
                        magic_id: *id,
                        effect: *eff,
                        effect_type: 4,
                        train_lv: 3,
                        ..mir2_data::MagicInfo::default()
                    })
                    .collect(),
            );
            Self {
                world,
                caster,
                online,
                saves,
                ground_sessions,
                magic_table,
                displays,
                gates,
                rx,
                fire_boom_rage: 1,
                snow_wind_range: 1,
                elec_blizzard_range: 2,
                amulet_shape: 5,
                registry: None,
                pending_657: Vec::new(),
            }
        }

        /// 走一次生产入口。`click` = 客户端报的点击格（`Recog` 的低/高字）；
        /// `target_actor_id` = `MakeLong(Param, Series)`（0 = 无目标对象）。
        /// `magic_attack_rage` 传 8（oracle `SystemShare.Config.MagicAttackRage` 探针默认值，
        /// 与既有 `spell_cmd_*` 用例同）。
        fn cast(&mut self, magic_id: u16, click: (i32, i32), target_actor_id: i32) {
            let mut catalog = game_svr::ability::StdItemCatalog::new();
            catalog.insert(
                1,
                mir2_data::StdItem {
                    name: "护身符".into(),
                    std_mode: 25,
                    shape: self.amulet_shape,
                    ..mir2_data::StdItem::default()
                },
            );
            let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
            let table = game_svr::mongen::MonsterTable::new(Vec::new());
            // **默认必须仍是"空注册表"而不是 `None`**：魔号 17 等支按 `registry.is_some()` 分流
            // （"无地图注册表 ⇒ 效果体不接"），把默认从 `Some(empty)` 改成 `None` 会改变这些既有行为。
            let fallback = mir2_envir::MapRegistry::from_entries(
                mir2_envir::MapLoader::new(".", "map", "envir"),
                Vec::new(),
            );
            let registry = self.registry.as_ref().unwrap_or(&fallback);
            handle_spell_cmd(
                game_svr::feature::make_long(
                    u16::try_from(click.0).unwrap_or(0),
                    u16::try_from(click.1).unwrap_or(0),
                ),
                magic_id,
                u16::try_from(target_actor_id).unwrap_or(0),
                0,
                "caster",
                911,
                &self.online,
                &mut self.world,
                &mut self.saves,
                &mut self.ground_sessions,
                &catalog,
                &self.magic_table,
                &pet_cfg,
                8,
                Some(registry),
                &table,
                &mut self.displays,
                &self.gates,
                self.fire_boom_rage,
                self.snow_wind_range,
                self.elec_blizzard_range,
            );
        }

        /// 召唤（17/30/41）施法接缝（卡 17）：与 [`Self::cast`] 同口径，但用 `monsters` 构造
        /// `MonsterTable`（Rust 怪物表）。golden 的 `stub_monster_race`/`stub_monster_hp`/new_slaves
        /// 的 name/level 由驱动传入（`race=100` WhiteSkeleton ⇒ `apply_slave_level_abilitys` 抬
        /// `max_hp` ⇒ 半补触发）。
        fn cast_slave(
            &mut self,
            magic_id: u16,
            click: (i32, i32),
            target_actor_id: i32,
            monsters: Vec<mir2_data::MonsterInfo>,
        ) {
            let mut catalog = game_svr::ability::StdItemCatalog::new();
            catalog.insert(
                1,
                mir2_data::StdItem {
                    name: "护身符".into(),
                    std_mode: 25,
                    shape: self.amulet_shape,
                    ..mir2_data::StdItem::default()
                },
            );
            let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();
            let table = game_svr::mongen::MonsterTable::new(monsters);
            // 召唤 spawner 需 MapRegistry 能 `name_of(map_id)`（`MonsterTableSpawner::spawn`）；
            // 写一张临时 0.map（200×200 全 0）供 `from_entries` 载入 name↔id（可行走性仍用 World 图）。
            // 每次调用取独立序号：多个用例并行跑同一 test binary 时不共享目录（C17 同型）。
            static DIR_SEQ: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
            let seq = DIR_SEQ.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
            let base =
                std::env::temp_dir().join(format!("magic17-map-{}-{seq}", std::process::id()));
            let _ = std::fs::create_dir_all(base.join("Map"));
            let (mw, mh) = (200_i16, 200_i16);
            let mut map_bytes = vec![0u8; mir2_envir::HEADER_BYTES];
            map_bytes[0..2].copy_from_slice(&mw.to_le_bytes());
            map_bytes[2..4].copy_from_slice(&mh.to_le_bytes());
            map_bytes.resize(
                mir2_envir::HEADER_BYTES
                    + usize::try_from(mw).unwrap()
                        * usize::try_from(mh).unwrap()
                        * mir2_envir::CELL_BYTES,
                0,
            );
            let _ = std::fs::write(base.join("Map").join("0.map"), &map_bytes);
            let registry = mir2_envir::MapRegistry::from_entries(
                mir2_envir::MapLoader::new(base.clone(), "Map", "Envir"),
                vec![mir2_envir::MapInfoEntry {
                    map_name: "map".to_string(),
                    map_file_name: "0".to_string(),
                    desc: String::new(),
                    server_index: 0,
                    flag: mir2_envir::MapInfoFlag::default(),
                }],
            );
            handle_spell_cmd(
                game_svr::feature::make_long(
                    u16::try_from(click.0).unwrap_or(0),
                    u16::try_from(click.1).unwrap_or(0),
                ),
                magic_id,
                u16::try_from(target_actor_id).unwrap_or(0),
                0,
                "caster",
                911,
                &self.online,
                &mut self.world,
                &mut self.saves,
                &mut self.ground_sessions,
                &catalog,
                &self.magic_table,
                &pet_cfg,
                8,
                Some(&registry),
                &table,
                &mut self.displays,
                &self.gates,
                self.fire_boom_rage,
                self.snow_wind_range,
                self.elec_blizzard_range,
            );
        }

        /// 取空 gate 通道：`(SM_* 帧体, `SendRaw` 短包/`+GD` ack)`。
        fn drain(&mut self) -> (Vec<SfFrame>, Vec<SfFrame>) {
            let mut frames = Vec::new();
            let mut raws = Vec::new();
            while let Ok(m) = self.rx.try_recv() {
                match m {
                    SimToGate::SendFrame { socket, body } => frames.push((socket, body)),
                    SimToGate::SendRaw { socket, payload } => raws.push((socket, payload)),
                    other => panic!("意外的下行：{other:?}"),
                }
            }
            (frames, raws)
        }

        /// 推进时钟并按生产节奏投递自身延时消息；返回本批出帧。
        /// 本卡起训练尾 640 走 `SendSelfDelayMsg(...,1000)`（`MagicManager.cs:666`）⇒ 只在
        /// +1000ms 交付批出现，施法批 `drain()` 里看不到它。
        fn deliver(&mut self, advance_ms: i64) -> Vec<SfFrame> {
            self.world.clock_ms += advance_ms;
            let mut frames = Vec::new();
            // **有界补泵的依据**（不是试出来的数）：oracle 每 tick 泵一次；.NET 四叉堆不稳定 ⇒
            // 队根是未到点项时「出队 + 以 Lowest 重入队」只结束本次泵（该项移到堆尾）。
            // 设本轮起点队列长度 q，则 q 次泵内每条消息都轮到过队根 ⇒ 所有到期项必已投递
            // 或只剩「泵门」拦截项；故上界取 q + 1（另设 64 上限防御）。
            // **(ii) pilot**：先放行上一 tick 的延迟 657（只在这一步的第一次 flush）。
            if !self.pending_657.is_empty() {
                let rec = mir2_world_bevy::TickRecord::default();
                drain_b3_self_deliveries_with_pending(
                    &rec,
                    &self.world,
                    &self.online,
                    &mut self.ground_sessions,
                    &self.gates,
                    &mut self.pending_657,
                    true,
                );
                frames.extend(self.drain().0);
            }
            let bound = (self.world.self_delay_msgs.len() + 1).min(64);
            for _ in 0..bound {
                if self.world.self_delay_msgs.is_empty() {
                    break;
                }
                let turns = self.world.deliver_self_delay_msgs_turns();
                let flat = mir2_world_bevy::slave::flatten_self_delay_turns(turns.clone());
                if flat.is_empty() && turns.is_empty() {
                    continue;
                }
                let rec = mir2_world_bevy::TickRecord {
                    slave_self_deliveries: flat,
                    slave_self_delivery_turns: turns,
                    ..Default::default()
                };
                drain_b3_self_deliveries_with_pending(
                    &rec,
                    &self.world,
                    &self.online,
                    &mut self.ground_sessions,
                    &self.gates,
                    &mut self.pending_657,
                    false,
                );
                frames.extend(self.drain().0);
            }
            frames
        }
    }

    #[test]
    #[ignore = "烟测：验证 cast_slave 接缝 + spawn 计数（race 100 WhiteSkeleton）"]
    fn skeleton_cast_smoke() {
        let mut rig = SpellFrameRig::new_layout(
            200,
            200,
            0,
            100,
            100,
            17,
            &[(17, 1)],
            &[
                ("target", 101, 100, false, 912),
                ("obs_in", 105, 100, false, 913),
                ("obs_out", 140, 100, false, 914),
            ],
        );
        rig.magic_table = magics::MagicTable::new(vec![mir2_data::MagicInfo {
            magic_id: 17,
            effect: 1,
            effect_type: 1,
            ..mir2_data::MagicInfo::default()
        }]);
        {
            let e = rig.world.entities.get_mut(rig.caster).unwrap();
            e.progression.level = 30;
            e.vitals.hp = 500;
            e.vitals.max_hp = 500;
        }
        let target = rig
            .online
            .iter()
            .find(|e| e.chr_name == "target")
            .unwrap()
            .actor_id;
        let before = rig.world.slave_count(rig.caster);
        let mon = mir2_data::MonsterInfo {
            name: "变异骷髅".into(),
            race: 100,
            level: 1,
            hp: 17,
            ..mir2_data::MonsterInfo::default()
        };
        rig.cast_slave(17, (101, 100), target, vec![mon]);
        let (frames, _) = rig.drain();
        let after = rig.world.slave_count(rig.caster);
        let regen = rig
            .world
            .slave_cast_regen_calls
            .last()
            .copied()
            .unwrap_or(999);
        let sid = rig
            .world
            .entities
            .get(rig.caster)
            .and_then(|c| c.slave_list.last().copied());
        let (shp, smax, slevel) = sid
            .and_then(|id| rig.world.entities.get(id))
            .map_or((0, 0, 0), |e| (e.hp, e.max_hp, e.level));
        eprintln!("SMOKE before={before} after={after} regen={regen} frames={} slave_hp={shp}/{smax} level={slevel}", frames.len());
        assert_eq!(regen, 1, "MonsterTableSpawner.spawn 应被调用 1 次");
        assert_eq!(after, before + 1, "应新增 1 个奴隶");
    }

    /// 某支召唤夹具（卡 17）：与 golden `skeleton.json` 的 fixture_spec 同几何
    /// （caster 100,100 / target 101,100 / obs_in 105,100 / obs_out 140,100；socket 911..914）。
    fn skeleton_rig(id_base: i32) -> SpellFrameRig {
        let mut rig = SpellFrameRig::new_layout(
            200,
            200,
            id_base,
            100,
            100,
            17,
            &[(17, 1)],
            &[
                ("target", 101, 100, false, 912),
                ("obs_in", 105, 100, false, 913),
                ("obs_out", 140, 100, false, 914),
            ],
        );
        rig.magic_table = magics::MagicTable::new(vec![mir2_data::MagicInfo {
            magic_id: 17,
            effect: 1,
            effect_type: 1,
            ..mir2_data::MagicInfo::default()
        }]);
        {
            let e = rig.world.entities.get_mut(rig.caster).unwrap();
            e.progression.level = 30;
            e.vitals.hp = 500;
            e.vitals.max_hp = 500;
        }
        {
            let sg = rig.ground_sessions.get_mut("caster").unwrap();
            sg.equip.abil.level = 30;
            sg.state.wabil.level = 30;
            sg.state.wabil.mc = 15;
            sg.state.wabil.sc = 15;
        }
        rig
    }

    /// 17 `SKILL_SKELLETON` 真实台账驱动（两例 summon_ok / cap_hit）。
    ///
    /// **对拍范围（卡 17 SCOPE）**：验「**给定怪物之后**的 adopt 行为」——`regen_calls`、
    /// `slave_count_before/after`、`new_slaves{name,level,hp,max_hp,master_is_caster}`、造怪前帧
    /// 17/638/642。**不比** `Rng`：造怪抽数**已记录在 golden `Rng` 中且可复现**
    /// （`[1500,2000,3000,3000,2000]` + `Random(3)`），而**本 stem 的驱动不做 RNG 记账**
    /// （台账无 `Rng` 键）——不是「抽 0 次」；`640`/`10123-p3` 随造怪抽数的消费位置不同。
    /// **656 未验（装置盲区）**：替身怪未绑定 `Envir` ⇒ `SendRefMsg` 早退，
    /// 见 `docs/issues/golden-harness-blind-spots.md` B1。
    fn skeleton_parity_drive(label: &str, id_base: i32) {
        std::env::set_var("MIR2_CLIENT_ABILITY_LAYOUT", "0");
        let stem = "skeleton";
        let dir = magic_ledger_dir();
        std::fs::create_dir_all(&dir).expect("台账目录必须可建");
        let run_id = ledger_run_id();
        let seed = golden_seed(stem, label);
        // Rng 实测（MG-24 验证面补洞）：开启 rng_trace 记录造怪/尾段抽数。
        // 进程级 OnceLock ⇒ 本驱动必须 `--exact --test-threads=1` 单独进程跑。
        let trace = dir.join(format!("{stem}_{label}_seed{seed}.rng.tsv"));
        assert!(
            !mir2_shared::rng_trace::enabled(),
            "rng_trace 已被本进程其它路径开启 ⇒ 请 --exact 单跑"
        );
        let _ = std::fs::remove_file(&trace);
        mir2_shared::rng_trace::enable(&trace, seed).expect("打开 rng trace");
        let n0 = trace_line_count(&trace);
        let mut rig = skeleton_rig(id_base);
        rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(seed);
        let caster = rig.caster;
        let target = fireball_actor(&rig, "target");

        // cap_hit：golden `pre_slave_count=1` ⇒ 预置 1 个已存在奴隶，令 `MakeSlave` 的
        // `SlaveList.Count < nMaxMob` 门失败（regen 0 / 不新增实体 / slave_list 不变）。
        // 直接造实体、不走施法 ⇒ 不污染帧与 RNG。预置 id = id_base+50，比对时排除。
        let preslave_id = id_base + 50;
        if label == "cap_hit" {
            let mut e = mir2_world_bevy::EntitySpawn::new(0, "preslave".to_string(), 100, 100);
            e.id = preslave_id;
            e.race = 100;
            let sid = rig.world.add_entity(e);
            {
                let m = rig.world.entities.get_mut(sid).unwrap();
                m.slave.master = Some(caster);
                m.slave.is_slave = true;
            }
            rig.world
                .entities
                .get_mut(caster)
                .unwrap()
                .slave
                .slave_list
                .push(sid);
        }

        let entities_before = rig.world.entities.len();
        let slave_before = rig.world.slave_count(caster);

        // 怪物表按 golden stub：race=100（WhiteSkeleton 真身）、HP=stub_wabil_hp=17；
        // MaxHP 由 `apply_slave_level_abilitys` 抬到 24 ⇒ 半补触发 20。
        let mon = mir2_data::MonsterInfo {
            name: "变异骷髅".into(),
            race: 100,
            level: 1,
            hp: 17,
            ..mir2_data::MonsterInfo::default()
        };
        rig.cast_slave(17, (101, 100), target, vec![mon]);
        let (cast_frames, _raws) = rig.drain();
        let n1 = trace_line_count(&trace);
        let cast_rng = trace_slice(&trace, n0, n1);
        // **本卡起 640 走自延迟**（`emit_magic_lvexp_delayed`：未升级 1000ms / 升级 800ms）⇒
        // 补交付回路：施法批 due=0；按 100ms 步进泵到 1000，交付帧记所在步的 `due_ms_rel`。
        let mut all_frames: Vec<(i32, Vec<u8>, i64)> = cast_frames
            .into_iter()
            .map(|(s, b)| (s, b, 0_i64))
            .collect();
        let mut elapsed = 0i64;
        while elapsed < 1000 {
            elapsed += 100;
            all_frames.extend(rig.deliver(100).into_iter().map(|(s, b)| (s, b, elapsed)));
        }

        let entities_after = rig.world.entities.len();
        let slave_after = rig.world.slave_count(caster);
        let regen = rig
            .world
            .slave_cast_regen_calls
            .last()
            .copied()
            .unwrap_or(usize::MAX);

        // 新增奴隶（排除 cap_hit 预置的 id）。
        let slave_ids: Vec<i32> = rig
            .world
            .entities
            .get(caster)
            .map(|c| c.slave_list.clone())
            .unwrap_or_default()
            .into_iter()
            .filter(|id| *id != preslave_id)
            .collect();
        let new_slaves: Vec<serde_json::Value> = slave_ids
            .iter()
            .filter_map(|id| rig.world.entities.get(*id))
            .map(|e| {
                serde_json::json!({
                    "name": e.entity().name,
                    "level": e.level,
                    "hp": e.hp,
                    "max_hp": e.max_hp,
                    "master_is_caster": e.master == Some(caster),
                })
            })
            .collect();

        let mut receivers: Vec<serde_json::Value> = Vec::new();
        for (who, socket) in [
            ("caster", 911),
            ("target", 912),
            ("obs_in", 913),
            ("obs_out", 914),
        ] {
            receivers.push(serde_json::json!({
                "Who": who,
                "Rm": [],
                "Sent": fireball_sent_with_due(&all_frames, socket),
            }));
        }

        let obs_in = fireball_actor(&rig, "obs_in");
        let obs_out = fireball_actor(&rig, "obs_out");
        assert_summon_id_contract(
            label,
            &[caster, target, obs_in, obs_out, preslave_id],
            &slave_ids,
            new_slaves.len(),
            &receivers,
        );

        let skel = serde_json::json!({
            "stub_wabil_hp": 17,
            "stub_abil_max_hp": 17,
            "stub_monster_race": 100,
            "pre_slave_count": slave_before,
            "slave_count_before": slave_before,
            "slave_count_after": slave_after,
            "regen_calls": regen,
            "new_slaves": new_slaves,
        });

        let ledger = serde_json::json!([{
            "Label": label,
            "Seed": seed,
            "SpellReturn": true,
            "Receivers": receivers,
            "Skeleton": skel,
            "Rng": cast_rng.iter().map(|(_, r, _)| *r).collect::<Vec<_>>(),
            "RngSites": cast_rng.iter().map(|(_, _, st)| st.replace(std::path::MAIN_SEPARATOR, "/")).collect::<Vec<_>>(),
            "RngSeqs": cast_rng.iter().map(|(q, _, _)| *q).collect::<Vec<_>>(),
            "RngBounds": trace_bounds(&trace, n0, n1),
            "world_entities_before": entities_before,
            "world_entities_after": entities_after,
        }]);
        let out = dir.join(format!("{stem}_{label}.json"));
        std::fs::write(&out, serde_json::to_string_pretty(&ledger).unwrap()).expect("台账必须可写");
        write_run_sidecar(&out, &run_id, seed);
        eprintln!(
            "[skeleton {label}] seed={seed} entities {entities_before}->{entities_after} slave {slave_before}->{slave_after} regen={regen} frames={} new={}",
            all_frames.len(),
            ledger[0]["Skeleton"]["new_slaves"].as_array().map_or(0, |a| a.len()),
        );
    }

    #[test]
    #[ignore = "真实台账驱动：需 --exact --test-threads=1 单独进程"]
    fn skeleton_parity_summon_ok() {
        skeleton_parity_drive("summon_ok", 1000);
    }

