    /// 30 `SKILL_SINSU` 真实台账驱动（**两例 `summon_ok` + `cap_hit`**；cap_hit 回召面已由 mapmgr 替身解锁）。
    ///
    /// 神兽 race=113（ELF_MONSTER）→ `apply_slave_level_abilitys` 0.3 第一支；HP=stub 17 ⇒ max 24，半补 20。
    /// `Rng`：**summon_ok 不比**——台账 `[373,221,1401,2314,1315,3,35,2]` 与 golden
    /// `[373,221,1401,2314,1315,1]` 的**前 5 抽逐值相同**，差异从第 6 抽起（golden 第 6 抽 =
    /// 训练尾 1、台账 = 3，另多 35/2 两抽）；造怪抽数本身已记录在 golden 中，差异是记账/消费序列不同。
    /// **cap_hit 逐值比**（门 fail 无造怪抽 + 落点确定无 RandXY 抽 ⇒ 两侧同源都 0 抽）。
    fn sinsu_parity_drive(label: &str, id_base: i32) {
        std::env::set_var("MIR2_CLIENT_ABILITY_LAYOUT", "0");
        let stem = "sinsu";
        let dir = magic_ledger_dir();
        std::fs::create_dir_all(&dir).expect("台账目录必须可建");
        let run_id = ledger_run_id();
        let seed = golden_seed(stem, label);
        // Rng 实测：开启 rng_trace 记录造怪/尾段抽数（opc-19 要"实测再定 Rng 是否同源"）。
        let trace = dir.join(format!("{stem}_{label}_seed{seed}.rng.tsv"));
        assert!(
            !mir2_shared::rng_trace::enabled(),
            "rng_trace 已被本进程其它路径开启 ⇒ 请 --exact 单跑"
        );
        let _ = std::fs::remove_file(&trace);
        mir2_shared::rng_trace::enable(&trace, seed).expect("打开 rng trace");
        let n0 = trace_line_count(&trace);
        let mut rig = sinsu_rig(id_base);
        rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(seed);
        let caster = rig.caster;
        let target = fireball_actor(&rig, "target");

        let entities_before = rig.world.entities.len();
        // cap_hit：预置 slave（精确名 神兽/race113/(0,0)，经 EntitySpawn 真实入世界，非只塞表）供 RecallSlave 移动。
        let preslave_id = id_base + 50;
        if label == "cap_hit" {
            let mut e = mir2_world_bevy::EntitySpawn::new(0, "神兽".to_string(), 0, 0);
            e.id = preslave_id;
            e.race = 113;
            e.level = 1;
            e.hp = 17;
            e.max_hp = 17;
            let sid = rig.world.add_entity(e);
            {
                let m = rig.world.entities.get_mut(sid).unwrap();
                m.slave.master = Some(caster);
                m.slave.is_slave = true;
            }
            rig.world
                .entities
                .get_mut(caster)
                .unwrap()
                .slave
                .slave_list
                .push(sid);
            // 朝向不在此强制：实际由 `handle_spell_cmd` 的 default 支 `Dir=GetNextDirection(cur→click)=DIR_RIGHT`
            // 决定（本 case click=(101,100) ⇒ 回召落点 (101,100)）；此处 ai.dir=4 是死赋值（default 支覆盖），已删。
        }
        let slave_before = rig.world.slave_count(caster);

        let mon = mir2_data::MonsterInfo {
            name: "神兽".into(),
            race: 113,
            level: 1,
            hp: 17,
            ..mir2_data::MonsterInfo::default()
        };
        let mon_race = mon.race; // tooth「race→100 必红」要：账本 stub_monster_race 取自实际 mon.race
        rig.cast_slave(30, (101, 100), target, vec![mon]);
        let (cast_frames, _raws) = rig.drain();
        let n1 = trace_line_count(&trace);
        let cast_rng = trace_slice(&trace, n0, n1);
        // **本卡起 640 走自延迟**（`emit_magic_lvexp_delayed`：未升级 1000ms / 升级 800ms）⇒
        // 补交付回路（施法批 due=0；100ms 步进泵到 1000，交付帧记所在步）。
        let mut all_frames: Vec<(i32, Vec<u8>, i64)> = cast_frames
            .into_iter()
            .map(|(s, b)| (s, b, 0_i64))
            .collect();
        let mut elapsed = 0i64;
        while elapsed < 1000 {
            elapsed += 100;
            all_frames.extend(rig.deliver(100).into_iter().map(|(s, b)| (s, b, elapsed)));
        }

        let entities_after = rig.world.entities.len();
        let slave_after = rig.world.slave_count(caster);
        let regen = rig
            .world
            .slave_cast_regen_calls
            .last()
            .copied()
            .unwrap_or(usize::MAX);
        // 回召观测：预置 slave before(0,0)/after；before≠after ⇒ recall_moved。
        let pre_after_xy = rig
            .world
            .entities
            .get(preslave_id)
            .map(|e| (i64::from(e.x), i64::from(e.y)));
        let (px_before, py_before) = (0i64, 0i64);
        let recall_moved = pre_after_xy.is_some_and(|(ax, ay)| ax != px_before || ay != py_before);

        let slave_ids: Vec<i32> = rig
            .world
            .entities
            .get(caster)
            .map(|c| c.slave_list.clone())
            .unwrap_or_default()
            .into_iter()
            .filter(|id| *id != preslave_id)
            .collect::<Vec<i32>>();
        let new_slaves: Vec<serde_json::Value> = slave_ids
            .iter()
            .filter_map(|id| rig.world.entities.get(*id))
            .map(|e| {
                serde_json::json!({
                    "name": e.entity().name,
                    "level": e.level,
                    "hp": e.hp,
                    "max_hp": e.max_hp,
                    "master_is_caster": e.master == Some(caster),
                })
            })
            .collect();

        let mut receivers: Vec<serde_json::Value> = Vec::new();
        for (who, socket) in [
            ("caster", 911),
            ("target", 912),
            ("obs_in", 913),
            ("obs_out", 914),
        ] {
            receivers.push(serde_json::json!({
                "Who": who,
                "Rm": [],
                "Sent": sinsu_sent(&all_frames, socket),
            }));
        }

        let obs_in = fireball_actor(&rig, "obs_in");
        let obs_out = fireball_actor(&rig, "obs_out");
        assert_summon_id_contract(
            label,
            &[caster, target, obs_in, obs_out, preslave_id],
            &slave_ids,
            new_slaves.len(),
            &receivers,
        );

        let sinsu = serde_json::json!({
            "stub_wabil_hp": 17,
            "stub_abil_max_hp": 17,
            "stub_monster_race": mon_race,
            "pre_slave_count": slave_before,
            "slave_count_before": slave_before,
            "slave_count_after": slave_after,
            "regen_calls": regen,
            "new_slaves": new_slaves,
            "pre_slave_xy_before": if label == "cap_hit" { serde_json::json!([{"name":"神兽","x":px_before,"y":py_before}]) } else { serde_json::json!([]) },
            "pre_slave_xy_after": match pre_after_xy { Some((ax, ay)) => serde_json::json!([{"name":"神兽","x":ax,"y":ay}]), None => serde_json::json!([]) },
            "recall_moved": recall_moved,
            "caster_x": i64::from(rig.world.entities.get(caster).map_or(0, |e| e.x)),
            "caster_y": i64::from(rig.world.entities.get(caster).map_or(0, |e| e.y)),
        });

        let ledger = serde_json::json!([{
            "Label": label,
            "Seed": seed,
            "SpellReturn": true,
            "Receivers": receivers,
            "SinSu": sinsu,
            "Rng": cast_rng.iter().map(|(_, r, _)| *r).collect::<Vec<_>>(),
            "RngSites": cast_rng.iter().map(|(_, _, st)| st.replace(std::path::MAIN_SEPARATOR, "/")).collect::<Vec<_>>(),
            "RngSeqs": cast_rng.iter().map(|(q, _, _)| *q).collect::<Vec<_>>(),
            "RngBounds": trace_bounds(&trace, n0, n1),
            "world_entities_before": entities_before,
            "world_entities_after": entities_after,
        }]);
        let out = dir.join(format!("{stem}_{label}.json"));
        std::fs::write(&out, serde_json::to_string_pretty(&ledger).unwrap()).expect("台账必须可写");
        write_run_sidecar(&out, &run_id, seed);
        eprintln!(
            "[sinsu {label}] seed={seed} entities {entities_before}->{entities_after} slave {slave_before}->{slave_after} regen={regen} frames={} new={}",
            all_frames.len(),
            ledger[0]["SinSu"]["new_slaves"].as_array().map_or(0, |a| a.len()),
        );
    }

    #[test]
    #[ignore = "真实台账驱动：需 --exact --test-threads=1 单独进程"]
    fn sinsu_parity_summon_ok() {
        sinsu_parity_drive("summon_ok", 1000);
    }

    #[test]
    #[ignore = "真实台账驱动：需 --exact --test-threads=1 单独进程"]
    fn sinsu_parity_cap_hit() {
        sinsu_parity_drive("cap_hit", 2000);
    }

    // ======================================================================
    // 卡 `openmir2-magic-parity` §22：火球（1/5）**真实台账**驱动
    // ======================================================================
    //
    // 输入 = 金标准 `mir2-rs/tests/parity/golden/magic/fireball.json` 的 C# 夹具（逐字段）：
    // caster(100,100, ActorId=id_base+1, Abil.Level=30, WAbil.MC=15) /
    // target(101,100, id_base+2, AntiMagic=3, HP=MaxHP=100, Abil.Level=20) /
    // obs_in(105,100, id_base+3) / obs_out(140,100, id_base+4)；魔表行 `{MagicId=1,Effect=1,EffectType=1}`
    // 其余字段缺省。三支的 ActorId 分段 = miss 1001.. / edge 2001.. / hit 3001..（C# ActorMgr 进程级，
    // 同一进程多用例必须不同 id；Rust 每支独立世界，但**故意用同一组 id**，让尾串逐字节可比）。
    //
    // 台账 = 两段：① `handle_spell_cmd` 施法段；② 推进世界时钟 ≥600ms 后
    // `World::deliver_self_delay_msgs` + 宿主出帧（`drain_b4_self_deliveries`，与 `sim_loop` 同一批函数）。
    // RNG 账本走 `rng_trace`：**不截断**，按行号分段 `n0`（夹具就绪）/ `n1`（施法段结束）/
    // `n2`（交付段结束）；交付段账本另存 `DeliverRng`（金标准只记施法段，故不进 `Rng` 比较面）。

    /// 火球台账落盘目录：`MIR2_MAGIC_LEDGER_DIR` 可覆盖；缺省 `<workspace>/target/magic-parity`。
    fn magic_ledger_dir() -> std::path::PathBuf {
        if let Ok(d) = std::env::var("MIR2_MAGIC_LEDGER_DIR") {
            return std::path::PathBuf::from(d);
        }
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../target/magic-parity")
    }

    /// **台账 run_id（空转防线，卡 §28）**：驱动与比较器必须用**同一个**由 harness 传入的 id
    /// （环境变量 `MIR2_LEDGER_RUN_ID`）。驱动的每个 case 落一份侧车 `<stem>_<label>.run.json`；
    /// 比较器断言侧车 id == 本次环境变量 —— 专门拦「驱动没跑/编译失败 ⇒ 比较器读上一次的陈旧
    /// 台账还绿」这类空转（2026-11-20 29 支牙 A 首跑踩到）。
    fn ledger_run_id() -> String {
        let id = std::env::var("MIR2_LEDGER_RUN_ID").unwrap_or_default();
        assert!(
            !id.is_empty(),
            "未设置 MIR2_LEDGER_RUN_ID：驱动与比较器都必须用同一 id 运行（卡 §28 空转防线）"
        );
        id
    }

    /// 写 sidecar `<stem>_<label>.run.json`（`{"run_id","seed"}`）。
    fn write_run_sidecar(out: &std::path::Path, run_id: &str, seed: i32) {
        let sidecar = out.with_extension("run.json");
        let v = serde_json::json!({ "run_id": run_id, "seed": seed });
        std::fs::write(&sidecar, serde_json::to_string_pretty(&v).unwrap())
            .expect("run.json 必须可写");
    }

    /// rng_trace TSV 的行数（`LineWriter` 逐行 flush ⇒ 运行中读到的一定是完整行）。
    fn trace_line_count(path: &std::path::Path) -> usize {
        std::fs::read_to_string(path)
            .map(|s| s.lines().count())
            .unwrap_or(0)
    }

    /// 读 rng_trace 的 `[from, to)` 行，解析为 `(seq, result, site)`。
    ///
    /// 头部两行（`INJECT_OK` / `SEED_PROBE`）落在 `n0` 之前，天然不进账本；这里仍对非数据行
    /// **硬失败**：静默跳过会让「某段整体缺失」伪装成空账本。
    fn trace_slice(path: &std::path::Path, from: usize, to: usize) -> Vec<(i64, i64, String)> {
        let text = std::fs::read_to_string(path).expect("rng trace 文件必须存在");
        let mut out = Vec::new();
        for (i, line) in text.lines().enumerate() {
            if i < from || i >= to {
                continue;
            }
            let cols: Vec<&str> = line.split('\t').collect();
            assert_eq!(
                cols.len(),
                5,
                "rng trace 第 {} 行不是 5 列数据行（头部行不得落进账本区间）: {line}",
                i + 1
            );
            let seq: i64 = cols[0].parse().expect("seq 必须是 int");
            let result: i64 = cols[3].parse().expect("result 必须是 int");
            out.push((seq, result, cols[4].to_string()));
        }
        assert_eq!(out.len(), to - from, "账本行数必须与行号区间一致");
        out
    }

    /// 读 rng_trace 的 `[from, to)` 行，只取每行的 **bound**（第 3 列 `arg`；`Next()` 记 0）。
    ///
    /// 用途（MG-24）：把「第 N 抽属于哪一次调用」变成断言，而不是按位置猜——造怪 ctor 5 抽的
    /// bound `[1500,2000,3000,3000,2000]`（`BaseObject.cs:439/441`、`AnimalObject.cs:76/77`、
    /// `MonsterObject.cs:65`）与训练尾 `Random(3)`（`MagicManager.cs:663`）。
    fn trace_bounds(path: &std::path::Path, from: usize, to: usize) -> Vec<i64> {
        let text = std::fs::read_to_string(path).expect("rng trace 文件必须存在");
        let mut out = Vec::new();
        for line in text.lines().skip(from).take(to - from) {
            let cols: Vec<&str> = line.split('\t').collect();
            assert_eq!(cols.len(), 5, "rng trace 行不是 5 列数据行: {line}");
            out.push(cols[2].parse().expect("bound(arg) 必须是 int"));
        }
        assert_eq!(out.len(), to - from, "账本行数必须与行号区间一致");
        out
    }

    /// trace 头部第二列 `INJECT_OK` 行的 seed（自证 `enable(path, seed)` 的 seed 与本支一致）。
    fn trace_header_seed(path: &std::path::Path) -> i32 {
        let text = std::fs::read_to_string(path).expect("rng trace 文件必须存在");
        let first = text.lines().next().expect("trace 必须已有头部");
        let cols: Vec<&str> = first.split('\t').collect();
        assert_eq!(cols[1], "INJECT_OK", "trace 头部第一行必须是 INJECT_OK");
        cols[2].parse().expect("INJECT_OK 的 seed 必须是 int")
    }

    // ======================================================================
    // 卡 `openmir2-magic-parity` §39：39 `SKILL_GROUPDEDING` 真实台账驱动
    // ======================================================================

    /// 39 的 rig：几何/魔表与 C# Golden 同（caster 100,100；target 101,100；obs_in 105,100；
    /// obs_out 140,100；魔表 `{39, effect=1, effect_type=1, train_lv=0}`）。
    fn groupdeding_rig(id_base: i32, mc: u16, sc: u16) -> SpellFrameRig {
        let mut rig = SpellFrameRig::new_layout(
            200,
            200,
            id_base,
            100,
            100,
            39,
            &[(39, 1)],
            &[
                ("target", 101, 100, false, 912),
                ("obs_in", 105, 100, false, 913),
                ("obs_out", 140, 100, false, 914),
            ],
        );
        // 魔表行 = C# `new MagicInfo { MagicId=39, Effect=1, EffectType=1 }`（其余缺省 0，
        // 尤其 `train_lv=0` ⇒ 训练尾不触发 `CheckMagicLevelUp` 升级支）。
        rig.magic_table = magics::MagicTable::new(vec![mir2_data::MagicInfo {
            magic_id: 39,
            effect: 1,
            effect_type: 1,
            ..mir2_data::MagicInfo::default()
        }]);
        {
            let e = rig.world.entities.get_mut(rig.caster).unwrap();
            e.progression.level = 30;
            e.player_run.luck = 0;
            e.player_run.power_rate = 100;
            e.vitals.hp = 500;
            e.vitals.max_hp = 500;
        }
        {
            let sg = rig.ground_sessions.get_mut("caster").unwrap();
            sg.state.wabil.level = 30;
            sg.state.wabil.mc = mc;
            sg.state.wabil.sc = sc;
            sg.state.wabil.hp = 500;
            sg.state.wabil.max_hp = 500;
        }
        let target = fireball_actor(&rig, "target");
        {
            let e = rig.world.entities.get_mut(target).unwrap();
            e.vitals.anti_magic = 3;
            e.vitals.hp = 100;
            e.vitals.max_hp = 100;
            e.progression.level = 20;
        }
        {
            let mut tsg = spell_session_ground(target);
            tsg.equip.abil.level = 20;
            tsg.equip.abil.max_exp = 50;
            tsg.state.wabil.level = 20;
            tsg.state.wabil.hp = 100;
            tsg.state.wabil.max_hp = 100;
            rig.ground_sessions.insert("target".into(), tsg);
        }
        for e in rig.online.clone() {
            if let Some(mut d) = rig.displays.get(e.actor_id).cloned() {
                d.feature = 0;
                rig.displays.set(e.actor_id, d);
            }
        }
        rig.saves
            .get_mut("caster")
            .unwrap()
            .record
            .data
            .magic
            .as_mut()
            .unwrap()[0]
            .as_mut()
            .unwrap()
            .level = 1;
        rig
    }

    /// 逐目标命中门抽值走查（与装置侧 C# 同一算法）：`mon{idx} -> (gate_idx, gate_val, hit)`。
    ///
    /// 抽序（HAM_PEACE ⇒ 只有非死怪进伤害链）：每只 `GetAttackPower`（2 抽）+ 命中门
    /// `Random(SpeedPoint)`（1 抽）+ 命中则护甲（1–2 抽）；最后若有任一非死怪则共享尾
    /// 训练 `Random(3)+1`（1 抽）。走查必须恰好耗尽 `draws`（夹具假设被破坏即红）。
    fn gdd_gate_ledger(
        specs: &[[i64; 14]],
        hit_point: i32,
        draws: &[i64],
        label: &str,
    ) -> std::collections::HashMap<usize, (i32, i64, bool)> {
        let mut out = std::collections::HashMap::new();
        let mut order: Vec<usize> = (0..specs.len()).filter(|i| specs[*i][9] == 0).collect();
        order.sort_by_key(|i| (specs[*i][0], specs[*i][1]));
        let mut di = 0usize;
        for idx in order {
            let ac = specs[idx][10];
            di += 2;
            assert!(di < draws.len(), "[{label}] mon{idx} 命中门越界");
            let gate_idx = di;
            let gate = draws[di];
            di += 1;
            let hit = gate < i64::from(hit_point);
            if hit {
                let lo = ac & 0xFF;
                assert!(di < draws.len(), "[{label}] mon{idx} 护甲骰越界");
                let r = draws[di];
                di += 1;
                if lo + r > 0 {
                    di += 1;
                }
            }
            out.insert(idx, (i32::try_from(gate_idx).unwrap(), gate, hit));
        }
        if specs.iter().any(|m| m[9] == 0) {
            di += 1; // 共享尾训练抽 `Random(3)+1`
        }
        assert_eq!(
            di,
            draws.len(),
            "[{label}] 逐目标抽值走查未耗尽：consumed={di} recorded={}",
            draws.len()
        );
        out
    }

    fn groupdeding_parity_drive(label: &str, id_base: i32) {
        std::env::set_var("MIR2_CLIENT_ABILITY_LAYOUT", "0");
        let stem = "groupdeding";
        let dir = magic_ledger_dir();
        std::fs::create_dir_all(&dir).expect("台账目录必须可建");
        let run_id = ledger_run_id();
        let seed = golden_seed(stem, label);

        let mc = golden_fixture_required(stem, label, "caster_mc");
        let sc = golden_fixture_required(stem, label, "caster_sc");
        let mut rig = groupdeding_rig(id_base, mc, sc);
        let target = fireball_actor(&rig, "target");
        if let Some(a) = golden_fixture_opt(stem, label, "anti_magic") {
            rig.world
                .entities
                .get_mut(target)
                .unwrap()
                .vitals
                .anti_magic = u16::try_from(a).unwrap_or(0);
        }
        if let Some(m) = golden_fixture_opt(stem, label, "target_max_hp") {
            let m = u16::try_from(m).unwrap_or(0);
            rig.world.entities.get_mut(target).unwrap().vitals.max_hp = m;
            rig.ground_sessions
                .get_mut("target")
                .unwrap()
                .state
                .wabil
                .max_hp = m;
        }
        if let Some(h) = golden_fixture_opt(stem, label, "target_hp") {
            let h = u16::try_from(h).unwrap_or(0);
            rig.world.entities.get_mut(target).unwrap().vitals.hp = h;
            rig.ground_sessions
                .get_mut("target")
                .unwrap()
                .state
                .wabil
                .hp = h;
        }
        let hit_point = i32::from(golden_fixture_required(stem, label, "caster_hit_point"));
        let dc = i32::from(golden_fixture_required(stem, label, "caster_dc"));
        let attack_mode =
            u8::try_from(golden_fixture_required(stem, label, "caster_attack_mode")).unwrap();
        let caster = rig.caster;
        {
            let e = rig.world.entities.get_mut(caster).unwrap();
            e.vitals.hit_point = u8::try_from(hit_point).unwrap();
            e.vitals.dc = dc;
            e.flags.attack_mode = attack_mode;
        }
        let specs = golden_monsters(stem, label);
        let monster_ids = place_monsters(&mut rig.world, &specs, id_base + 10);
        assert_eq!(monster_ids.len(), specs.len());
        let mon_hp_before: Vec<u16> = monster_ids
            .iter()
            .map(|id| rig.world.entities.get(*id).unwrap().hp)
            .collect();

        // **种子/台账安装必须在放怪之后**（C# `RngSeam.Install` 在 DoSpell 前、怪物创建后；
        // `place_monsters` 的 `world.tick()` 不得污染播种后的序列）。
        let trace = dir.join(format!("{stem}_{label}_seed{seed}.rng.tsv"));
        assert!(
            !mir2_shared::rng_trace::enabled(),
            "rng_trace 已被本进程其它路径开启 ⇒ 请以 --exact 单跑本用例"
        );
        let _ = std::fs::remove_file(&trace);
        mir2_shared::rng_trace::enable(&trace, seed).expect("打开 rng trace");
        assert_eq!(
            trace_header_seed(&trace),
            seed,
            "trace 头部 seed 必须与本支一致"
        );
        rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(seed);

        let n0 = trace_line_count(&trace);
        let hp_before = rig.world.entities.get(target).unwrap().hp;

        // ---- 段①：生产入口施法 ----
        rig.cast(39, (101, 100), target);
        let n1 = trace_line_count(&trace);
        let (cast_frames, _raws) = rig.drain();
        let mon_hp_after: Vec<u16> = monster_ids
            .iter()
            .map(|id| rig.world.entities.get(*id).unwrap().hp)
            .collect();
        let hp_after = rig.world.entities.get(target).unwrap().hp;

        // 交付前抓 caster 的自延迟载荷（RM_DELAYMAGIC / RM_MAGIC_LVEXP）。
        let mut delay_msgs: Vec<(i32, i32, i32, i32, u8)> = Vec::new();
        let mut lv_exp: Option<(i32, i32, i32)> = None;
        for m in rig
            .world
            .self_delay_msgs
            .iter()
            .filter(|m| m.actor_id == caster)
        {
            if m.ident == mir2_world_bevy::slave::RM_DELAYMAGIC {
                delay_msgs.push((m.w_param, m.n_param1, m.n_param2, m.n_param3, m.priority));
            } else if m.ident == mir2_world_bevy::slave::RM_MAGIC_LVEXP {
                lv_exp = Some((m.n_param1, m.n_param2, m.n_param3));
            }
        }

        // ---- 段②：按 due 时刻分步推进世界时钟并交付（不调 drain_b4：怪物 RM_MAGSTRUCK
        // 只记 RM、不 Operate；B3 只出 640 等自延迟帧）。----
        let wait_ms = golden_wait_ms(stem, label);
        let mut deliver_frames: Vec<SfFrame> = Vec::new();
        let mut struck_rm: Vec<(i32, i32)> = Vec::new();
        let mut elapsed = 0u64;
        while elapsed < wait_ms {
            rig.world.clock_ms += 100;
            elapsed += 100;
            let outs = rig.world.deliver_self_delay_msgs();
            for s in std::mem::take(&mut rig.world.pending_mag_struck) {
                struck_rm.push((s.target_id, s.power));
            }
            if outs.is_empty() {
                continue;
            }
            let rec = mir2_world_bevy::TickRecord {
                slave_self_deliveries: outs,
                ..Default::default()
            };
            drain_b3_self_deliveries(
                &rec,
                &rig.world,
                &rig.online,
                &mut rig.ground_sessions,
                &rig.gates,
            );
            let (mut sf, _r2) = rig.drain();
            deliver_frames.append(&mut sf);
        }
        let n2 = trace_line_count(&trace);
        let cast_rng = trace_slice(&trace, n0, n1);
        let deliver_rng = trace_slice(&trace, n1, n2);

        let mut all_frames = cast_frames;
        all_frames.extend(deliver_frames);

        // ---- RM 列（弱比较面）----
        let range = chat::send_ref_msg_range();
        let in_range = chat::hear_targets(&rig.world, caster, range);
        let map_id = rig.world.entities.get(caster).map_or(0, |e| e.map_id);
        let processed_coords: Vec<(i32, i32)> = rig
            .world
            .mag_objects_in_range(map_id, 101, 100, 1)
            .into_iter()
            .filter(|id| *id != caster)
            .filter_map(|id| rig.world.entities.get(id).map(|e| (e.x, e.y)))
            .collect();
        let mut rm_by_who: std::collections::HashMap<String, Vec<serde_json::Value>> =
            std::collections::HashMap::new();
        let who_of = |id: i32| {
            rig.online
                .iter()
                .find(|e| e.actor_id == id)
                .map(|e| e.chr_name.clone())
        };
        let magic_p2 = game_svr::feature::make_long(101, 100);
        for id in &in_range {
            let Some(who) = who_of(*id) else { continue };
            let v = rm_by_who.entry(who).or_default();
            v.push(fireball_rm(10008, 1, 101, 100, 39, 24, false));
            v.push(fireball_rm(
                10120,
                0,
                257,
                i64::from(magic_p2),
                i64::from(target),
                136,
                false,
            ));
            for (x, y) in &processed_coords {
                v.push(fireball_rm(
                    10205,
                    0,
                    i64::from(*x),
                    i64::from(*y),
                    1,
                    221,
                    false,
                ));
            }
        }
        let caster_rm = rm_by_who.entry("caster".into()).or_default();
        for (w, p1, p2, p3, prio) in &delay_msgs {
            caster_rm.push(fireball_rm(
                8021,
                i64::from(*w),
                i64::from(*p1),
                i64::from(*p2),
                i64::from(*p3),
                i64::from(*prio),
                true,
            ));
        }
        if let Some((magic_id, level, tran)) = lv_exp {
            caster_rm.push(fireball_rm(
                10123,
                0,
                i64::from(magic_id),
                i64::from(level),
                i64::from(tran),
                255,
                true,
            ));
        }

        // ---- 接收者 ----
        let mut receivers: Vec<serde_json::Value> = Vec::new();
        for (who, socket) in [
            ("caster", 911),
            ("target", 912),
            ("obs_in", 913),
            ("obs_out", 914),
        ] {
            receivers.push(serde_json::json!({
                "Who": who,
                "Rm": rm_by_who.get(who).cloned().unwrap_or_default(),
                "Sent": fireball_sent(&all_frames, socket),
            }));
        }
        let cast_values: Vec<i64> = cast_rng.iter().map(|(_, r, _)| *r).collect();
        let gate = gdd_gate_ledger(&specs, hit_point, &cast_values, label);
        for (i, id) in monster_ids.iter().enumerate() {
            let rm: Vec<serde_json::Value> = struck_rm
                .iter()
                .filter(|(tid, _)| tid == id)
                .map(|(_, power)| fireball_rm(8044, 0, i64::from(*power), 0, 0, 108, false))
                .collect();
            let mut mon = serde_json::json!({
                "Who": format!("mon{i}"),
                "Rm": rm,
                "Sent": Vec::<serde_json::Value>::new(),
                "HpBefore": i64::from(mon_hp_before[i]),
                "HpAfter": i64::from(mon_hp_after[i]),
            });
            if let Some((gi, gv, gh)) = gate.get(&i) {
                mon["GateIndex"] = serde_json::json!(gi);
                mon["GateDraw"] = serde_json::json!(gv);
                mon["GateHit"] = serde_json::json!(gh);
            }
            receivers.push(mon);
        }

        let ledger = serde_json::json!([{
            "Label": label,
            "Seed": seed,
            "SpellReturn": true,
            "Receivers": receivers,
            "Rng": cast_rng.iter().map(|(_, r, _)| *r).collect::<Vec<_>>(),
            "RngSites": cast_rng.iter().map(|(_, _, s)| s.replace('\\', "/")).collect::<Vec<_>>(),
            "RngSeqs": cast_rng.iter().map(|(s, _, _)| *s).collect::<Vec<_>>(),
            "DeliverRng": deliver_rng.iter().map(|(_, r, _)| *r).collect::<Vec<_>>(),
            "DeliverRngSites": deliver_rng.iter().map(|(_, _, s)| s.replace('\\', "/")).collect::<Vec<_>>(),
            "TargetHpBefore": hp_before,
            "TargetHp": hp_after,
            "NotDue": [],
            "CasterMp": 0,
        }]);
        let out = dir.join(format!("{stem}_{label}.json"));
        std::fs::write(&out, serde_json::to_string_pretty(&ledger).unwrap()).expect("台账必须可写");
        write_run_sidecar(&out, &run_id, seed);
        eprintln!(
            "[groupdeding {label}] seed={seed} cast_rng={:?} deliver_rng={:?} mon_hp={:?}->{:?}",
            cast_values,
            deliver_rng.iter().map(|(_, r, _)| *r).collect::<Vec<_>>(),
            mon_hp_before,
            mon_hp_after
        );
    }

