    /// **MG-55（46 分身术）**真实台账驱动：金标准 `golden/magic/clone46.json`（单支 `clone`）。
    ///
    /// 输入**一律从 golden `Fixture` 读**（caster 等级/MC/SC/AntiMagic、`Dir/Gender/Hair`、
    /// 魔表 `TrainLv/MaxTrain[0]`、seed、`wait_ms`）。观测面 = 克隆体静态字段 + 逐收件人
    /// `SM_TURN(10)` / `SM_FEATURECHANGED(41)` + 训练尾 640。
    ///
    /// **ActorId 归一化**：克隆体 id 由**进程级自增**分配（C# `ActorEntity.cs:20`；Rust
    /// `alloc_id`），两侧数值不可比 ⇒ 台账记本侧 `Clone.actor_id`，比较器据此把「等于克隆体
    /// id 的 recog」归一化后再逐帧比（不把 id 本身写进相等判据）。
    fn clone46_parity_drive(label: &str) {
        std::env::set_var("MIR2_CLIENT_ABILITY_LAYOUT", "0");
        let stem = "clone46";
        let dir = magic_ledger_dir();
        std::fs::create_dir_all(&dir).expect("台账目录必须可建");
        let run_id = ledger_run_id();
        let seed = golden_seed(stem, label);
        let trace = dir.join(format!("{stem}_{label}_seed{seed}.rng.tsv"));
        assert!(
            !mir2_shared::rng_trace::enabled(),
            "rng_trace 已被本进程其它路径开启 ⇒ 请 --exact 单跑"
        );
        let _ = std::fs::remove_file(&trace);
        mir2_shared::rng_trace::enable(&trace, seed).expect("打开 rng trace");
        assert_eq!(
            trace_header_seed(&trace),
            seed,
            "trace 头部 seed 必须与本支一致"
        );
        // ---- 输入一律从 golden 读（缺键即红）----
        let magic_id = golden_fixture_required(stem, label, "magic_id");
        let effect = golden_fixture_required(stem, label, "effect");
        let effect_type = golden_fixture_required(stem, label, "effect_type");
        let user_magic_level = golden_fixture_required(stem, label, "user_magic_level");
        let caster_level = golden_fixture_required(stem, label, "caster_level");
        let caster_mc = golden_fixture_required(stem, label, "caster_mc");
        let caster_sc = golden_fixture_required(stem, label, "caster_sc");
        let anti_magic = golden_fixture_required(stem, label, "anti_magic");
        let caster_actor_id = golden_fixture_required(stem, label, "caster_actor_id");
        let caster_dir_in = golden_fixture_required(stem, label, "caster_dir");
        let caster_gender = golden_fixture_required(stem, label, "caster_gender");
        let caster_hair = golden_fixture_required(stem, label, "caster_hair");
        let magic_train_lv = golden_fixture_required(stem, label, "magic_train_lv");
        let magic_max_train0 = golden_fixture_required(stem, label, "magic_max_train0");
        let pre_face = golden_case_for(stem, label)["Fixture"]["pre_spell_face_target"]
            .as_bool()
            .expect("golden 必须记录 pre_spell_face_target（夹具输入不许缺省兜底）");
        assert!(
            pre_face,
            "[{stem}/{label}] 生产路径在 DoSpell 前转向点击坐标；pre_spell_face_target 必须为 true"
        );
        let fast_train = golden_case_for(stem, label)["Fixture"]["fast_train"]
            .as_bool()
            .expect("golden 必须记录 fast_train（输入不许缺省兜底）");
        assert!(
            !fast_train,
            "[{stem}/{label}] PlayObject.FastTrain 缺省 false（只有快速修炼项链会置 true）；夹具必须为 false"
        );
        let caster_gender = u8::try_from(caster_gender).expect("caster_gender 越界");
        let caster_hair = u8::try_from(caster_hair).expect("caster_hair 越界");
        let level_u8 = u8::try_from(caster_level).expect("caster_level 越界");
        let id_base = i32::from(caster_actor_id) - 1;
        let mut rig = SpellFrameRig::new_layout(
            200,
            200,
            id_base,
            100,
            100,
            magic_id,
            &[(
                magic_id,
                u8::try_from(user_magic_level).expect("user_magic_level 越界"),
            )],
            &[
                ("target", 101, 100, false, 912),
                ("obs_in", 105, 100, false, 913),
                ("obs_out", 140, 100, false, 914),
            ],
        );
        rig.magic_table = magics::MagicTable::new(vec![mir2_data::MagicInfo {
            magic_id,
            effect: u8::try_from(effect).expect("effect 越界"),
            effect_type: u8::try_from(effect_type).expect("effect_type 越界"),
            train_lv: u8::try_from(magic_train_lv).expect("train_lv 越界"),
            train_level: [0; 4],
            max_train: [i32::from(magic_max_train0), 0, 0, 0],
            ..mir2_data::MagicInfo::default()
        }]);
        // UserMagic 内存态：level 从 golden 读、TranPoint=0（与装置 `um.TranPoint=0` 同源）。
        {
            let list = rig
                .saves
                .get_mut("caster")
                .and_then(|s| s.record.data.magic.as_mut())
                .expect("new_layout 必须给 caster 一条 magic 记录");
            let m = list
                .iter_mut()
                .flatten()
                .find(|m| m.mag_idx == magic_id)
                .expect("caster 魔表必须含本魔号");
            m.level = u8::try_from(user_magic_level).expect("user_magic_level 越界");
            m.tran_point = 0;
        }
        {
            let e = rig.world.entities.get_mut(rig.caster).unwrap();
            e.progression.level = level_u8;
            e.vitals.hp = 500;
            e.vitals.max_hp = 500;
        }
        {
            let sg = rig.ground_sessions.get_mut("caster").unwrap();
            sg.equip.abil.level = level_u8;
            sg.state.wabil.level = level_u8;
            sg.state.wabil.mc = caster_mc;
            sg.state.wabil.sc = caster_sc;
        }
        {
            let t = fireball_actor(&rig, "target");
            let e = rig.world.entities.get_mut(t).unwrap();
            e.vitals.anti_magic = anti_magic;
        }
        // 主人展示面：Gender/Hair 无损编码进 feature（`clone_display` 从位域反解）。
        // Dress/Weapon 归 0（夹具无装备，与 C# 登录序一致）。
        let caster_feature = game_svr::feature::make_human_feature(
            0,
            caster_gender,
            caster_gender,
            caster_hair.wrapping_mul(2).wrapping_add(caster_gender),
        );
        rig.displays.set(
            rig.caster,
            downlink::ActorDisplay::new(4, 0, caster_feature, 0, 0, 255, b"caster".to_vec()),
        );
        rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(seed);
        let target = fireball_actor(&rig, "target");
        let hp_before = i64::from(rig.world.entities.get(target).unwrap().hp);
        let (level_before, tp_before) = skill_tail_rcd(&rig, magic_id);
        let n0 = trace_line_count(&trace);
        rig.cast(magic_id, (101, 100), target);
        let n1 = trace_line_count(&trace);
        let (cast_frames, _raws) = rig.drain();
        let mut all_frames: Vec<(i32, Vec<u8>, i64)> =
            cast_frames.into_iter().map(|(s, b)| (s, b, 0i64)).collect();
        // 跨 1000ms 排水（640 是 `SendSelfDelayMsg(…,1000)` 自投递；与 golden `wait_ms` 同值）。
        let wait_ms = golden_wait_ms(stem, label);
        let mut elapsed: u64 = 0;
        while elapsed < wait_ms {
            rig.world.clock_ms += 100;
            elapsed += 100;
            let outs = rig.world.deliver_self_delay_msgs();
            if outs.is_empty() {
                continue;
            }
            let rec = mir2_world_bevy::TickRecord {
                slave_self_deliveries: outs.clone(),
                ..Default::default()
            };
            drain_b4_self_deliveries(
                &rec,
                &mut rig.world,
                &rig.online,
                &mut rig.displays,
                &mut rig.ground_sessions,
                &rig.gates,
                0,
                0,
                b"",
            );
            drain_b3_self_deliveries(
                &rec,
                &rig.world,
                &rig.online,
                &mut rig.ground_sessions,
                &rig.gates,
            );
            let (mut step_frames, _raws2) = rig.drain();
            for f in step_frames.drain(..) {
                all_frames.push((f.0, f.1, elapsed as i64));
            }
        }
        let n2 = trace_line_count(&trace);
        let cast_rng = trace_slice(&trace, n0, n1);
        let deliver_rng = trace_slice(&trace, n1, n2);
        let (level_after, tp_after) = skill_tail_rcd(&rig, magic_id);
        let hp_after = i64::from(rig.world.entities.get(target).unwrap().hp);
        // ---- 克隆体（**B20**：oracle actor-id 非确定 ⇒ 绝对值不入 golden；本侧 id 仅用于
        // 同侧关系断言与台账可见性，不跨栈比）----
        let clone_count = rig.world.entities.iter_ref().filter(|e| e.is_clone).count();
        assert_eq!(clone_count, 1, "46 施法后应恰有一个克隆体实体");
        let (clone_id, cx, cy) = {
            let c = rig
                .world
                .entities
                .iter_ref()
                .find(|e| e.name == mir2_world_bevy::CLONE_NAME)
                .expect("46 施法后应有克隆体实体");
            (c.id, c.x, c.y)
        };
        let sibling_ids = [
            rig.caster,
            fireball_actor(&rig, "target"),
            fireball_actor(&rig, "obs_in"),
            fireball_actor(&rig, "obs_out"),
        ];
        assert!(
            rig.world.entities.get(clone_id).is_some(),
            "克隆体必须已落库"
        );
        let clone_dir = rig.world.entities.get(clone_id).unwrap().ai.dir;
        let clone_display = rig.displays.get(clone_id).expect("克隆体展示必须登记");
        let cf = u32::try_from(clone_display.feature).expect("feature 必须非负");
        let clone_gender = ((cf >> 8) & 1) as u8;
        let clone_hair = (((cf >> 16) & 0xFF) as u8) >> 1;
        let caster_dir_now = actor_dir(&rig.world, &rig.displays, rig.caster);
        let caster_display = rig.displays.get(rig.caster).expect("caster 展示必须存在");
        let cf2 = u32::try_from(caster_display.feature).expect("caster feature 必须非负");
        // ---- RM 列（装配；与 oracle `SendRefMsg` 参数逐项对应）----
        let spell_rm = fireball_rm(
            10008,
            i64::from(effect),
            101,
            100,
            i64::from(magic_id),
            24,
            false,
        );
        let fire_rm = fireball_rm(
            10120,
            0,
            i64::from(effect_type) | (i64::from(effect) << 8),
            101 | (100 << 16),
            i64::from(target),
            136,
            false,
        );
        let lvexp_rm = fireball_rm(
            10123,
            0,
            i64::from(magic_id),
            i64::from(level_after),
            i64::from(tp_after),
            255,
            true,
        );
        let rm_of = |who: &str| -> Vec<serde_json::Value> {
            // 出生零帧 ⇒ **无** RM_TURN(10001) 到达任何收件人（克隆体自投递）。
            match who {
                "caster" => vec![spell_rm.clone(), fire_rm.clone(), lvexp_rm.clone()],
                "target" | "obs_in" => vec![spell_rm.clone(), fire_rm.clone()],
                _ => Vec::new(),
            }
        };
        let mut receivers: Vec<serde_json::Value> = Vec::new();
        let mut clone_receivers: Vec<serde_json::Value> = Vec::new();
        for (who, socket) in [
            ("caster", 911),
            ("target", 912),
            ("obs_in", 913),
            ("obs_out", 914),
        ] {
            let sent = fireball_sent_with_due(&all_frames, socket);
            let clone_frames: Vec<serde_json::Value> = sent
                .iter()
                .filter(|f| {
                    let id = f.get("ident").and_then(serde_json::Value::as_i64);
                    id == Some(i64::from(mir2_protocol::messages::SM_TURN))
                        || id == Some(i64::from(mir2_protocol::messages::SM_FEATURECHANGED))
                })
                .cloned()
                .collect();
            clone_receivers.push(serde_json::json!({ "who": who, "frames": clone_frames }));
            receivers.push(serde_json::json!({
                "Who": who,
                "Rm": rm_of(who),
                "Sent": sent,
            }));
        }
        let mi = rig.magic_table.get(magic_id).expect("魔表必须有该魔号");
        let n_level = skill_tail_n_level(level_after, mi.train_lv);
        let mt_used = mi.max_train.get(n_level).copied().unwrap_or(0);
        let train = serde_json::json!({
            "level_before": level_before,
            "level_after": level_after,
            "tran_point_before": tp_before,
            "tran_point_after": tp_after,
            "train_lv": mi.train_lv,
            "max_train0": mi.max_train.first().copied().unwrap_or(0),
            "n_level": n_level,
            "max_train_at_level": mt_used,
            "train_level_at_level": mi.train_level[n_level],
        });
        let has_640 = all_frames
            .iter()
            .filter(|(s, _, _)| *s == 911)
            .filter(|(_, b, _)| sf_ident(b) == mir2_protocol::messages::SM_MAGIC_LVEXP)
            .count()
            == 1;
        let clone_block = serde_json::json!({
            "name": mir2_world_bevy::CLONE_NAME,
            // 本侧 id 可见（供关系断言/复核），**不与 golden 比**。
            "actor_id": clone_id,
            "sibling_actor_ids": sibling_ids,
            "clone_ordinal": 0,
            "clone_count": clone_count,
            "actor_id_policy": "oracle_guid_nondeterministic",
            "x": cx,
            "y": cy,
            "dir": i64::from(clone_dir),
            "gender": i64::from(clone_gender),
            "hair": i64::from(clone_hair),
            "caster_dir": i64::from(caster_dir_now),
            "caster_gender": i64::from(((cf2 >> 8) & 1) as u8),
            "caster_hair": i64::from((((cf2 >> 16) & 0xFF) as u8) >> 1),
            "has_640": has_640,
            "receivers": clone_receivers,
        });
        let ledger = serde_json::json!([{
            "Label": label,
            "Seed": seed,
            "SpellReturn": true,
            "Receivers": receivers,
            // `verify` 的 `Rng` 判据 = `golden.Rng == rust.Rng ++ rust.DeliverRng`（cover_drain）。
            "Rng": cast_rng.iter().map(|(_, r, _)| *r).collect::<Vec<_>>(),
            "RngSites": cast_rng.iter().map(|(_, _, st)| st.replace(std::path::MAIN_SEPARATOR, "/")).collect::<Vec<_>>(),
            "RngSeqs": cast_rng.iter().map(|(sq, _, _)| *sq).collect::<Vec<_>>(),
            "DeliverRng": deliver_rng.iter().map(|(_, r, _)| *r).collect::<Vec<_>>(),
            "DeliverRngSites": deliver_rng.iter().map(|(_, _, st)| st.replace(std::path::MAIN_SEPARATOR, "/")).collect::<Vec<_>>(),
            "DeliverRngSeqs": deliver_rng.iter().map(|(sq, _, _)| *sq).collect::<Vec<_>>(),
            "TargetHpBefore": hp_before,
            "TargetHp": hp_after,
            "Train": train,
            "Clone": clone_block,
        }]);
        let out = dir.join(format!("{stem}_{label}.json"));
        std::fs::write(&out, serde_json::to_string_pretty(&ledger).unwrap()).expect("台账必须可写");
        write_run_sidecar(&out, &run_id, seed);
        // ---- 断言（落盘之后：红了也要留下本次台账，比较器才能给语义红）----
        // 前提：**构造期 5 抽 + 训练尾 1 抽 = 6**、交付段零抽、训练值 = TranPoint 增量 − 1。
        assert_eq!(
            cast_rng.len(),
            6,
            "[{stem}/{label}] 应恰 6 抽（克隆体 ctor 5 + 训练尾 1）；实得 {:?}",
            cast_rng.iter().map(|(_, v, _)| *v).collect::<Vec<_>>()
        );
        assert_eq!(
            i64::from(tp_after),
            i64::from(tp_before) + cast_rng[5].1 + 1,
            "[{stem}/{label}] 训练尾抽值必须等于 TranPoint 增量 − 1（抽序错位会在这里红）"
        );
        assert!(
            deliver_rng.is_empty(),
            "[{stem}/{label}] 交付段不应有抽取；实得 {:?}",
            deliver_rng
        );
        assert_eq!(
            level_after, level_before,
            "[{stem}/{label}] 本批只做未升级支"
        );
        assert!(
            i64::from(mt_used) > i64::from(tp_after),
            "[{stem}/{label}] 前提：MaxTrain[nLevel={n_level}]={mt_used} 必须 > TranPoint={tp_after}"
        );
        // 帧面（oracle 形态；驱动自带牙）。
        let idents = |socket: i32| -> Vec<u16> {
            all_frames
                .iter()
                .filter(|(s, _, _)| *s == socket)
                .map(|(_, b, _)| sf_ident(b))
                .collect()
        };
        assert_eq!(
            idents(911),
            vec![
                mir2_protocol::messages::SM_MAGICFIRE,
                mir2_protocol::messages::SM_MAGIC_LVEXP,
            ],
            "[{stem}/{label}] caster 帧序应为 [638,640]（出生零帧）"
        );
        for socket in [912, 913] {
            assert_eq!(
                idents(socket),
                vec![
                    mir2_protocol::messages::SM_SPELL,
                    mir2_protocol::messages::SM_MAGICFIRE,
                ],
                "[{stem}/{label}] socket {socket} 帧序应为 [17,638]（出生零帧）"
            );
        }
        assert!(idents(914).is_empty(), "[{stem}/{label}] obs_out 必须零帧");
        for socket in [911, 912, 913] {
            let turns: Vec<u16> = idents(socket)
                .into_iter()
                .filter(|id| {
                    *id == mir2_protocol::messages::SM_TURN
                        || *id == mir2_protocol::messages::SM_FEATURECHANGED
                })
                .collect();
            assert!(
                turns.is_empty(),
                "[{stem}/{label}] socket {socket} 不得有出生帧（oracle FixedHideMode 自投递）；实得 {turns:?}"
            );
        }
        assert!(has_640, "[{stem}/{label}] 训练尾 640 必须存在");
        assert_eq!(
            clone_dir,
            (caster_dir_now + 4) % 8,
            "[{stem}/{label}] clone.dir 必须是 GetBackDir(caster_dir)：{clone_dir} vs {caster_dir_now}"
        );
        assert_eq!(
            clone_gender, caster_gender,
            "[{stem}/{label}] Gender 必须复制"
        );
        assert_eq!(clone_hair, caster_hair, "[{stem}/{label}] Hair 必须复制");
        let _ = caster_dir_in;
        eprintln!(
            "[{stem} {label}] seed={seed} clone={clone_id} pos=({cx},{cy}) dir={clone_dir} gender={clone_gender} hair={clone_hair} frames={}",
            all_frames.len()
        );
    }

    #[test]
    #[ignore = "真实台账驱动：需 --exact --test-threads=1 单独进程"]
    fn clone46_parity_clone() {
        clone46_parity_drive("clone");
    }

    /// **MG-36（22 火墙 `MagMakeFireCross`）**真实台账驱动：金标准 `golden/magic/firecross.json`
    /// （三支 `base` / `pre_center` / `safe_zone`）。
    ///
    /// 观测面：事件表（`EventType/x/y/ContinueTime/Damage`；**不记 RunTick/时间戳**）+ 安全区门 +
    /// 预占去重 + 帧面/RNG。逐 tick 的 3000ms 伤害不启动（事件进程不在 harness）。
    fn firecross_parity_drive(label: &str) {
        std::env::set_var("MIR2_CLIENT_ABILITY_LAYOUT", "0");
        let stem = "firecross";
        let dir = magic_ledger_dir();
        std::fs::create_dir_all(&dir).expect("台账目录必须可建");
        let run_id = ledger_run_id();
        let seed = golden_seed(stem, label);
        let trace = dir.join(format!("{stem}_{label}_seed{seed}.rng.tsv"));
        assert!(
            !mir2_shared::rng_trace::enabled(),
            "rng_trace 已被本进程其它路径开启 ⇒ 请 --exact 单跑"
        );
        let _ = std::fs::remove_file(&trace);
        mir2_shared::rng_trace::enable(&trace, seed).expect("打开 rng trace");
        assert_eq!(
            trace_header_seed(&trace),
            seed,
            "trace 头部 seed 必须与本支一致"
        );
        // ---- 输入一律从 golden 读（缺键即红）----
        let magic_id = golden_fixture_required(stem, label, "magic_id");
        let effect = golden_fixture_required(stem, label, "effect");
        let effect_type = golden_fixture_required(stem, label, "effect_type");
        let user_magic_level = golden_fixture_required(stem, label, "user_magic_level");
        let caster_level = golden_fixture_required(stem, label, "caster_level");
        let caster_mc = golden_fixture_required(stem, label, "caster_mc");
        let caster_sc = golden_fixture_required(stem, label, "caster_sc");
        let anti_magic = golden_fixture_required(stem, label, "anti_magic");
        let caster_actor_id = golden_fixture_required(stem, label, "caster_actor_id");
        let magic_train_lv = golden_fixture_required(stem, label, "magic_train_lv");
        let magic_max_train0 = golden_fixture_required(stem, label, "magic_max_train0");
        let red_f = golden_fixture_required(stem, label, "red_msg_f_color");
        let red_b = golden_fixture_required(stem, label, "red_msg_b_color");
        let fx = golden_case_for(stem, label)["Fixture"].clone();
        let safe_zone = fx["firecross_safe_zone"]
            .as_bool()
            .expect("golden 必须记录 firecross_safe_zone（输入不许缺省兜底）");
        let pre_cells: Vec<(i32, i32)> = fx["pre_event_cells"]
            .as_array()
            .expect("golden 必须记录 pre_event_cells（数组）")
            .iter()
            .map(|c| {
                let a = c.as_array().expect("pre_event_cells 每项是 [x,y]");
                (
                    i32::try_from(a[0].as_i64().expect("x")).expect("x i32"),
                    i32::try_from(a[1].as_i64().expect("y")).expect("y i32"),
                )
            })
            .collect();
        let level_u8 = u8::try_from(caster_level).expect("caster_level 越界");
        let id_base = i32::from(caster_actor_id) - 1;
        let mut rig = SpellFrameRig::new_layout(
            200,
            200,
            id_base,
            100,
            100,
            magic_id,
            &[(
                magic_id,
                u8::try_from(user_magic_level).expect("user_magic_level 越界"),
            )],
            &[
                ("target", 101, 100, false, 912),
                ("obs_in", 105, 100, false, 913),
                ("obs_out", 140, 100, false, 914),
            ],
        );
        rig.magic_table = magics::MagicTable::new(vec![mir2_data::MagicInfo {
            magic_id,
            effect: u8::try_from(effect).expect("effect 越界"),
            effect_type: u8::try_from(effect_type).expect("effect_type 越界"),
            train_lv: u8::try_from(magic_train_lv).expect("train_lv 越界"),
            train_level: [0; 4],
            max_train: [i32::from(magic_max_train0), 0, 0, 0],
            ..mir2_data::MagicInfo::default()
        }]);
        {
            let list = rig
                .saves
                .get_mut("caster")
                .and_then(|s| s.record.data.magic.as_mut())
                .expect("new_layout 必须给 caster 一条 magic 记录");
            let m = list
                .iter_mut()
                .flatten()
                .find(|m| m.mag_idx == magic_id)
                .expect("caster 魔表必须含本魔号");
            m.level = u8::try_from(user_magic_level).expect("user_magic_level 越界");
            m.tran_point = 0;
        }
        {
            let e = rig.world.entities.get_mut(rig.caster).unwrap();
            e.progression.level = level_u8;
            e.vitals.hp = 500;
            e.vitals.max_hp = 500;
            e.flags.in_safe_zone = safe_zone;
        }
        {
            let sg = rig.ground_sessions.get_mut("caster").unwrap();
            sg.equip.abil.level = level_u8;
            sg.state.wabil.level = level_u8;
            sg.state.wabil.mc = caster_mc;
            sg.state.wabil.sc = caster_sc;
        }
        {
            let t = fireball_actor(&rig, "target");
            let e = rig.world.entities.get_mut(t).unwrap();
            e.vitals.anti_magic = anti_magic;
        }
        // B5 配置：安全区门 + 红字颜色（一律取 golden 的记录值）。
        {
            let mut cfg = rig.world.b5_cfg;
            cfg.disable_in_safe_zone_fire_cross = safe_zone;
            cfg.red_msg_f_color = u8::try_from(red_f).expect("red_msg_f_color 越界");
            cfg.red_msg_b_color = u8::try_from(red_b).expect("red_msg_b_color 越界");
            rig.world.set_b5_config(cfg);
        }
        // 预置事件（oracle ctor + AddMapEvent：只落格子；**不进** EventMgr）。
        let map_id = rig.world.entities.get(rig.caster).unwrap().map_id;
        for (x, y) in &pre_cells {
            rig.world
                .add_fire_burn_event(rig.caster, map_id, *x, *y, 0, 1);
        }
        let pre_count = rig.world.sim.fire_burn_events.len();
        assert_eq!(
            pre_count,
            pre_cells.len(),
            "[{stem}/{label}] 预置事件条数必须等于 Fixture.pre_event_cells"
        );
        rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(seed);
        let target = fireball_actor(&rig, "target");
        let hp_before = i64::from(rig.world.entities.get(target).unwrap().hp);
        let (level_before, tp_before) = skill_tail_rcd(&rig, magic_id);
        let n0 = trace_line_count(&trace);
        // **MG-36 ①（2026-11-26）**：tick 臂的绝对钟基数在**施法之前**落到 world——
        // oracle 在 `ClockSeam.Begin(1000000)` 下建事件 ⇒ `RunStart = GetTickCount() = 1000000`。
        if let Some(cast_ms) = fx["fire_cast_ms"].as_i64() {
            rig.world.clock_ms = cast_ms;
        }
        rig.cast(magic_id, (101, 100), target);
        // **MG-36 ②（2026-11-26）**：`RunTick` 是 oracle `MapEvent` ctor 的常量 500（`MapEvent.cs:76`）；
        // 行为面已由 `tick_boundaries` 的 `+500/+501` 整点钉住，这里再钉字段面：全部事件 `run_tick_ms == 500`。
        assert!(
            rig.world
                .fire_burn_events
                .iter()
                .all(|e| e.run_tick_ms == 500),
            "[firecross/{label}] 所有火墙事件 RunTick 必须 = 500（oracle ctor 常量）"
        );
        let n1 = trace_line_count(&trace);
        let (cast_frames, _raws) = rig.drain();
        let mut all_frames: Vec<(i32, Vec<u8>, i64)> =
            cast_frames.into_iter().map(|(s, b)| (s, b, 0i64)).collect();
        let wait_ms = golden_wait_ms(stem, label);
        let mut elapsed: u64 = 0;
        while elapsed < wait_ms {
            rig.world.clock_ms += 100;
            elapsed += 100;
            let outs = rig.world.deliver_self_delay_msgs();
            if outs.is_empty() {
                continue;
            }
            let rec = mir2_world_bevy::TickRecord {
                slave_self_deliveries: outs.clone(),
                ..Default::default()
            };
            drain_b4_self_deliveries(
                &rec,
                &mut rig.world,
                &rig.online,
                &mut rig.displays,
                &mut rig.ground_sessions,
                &rig.gates,
                0,
                0,
                b"",
            );
            drain_b3_self_deliveries(
                &rec,
                &rig.world,
                &rig.online,
                &mut rig.ground_sessions,
                &rig.gates,
            );
            let (mut step_frames, _raws2) = rig.drain();
            for f in step_frames.drain(..) {
                all_frames.push((f.0, f.1, elapsed as i64));
            }
        }
        let n2 = trace_line_count(&trace);
        let cast_rng = trace_slice(&trace, n0, n1);
        let deliver_rng = trace_slice(&trace, n1, n2);
        let (level_after, tp_after) = skill_tail_rcd(&rig, magic_id);
        let hp_after = i64::from(rig.world.entities.get(target).unwrap().hp);
        // ---- 事件快照（只取本 case 新增的；排除预置）----
        let mut events: Vec<serde_json::Value> = rig
            .world
            .sim
            .fire_burn_events
            .iter()
            .skip(pre_count)
            .filter(|e| e.map_id == map_id)
            .map(|e| {
                serde_json::json!({
                    "x": e.x,
                    "y": e.y,
                    "type": e.event_type,
                    "damage": e.damage,
                    "continue_ms": e.continue_ms,
                })
            })
            .collect();
        events.sort_by_key(|e| (e["x"].as_i64().unwrap_or(0), e["y"].as_i64().unwrap_or(0)));
        // **退化守卫（S 序列同款）**：非安全区支必须至少产生 1 条事件；0 条即具名红。
        let expected_events = if safe_zone { 0 } else { 5 - pre_cells.len() };
        // ---- RM 列（装配；与 oracle `SendRefMsg`/`SendMsg` 参数逐项对应）----
        let spell_rm = fireball_rm(
            10008,
            i64::from(effect),
            101,
            100,
            i64::from(magic_id),
            24,
            false,
        );
        let fire_rm = fireball_rm(
            10120,
            0,
            i64::from(effect_type) | (i64::from(effect) << 8),
            101 | (100 << 16),
            i64::from(target),
            136,
            false,
        );
        let sys_rm = fireball_rm(11004, 0, i64::from(red_f), i64::from(red_b), 0, 252, false);
        let lvexp_rm = fireball_rm(
            10123,
            0,
            i64::from(magic_id),
            i64::from(level_after),
            i64::from(tp_after),
            255,
            true,
        );
        let has_640 = all_frames
            .iter()
            .filter(|(s, _, _)| *s == 911)
            .filter(|(_, b, _)| sf_ident(b) == mir2_protocol::messages::SM_MAGIC_LVEXP)
            .count()
            == 1;
        let red_sysmsg = all_frames
            .iter()
            .filter(|(s, _, _)| *s == 911)
            .filter(|(_, b, _)| sf_ident(b) == mir2_protocol::messages::SM_SYSMESSAGE)
            .count()
            == 1;
        let rm_of = |who: &str| -> Vec<serde_json::Value> {
            match who {
                "caster" => {
                    let mut v = vec![spell_rm.clone(), fire_rm.clone()];
                    if safe_zone {
                        v.push(sys_rm.clone());
                    } else {
                        v.push(lvexp_rm.clone());
                    }
                    v
                }
                "target" | "obs_in" => vec![spell_rm.clone(), fire_rm.clone()],
                _ => Vec::new(),
            }
        };
        let mut receivers: Vec<serde_json::Value> = Vec::new();
        for (who, socket) in [
            ("caster", 911),
            ("target", 912),
            ("obs_in", 913),
            ("obs_out", 914),
        ] {
            receivers.push(serde_json::json!({
                "Who": who,
                "Rm": rm_of(who),
                "Sent": fireball_sent_with_due(&all_frames, socket),
            }));
        }
        let mi = rig.magic_table.get(magic_id).expect("魔表必须有该魔号");
        let n_level = skill_tail_n_level(level_after, mi.train_lv);
        let mt_used = mi.max_train.get(n_level).copied().unwrap_or(0);
        let train = serde_json::json!({
            "level_before": level_before,
            "level_after": level_after,
            "tran_point_before": tp_before,
            "tran_point_after": tp_after,
            "train_lv": mi.train_lv,
            "max_train0": mi.max_train.first().copied().unwrap_or(0),
            "n_level": n_level,
            "max_train_at_level": mt_used,
            "train_level_at_level": mi.train_level[n_level],
        });
        // **MG-36 ①（2026-11-26）**：tick 臂在**帧/台账采集之后**跑（避免推进钟让延迟消息提前到期、
        // 污染交付段抽数）。基数 = **事件登记时刻**（`Fixture.fire_cast_ms`，oracle `ClockSeam` 绝对值），
        // **不是**此处的 `rig.world.clock_ms`——排水步进已把钟推到 `+1200`，拿它当基数会让 `+500`
        // 的 `RunTick` 整点门整体错位（repro 原文见交接 §21.1）。
        // 期望（解析硬写，不读 golden、不读 C#）：`RunTick=500` 的 `+500` 不跑、`+501` 跑；
        // `FireRunTick` 的 `+3501` 距上次结算**恰 3000**（不 > 3000）不结算、`+4002` 结算
        // ⇒ 累计 = [0, 1, 1, 1, 2]。
        if let Some(deltas) = fx["fire_ticks_ms"].as_array() {
            let t0 = fx["fire_cast_ms"]
                .as_i64()
                .unwrap_or_else(|| panic!("[{stem}/{label}] golden 必须记录 fire_cast_ms"));
            let mut cum = Vec::new();
            for d in deltas {
                let delta = d.as_i64().expect("fire_ticks_ms 必须是整数");
                rig.world.clock_ms = t0 + delta;
                rig.world.run_map_events();
                cum.push(i64::try_from(rig.world.pending_mag_struck.len()).unwrap());
            }
            assert_eq!(
                cum,
                vec![0, 1, 1, 1, 2],
                "[firecross/{label}] tick 累计 struck 必须 = [0,1,1,1,2]（RunTick 500 / Fire 3000 两门整点）"
            );
        }

        let firecross_block = serde_json::json!({
            "events": events,
            "pre_event_cells": pre_cells
                .iter()
                .map(|(x, y)| serde_json::json!([x, y]))
                .collect::<Vec<_>>(),
            "safe_zone_flag": safe_zone,
            "disable_in_safe_zone_fire_cross": safe_zone,
            "in_safe_zone_at_cast": safe_zone,
            "red_sysmsg": red_sysmsg,
            "red_sysmsg_text": "",
            "has_640": has_640,
        });
        let ledger = serde_json::json!([{
            "Label": label,
            "Seed": seed,
            "SpellReturn": true,
            "Receivers": receivers,
            "Rng": cast_rng.iter().map(|(_, r, _)| *r).collect::<Vec<_>>(),
            "RngSites": cast_rng.iter().map(|(_, _, st)| st.replace(std::path::MAIN_SEPARATOR, "/")).collect::<Vec<_>>(),
            "RngSeqs": cast_rng.iter().map(|(sq, _, _)| *sq).collect::<Vec<_>>(),
            "DeliverRng": deliver_rng.iter().map(|(_, r, _)| *r).collect::<Vec<_>>(),
            "DeliverRngSites": deliver_rng.iter().map(|(_, _, st)| st.replace(std::path::MAIN_SEPARATOR, "/")).collect::<Vec<_>>(),
            "DeliverRngSeqs": deliver_rng.iter().map(|(sq, _, _)| *sq).collect::<Vec<_>>(),
            "TargetHpBefore": hp_before,
            "TargetHp": hp_after,
            "Train": train,
            "FireCross": firecross_block,
        }]);
        let out = dir.join(format!("{stem}_{label}.json"));
        std::fs::write(&out, serde_json::to_string_pretty(&ledger).unwrap()).expect("台账必须可写");
        write_run_sidecar(&out, &run_id, seed);
        // ---- 断言（落盘后；红了也留台账）----
        // **事件退化守卫（S 序列同款）**：非安全区支必须至少产生 1 条事件；0 条即具名红。
        assert_eq!(
            events.len(),
            expected_events,
            "[{stem}/{label}] 火墙事件数 {}/{expected_events}（预占 {}，safe={safe_zone}）",
            events.len(),
            pre_cells.len()
        );
        if expected_events > 0 {
            assert!(
                !events.is_empty(),
                "[{stem}/{label}] 本 case 未产生任何火墙事件（退化：五格登记一次都没执行）"
            );
        }
        let expected_draws = if safe_zone { 6 } else { 7 };
        assert_eq!(
            cast_rng.len(),
            expected_draws,
            "[{stem}/{label}] 应恰 {expected_draws} 抽（安全区支无训练尾）；实得 {:?}",
            cast_rng.iter().map(|(_, v, _)| *v).collect::<Vec<_>>()
        );
        assert!(
            deliver_rng.is_empty(),
            "[{stem}/{label}] 交付段不应有抽取；实得 {:?}",
            deliver_rng
        );
        if !safe_zone {
            assert_eq!(
                i64::from(tp_after),
                i64::from(tp_before) + cast_rng[6].1 + 1,
                "[{stem}/{label}] 训练尾抽值必须等于 TranPoint 增量 − 1"
            );
        } else {
            assert_eq!(tp_after, tp_before, "[{stem}/{label}] 安全区支不得训练");
        }
        assert_eq!(
            has_640, !safe_zone,
            "[{stem}/{label}] has_640 必须等于「非安全区」"
        );
        assert_eq!(
            red_sysmsg, safe_zone,
            "[{stem}/{label}] red_sysmsg 必须等于「安全区」"
        );
        let idents = |socket: i32| -> Vec<u16> {
            all_frames
                .iter()
                .filter(|(s, _, _)| *s == socket)
                .map(|(_, b, _)| sf_ident(b))
                .collect()
        };
        let want_caster = if safe_zone {
            vec![
                mir2_protocol::messages::SM_MAGICFIRE,
                mir2_protocol::messages::SM_SYSMESSAGE,
            ]
        } else {
            vec![
                mir2_protocol::messages::SM_MAGICFIRE,
                mir2_protocol::messages::SM_MAGIC_LVEXP,
            ]
        };
        assert_eq!(idents(911), want_caster, "[{stem}/{label}] caster 帧序");
        for socket in [912, 913] {
            assert_eq!(
                idents(socket),
                vec![
                    mir2_protocol::messages::SM_SPELL,
                    mir2_protocol::messages::SM_MAGICFIRE,
                ],
                "[{stem}/{label}] socket {socket} 帧序应为 [17,638]"
            );
        }
        assert!(idents(914).is_empty(), "[{stem}/{label}] obs_out 必须零帧");
        eprintln!(
            "[{stem} {label}] seed={seed} safe={safe_zone} pre={} events={} rng={:?}",
            pre_cells.len(),
            expected_events,
            cast_rng.iter().map(|(_, v, _)| *v).collect::<Vec<_>>()
        );
    }

    #[test]
    #[ignore = "真实台账驱动：需 --exact --test-threads=1 单独进程"]
    fn firecross_parity_base() {
        firecross_parity_drive("base");
    }

    #[test]
    #[ignore = "真实台账驱动：需 --exact --test-threads=1 单独进程"]
    fn firecross_parity_tick_boundaries() {
        firecross_parity_drive("tick_boundaries");
    }

    #[test]
    #[ignore = "真实台账驱动：需 --exact --test-threads=1 单独进程"]
    fn firecross_parity_pre_center() {
        firecross_parity_drive("pre_center");
    }

    #[test]
    #[ignore = "真实台账驱动：需 --exact --test-threads=1 单独进程"]
    fn firecross_parity_safe_zone() {
        firecross_parity_drive("safe_zone");
    }

    /// **MG-34（20 诱惑之光）**真实台账驱动：七支（`self_master`/`adopt_ok`/`level_gate_fail`/
    /// `branch_else`/`outer_fail_true`/`outer_fail_false`/`crazy`）。
    ///
    /// 输入全从 golden `Fixture` 读；配置四键（`mag_tamming_*`）从 `Fixture.server_conf` 构造
    /// `PetSlaveConfig`（**不落 World**）。观测：60005 待投递、8090/8101 待投递 + 宿主帧、
    /// caster SlaveList、怪物术后面、Rng。
    /// **不建模/不比较**：`CanReAlive` 清除后效、`MonGen.ActiveCount--`（golden 记录，Rust 无字段）。
    fn tamming_parity_drive(label: &str) {
        std::env::set_var("MIR2_CLIENT_ABILITY_LAYOUT", "0");
        let stem = "tamming";
        let dir = magic_ledger_dir();
        std::fs::create_dir_all(&dir).expect("台账目录必须可建");
        let run_id = ledger_run_id();
        let seed = golden_seed(stem, label);
        let trace = dir.join(format!("{stem}_{label}_seed{seed}.rng.tsv"));
        assert!(
            !mir2_shared::rng_trace::enabled(),
            "rng_trace 已被本进程其它路径开启 ⇒ 请 --exact 单跑"
        );
        let _ = std::fs::remove_file(&trace);
        mir2_shared::rng_trace::enable(&trace, seed).expect("打开 rng trace");
        assert_eq!(trace_header_seed(&trace), seed, "trace 头部 seed");

        let magic_id = golden_fixture_required(stem, label, "magic_id");
        let effect = golden_fixture_required(stem, label, "effect");
        let effect_type = golden_fixture_required(stem, label, "effect_type");
        let user_magic_level = golden_fixture_required(stem, label, "user_magic_level");
        let caster_level = golden_fixture_required(stem, label, "caster_level");
        let caster_mc = golden_fixture_required(stem, label, "caster_mc");
        let caster_sc = golden_fixture_required(stem, label, "caster_sc");
        let caster_actor_id = golden_fixture_required(stem, label, "caster_actor_id");
        let fx = golden_case_for(stem, label)["Fixture"].clone();
        let mon = &fx["monsters"][0];
        let mon_x = i32::try_from(mon["x"].as_i64().expect("x")).expect("x i32");
        let mon_y = i32::try_from(mon["y"].as_i64().expect("y")).expect("y i32");
        let mon_race = u8::try_from(mon["race"].as_u64().expect("race")).expect("race u8");
        let mon_level = u8::try_from(mon["level"].as_u64().expect("level")).expect("level u8");
        let mon_hp = u16::try_from(mon["hp"].as_u64().expect("hp")).expect("hp u16");
        let mon_life =
            u8::try_from(mon["life_attrib"].as_u64().expect("life_attrib")).expect("life u8");
        let mon_walk = mon["walk_speed"].as_i64().expect("walk_speed");
        let mon_next_hit = mon["next_hit_time"].as_i64().expect("next_hit_time");
        let master_caster = mon["master_caster"].as_bool().expect("master_caster");
        let mon_name = mon["name"].as_str().expect("monster.name").to_string();
        let caster_name = fx["caster_name"]
            .as_str()
            .expect("Fixture.caster_name")
            .to_string();
        let slave_colors: Vec<u8> = fx["slave_colors"]
            .as_array()
            .expect("Fixture.slave_colors")
            .iter()
            .map(|b| u8::try_from(b.as_u64().expect("slave color")).expect("u8"))
            .collect();
        // 配置四键：只从 golden `server_conf` 构造 `PetSlaveConfig`（不落 World）。
        let sc = fx["server_conf"].as_object().expect("server_conf");
        let cfg_i32 = |k: &str| -> i32 {
            i32::try_from(
                sc.get(k)
                    .and_then(serde_json::Value::as_i64)
                    .unwrap_or_else(|| panic!("[{stem}/{label}] server_conf 缺 {k}")),
            )
            .expect("server_conf i32")
        };
        let mut cfg = mir2_data::pet_slave::PetSlaveConfig {
            mag_tamming_level: cfg_i32("mag_tamming_level"),
            mag_tamming_target_level: cfg_i32("mag_tamming_target_level"),
            mag_tamming_hp_rate: cfg_i32("mag_tamming_hp_rate"),
            mag_tamming_count: u8::try_from(cfg_i32("mag_tamming_count"))
                .expect("mag_tamming_count u8"),
            ..Default::default()
        };
        for (i, c) in slave_colors.iter().enumerate().take(cfg.slave_color.len()) {
            cfg.slave_color[i] = *c;
        }

        let level_u8 = u8::try_from(caster_level).expect("caster_level 越界");
        let id_base = i32::from(caster_actor_id) - 1;
        let mut rig = SpellFrameRig::new_layout(
            200,
            200,
            id_base,
            100,
            100,
            magic_id,
            &[(
                magic_id,
                u8::try_from(user_magic_level).expect("user_magic_level 越界"),
            )],
            &[
                ("target", 101, 100, false, 912),
                ("obs_in", 105, 100, false, 913),
                ("obs_out", 140, 100, false, 914),
            ],
        );
        rig.magic_table = magics::MagicTable::new(vec![mir2_data::MagicInfo {
            magic_id,
            effect: u8::try_from(effect).expect("effect"),
            effect_type: u8::try_from(effect_type).expect("effect_type"),
            ..mir2_data::MagicInfo::default()
        }]);
        {
            let list = rig
                .saves
                .get_mut("caster")
                .and_then(|s| s.record.data.magic.as_mut())
                .expect("caster 魔表");
            let m = list
                .iter_mut()
                .flatten()
                .find(|m| m.mag_idx == magic_id)
                .expect("魔号必须存在");
            m.level = u8::try_from(user_magic_level).expect("level");
            m.tran_point = 0;
        }
        {
            let mut e = rig.world.entities.get_mut(rig.caster).unwrap();
            // `GetShowName` 的主人名取 golden 的真名（`golden-caster`）。
            e.name = caster_name;
            e.progression.level = level_u8;
            e.vitals.hp = 500;
            e.vitals.max_hp = 500;
        }
        {
            let sg = rig.ground_sessions.get_mut("caster").unwrap();
            sg.equip.abil.level = level_u8;
            sg.state.wabil.level = level_u8;
            sg.state.wabil.mc = caster_mc;
            sg.state.wabil.sc = caster_sc;
        }
        // 怪物实体：id = id_base+10（与 C# 装置 `idBase+10` 同段）。
        let mon_id = {
            let mut e = mir2_world_bevy::EntitySpawn::new(0, mon_name.clone(), mon_x, mon_y);
            e.id = id_base + 10;
            e.race = mon_race;
            e.level = mon_level;
            e.hp = mon_hp;
            e.max_hp = mon_hp;
            e.life_attrib = mon_life;
            let id = rig.world.add_entity(e);
            {
                let m = rig.world.entities.get_mut(id).unwrap();
                m.ai.walk_speed = mon_walk;
                m.ai.next_hit_time = mon_next_hit;
                if master_caster {
                    m.slave.master = Some(rig.caster);
                }
            }
            id
        };
        rig.world.tick();
        rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(seed);
        let (level_before, tp_before) = skill_tail_rcd(&rig, magic_id);
        let player_target = fireball_actor(&rig, "target");
        let hp_before = i64::from(rig.world.entities.get(player_target).unwrap().hp);
        let n0 = trace_line_count(&trace);
        rig.cast(magic_id, (mon_x, mon_y), mon_id);
        let n1 = trace_line_count(&trace);
        let (cast_frames, _raws) = rig.drain();
        let mut all_frames: Vec<(i32, Vec<u8>, i64)> =
            cast_frames.into_iter().map(|(s, b)| (s, b, 0i64)).collect();
        // 怪物 Ref 帧（656/42）：先快照待办，再走宿主 drain（产生真实帧）。
        let ref_snapshot: Vec<(u16, Vec<i32>)> = rig
            .world
            .pending_monster_ref_msgs
            .iter()
            .map(|m| (m.ident, m.recipients.clone()))
            .collect();
        let holy: Vec<i32> = rig
            .world
            .self_delay_msgs
            .iter()
            .filter(|m| {
                m.actor_id == mon_id && m.ident == mir2_world_bevy::slave::RM_MAKEHOLYSEIZEMODE
            })
            .map(|m| m.w_param)
            .collect();
        drain_monster_ref_msgs(&mut rig.world, &rig.displays, &rig.online, &rig.gates, &cfg);
        let (mut ref_frames, _raws3) = rig.drain();
        for f in ref_frames.drain(..) {
            all_frames.push((f.0, f.1, 0i64));
        }
        let wait_ms = golden_wait_ms(stem, label);
        let mut elapsed: u64 = 0;
        while elapsed < wait_ms {
            rig.world.clock_ms += 100;
            elapsed += 100;
            let mut outs = rig.world.deliver_self_delay_msgs();
            // **装置口径**：oracle `RecordingMonster` 被动、不 `Operate` ⇒ 60005 不被处理；
            // 这里同样丢弃该投递（Rng/帧面均不入账），避免驱动凭空产出 656。
            outs.retain(|m| m.ident != mir2_world_bevy::slave::RM_MAKEHOLYSEIZEMODE);
            if outs.is_empty() {
                continue;
            }
            let rec = mir2_world_bevy::TickRecord {
                slave_self_deliveries: outs.clone(),
                ..Default::default()
            };
            drain_b4_self_deliveries(
                &rec,
                &mut rig.world,
                &rig.online,
                &mut rig.displays,
                &mut rig.ground_sessions,
                &rig.gates,
                0,
                0,
                b"",
            );
            drain_b3_self_deliveries(
                &rec,
                &rig.world,
                &rig.online,
                &mut rig.ground_sessions,
                &rig.gates,
            );
            let (mut step_frames, _raws2) = rig.drain();
            for f in step_frames.drain(..) {
                all_frames.push((f.0, f.1, elapsed as i64));
            }
        }
        let n2 = trace_line_count(&trace);
        let cast_rng = trace_slice(&trace, n0, n1);
        let deliver_rng = trace_slice(&trace, n1, n2);
        let (level_after, tp_after) = skill_tail_rcd(&rig, magic_id);
        let hp_after = i64::from(rig.world.entities.get(player_target).unwrap().hp);
        let has_640 = all_frames
            .iter()
            .filter(|(s, _, _)| *s == 911)
            .filter(|(_, b, _)| sf_ident(b) == mir2_protocol::messages::SM_MAGIC_LVEXP)
            .count()
            == 1;
        // ---- RM 列（装配；60005/8090/8101 来自**实际待办**）----
        let spell_rm = fireball_rm(
            10008,
            i64::from(effect),
            i64::from(mon_x),
            i64::from(mon_y),
            i64::from(magic_id),
            24,
            false,
        );
        let fire_rm = fireball_rm(
            10120,
            0,
            i64::from(effect_type) | (i64::from(effect) << 8),
            i64::from(mon_x) | (i64::from(mon_y) << 16),
            i64::from(mon_id),
            136,
            false,
        );
        let lvexp_rm = fireball_rm(
            10123,
            0,
            i64::from(magic_id),
            i64::from(level_after),
            i64::from(tp_after),
            255,
            true,
        );
        let ref_rm =
            |ident: u16| fireball_rm(i64::from(ident), 0, 0, 0, 0, i64::from(ident & 0xFF), false);
        let rm_of = |who: &str| -> Vec<serde_json::Value> {
            match who {
                "caster" | "target" | "obs_in" => {
                    let actor_id = match who {
                        "caster" => rig.caster,
                        "target" => fireball_actor(&rig, "target"),
                        _ => fireball_actor(&rig, "obs_in"),
                    };
                    let mut v = vec![spell_rm.clone(), fire_rm.clone()];
                    if who == "caster" && has_640 {
                        v.push(lvexp_rm.clone());
                    }
                    for (ident, recipients) in &ref_snapshot {
                        if recipients.contains(&actor_id) {
                            v.push(ref_rm(*ident));
                        }
                    }
                    v
                }
                "mon0" => holy
                    .iter()
                    .map(|w| fireball_rm(60005, i64::from(*w), 0, 0, 0, 101, false))
                    .collect(),
                _ => Vec::new(),
            }
        };
        let mut receivers: Vec<serde_json::Value> = Vec::new();
        for (who, socket) in [
            ("caster", 911),
            ("target", 912),
            ("obs_in", 913),
            ("obs_out", 914),
        ] {
            receivers.push(serde_json::json!({
                "Who": who,
                "Rm": rm_of(who),
                "Sent": fireball_sent_with_due(&all_frames, socket),
            }));
        }
        let (master, walk_speed, next_hit_time, slave_make_level, crazy_mode, crazy_interval) = {
            let e = rig.world.entities.get(mon_id).unwrap();
            let master = match e.master {
                Some(id) if id == rig.caster => serde_json::Value::String("caster".into()),
                Some(_) => serde_json::Value::String("other".into()),
                None => serde_json::Value::Null,
            };
            (
                master,
                e.ai.walk_speed,
                e.ai.next_hit_time,
                e.slave_make_level,
                e.ai.crazy_mode,
                e.ai.crazy_mode_interval,
            )
        };
        let mon_hp_after = i64::from(rig.world.entities.get(mon_id).unwrap().hp);
        let slave_ids: Vec<i32> = rig
            .world
            .entities
            .get(rig.caster)
            .map(|e| e.slave_list.clone())
            .unwrap_or_default();
        let slave_rel: Vec<i64> = slave_ids
            .iter()
            .map(|id| if *id == mon_id { 0 } else { -1 })
            .collect();
        receivers.push(serde_json::json!({
            "Who": "mon0",
            "Rm": rm_of("mon0"),
            "Sent": Vec::<serde_json::Value>::new(),
        }));
        let mi = rig.magic_table.get(magic_id).expect("魔表");
        let n_level = skill_tail_n_level(level_after, mi.train_lv);
        let mt_used = mi.max_train.get(n_level).copied().unwrap_or(0);
        let train = serde_json::json!({
            "level_before": level_before,
            "level_after": level_after,
            "tran_point_before": tp_before,
            "tran_point_after": tp_after,
            "train_lv": mi.train_lv,
            "max_train0": mi.max_train.first().copied().unwrap_or(0),
            "n_level": n_level,
            "max_train_at_level": mt_used,
            "train_level_at_level": mi.train_level[n_level],
        });
        let tamming_block = serde_json::json!({
            "spell_return": true,
            "has_640": has_640,
            "rm_makeholyseize": holy.iter().map(|w| serde_json::json!({"who": "mon0", "w_param": w})).collect::<Vec<_>>(),
            "slave_list_rel": slave_rel,
            "slave_count_after": slave_ids.len(),
            "monsters_after": [{
                "name": mon_name,
                "master": master,
                "hp": mon_hp_after,
                "max_hp": i64::from(mon_hp),
                "walk_speed": walk_speed,
                "next_hit_time": next_hit_time,
                "slave_make_level": i64::from(slave_make_level),
                "crazy_mode": crazy_mode,
                "crazy_interval_ms": crazy_interval,
            }],
        });
        let ledger = serde_json::json!([{
            "Label": label,
            "Seed": seed,
            "SpellReturn": true,
            "Receivers": receivers,
            "Rng": cast_rng.iter().map(|(_, r, _)| *r).collect::<Vec<_>>(),
            "RngSites": cast_rng.iter().map(|(_, _, st)| st.replace(std::path::MAIN_SEPARATOR, "/")).collect::<Vec<_>>(),
            "RngSeqs": cast_rng.iter().map(|(sq, _, _)| *sq).collect::<Vec<_>>(),
            "DeliverRng": deliver_rng.iter().map(|(_, r, _)| *r).collect::<Vec<_>>(),
            "DeliverRngSites": deliver_rng.iter().map(|(_, _, st)| st.replace(std::path::MAIN_SEPARATOR, "/")).collect::<Vec<_>>(),
            "DeliverRngSeqs": deliver_rng.iter().map(|(sq, _, _)| *sq).collect::<Vec<_>>(),
            "TargetHpBefore": hp_before,
            "TargetHp": hp_after,
            "Train": train,
            "Tamming": tamming_block,
        }]);
        let out = dir.join(format!("{stem}_{label}.json"));
        std::fs::write(&out, serde_json::to_string_pretty(&ledger).unwrap()).expect("台账可写");
        write_run_sidecar(&out, &run_id, seed);
        // ---- 断言（落盘后）----
        assert!(
            deliver_rng.is_empty(),
            "[{stem}/{label}] 交付段不应有抽取；实得 {:?}",
            deliver_rng
        );
        eprintln!(
            "[{stem} {label}] seed={seed} holy={:?} refs={:?} slave={:?} frames={:?}",
            holy,
            ref_snapshot.iter().map(|(i, _)| *i).collect::<Vec<_>>(),
            slave_rel,
            all_frames
                .iter()
                .map(|(s, b, _)| (*s, sf_ident(b)))
                .collect::<Vec<_>>()
        );
    }

