    fn snowwind_assert(stem: &str, label: &str, seed: i32, base: i32) {
        fireball_parity_drive(stem, 33, 1, label, seed, base);
        fireball_case_assert(stem, label);
        b1_golden_drain_assert("snowwind.json", label, 2);
        let c = defence_case(stem, label);
        let n = |who: &str, field: &str, ident: i64| healing_count(&c, who, field, ident);
        let seq_of = |who: &str| -> Vec<i64> {
            c["Receivers"]
                .as_array()
                .unwrap()
                .iter()
                .find(|r| r["Who"] == who)
                .unwrap()["Sent"]
                .as_array()
                .unwrap()
                .iter()
                .filter_map(|m| m["ident"].as_i64())
                .collect()
        };
        // **时间忠实序**（`StepDrainMs=100`）：31/656 在 600ms 交付批、640 在 1000ms
        // ⇒ 640 在末位（旧 golden 的 `[638,640,31,656]` 是「一次排空」的 per-actor pass 伪影）。
        assert_eq!(
            seq_of("caster"),
            vec![638, 31, 656, 640],
            "[{stem}/{label}] caster 帧序"
        );
        assert_eq!(
            seq_of("target"),
            vec![17, 638, 53, 31, 656],
            "[{stem}/{label}] target 帧序"
        );
        assert_eq!(
            seq_of("obs_in"),
            vec![17, 638, 31, 656],
            "[{stem}/{label}] obs_in 帧序"
        );
        assert_eq!(
            n("obs_out", "Sent", 31),
            0,
            "[{stem}/{label}] obs_out 不得有帧"
        );
        // **期望一律取自 golden**（§22：不写死数值）。s5/s13 的伤害随 MC 区间分叉后，
        // 旧的常量 85 会把**正确**的输出判红；而且它从未真正验过"Rust HP == golden"。
        // 同族教训：cloak/big_cloak 的 `(0,0,0)` 也是这类过期硬编码。
        let g = golden_case_for(stem, label);
        assert_eq!(
            c["TargetHpBefore"].as_i64(),
            g["Fixture"]["target_hp"].as_i64(),
            "[{stem}/{label}] HP 前须等于 golden Fixture.target_hp"
        );
        assert_eq!(
            c["TargetHp"].as_i64(),
            g["TargetHp"].as_i64(),
            "[{stem}/{label}] 术后 HP 须等于 golden TargetHp"
        );
        assert_eq!(n("target", "Rm", 8044), 1, "[{stem}/{label}] target 8044");
        assert_eq!(n("target", "Rm", 10052), 1, "[{stem}/{label}] target 10052");
        for who in ["caster", "target", "obs_in"] {
            assert_eq!(n(who, "Rm", 8103), 1, "[{stem}/{label}] {who} 8103");
            assert_eq!(n(who, "Rm", 8090), 1, "[{stem}/{label}] {who} 8090");
        }
        assert_eq!(n("caster", "Rm", 10123), 1, "[{stem}/{label}] caster 10123");
        // 魔号语义（oracle 分派）：RM 10008 的 p3 与 10123 的 p1 必须是 **33**。
        let p3_of_10008 = |who: &str| -> Option<i64> {
            c["Receivers"]
                .as_array()
                .unwrap()
                .iter()
                .find(|r| r["Who"] == who)
                .unwrap()["Rm"]
                .as_array()
                .unwrap()
                .iter()
                .find(|m| m["ident"] == 10008)
                .and_then(|m| m["p3"].as_i64())
        };
        assert_eq!(
            p3_of_10008("caster"),
            Some(33),
            "[{stem}/{label}] RM 10008.p3 = 魔号 33"
        );
        let p1_of_10123 = |who: &str| -> Option<i64> {
            c["Receivers"]
                .as_array()
                .unwrap()
                .iter()
                .find(|r| r["Who"] == who)
                .unwrap()["Rm"]
                .as_array()
                .unwrap()
                .iter()
                .find(|m| m["ident"] == 10123)
                .and_then(|m| m["p1"].as_i64())
        };
        assert_eq!(
            p1_of_10123("caster"),
            Some(33),
            "[{stem}/{label}] RM 10123.p1 = 魔号 33"
        );
    }

