    fn rm_path_teeth_drain_spell_monster_sender_no_self() {
        let mut world = mir2_world_bevy::World::new(64, 64);
        let mut p = mir2_world_bevy::EntitySpawn::new(0, "P".to_string(), 10, 10);
        p.race = mir2_world_bevy::ACTOR_RACE_PLAY;
        let pid = world.add_entity(p);
        let mut m = mir2_world_bevy::EntitySpawn::new(0, "火球怪".to_string(), 20, 20);
        m.race = 101;
        let mid = world.add_entity(m);
        world.tick();

        let (tx, mut rx) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx);
        let online: OnlineRegistry = OnlineRegistry::from(vec![OnlineEntry {
            account: "a".to_string(),
            chr_name: "P".to_string(),
            session_id: 1,
            gate_idx: 0,
            socket: 5,
            actor_id: pid,
        }]);
        let displays = downlink::DisplayTable::new();
        let pet_cfg = mir2_data::pet_slave::PetSlaveConfig::default();

        world
            .pending_monster_ref_msgs
            .push(mir2_world_bevy::MonsterRefMsg {
                actor_id: mid,
                ident: mir2_world_bevy::monai::RM_SPELL,
                w_param: 48,
                n_param1: 20,
                n_param2: 20,
                n_param3: 0,
                target_x: 0,
                target_y: 0,
                dir: 0,
                x: 20,
                y: 20,
                map_id: 0,
                status: 0,
                self_only: false,
                recipients: vec![pid],
            });
        drain_monster_ref_msgs(&mut world, &displays, &online, &gates, &pet_cfg);
        let mut n = 0usize;
        while let Ok(ev) = rx.try_recv() {
            if let SimToGate::SendFrame { body, .. } = ev {
                if u16::from_le_bytes([body[4], body[5]]) == mir2_protocol::messages::SM_SPELL {
                    n += 1;
                }
            }
        }
        assert_eq!(n, 1, "怪物 sender 的 RM_SPELL：玩家收 1 条 SM_SPELL");
        assert!(
            !online.iter().any(|e| e.actor_id == mid),
            "sender 怪物不在 online ⇒ 不可能自帧"
        );
    }

