    /// **Lane 1（`openmir2-monster-attack-smhit`）**：怪普攻在**生产 tick 路径**上出
    /// `SM_HIT(14)`，并与同击的 `SM_STRUCK(31)` 保持 oracle 时序——`RM_HIT` 即时
    /// （`SendAttackMsg`），`RM_STRUCK` 走 `SendStruckDelayMsg(RM_REFMESSAGE, …, 200ms)`
    /// ⇒ 后者最早在**下一** tick 到点。
    ///
    /// 断言：① 视野内每个玩家各收 1 条 `SM_HIT`，界外玩家 0 条；② 12B 头逐字节
    /// （Recog=攻方 ActorId、Ident=14、Param=X、Tag=Y、Series=Dir、无尾）；③ tick1 不得有
    /// `SM_STRUCK`，tick2 才有且序在全部 `SM_HIT` 之后；④ 收件人 = {受击者, 观察者}。
    ///
    /// 牙：删 `attack_target` 尾部的 `send_ref_msg` ⇒ `SM_HIT` 计数 0；把 `Dir` 传成 0
    /// ⇒ Series 断言红；去掉 `RM_REFMESSAGE` 延迟层（或让 SM_STRUCK 在 tick1 出帧）
    /// ⇒ 「tick1 无 SM_STRUCK / 帧序」断言红。
    #[test]
    fn monster_attack_produces_sm_hit_then_struck_on_production_path() {
        let mut world = mir2_world_bevy::World::with_maps(vec![(64, 64)]);
        world.enable_monster_ai();
        // 本条测怪攻击 ⇒ SM_HIT 的出帧路径，不是跳步门 ⇒ interval=0 关掉门。
        world.set_process_monster_interval(0);
        world.enable_refmessage_delay();
        let mut m = mir2_world_bevy::EntitySpawn::new(0, "半兽人".to_string(), 10, 12);
        m.race = 60;
        m.hp = 60;
        m.max_hp = 60;
        m.dc = 10 | (10 << 8);
        m.ai.walk_speed = 0; // 放开走时钟门（不影响攻击门）
        m.ai.walk_tick = 0;
        m.ai.attack_tick = -10_000; // tick1 必到点
        m.ai.next_hit_time = 2_000;
        let mid = world.add_entity(m);
        let mut v = mir2_world_bevy::EntitySpawn::new(0, "victim".to_string(), 11, 12);
        v.hp = 100;
        v.max_hp = 100;
        let vid = world.add_entity(v);
        let mut o = mir2_world_bevy::EntitySpawn::new(0, "obs".to_string(), 13, 12);
        o.hp = 100;
        o.max_hp = 100;
        let oid = world.add_entity(o);
        let mut f = mir2_world_bevy::EntitySpawn::new(0, "far".to_string(), 40, 40);
        f.hp = 100;
        f.max_hp = 100;
        let _fid = world.add_entity(f);
        world.entities.get_mut(mid).unwrap().ai.target_creature = Some(vid);

        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let online: OnlineRegistry = OnlineRegistry::from(vec![
            OnlineEntry {
                account: "a".to_string(),
                chr_name: "victim".to_string(),
                session_id: 1,
                gate_idx: 0,
                socket: 5,
                actor_id: vid,
            },
            OnlineEntry {
                account: "b".to_string(),
                chr_name: "obs".to_string(),
                session_id: 2,
                gate_idx: 0,
                socket: 6,
                actor_id: oid,
            },
            OnlineEntry {
                account: "c".to_string(),
                chr_name: "far".to_string(),
                session_id: 3,
                gate_idx: 0,
                socket: 7,
                actor_id: _fid,
            },
        ]);
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            vid,
            downlink::ActorDisplay::new(4, 0, 0x1234, 0, 0x2, 255, b"victim".to_vec()),
        );
        let table =
            game_svr::mongen::MonsterTable::new(Vec::<mir2_data::models::MonsterInfo>::new());
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();

        fn take_frames(rx: &mut mpsc::UnboundedReceiver<SimToGate>) -> Vec<(i32, Vec<u8>)> {
            let mut out = Vec::new();
            while let Ok(ev) = rx.try_recv() {
                if let SimToGate::SendFrame { body, socket } = ev {
                    out.push((socket, body));
                }
            }
            out
        }

        // ---- tick1：怪攻击 ⇒ 立即出 SM_HIT（RM_REFMESSAGE 尚未到点）----
        let rec1 = tick_world_with_specials(
            &mut world,
            None,
            &table,
            None,
            &mut displays,
            &online,
            &gates,
            &mir2_data::pet_slave::PetSlaveConfig::default(),
        );
        let frames = take_frames(&mut rx0);
        let hits: Vec<_> = frames
            .iter()
            .filter(|(_, b)| u16::from_le_bytes([b[4], b[5]]) == mir2_protocol::messages::SM_HIT)
            .cloned()
            .collect();
        let colors: Vec<_> = frames
            .iter()
            .filter(|(_, b)| {
                u16::from_le_bytes([b[4], b[5]]) == mir2_protocol::messages::SM_CHANGENAMECOLOR
            })
            .cloned()
            .collect();
        assert_eq!(frames.len(), 4, "RM_HIT + 656 各两条，不得混入其它帧");
        assert_eq!(
            hits.len(),
            2,
            "受击者 + 观察者各 1 条 SM_HIT；界外玩家 0 条"
        );
        assert_eq!(colors.len(), 2, "同一出手臂另产两条 656");
        for (socket, body) in &colors {
            assert!(matches!(*socket, 5 | 6), "656 界外玩家不得收件");
            assert_eq!(body, &smframe::sm_changenamecolor(mid, 255));
        }
        let expect = smframe::sm_action_hit(
            mir2_protocol::messages::SM_HIT,
            mid,
            10,
            12,
            2, // `Direction.Right`（C# `Enums/Direction.cs:7`）
            &[],
        );
        assert_eq!(expect.len(), 12, "SM_HIT = 12B 头、无尾");
        let mut socks: Vec<i32> = hits.iter().map(|(s, _)| *s).collect();
        socks.sort_unstable();
        assert_eq!(socks, vec![5, 6], "收件人恰为受击者(5)与观察者(6)");
        for (_, body) in &hits {
            assert_eq!(body, &expect, "SM_HIT 逐字节 = smframe 口径");
            assert_eq!(&body[0..4], &mid.to_le_bytes(), "Recog = 攻方 ActorId");
            assert_eq!(
                u16::from_le_bytes([body[4], body[5]]),
                mir2_protocol::messages::SM_HIT,
                "Ident = 14"
            );
            assert_eq!(u16::from_le_bytes([body[6], body[7]]), 10, "Param = X");
            assert_eq!(u16::from_le_bytes([body[8], body[9]]), 12, "Tag = Y");
            assert_eq!(
                u16::from_le_bytes([body[10], body[11]]),
                2,
                "Series = Dir（Direction.Right）"
            );
        }
        // 同击的 SM_STRUCK 在 tick1 必须还没到点。
        drain_combat_downlink(&rec1, &mut world, &displays, &online, &mut sessions, &gates);
        let early = take_frames(&mut rx0);
        assert!(
            early.is_empty(),
            "tick1 不得出 SM_STRUCK（RM_REFMESSAGE 200ms 延迟层）"
        );

        // ---- tick2：延迟到点 ⇒ SM_STRUCK；tick2 不得再有 SM_HIT（攻击间隔门）----
        let rec2 = tick_world_with_specials(
            &mut world,
            None,
            &table,
            None,
            &mut displays,
            &online,
            &gates,
            &mir2_data::pet_slave::PetSlaveConfig::default(),
        );
        let tick2_frames = take_frames(&mut rx0);
        assert!(
            tick2_frames.is_empty(),
            "tick2 攻击间隔门未过 ⇒ 不得多出 SM_HIT（也不得有其它帧）"
        );
        drain_combat_downlink(&rec2, &mut world, &displays, &online, &mut sessions, &gates);
        let struck = take_frames(&mut rx0);
        assert_eq!(struck.len(), 2, "SM_STRUCK 发给受击者自身 + 观察者");
        let mut struck_socks: Vec<i32> = struck.iter().map(|(s, _)| *s).collect();
        struck_socks.sort_unstable();
        assert_eq!(struck_socks, vec![5, 6]);
        for (_, body) in &struck {
            assert_eq!(
                u16::from_le_bytes([body[4], body[5]]),
                mir2_protocol::messages::SM_STRUCK,
                "tick2 = SM_STRUCK"
            );
            assert_eq!(
                i32::from_le_bytes([body[0], body[1], body[2], body[3]]),
                vid,
                "SM_STRUCK Recog = 受击者"
            );
        }
    }

    /// **MB-2**：`RM_FLYAXE`/`RM_LIGHTING`/`RM_ALIVE` 的生产排水逐字节映射
    /// （`DualAxeMonster.cs:29` / `LightingZombi.cs:22` / `BaseObject.Base.cs:357`）。
    ///
    /// 牙：`RM_FLYAXE` 删掉目标存在守卫 ⇒ 目标缺失的消息也会出帧（本用例断言 3 帧）。
    #[test]
    fn mb2_ref_frames_encode_flyaxe_lighting_alive() {
        let mut world = mir2_world_bevy::World::new(64, 64);
        let mut m = mir2_world_bevy::EntitySpawn::new(0, "斧".to_string(), 10, 10);
        m.race = 87;
        let mid = world.add_entity(m);
        let t = mir2_world_bevy::EntitySpawn::new(0, "目标".to_string(), 11, 10);
        let tid = world.add_entity(t);
        let mut p = mir2_world_bevy::EntitySpawn::new(0, "P".to_string(), 12, 10);
        p.race = mir2_world_bevy::ACTOR_RACE_PLAY;
        let pid = world.add_entity(p);

        let displays = downlink::DisplayTable::new();
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "ua".into(),
                chr_name: "P".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 5,
                actor_id: pid,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: std::collections::HashMap<u8, mpsc::UnboundedSender<SimToGate>> =
            std::collections::HashMap::new();
        gates.insert(0, tx0);

        let msg = |ident: u16,
                   w_param: i32,
                   n1: i32,
                   n2: i32,
                   n3: i32,
                   tx: i32,
                   ty: i32|
         -> mir2_world_bevy::MonsterRefMsg {
            mir2_world_bevy::MonsterRefMsg {
                actor_id: mid,
                ident,
                w_param,
                n_param1: n1,
                n_param2: n2,
                n_param3: n3,
                target_x: tx,
                target_y: ty,
                dir: 2,
                x: 10,
                y: 10,
                map_id: 0,
                status: 0x2,
                self_only: false,
                recipients: vec![pid],
            }
        };
        world.pending_monster_ref_msgs.push(msg(
            mir2_world_bevy::monai::RM_FLYAXE,
            2,
            10,
            10,
            tid,
            11,
            10,
        ));
        world.pending_monster_ref_msgs.push(msg(
            mir2_world_bevy::monai::RM_LIGHTING,
            1,
            10,
            10,
            tid,
            11,
            10,
        ));
        world.pending_monster_ref_msgs.push(msg(
            mir2_world_bevy::monai::RM_ALIVE,
            2,
            10,
            10,
            0,
            0,
            0,
        ));
        // 目标不存在 ⇒ oracle `ActorMgr.Get(nParam3) != null` 守卫不发帧。
        world.pending_monster_ref_msgs.push(msg(
            mir2_world_bevy::monai::RM_FLYAXE,
            2,
            10,
            10,
            9999,
            11,
            10,
        ));

        drain_monster_ref_msgs(
            &mut world,
            &displays,
            &online,
            &gates,
            &mir2_data::pet_slave::PetSlaveConfig::default(),
        );
        let mut bodies = Vec::new();
        while let Ok(ev) = rx0.try_recv() {
            if let SimToGate::SendFrame { body, socket } = ev {
                assert_eq!(socket, 5);
                bodies.push(body);
            }
        }
        assert_eq!(bodies.len(), 3, "目标缺失的 RM_FLYAXE 不得出帧");
        assert_eq!(
            bodies[0],
            smframe::sm_flyaxe(mid, 10, 10, 2, 11, 10, tid),
            "SM_FLYAXE：头(施法者) + 尾(目标坐标/ID)"
        );
        assert_eq!(
            bodies[1],
            smframe::sm_lighting(mid, 10, 10, 2, 11, 10, tid, 1),
            "SM_LIGHTING：Series=Dir，尾 Tag2=wParam"
        );
        assert_eq!(
            bodies[2],
            smframe::sm_alive(mid, 10, 10, 2, &downlink::char_desc(0, 0)),
            "SM_ALIVE：头(X,Y,Dir) + 8B CharDesc"
        );
        assert!(world.pending_monster_ref_msgs.is_empty());
    }

    /// **T-148**：怪物侧 `RM_SPELL`/`RM_MAGICFIRE` 的宿主排水。
    ///
    /// 世界侧走**生产分派** `mir2_world_bevy::monai::monster_class_run`（race 215 =
    /// `FireballMonster`，`FireballMonster.cs:39-40`）产出两帧；宿主走生产
    /// [`drain_monster_ref_msgs`]。断言：① 两帧逐字节 = `smframe` 口径
    /// （`SM_SPELL` 头 `(ActorId, x=nParam1, y=nParam2, Series=wParam)` + `nParam3.ToString()`
    /// ASCII 尾；`SM_MAGICFIRE` 头 `(ActorId, LoWord(nParam2), HiWord(nParam2),
    /// MakeWord(EffectType, Effect))` + `Encode(4B target)` 尾）；② 收件人 = 发帧坐标 ±12
    /// 内的玩家（目标 + 前格观察者），界外玩家 0 帧、同格怪物 0 帧。
    ///
    /// 牙：删 `RM_SPELL` 支 ⇒ 落 `_ => continue` ⇒ 帧数/字节断言红；把 `RM_MAGICFIRE` 的
    /// `lo_word/hi_word(nParam2)` 对调或 targetId 传 0 ⇒ 头/尾断言红。
    #[test]
    fn t148_monster_spell_and_magicfire_on_production_drain() {
        use mir2_world_bevy::ACTOR_RACE_PLAY;
        let mut world = mir2_world_bevy::World::new(64, 64);
        world.clock_ms = 100_000;
        // `fireball_setup` 等价造景（world 侧 R19 用例同参）：怪 (10,10)、DC=10..10、
        // AntiMagic>0、SpellTick=0、NextHitTime=2000；Target=(12,10)、前格 pose=(11,10)。
        let mut m = mir2_world_bevy::EntitySpawn::new(0, "火球".to_string(), 10, 10);
        m.race = 215;
        m.hp = 1000;
        m.max_hp = 1000;
        m.dc = 10 | (10 << 8);
        m.anti_magic = 1;
        m.spell_tick = 0;
        m.ai.next_hit_time = 2_000;
        m.ai.target_focus_tick = 100_000;
        m.ai.target_x = 12;
        m.ai.target_y = 10;
        m.ai.dir = 2; // `Direction.Right`
        let mid = world.add_entity(m);
        assert!(world.enter_world(mid));
        let mut target = mir2_world_bevy::EntitySpawn::new(0, "目标".to_string(), 12, 10);
        target.race = ACTOR_RACE_PLAY;
        target.hp = 500;
        target.max_hp = 500;
        let tid = world.add_entity(target);
        assert!(world.enter_world(tid));
        let mut pose = mir2_world_bevy::EntitySpawn::new(0, "前格".to_string(), 11, 10);
        pose.race = ACTOR_RACE_PLAY;
        pose.hp = 500;
        pose.max_hp = 500;
        pose.mac = 5 | (5 << 8);
        let pid = world.add_entity(pose);
        assert!(world.enter_world(pid));
        let mut far = mir2_world_bevy::EntitySpawn::new(0, "界外".to_string(), 40, 40);
        far.race = ACTOR_RACE_PLAY;
        far.hp = 500;
        far.max_hp = 500;
        let fid = world.add_entity(far);
        assert!(world.enter_world(fid));
        let mut watcher = mir2_world_bevy::EntitySpawn::new(0, "同格怪".to_string(), 13, 10);
        watcher.race = 60;
        watcher.hp = 100;
        watcher.max_hp = 100;
        let wid = world.add_entity(watcher);
        assert!(world.enter_world(wid));
        world.entities.get_mut(mid).unwrap().ai.target_creature = Some(tid);

        assert!(
            mir2_world_bevy::monai::monster_class_run(&mut world, mid).is_some(),
            "race 215 必须走 FireballMonster 的生产分派"
        );
        let idents: Vec<u16> = world
            .pending_monster_ref_msgs
            .iter()
            .map(|f| f.ident)
            .collect();
        assert_eq!(
            idents,
            vec![
                mir2_world_bevy::monai::RM_SPELL,
                mir2_world_bevy::monai::RM_MAGICFIRE,
                mir2_protocol::messages::RM_CHANGENAMECOLOR,
            ],
            "world 侧先施法两帧，再有目标时的 Break 656"
        );

        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let online: OnlineRegistry = OnlineRegistry::from(vec![
            OnlineEntry {
                account: "a".to_string(),
                chr_name: "目标".to_string(),
                session_id: 1,
                gate_idx: 0,
                socket: 5,
                actor_id: tid,
            },
            OnlineEntry {
                account: "b".to_string(),
                chr_name: "前格".to_string(),
                session_id: 2,
                gate_idx: 0,
                socket: 6,
                actor_id: pid,
            },
            OnlineEntry {
                account: "c".to_string(),
                chr_name: "界外".to_string(),
                session_id: 3,
                gate_idx: 0,
                socket: 7,
                actor_id: fid,
            },
        ]);
        let displays = downlink::DisplayTable::new();
        drain_monster_ref_msgs(
            &mut world,
            &displays,
            &online,
            &gates,
            &mir2_data::pet_slave::PetSlaveConfig::default(),
        );

        let mut by_socket: HashMap<i32, Vec<Vec<u8>>> = HashMap::new();
        while let Ok(ev) = rx0.try_recv() {
            if let SimToGate::SendFrame { body, socket } = ev {
                by_socket.entry(socket).or_default().push(body);
            }
        }
        let mut sockets: Vec<i32> = by_socket.keys().copied().collect();
        sockets.sort_unstable();
        assert_eq!(
            sockets,
            vec![5, 6],
            "收件人 = ±12 内两名玩家（目标 + 前格）；界外玩家/同格怪（race 60）0 帧"
        );
        let want_spell = smframe::sm_spell(mid, 12, 10, 48, 48);
        let want_fire = smframe::sm_magicfire(mid, 12, 10, 2, 48, tid);
        let want_color = smframe::sm_changenamecolor(mid, 255);
        for socket in [5, 6] {
            assert_eq!(
                by_socket[&socket],
                vec![want_spell.clone(), want_fire.clone(), want_color.clone()],
                "socket {socket}：SM_SPELL → SM_MAGICFIRE → Break 656 逐字节"
            );
        }
        // 逐字段钉 oracle（不依赖 `smframe` 自证）：`SM_SPELL` 头 + ASCII 尾。
        let spell = &by_socket[&5][0];
        assert_eq!(
            i32::from_le_bytes([spell[0], spell[1], spell[2], spell[3]]),
            mid,
            "Recog = processMsg.ActorId"
        );
        assert_eq!(
            u16::from_le_bytes([spell[4], spell[5]]),
            mir2_protocol::messages::SM_SPELL
        );
        assert_eq!(
            u16::from_le_bytes([spell[6], spell[7]]),
            12,
            "Param = nParam1"
        );
        assert_eq!(
            u16::from_le_bytes([spell[8], spell[9]]),
            10,
            "Tag = nParam2"
        );
        assert_eq!(
            u16::from_le_bytes([spell[10], spell[11]]),
            48,
            "Series = wParam（Effect）"
        );
        assert_eq!(
            &spell[12..],
            b"48",
            "尾 = nParam3.ToString()（MagicId ASCII）"
        );
        // `SM_MAGICFIRE`：LoWord/HiWord(nParam2) + MakeWord(EffectType, Effect) + 4B 尾。
        let fire = &by_socket[&5][1];
        assert_eq!(
            u16::from_le_bytes([fire[4], fire[5]]),
            mir2_protocol::messages::SM_MAGICFIRE
        );
        assert_eq!(
            u16::from_le_bytes([fire[6], fire[7]]),
            12,
            "x = LoWord(nParam2)"
        );
        assert_eq!(
            u16::from_le_bytes([fire[8], fire[9]]),
            10,
            "y = HiWord(nParam2)"
        );
        assert_eq!(
            u16::from_le_bytes([fire[10], fire[11]]),
            mir2_shared::hutil::make_word(2, 48),
            "Series = MakeWord(EffectType, Effect)"
        );
        assert_eq!(
            &fire[12..],
            &mir2_protocol::edcode::encode(&tid.to_le_bytes())[..],
            "尾 = EncodeBuffer(GetBytes(nParam3), 4)"
        );
        assert!(
            world.pending_monster_ref_msgs.is_empty(),
            "排空后队列必须为空"
        );
    }

    /// **T-134**：`RM_SPACEMOVE_FIRE` 的宿主排水（`TeleMonster.cs:20` 自发的支）。
    ///
    /// 世界侧走生产分派 `monster_class_run`（race 203）；发帧后怪立即 `SpaceMove` 到目标格
    /// ⇒ 排水必须按**发帧时刻**的收件人快照送达（目标/观察者各一条 `SM_SPACEMOVE_HIDE(800)`）。
    ///
    /// 「观察者」(5,10) 在发帧点 (10,10) 与落点 (13,10) 的 ±12 内**都命中**，单靠它区分不了
    /// 「快照」与「重算」；故另置**落点专属观察者** (24,10)：|24-10|=14 > 12（发帧点外）、
    /// |24-13|=11 ≤ 12（落点内）⇒ 按发帧快照 0 帧，按落点重算会多一帧。
    ///
    /// 牙：删 `RM_SPACEMOVE_FIRE` 支 ⇒ 0 帧（红）；把 ident 改成 `SM_SPACEMOVE_HIDE2(806)` ⇒
    /// 逐字节断言红；收件人改按**落点重算**（此刻实体已在 (13,10)）⇒ 落点专属观察者 socket 8
    /// 多收一帧（红）。
    #[test]
    fn t134_spacemove_fire_on_production_drain() {
        use mir2_world_bevy::ACTOR_RACE_PLAY;
        let mut world = mir2_world_bevy::World::new(64, 64);
        world.clock_ms = 100_000;
        let mut m = mir2_world_bevy::EntitySpawn::new(0, "瞬移怪".to_string(), 10, 10);
        m.race = 203; // `TeleMonster`
        let mid = world.add_entity(m);
        assert!(world.enter_world(mid));
        let mut p = mir2_world_bevy::EntitySpawn::new(0, "目标".to_string(), 13, 10);
        p.race = ACTOR_RACE_PLAY;
        p.hp = 100;
        p.max_hp = 100;
        let pid = world.add_entity(p);
        assert!(world.enter_world(pid));
        let mut o = mir2_world_bevy::EntitySpawn::new(0, "观察者".to_string(), 5, 10);
        o.race = ACTOR_RACE_PLAY;
        o.hp = 100;
        o.max_hp = 100;
        let oid = world.add_entity(o);
        assert!(world.enter_world(oid));
        // 落点专属观察者：发帧点 (10,10) ±12 外（|24-10| = 14 > 12），落点 (13,10) ±12 内
        // （|24-13| = 11 ≤ 12）⇒ 只有「按落点重算」才会被命中。
        let mut late = mir2_world_bevy::EntitySpawn::new(0, "落点观察者".to_string(), 24, 10);
        late.race = ACTOR_RACE_PLAY;
        late.hp = 100;
        late.max_hp = 100;
        let lid = world.add_entity(late);
        assert!(world.enter_world(lid));
        let mut far = mir2_world_bevy::EntitySpawn::new(0, "界外".to_string(), 40, 40);
        far.race = ACTOR_RACE_PLAY;
        far.hp = 100;
        far.max_hp = 100;
        let fid = world.add_entity(far);
        assert!(world.enter_world(fid));
        {
            let a = &mut world.entities.get_mut(mid).unwrap().ai;
            a.target_creature = Some(pid);
            a.target_x = 0;
            a.target_y = 0; // 字段错位 ⇒ |10-0| > 5 触发瞬移
            a.search_enemy_tick = 100_000;
        }

        assert!(mir2_world_bevy::monai::monster_class_run(&mut world, mid).is_some());
        let frame = world
            .pending_monster_ref_msgs
            .iter()
            .find(|f| f.ident == mir2_world_bevy::monai::RM_SPACEMOVE_FIRE)
            .expect("TeleMonster 必须产 RM_SPACEMOVE_FIRE");
        assert_eq!(frame.actor_id, mid, "`this.SendRefMsg` ⇒ 发帧者是怪自己");
        assert_eq!(
            (
                world.entities.get(mid).unwrap().x,
                world.entities.get(mid).unwrap().y
            ),
            (13, 10),
            "发帧后立即 SpaceMove 到目标当前格（排水仍须按快照送达）"
        );

        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let online: OnlineRegistry = OnlineRegistry::from(vec![
            OnlineEntry {
                account: "a".to_string(),
                chr_name: "目标".to_string(),
                session_id: 1,
                gate_idx: 0,
                socket: 5,
                actor_id: pid,
            },
            OnlineEntry {
                account: "b".to_string(),
                chr_name: "观察者".to_string(),
                session_id: 2,
                gate_idx: 0,
                socket: 6,
                actor_id: oid,
            },
            OnlineEntry {
                account: "d".to_string(),
                chr_name: "落点观察者".to_string(),
                session_id: 4,
                gate_idx: 0,
                socket: 8,
                actor_id: lid,
            },
            OnlineEntry {
                account: "c".to_string(),
                chr_name: "界外".to_string(),
                session_id: 3,
                gate_idx: 0,
                socket: 7,
                actor_id: fid,
            },
        ]);
        let displays = downlink::DisplayTable::new();
        drain_monster_ref_msgs(
            &mut world,
            &displays,
            &online,
            &gates,
            &mir2_data::pet_slave::PetSlaveConfig::default(),
        );
        let mut socks = Vec::new();
        let want = smframe::sm_spacemove_hide(mir2_protocol::messages::SM_SPACEMOVE_HIDE, mid);
        while let Ok(ev) = rx0.try_recv() {
            if let SimToGate::SendFrame { body, socket } = ev {
                assert_eq!(body, want, "SM_SPACEMOVE_HIDE：头 (ActorId,0,0,0)，无尾");
                socks.push(socket);
            }
        }
        socks.sort_unstable();
        assert_eq!(
            socks,
            vec![5, 6],
            "发帧点 ±12 内玩家各一条；界外与落点专属观察者 0 帧"
        );
        assert!(
            !socks.contains(&8),
            "落点专属观察者 (24,10) 必须 0 帧：收件人是发帧时刻快照，不按落点重算"
        );
    }

    /// **T-135**：`RM_CHARSTATUSCHANGED` 的宿主排水——`Series` 是**每个收件人自己**的
    /// `HitSpeed`（`PlayObject.Message.cs:1845-1846` 的 `this.HitSpeed`）。
    ///
    /// 世界侧走生产分派 `monster_class_run`（race 210 = `FrostTiger`：`MagMakePrivateTransparent`
    /// 收尾的 `StatusChanged()`）。两名玩家 `hit_speed` 不同（7 / 13）⇒ 两条帧只差 `Series`。
    ///
    /// `nParam1` 必须让 `LoWord/HiWord` **可区分**，否则「lo/hi 对调」的牙打不响：
    /// oracle `GetCharStatus() = GetBuffStatus(this) | (CharStatusEx & 0x0000FFFF)`
    /// （`BaseObject.cs:1492-1502`）⇒ 置 `char_status_ex = 0x0001_0002` 时高 16 位被丢弃
    /// （`Param = 0x0002`），`Tag` 的非零位只能来自 buff 位（`DefensePower` 榜首 ⇒ bit31
    /// = `0x8000`）⇒ `status = 0x8000_0002`，`Param/Tag` 两半互异。
    ///
    /// 牙：把 `hit_speed` 改成常数 0（单 body 广播）⇒ 第二条帧的 `Series` 断言红；删
    /// 10139 支 ⇒ 0 帧（红）；`LoWord/HiWord(nParam1)` 对调 ⇒ 头断言（`Param=0x0002`）红。
    #[test]
    fn t135_charstatuschanged_per_recipient_hit_speed_on_production_drain() {
        use mir2_world_bevy::ACTOR_RACE_PLAY;
        let mut world = mir2_world_bevy::World::new(64, 64);
        world.clock_ms = 100_000;
        let mut tiger = mir2_world_bevy::EntitySpawn::new(0, "霜虎".to_string(), 10, 10);
        tiger.race = 210; // `FrostTiger`
        let tid = world.add_entity(tiger);
        assert!(world.enter_world(tid));
        // 让 `nParam1` 的上下 16 位互异（见本用例文档）：`CharStatusEx` 只并入低 16 位
        // （0x0001_0002 ⇒ 低半 0x0002、高半被 `& 0xFFFF` 丢弃）；高半取 buff 首位 bit31。
        world.entities.get_mut(tid).unwrap().buff.char_status_ex = 0x0001_0002;
        world.defence_up(tid, 10);
        let mut p1 = mir2_world_bevy::EntitySpawn::new(0, "甲".to_string(), 11, 10);
        p1.race = ACTOR_RACE_PLAY;
        p1.hit_speed = 7;
        let p1id = world.add_entity(p1);
        assert!(world.enter_world(p1id));
        let mut p2 = mir2_world_bevy::EntitySpawn::new(0, "乙".to_string(), 12, 10);
        p2.race = ACTOR_RACE_PLAY;
        p2.hit_speed = 13;
        let p2id = world.add_entity(p2);
        assert!(world.enter_world(p2id));
        let mut far = mir2_world_bevy::EntitySpawn::new(0, "界外".to_string(), 40, 40);
        far.race = ACTOR_RACE_PLAY;
        far.hit_speed = 99;
        let fid = world.add_entity(far);
        assert!(world.enter_world(fid));
        world.entities.get_mut(tid).unwrap().ai.search_enemy_tick = 100_000;

        assert!(mir2_world_bevy::monai::monster_class_run(&mut world, tid).is_some());
        let status = world.entities.get(tid).unwrap().char_status;
        assert_eq!(
            status, 0x8000_0002u32 as i32,
            "CharStatusEx 低半 0x0002 | buff bit31 0x8000_0000"
        );
        let frame = world
            .pending_monster_ref_msgs
            .iter()
            .find(|f| f.ident == mir2_world_bevy::monai::RM_CHARSTATUSCHANGED)
            .expect("`StatusChanged()` 必须产 RM_CHARSTATUSCHANGED");
        assert_eq!(frame.actor_id, tid, "StatusChanged 由霜虎自己发");
        assert_eq!(frame.n_param1, status, "nParam1 = 收尾后的 CharStatus");

        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let online: OnlineRegistry = OnlineRegistry::from(vec![
            OnlineEntry {
                account: "a".to_string(),
                chr_name: "甲".to_string(),
                session_id: 1,
                gate_idx: 0,
                socket: 5,
                actor_id: p1id,
            },
            OnlineEntry {
                account: "b".to_string(),
                chr_name: "乙".to_string(),
                session_id: 2,
                gate_idx: 0,
                socket: 6,
                actor_id: p2id,
            },
            OnlineEntry {
                account: "c".to_string(),
                chr_name: "界外".to_string(),
                session_id: 3,
                gate_idx: 0,
                socket: 7,
                actor_id: fid,
            },
        ]);
        let displays = downlink::DisplayTable::new();
        drain_monster_ref_msgs(
            &mut world,
            &displays,
            &online,
            &gates,
            &mir2_data::pet_slave::PetSlaveConfig::default(),
        );
        let mut by_socket: HashMap<i32, Vec<u8>> = HashMap::new();
        while let Ok(ev) = rx0.try_recv() {
            if let SimToGate::SendFrame { body, socket } = ev {
                assert!(by_socket.insert(socket, body).is_none(), "每收件人恰一条");
            }
        }
        let mut sockets: Vec<i32> = by_socket.keys().copied().collect();
        sockets.sort_unstable();
        assert_eq!(sockets, vec![5, 6], "±12 内两名玩家各一条；界外玩家 0 帧");
        assert_eq!(
            by_socket[&5],
            smframe_ext::sm_charstatuschanged(tid, status, 7),
            "Series = 收件人甲自己的 HitSpeed(7)"
        );
        assert_eq!(
            by_socket[&6],
            smframe_ext::sm_charstatuschanged(tid, status, 13),
            "Series = 收件人乙自己的 HitSpeed(13)（不是发送者/常数）"
        );
        let body = &by_socket[&5];
        assert_eq!(
            u16::from_le_bytes([body[4], body[5]]),
            mir2_protocol::messages::SM_CHARSTATUSCHANGED
        );
        assert_eq!(
            u16::from_le_bytes([body[6], body[7]]),
            0x0002,
            "Param = LoWord(nParam1) = CharStatusEx 低半（字面量，防 lo/hi 对调）"
        );
        assert_eq!(
            u16::from_le_bytes([body[8], body[9]]),
            0x8000,
            "Tag = HiWord(nParam1) = buff bit31（字面量，防 lo/hi 对调）"
        );
        assert_eq!(
            i32::from_le_bytes([body[0], body[1], body[2], body[3]]),
            tid,
            "Recog = processMsg.ActorId"
        );
    }

    /// **复验 MB-1 F1 回归**：`ComeDown` 先发 `RM_DIGDOWN` 再置 `FixedHideMode=true`；
    /// 宿主排水必须用**发帧时刻**的收件人快照，否则按此刻的 hide 状态重算会整帧丢失。
    ///
    /// **牙**：把排水改回 `broadcast_ref_msg_opt`（此刻重算）⇒ 本用例红（0 帧）。
    #[test]
    fn mb1_digdown_survives_come_down_hide_state() {
        let mut world = mir2_world_bevy::World::new(64, 64);
        let mut p = mir2_world_bevy::EntitySpawn::new(0, "P".to_string(), 11, 10);
        p.race = mir2_world_bevy::ACTOR_RACE_PLAY;
        let pid = world.add_entity(p);
        let mut m = mir2_world_bevy::EntitySpawn::new(0, "钉怪".to_string(), 10, 10);
        m.race = 85;
        // `ComeDown` 之后的状态：已隐藏。
        m.fixed_hide_mode = true;
        let mid = world.add_entity(m);

        let displays = downlink::DisplayTable::new();
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "ua".into(),
                chr_name: "P".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 5,
                actor_id: pid,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: std::collections::HashMap<u8, mpsc::UnboundedSender<SimToGate>> =
            std::collections::HashMap::new();
        gates.insert(0, tx0);

        world
            .pending_monster_ref_msgs
            .push(mir2_world_bevy::MonsterRefMsg {
                actor_id: mid,
                ident: mir2_world_bevy::monai::RM_DIGDOWN,
                w_param: 0,
                n_param1: 0,
                n_param2: 0,
                n_param3: 0,
                target_x: 0,
                target_y: 0,
                dir: 2,
                x: 10,
                y: 10,
                map_id: 0,
                status: 0,
                self_only: false,
                // 发帧时刻（尚未隐藏）快照到玩家。
                recipients: vec![pid],
            });
        drain_monster_ref_msgs(
            &mut world,
            &displays,
            &online,
            &gates,
            &mir2_data::pet_slave::PetSlaveConfig::default(),
        );
        let mut frames = 0;
        while let Ok(ev) = rx0.try_recv() {
            if let SimToGate::SendFrame { body, socket } = ev {
                assert_eq!(socket, 5);
                assert_eq!(body, smframe::sm_digdown(mid, 10, 10));
                frames += 1;
            }
        }
        assert_eq!(frames, 1, "sender 已隐藏也必须按发帧快照送达（复验 F1）");
    }

    /// **G-8 / G-10**：坐标与伤害都按 `(ushort)` **截断/回绕**（旧实现分别归 0 / 饱和）。
    #[test]
    fn wire_coord_and_damage_truncate_like_ushort() {
        assert_eq!(wire_coord(287), 287);
        assert_eq!(wire_coord(618), 618);
        assert_eq!(wire_coord(-1), 0xFFFF, "负坐标 = 二补数低 16 位");
        assert_eq!(wire_coord(40000), 40000, "i16 越界不再归 0（G-8）");
        assert_eq!(wire_coord(70000), 4464, "低 16 位截断");
        assert_eq!(wire_damage(70000), 4464, "伤害回绕到 4464（G-10）");
        assert_eq!(wire_damage(65535), 65535);
        assert_eq!(wire_damage(-1), 0xFFFF);
    }

    // ═════════════ 卡 `openmir2-rm-delaymagic-six-ids` / `openmir2-rm-delaypushed` ═════════════
    //
    // 六魔号的效果体在 oracle 里把伤害/推挤**自投递**到施法者队列（`SendSelfDelayMsg`），
    // 到点由 `Operate(RM_DELAYMAGIC)`/`Operate(RM_DELAYPUSHED)` 结算。本组用例走**生产入口**
    // `handle_spell_cmd`，断言入队点与投递臂同点同次。

    /// B1 六魔号的魔法模板（`power=5,max_power=10,def_power=2,def_max_power=8,train_lv=3`）。
    fn b1_six_magic(id: u16) -> mir2_data::MagicInfo {
        mir2_data::MagicInfo {
            magic_id: id,
            effect: 4,
            effect_type: 4,
            power: 5,
            max_power: 10,
            def_power: 2,
            def_max_power: 8,
            train_lv: 3,
            train_level: [0; 4],
            max_train: [1000; 4],
            ..mir2_data::MagicInfo::default()
        }
    }

    /// 手写 oracle 取数序（B1 六魔号）：骰门 → MPow → GetPower → GetAttackPower（玩家
    /// `Luck<=0` 再 `Random(10)`）；返回 `(对照流, nPower)`。
    fn b1_six_replay(
        seed: i32,
        magic: &mir2_data::MagicInfo,
        level: u8,
        stat: i32,
    ) -> (mir2_shared::rng::RandomNumber, i32) {
        let mut c = mir2_shared::rng::RandomNumber::with_seed(seed);
        let _dice = c.random_below(10);
        let mpow = i32::from(magic.power)
            + c.random_below(i32::from(magic.max_power) - i32::from(magic.power));
        let base = mir2_shared::hutil::round(
            f64::from(mpow) / f64::from(magic.train_lv + 1) * f64::from(level + 1),
        ) + i32::from(magic.def_power)
            + c.random_below(i32::from(magic.def_max_power) - i32::from(magic.def_power))
            + i32::from((stat & 0xff) as u8);
        let lo = i32::from((stat & 0xff) as u8);
        let hi = i32::from(((stat >> 8) & 0xff) as u8);
        let mut power = base + c.random_range(0, hi - lo + 2);
        if c.random_below(10) == 0 {
            power = base;
        }
        (c, power)
    }

    /// 六魔号各恰一条 `RM_DELAYMAGIC`：载荷 `(nPower, MakeLong(tx,ty), 2, target, delay)`；
    /// 未到点不结算，到点后目标侧 `RM_MAGSTRUCK`（31）落地。
    #[test]
    fn six_ids_enqueue_delay_magic_and_deliver_only_at_due_time() {
        const SM_31: u16 = mir2_protocol::messages::SM_STRUCK;
        for (magic_id, delay_ms, stat) in [
            (1u16, 600i64, 0x0A05),
            (5, 600, 0x0A05),
            (11, 600, 0x0A05),
            (13, 1200, 0x0A05),
            (44, 600, 0x0A05),
            (45, 600, 0x0A05),
        ] {
            let magic = b1_six_magic(magic_id);
            let amulet = (magic_id == 13).then_some(600);
            let mut rig = B4Rig::new(magic.clone(), 1, amulet);
            let m = rig.add_monster("m", 11, 10, 80, 10, 0, 0, 0);
            rig.seed(0);
            let seed = B4_SEED;
            rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(seed);
            let (expect_stream, expect_power) = b1_six_replay(seed, &magic, 1, stat);
            if magic_id == 13 {
                // 13 的 `CheckAmulet(1, 1)` 要求 `StdMode==25 && Shape==5`（护身符）。
                let mut catalog = game_svr::ability::StdItemCatalog::new();
                catalog.insert(
                    1,
                    mir2_data::StdItem {
                        name: "护身符".into(),
                        std_mode: 25,
                        shape: 5,
                        ..mir2_data::StdItem::default()
                    },
                );
                rig.cast_with_catalog(magic_id, (11, 10), m, &catalog);
            } else {
                rig.cast(magic_id, (11, 10), m);
            }
            let delays = rig.delay_msgs(mir2_world_bevy::slave::RM_DELAYMAGIC);
            assert_eq!(delays.len(), 1, "[{magic_id}] 恰一条 RM_DELAYMAGIC");
            let d = delays[0];
            assert_eq!(
                (d.actor_id, d.w_param, d.n_param1, d.n_param2, d.n_param3),
                (
                    rig.caster,
                    expect_power,
                    game_svr::feature::make_long(11, 10),
                    2,
                    m
                ),
                "[{magic_id}] RM_DELAYMAGIC 载荷（nPower/MakeLong/rage/target）"
            );
            assert_eq!(
                d.deliver_at_ms,
                rig.world.clock_ms + delay_ms,
                "[{magic_id}] 延时（13=1200ms，其余 600ms）"
            );
            // 取数序：效果体 5 抽 + 共享尾 `Random(3)`；推挤门（44）另计，level=1 ⇒ push=-1。
            let mut trace = expect_stream;
            let _tail = trace.random_below(3);
            if magic_id == 44 {
                let _p20 = trace.random_below(20);
                let _plv = trace.random_below(1);
            }
            assert_eq!(
                format!("{:?}", rig.world.rng),
                format!("{:?}", trace),
                "[{magic_id}] 施法 tick 取数序不变（入队不抽数）"
            );
            // 未到点：目标不结算、无 31。
            let f = rig.deliver(delay_ms - 1);
            assert_eq!(b4_count(&f, 911, SM_31), 0, "[{magic_id}] 未到点不落地");
            // 到点：投递者侧 MSD + 目标侧 `R(1000)`/MSD ⇒ 31。
            // **本卡起 640（`RM_MAGIC_LVEXP`, Lowest=255）在 +1000ms 与 `RM_DELAYMAGIC`
            // （同优先级）共用四叉堆**：泵在堆根未到点时「重入队 + 结束本次泵」，.NET 堆不稳定
            // ⇒ 到点后可能还要再泵几次才轮到 `RM_DELAYMAGIC`（生产每 tick 都泵）。
            // 按生产节奏补泵：上界与测试辅助同一推导（起点队列长度 q ⇒ q 次泵内每条消息都轮到
            // 过队根 ⇒ 到期项必已投递或只剩泵门拦截项），即 q + 1，另设 64 上限。
            let bound = (rig.world.self_delay_msgs.len() + 1).min(64);
            let mut f = Vec::new();
            for _ in 0..bound {
                f.extend(rig.deliver(1));
                if b4_count(&f, 911, SM_31) >= 1 {
                    break;
                }
            }
            assert!(
                b4_count(&f, 911, SM_31) >= 1,
                "[{magic_id}] 到点后 RM_MAGSTRUCK(31) 落地"
            );
        }
    }

    /// 找「44 的推挤门与 `Random(5)` 同时通过」的种子（B4Rig 施法前取数序固定）。
    fn seed_for_hb_push() -> i32 {
        for seed in 1..100_000 {
            let magic = b1_six_magic(44);
            let (mut c, _) = b1_six_replay(seed, &magic, 5, 0x0A05);
            if c.random_below(20) < 6 + 5 * 3 + 50 && c.random_below(5) - 1 > 0 {
                return seed;
            }
        }
        panic!("找不到 44 推挤门通过的种子");
    }

    /// **`openmir2-rm-delaypushed`**：44 的 `push > 0` ⇒ 恰一条 `RM_DELAYPUSHED`
    /// （`wParam=GetNextDirection`、`nParam2=push`、`nParam3=target`、600ms）；
    /// 到点前不动，到点后 `CharPushed` 逐格推进并回 `Dir = GetBackDir(nDir)`。
    #[test]
    fn hb_fireball_push_delivers_char_pushed_at_due_time() {
        const SM_BACKSTEP: u16 = mir2_protocol::messages::SM_BACKSTEP;
        let magic = b1_six_magic(44);
        let mut rig = B4Rig::new(magic, 5, None);
        // `StickMode` 读目标实体的 `Entity.stick_mode`（本例缺省 false）；caster 60 > target 10 ⇒ 门开。
        let m = rig.add_monster("m", 11, 10, 80, 10, 0, 0, 0);
        rig.seed(0);
        let seed = seed_for_hb_push();
        rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(seed);
        rig.cast(44, (11, 10), m);
        let delays = rig.delay_msgs(mir2_world_bevy::slave::RM_DELAYPUSHED);
        assert_eq!(delays.len(), 1, "push > 0 ⇒ 恰一条 RM_DELAYPUSHED");
        let d = delays[0];
        let dir = mir2_world_bevy::magic::next_direction(10, 10, 11, 10);
        let push = d.n_param2;
        assert!(push > 0, "push 必须 > 0");
        assert_eq!(
            (d.actor_id, d.w_param, d.n_param1, d.n_param3),
            (
                rig.caster,
                i32::from(dir),
                game_svr::feature::make_long(11, 10),
                m
            ),
            "RM_DELAYPUSHED 载荷（nDir/MakeLong/push/target）"
        );
        assert_eq!(d.deliver_at_ms, rig.world.clock_ms + 600);
        // 到点前：位置不变、无 SM_BACKSTEP。
        let f = rig.deliver(599);
        assert_eq!(
            (
                rig.world.entities.get(m).unwrap().x,
                rig.world.entities.get(m).unwrap().y
            ),
            (11, 10),
            "到点前不推"
        );
        assert_eq!(b4_count(&f, 911, SM_BACKSTEP), 0);
        // 到点：逐格推进 `push` 格，方向 = back_dir，帧方向 = back_dir。
        let f = rig.deliver(1);
        let back = mir2_world_bevy::magic::back_dir(dir);
        let e = rig.world.entities.get(m).unwrap();
        assert_eq!(
            (e.x, e.y, e.dir()),
            (11 + push, 10, back),
            "CharPushed 推进 push 格并把 Dir 置为 nBackDir"
        );
        let steps = b4_all(&f, 911, SM_BACKSTEP);
        assert_eq!(steps.len() as i32, push, "逐格一条 SM_BACKSTEP");
        for b in &steps {
            assert_eq!(
                b4_cmd(b).series & 0xFF,
                u16::from(back),
                "SM_BACKSTEP 的帧方向 = nBackDir"
            );
        }
    }

    /// 阴性对照：caster 等级不高于目标 ⇒ 推挤两抽都不发生、无 `RM_DELAYPUSHED`
    /// （但 `RM_DELAYMAGIC` 照常）。
    #[test]
    fn hb_fireball_push_gate_closed_draws_nothing_and_enqueues_no_push() {
        let magic = b1_six_magic(44);
        let mut rig = B4Rig::new(magic.clone(), 5, None);
        let m = rig.add_monster("m", 11, 10, 80, 60, 0, 0, 0); // level == caster
        rig.seed(0);
        let seed = B4_SEED;
        rig.world.rng = mir2_shared::rng::RandomNumber::with_seed(seed);
        let (expect_stream, _) = b1_six_replay(seed, &magic, 5, 0x0A05);
        rig.cast(44, (11, 10), m);
        assert!(rig
            .delay_msgs(mir2_world_bevy::slave::RM_DELAYPUSHED)
            .is_empty());
        assert_eq!(
            rig.delay_msgs(mir2_world_bevy::slave::RM_DELAYMAGIC).len(),
            1,
            "等级门只关推挤支，不关 RM_DELAYMAGIC"
        );
        // magic level=5 ⇒ 共享尾的 `level < 3` 门关，`Random(3)` 不抽。
        let trace = expect_stream;
        assert_eq!(
            format!("{:?}", rig.world.rng),
            format!("{:?}", trace),
            "推挤门关 ⇒ 无 Random(20)/Random(Level)"
        );
    }

    // ═════════════ 卡 `openmir2-player-dir-supply` ═════════════

    /// `Entity.ai.dir` 是唯一权威：展示表与实体不一致时 `GetPoseCreate`/`actor_dir` 读实体。
    #[test]
    fn player_dir_authority_beats_stale_display_table() {
        use mir2_protocol::messages::CM_TURN;
        let mut world = mir2_world_bevy::World::new(32, 32);
        let mover = {
            let mut e = mir2_world_bevy::EntitySpawn::new(0, "mover".to_string(), 10, 10);
            e.race = mir2_world_bevy::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        let target = {
            let mut e = mir2_world_bevy::EntitySpawn::new(0, "target".to_string(), 11, 10);
            e.race = mir2_world_bevy::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        world.tick();
        let mut displays = downlink::DisplayTable::new();
        // 展示表故意停在**错误**方向（西=6），实体（东=2）才是权威。
        displays.set(
            mover,
            downlink::ActorDisplay::new(6, 0, 111, 0, 0, 255, b"mover".to_vec()),
        );
        displays.set(
            target,
            downlink::ActorDisplay::new(6, 0, 112, 0, 0, 255, b"target".to_vec()),
        );
        world.entities.get_mut(mover).unwrap().ai.dir = 2; // 东
        assert_eq!(actor_dir(&world, &displays, mover), 2, "读实体不读展示表");
        assert_eq!(
            pose_create(&world, &displays, mover),
            Some(target),
            "GetPoseCreate 用实体 Dir（东格有目标；若读展示表西格为空）"
        );
        // 反过来：实体朝西（空）而展示表朝东（有目标）⇒ 必须取不到。
        world.entities.get_mut(mover).unwrap().ai.dir = 6;
        assert_eq!(
            pose_create(&world, &displays, mover),
            None,
            "实体朝西 ⇒ 前方无目标（展示表朝东不得生效）"
        );

        // `CM_TURN`：实体与展示表同时落新值（展示表是投影）。
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "ua".into(),
                chr_name: "mover".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: mover,
            },
        );
        let (tx0, _rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates = std::collections::HashMap::new();
        gates.insert(0, tx0);
        handle_move_cmd(
            CM_TURN,
            game_svr::feature::make_long(10, 10),
            5,
            "mover",
            901,
            &online,
            &mut std::collections::HashMap::new(),
            &mut world,
            &mut displays,
            &gates,
            None,
        );
        assert_eq!(world.entities.get(mover).unwrap().ai.dir, 5, "转身写实体");
        assert_eq!(displays.get(mover).unwrap().dir, 5, "展示表按实体投影");
        // 展示表再次被弄脏 ⇒ 权威读仍取实体（模拟失败支的落后值）。
        set_display_dir(&mut displays, mover, 1);
        assert_eq!(
            actor_dir(&world, &displays, mover),
            5,
            "展示表脏值不影响权威读"
        );
    }

    // ═════════════ 卡 `openmir2-player-drop-useitems`（宿主帧面）═════════════

    /// 玩家死亡 `DropUseItems` 的 `SM_DELITEMS(709)`：`ItemDesc & 8` 的绑定件被清槽
    /// 并出 `"/MakeIndex/"` 尾；世界实体与会话两边的 `Index` 都归 0（`MakeIndex` 保留）。
    #[test]
    fn player_death_drop_use_items_emits_sm_delitems_and_clears_slots() {
        use mir2_protocol::messages::SM_DELITEMS;
        let mut world = mir2_world_bevy::World::new(32, 32);
        let dead = {
            let mut e = mir2_world_bevy::EntitySpawn::new(0, "dead".to_string(), 10, 10);
            e.race = mir2_world_bevy::ACTOR_RACE_PLAY;
            e.hp = 0;
            e.use_items[0] = mir2_world_bevy::entity::UseItemSlot {
                make_index: 77,
                index: 1,
                dura: 500,
                dura_max: 1000,
                desc: [0; 14],
            };
            world.add_entity(e)
        };
        let killer = {
            let mut e = mir2_world_bevy::EntitySpawn::new(0, "killer".to_string(), 11, 10);
            e.race = mir2_world_bevy::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        world.entities.get_mut(dead).unwrap().attribution.exp_hitter = Some(killer);
        world.set_item_catalog(vec![mir2_data::StdItem {
            name: "绑定件".into(),
            item_desc: 8,
            ..mir2_data::StdItem::default()
        }]);
        world.set_death_drop_config(1, 1, 3, Vec::new());
        let rec = world.tick();
        assert_eq!(rec.death_use_item_drops.len(), 1, "死亡结算产出删除列表");

        let mut sg = test_session_ground(dead);
        sg.use_items[0] = Some(game_svr::bag::BagItem {
            make_index: 77,
            index: 1,
            dura: 500,
            dura_max: 1000,
            desc: [0; 14],
        });
        let mut ground_sessions = std::collections::HashMap::new();
        ground_sessions.insert("dead".to_string(), sg);
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "ud".into(),
                chr_name: "dead".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 913,
                actor_id: dead,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates = std::collections::HashMap::new();
        gates.insert(0, tx0);
        drain_death_use_item_drops(&rec, &online, &gates);
        let mut frames = Vec::new();
        while let Ok(SimToGate::SendFrame { socket, body }) = rx0.try_recv() {
            frames.push((socket, body));
        }
        assert_eq!(frames.len(), 1, "恰一条 SM_DELITEMS");
        assert_eq!(frames[0].0, 913);
        let cmd = b4_cmd(&frames[0].1);
        assert_eq!(cmd.ident, SM_DELITEMS);
        assert_eq!(cmd.series, 1, "删除件数");
        assert_eq!(
            mir2_protocol::edcode::decode(&frames[0].1[12..]),
            b"/77/".to_vec(),
            "ItemName 空（第一段只填 MakeIndex）⇒ \"/MakeIndex/\""
        );
        // 世界实体与会话两侧的槽都清了 Index、保留 MakeIndex。
        assert_eq!(world.entities.get(dead).unwrap().use_items[0].index, 0);
        let sg = ground_sessions.get_mut("dead").unwrap();
        sync_use_items_to_session(&world, sg);
        assert_eq!(sg.use_items[0].as_ref().unwrap().index, 0);
        assert_eq!(sg.use_items[0].as_ref().unwrap().make_index, 77);
    }

    /// **C1 进程级判据**：生产 `sim_loop` 的建世界入口 [`production_world`] 会把
    /// `EnterConfig::world_item_catalog` 接进 `World::item_catalog` —— 死亡
    /// `DropUseItems` 能查到 `ItemDesc & 8` 的模板，清槽并出 `SM_DELITEMS` 的
    /// `"/MakeIndex/"` 尾。**不手工写 `world.item_catalog`**。
    ///
    /// 红检：删掉 `production_world` 里的 `set_item_catalog` 调用（或 `sim_loop`
    /// 不传表）⇒ `get_std_item` 恒 `None` ⇒ 删除列表为空/无帧 ⇒ 本用例红。
    #[test]
    fn production_world_wires_item_catalog_into_death_drop() {
        use mir2_protocol::messages::SM_DELITEMS;
        let mut cfg = EnterConfig::for_test(crate::strings::StringConf::defaults());
        cfg.world_item_catalog = vec![mir2_data::StdItem {
            name: "绑定件".into(),
            item_desc: 8,
            ..mir2_data::StdItem::default()
        }];
        // 与 `sim_loop` 同一条生产入口。
        let mut world = production_world(
            vec![(32, 32)],
            &std::sync::Arc::new(std::sync::atomic::AtomicI32::new(0)),
            &mut cfg.world_item_catalog,
        );
        assert!(
            cfg.world_item_catalog.is_empty(),
            "顺序表已移入世界（生产路径不复制、不手工设字段）"
        );
        let dead = {
            let mut e = mir2_world_bevy::EntitySpawn::new(0, "dead".to_string(), 10, 10);
            e.race = mir2_world_bevy::ACTOR_RACE_PLAY;
            e.hp = 0;
            e.use_items[0] = mir2_world_bevy::entity::UseItemSlot {
                make_index: 77,
                index: 1,
                dura: 500,
                dura_max: 1000,
                desc: [0; 14],
            };
            world.add_entity(e)
        };
        let killer = {
            let mut e = mir2_world_bevy::EntitySpawn::new(0, "killer".to_string(), 11, 10);
            e.race = mir2_world_bevy::ACTOR_RACE_PLAY;
            world.add_entity(e)
        };
        world.entities.get_mut(dead).unwrap().attribution.exp_hitter = Some(killer);
        world.set_death_drop_config(1, 1, 3, Vec::new());
        let rec = world.tick();
        assert_eq!(
            rec.death_use_item_drops,
            vec![(dead, vec![(0usize, String::new(), 77)])],
            "生产目录查得到模板 ⇒ 第一段清槽并记 DeleteItem"
        );
        assert_eq!(world.entities.get(dead).unwrap().use_items[0].index, 0);

        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "ud".into(),
                chr_name: "dead".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 914,
                actor_id: dead,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates = std::collections::HashMap::new();
        gates.insert(0, tx0);
        drain_death_use_item_drops(&rec, &online, &gates);
        let mut frames = Vec::new();
        while let Ok(SimToGate::SendFrame { socket, body }) = rx0.try_recv() {
            frames.push((socket, body));
        }
        assert_eq!(frames.len(), 1, "恰一条 SM_DELITEMS（生产接线可达）");
        assert_eq!(frames[0].0, 914);
        let cmd = b4_cmd(&frames[0].1);
        assert_eq!(cmd.ident, SM_DELITEMS);
        assert_eq!(cmd.series, 1);
        assert_eq!(
            mir2_protocol::edcode::decode(&frames[0].1[12..]),
            b"/77/".to_vec(),
            "尾 = 斜杠 MakeIndex 斜杠（ItemName 空）"
        );
    }

    /// **I1 判据（克隆体 AOI 出现帧方向）**：`spawn_clone` 把
    /// `GetBackDir(主人)` 写进**实体** `Entity.ai.dir`；AOI 出现帧读实体 ⇒ 方向 = back-dir，
    /// 不是 0。展示表登记的是同一值（投影），所以红检必须打实体。
    ///
    /// 红检：删掉 `spawn_clone` 的 `e.ai.dir = out.dir` ⇒ 实体方向 0 ⇒ `SM_TURN.Series`
    /// 断言（6）必红。
    #[test]
    fn aoi_show_clone_uses_entity_back_dir() {
        use std::collections::HashMap;

        let mut world = mir2_world_bevy::World::new(64, 64);
        world.open_session("p");
        let p = world
            .enter_map("p", mir2_world_bevy::EntitySpawn::new(0, "p", 10, 10), 0)
            .expect("玩家进图");
        world.entities.get_mut(p).unwrap().flags.want_ref_msg = true;
        // 主人施法方向 2 ⇒ 克隆体 `GetBackDir(2)` = 6。
        let out = mir2_world_bevy::slave::spawn_clone(&mut world, p, 2)
            .expect("主人在世界 ⇒ 应造出克隆体");
        assert_eq!(out.dir, 6);
        assert_eq!(
            world.entities.get(out.clone_id).unwrap().ai.dir,
            6,
            "spawn_clone 必须写实体 ai.dir（oracle PlayCloneObject.Dir）"
        );

        let caster_display =
            downlink::ActorDisplay::new(2, 0, 0, 0, 0, downlink::PLAYER_NAME_COLOR, Vec::new());
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            out.clone_id,
            downlink::clone_display(out.dir, &caster_display),
        );
        // 观察者的可见集直接钉入克隆体（Show）——出现帧路径只读实体方向。
        world
            .entities
            .map_binding_mut(p)
            .unwrap()
            .visible_actors
            .push(mir2_world_bevy::entity::VisibleBaseObject {
                target: out.clone_id,
                flag: mir2_world_bevy::VisibleFlag::Show,
            });
        world.entities.get_mut(p).unwrap().ai.search_tick = world.clock_ms;

        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "up".into(),
                chr_name: "p".into(),
                session_id: 1,
                gate_idx: 0,
                socket: 902,
                actor_id: p,
            },
        );
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let _ = drain_aoi_downlink(&world, &displays, &online, &gates, None, None, None);

        let mut frames = Vec::new();
        while let Ok(SimToGate::SendFrame { body, .. }) = rx0.try_recv() {
            let cm = mir2_protocol::frame::CommandMessage::from_bytes(&body)
                .expect("SM_* body 至少 12B");
            frames.push((cm.recog, cm.ident, cm.series));
        }
        assert_eq!(frames.len(), 2, "出现帧 = SM_TURN + SM_FEATURECHANGED");
        assert_eq!(frames[0].0, out.clone_id);
        assert_eq!(frames[0].1, mir2_protocol::messages::SM_TURN);
        assert_eq!(
            frames[0].2 & 0xFF,
            6,
            "克隆体出现帧方向 = 实体 back-dir（6），不是 0"
        );
    }

    /// **M2 判据**：`HUtil32.MakeLong(ushort, ushort)` 的坐标是**低 16 位二补数**，
    /// 越界/负数不得归 0。
    ///
    /// 红检：把 `wire_coord` 换回 `u16::try_from(v).unwrap_or(0)` ⇒ `-1` 归 0 断言必红。
    #[test]
    fn make_long_keeps_low_16_bit_twos_complement() {
        assert_eq!(wire_coord(-1), 0xFFFF, "`(ushort)-1` = 65535");
        assert_eq!(wire_coord(70_000), 70_000_i32 as u16, "超界保留低 16 位");
        assert_ne!(wire_coord(-1), 0, "不得归 0");
        assert_eq!(
            game_svr::feature::make_long(wire_coord(-1), wire_coord(-2)),
            0xFFFF | (0xFFFE_i32 << 16),
            "低/高字都保留二补数"
        );
    }
