    // ───────────────────────── PL-3（P25/P26/P27）─────────────────────────

    /// PL-3 地图夹具：临时 `Envir/MapInfo.txt` + `Map/fa.map`（16×16），注册表 id 0 = `A`。
    pub(crate) fn pl3_registry(flag_line: &str) -> (mir2_envir::MapRegistry, std::path::PathBuf) {
        use std::sync::atomic::{AtomicU32, Ordering};
        static N: AtomicU32 = AtomicU32::new(0);
        let dir = std::env::temp_dir().join(format!(
            "pl3-map-{}-{}",
            std::process::id(),
            N.fetch_add(1, Ordering::Relaxed)
        ));
        let map_dir = dir.join("Map");
        let envir = dir.join("Envir");
        std::fs::create_dir_all(&map_dir).unwrap();
        std::fs::create_dir_all(&envir).unwrap();
        let mut buf = vec![0u8; mir2_envir::HEADER_BYTES + 16 * 16 * mir2_envir::CELL_BYTES];
        buf[0..2].copy_from_slice(&16u16.to_le_bytes());
        buf[2..4].copy_from_slice(&16u16.to_le_bytes());
        std::fs::write(map_dir.join("fa.map"), buf).unwrap();
        // `MapInfo` 的 `DECHP(time/point)` 口径（`Maps.cs:198-209`：`/` 之后是 point）。
        let text = format!("[A|fa 甲] {flag_line}\n");
        let (bytes, _, _) = encoding_rs::GBK.encode(&text);
        std::fs::write(envir.join("MapInfo.txt"), bytes.as_ref()).unwrap();
        let reg = mir2_envir::MapLoader::new(&dir, "Map", "Envir")
            .load_registry()
            .unwrap();
        assert!(
            reg.flag_of(0).is_some(),
            "夹具注册表必须加载出 id 0（MapInfo/地图文件/GBK）"
        );
        (reg, dir)
    }

    #[allow(clippy::type_complexity)]
    fn p25_fixture(
        flag_line: &str,
        hp: u16,
        max_hp: u16,
        show_hp: bool,
    ) -> (
        mir2_world_bevy::World,
        HashMap<String, SessionGround>,
        OnlineRegistry,
        HashMap<u8, mpsc::UnboundedSender<SimToGate>>,
        mpsc::UnboundedReceiver<SimToGate>,
        i32,
        mir2_envir::MapRegistry,
        std::path::PathBuf,
    ) {
        let (registry, dir) = pl3_registry(flag_line);
        let mut world = mir2_world_bevy::World::with_maps(vec![(16, 16)]);
        world.open_session("p25a");
        let mut ent = new_player_entity("p25a".to_string(), 2, 2);
        ent.hp = hp;
        ent.max_hp = max_hp;
        let actor = world.enter_map("p25a", ent, 0).unwrap();
        let mut sg = test_session_ground(actor);
        sg.state.wabil.hp = hp;
        sg.state.wabil.max_hp = max_hp;
        sg.show_hp = show_hp;
        // `DecHpTick/IncHpTick` ctor 不赋值 ⇒ 0（进图后第一次立即触发）。
        sg.dec_hp_tick = 0;
        sg.inc_hp_tick = 0;
        let mut sessions = HashMap::new();
        sessions.insert("p25a".to_string(), sg);
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(&mut online, entry("a", "p25a", 1, 0, 901, actor));
        let (tx, rx) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates = HashMap::new();
        gates.insert(0u8, tx);
        (world, sessions, online, gates, rx, actor, registry, dir)
    }

    /// **B4 #8（`drain_player_map_hp`）表征测试 —— 无牙（当前不可观测）**：
    /// 出口只进 `RunFrames`（`BTreeMap<i32,Slot>`，flush 按 **actor_id** 升序）⇒ 跨会话输出与
    /// `names` 遍历序无关，删 sort 不会让本用例变红。按 opc-27 裁决走 (b)：把「优化前」的产出
    /// （帧逐字段 + 实体/会话状态）固化成字面量，供 `sort`→`sort_unstable` 的前后差分比对。
    #[test]
    fn map_hp_outputs_are_stable_characterization_no_tooth() {
        use mir2_protocol::frame::CommandMessage;
        use std::collections::HashMap;
        let (registry, dir) = pl3_registry("DECHP(1/10)");
        let names = [
            "kilo", "alpha", "mike", "bravo", "november", "charlie", "oscar", "delta",
        ];
        let mut world = mir2_world_bevy::World::with_maps(vec![(400, 400)]);
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        let mut online: OnlineRegistry = OnlineRegistry::new();
        let (tx0, mut rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let mut actor_of: HashMap<&str, i32> = HashMap::new();
        for (i, name) in names.iter().enumerate() {
            let name: &str = name;
            let x = 10 + i as i32 * 20;
            world.open_session(name);
            let id = world
                .enter_map(name, mir2_world_bevy::EntitySpawn::new(0, name, x, 10), 0)
                .expect("进世界");
            world.entities.get_mut(id).unwrap().vitals.hp = 100;
            world.entities.get_mut(id).unwrap().vitals.max_hp = 100;
            let mut sg = test_session_ground(id);
            sg.state.wabil.hp = 100;
            sg.state.wabil.max_hp = 100;
            sg.state.wabil.mp = 0;
            sg.state.wabil.max_mp = 0;
            sg.dec_hp_tick = 0;
            sg.inc_hp_tick = 0;
            sessions.insert(name.to_string(), sg);
            online_set(&mut online, entry("acct", name, 1, 0, 901 + i as i32, id));
            actor_of.insert(name, id);
        }
        let mut frames = game_svr::run_frames::RunFrames::new();
        drain_player_map_hp(
            &mut world,
            &mut sessions,
            &online,
            Some(&registry),
            1_001,
            &mut frames,
        );
        flush_run_frames(&mut frames, &world, &online, &sessions, &gates, 12);

        // 参考值（优化前实测固化）：每会话一条 53，载荷 (HP=90, MP=0, MaxHP=100)；
        // 顺序 = actor_id 升序 = 本构造的插入序（= `names` 数组序）。
        let mut got: Vec<(i32, u16, u16, u16)> = Vec::new();
        while let Ok(SimToGate::SendFrame { socket, body }) = rx0.try_recv() {
            let cm = CommandMessage::from_bytes(&body).expect("SM_* body 至少 12B");
            assert_eq!(cm.ident, mir2_protocol::messages::SM_HEALTHSPELLCHANGED);
            got.push((socket, cm.param, cm.tag, cm.series));
        }
        let want: Vec<(i32, u16, u16, u16)> = names
            .iter()
            .enumerate()
            .map(|(i, _)| (901 + i as i32, 90, 0, 100))
            .collect();
        assert_eq!(got, want, "drain_player_map_hp 的表征产出（帧逐字段）");
        for name in names {
            assert_eq!(
                world.entities.get(actor_of[name]).unwrap().hp,
                90,
                "实体 HP=90 ChrName={name}"
            );
            assert_eq!(
                sessions[name].state.wabil.hp, 90,
                "投影 HP=90 ChrName={name}"
            );
            assert_eq!(
                sessions[name].dec_hp_tick, 1_001,
                "DecHpTick 刷新 ChrName={name}"
            );
        }
        std::fs::remove_dir_all(dir).ok();
    }

    /// P25-1：`DECHP(1/10)`、HP=100 ⇒ `now=1001` 后 HP=90、一条 53；`==1000` 不触发。
    #[test]
    fn p25_dechp_updates_entity_and_emits_one_frame() {
        let (mut world, mut sessions, online, gates, mut rx, actor, registry, dir) =
            p25_fixture("DECHP(1/10)", 100, 100, false);
        let mut frames = game_svr::run_frames::RunFrames::new();
        drain_player_map_hp(
            &mut world,
            &mut sessions,
            &online,
            Some(&registry),
            1001,
            &mut frames,
        );
        flush_run_frames(&mut frames, &world, &online, &sessions, &gates, 12);
        assert_eq!(world.entities.get(actor).unwrap().hp, 90);
        assert_eq!(sessions.get("p25a").unwrap().state.wabil.hp, 90);
        assert_eq!(
            take_frame_idents(&mut rx),
            vec![mir2_protocol::messages::SM_HEALTHSPELLCHANGED]
        );
        // 恰好 1000 ⇒ 严格 `>` 不触发。
        let mut frames = game_svr::run_frames::RunFrames::new();
        drain_player_map_hp(
            &mut world,
            &mut sessions,
            &online,
            Some(&registry),
            2001,
            &mut frames,
        );
        flush_run_frames(&mut frames, &world, &online, &sessions, &gates, 12);
        assert_eq!(world.entities.get(actor).unwrap().hp, 90);
        assert!(take_frame_idents(&mut rx).is_empty());
        std::fs::remove_dir_all(dir).ok();
    }

    /// **P25-6 核心牙（INCHP bug）**：`DECHP(1/10)+INCHP(1/7)`、HP=50/Max=100
    /// ⇒ 同 Run 恰 **1** 条 53（头-only 去重），载荷 HP=**50**（40+10，不是 47）。
    #[test]
    fn p25_dechp_plus_inchp_one_frame_with_final_payload() {
        let (mut world, mut sessions, online, gates, mut rx, actor, registry, dir) =
            p25_fixture("DECHP(1/10) INCHP(1/7)", 50, 100, false);
        let mut frames = game_svr::run_frames::RunFrames::new();
        drain_player_map_hp(
            &mut world,
            &mut sessions,
            &online,
            Some(&registry),
            1001,
            &mut frames,
        );
        flush_run_frames(&mut frames, &world, &online, &sessions, &gates, 12);
        assert_eq!(world.entities.get(actor).unwrap().hp, 50);
        let mut bodies = Vec::new();
        while let Ok(SimToGate::SendFrame { body, .. }) = rx.try_recv() {
            bodies.push(body);
        }
        assert_eq!(bodies.len(), 1, "同组 SendUpdateMsg 头-only 去重 ⇒ 恰 1 条");
        // 53 的载荷在出队时读 `WAbil` ⇒ HP=50。
        if game_svr::smframe::client_layout_enabled() {
            let desc = mir2_protocol::edcode::decode(&bodies[0][12..]);
            let at = |o: usize| i32::from_le_bytes(desc[o..o + 4].try_into().unwrap());
            assert_eq!(at(0), 50, "Feature = HP（终态）");
        }
        std::fs::remove_dir_all(dir).ok();
    }

    /// P25-7：`INCHP`-only（`nDECHPPOINT=0`）⇒ HP 不变，但每周期仍出一条 53。
    #[test]
    fn p25_inchp_only_noop_but_emits_each_period() {
        let (mut world, mut sessions, online, gates, mut rx, actor, registry, dir) =
            p25_fixture("INCHP(1/7)", 50, 100, false);
        for now in [1001_i64, 2002] {
            let mut frames = game_svr::run_frames::RunFrames::new();
            drain_player_map_hp(
                &mut world,
                &mut sessions,
                &online,
                Some(&registry),
                now,
                &mut frames,
            );
            flush_run_frames(&mut frames, &world, &online, &sessions, &gates, 12);
            assert_eq!(
                take_frame_idents(&mut rx),
                vec![mir2_protocol::messages::SM_HEALTHSPELLCHANGED],
                "now={now}"
            );
        }
        assert_eq!(world.entities.get(actor).unwrap().hp, 50, "加 0 点");
        std::fs::remove_dir_all(dir).ok();
    }

