    // ---- CM_DROPGOLD / CM_BUTCH 深体 RNG 合同（卡 `openmir2-inbound-dropgold-rng`，tier R） ----

    /// 卡 `openmir2-inbound-dropgold-rng` 的派发夹具：`hero` 落格 + `corpse`（动物尸）+ 帧表 + 种子。
    ///
    /// 返回 `(world, hero, corpse, sessions, online, gates, rx, cfg, displays, pwd_sessions)`；
    /// 调用方在首个 `world.tick()`（落格）之后才可重设 `world.rng`（`Enter` 本身不抽数，
    /// 但夹具统一在落格后钉种子，避免把落格序算进流位）。
    #[allow(clippy::type_complexity)]
    fn dropgold_butch_rig(
        seed: i32,
        with_corpse: bool,
    ) -> (
        mir2_world_bevy::World,
        i32,
        i32,
        HashMap<String, SessionGround>,
        OnlineRegistry,
        HashMap<u8, mpsc::UnboundedSender<SimToGate>>,
        mpsc::UnboundedReceiver<SimToGate>,
        GroundCfg,
        downlink::DisplayTable,
        std::collections::HashMap<String, game_svr::inbound::PwdSession>,
    ) {
        let mut world = mir2_world_bevy::World::new(32, 32);
        let hero = world.add_entity({
            let mut e = mir2_world_bevy::EntitySpawn::new(1, "hero", 10, 10);
            e.race = mir2_world_bevy::ACTOR_RACE_PLAY;
            e.want_ref_msg = true;
            e
        });
        let mut corpse_id = 0;
        if with_corpse {
            // (12,9)：`|Δx|=2` 恰在闭边界；race 53 = AnimalWolf（`Animal` 且 ∈ [50,80)）。
            let mut corpse = mir2_world_bevy::EntitySpawn::new(0, "corpse", 12, 9);
            corpse.race = 53;
            corpse.death = true;
            corpse.ai.dir = 5;
            corpse_id = world.add_entity(corpse);
        }
        // 落格（`Envir.IsValidObject` 读格内成员关系），随后钉种子。
        world.tick();
        world.rng = mir2_shared::rng::RandomNumber::with_seed(seed);

        let mut sg = test_session_ground(hero);
        sg.state.gold = 1_000;
        let mut sessions: HashMap<String, SessionGround> = HashMap::new();
        sessions.insert("hero".to_string(), sg);
        let mut online: OnlineRegistry = OnlineRegistry::new();
        online_set(
            &mut online,
            OnlineEntry {
                account: "ua".to_string(),
                chr_name: "hero".to_string(),
                session_id: 1,
                gate_idx: 0,
                socket: 901,
                actor_id: hero,
            },
        );
        let (tx0, rx0) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>> = HashMap::new();
        gates.insert(0, tx0);
        let cfg = GroundCfg {
            human_max_gold: 10_000_000,
            floor_item_can_pick_up_time: 120_000,
            control_drop_item: false,
            in_safe_disable_drop: false,
            can_drop_price: 500,
            can_drop_gold: 1000,
            drop_item_rage: 3,
        };
        let mut displays = downlink::DisplayTable::new();
        displays.set(
            hero,
            downlink::ActorDisplay::new(2, 0, 0, 0, 0, 255, Vec::new()),
        );
        if with_corpse {
            displays.set(
                corpse_id,
                downlink::ActorDisplay::new(5, 0, 0x0A_1234, 0, 0, 255, b"corpse".to_vec()),
            );
        }
        let pwd_sessions = std::collections::HashMap::new();
        (
            world,
            hero,
            corpse_id,
            sessions,
            online,
            gates,
            rx0,
            cfg,
            displays,
            pwd_sessions,
        )
    }

    /// 取 `world.rng` 之后的 `n` 个抽数（用于逐位比较流位）。
    fn rng_probe(rng: &mut mir2_shared::rng::RandomNumber, n: usize) -> Vec<i32> {
        (0..n).map(|_| rng.random_below(1_000_000)).collect()
    }

    /// **判据 A（R 片）**：`CM_DROPGOLD` 深体**零抽数**——oracle `ClientDropGold`
    /// （`PlayObject.Operate.cs:222-249`）→ `DropGoldDown`（`BaseObject.cs:735-771`）→
    /// `GetDropPosition`（`BaseObject.cs:470-527`，纯确定性格扫，**无 `Random`**）→
    /// `AddItemToMap`（`Envirnoment.cs:88-96`）**首行 `ItemId == 0 ⇒ false`**，而
    /// `MapItem` 的 ctor 已把 `ItemId` 自增**注释掉**（`SystemModule/Data/MapItem.cs:39-42`）
    /// ⇒ `DropGoldDown` **恒 false**（BUG-REPLICA 2）⇒ 金币净不变，但 `GoldChanged()` 照发。
    ///
    /// 本用例钉三件事：① 世界 RNG 流位**逐位不变**（= 0 抽）；② 653 帧的 `Recog` = 净金币（不变）；
    /// ③ 金币数只取 `recog`（wire：`MakeMessage(CM_DROPGOLD, dropgold, …)`，`RobotPlayer.cs:4898`），
    /// `param/tag/series` 不参与。
    ///
    /// 牙（实测）：在派发臂里插一次 `world.rng.random_below(2)` ⇒ ①红；把 `client_drop_gold`
    /// 的净金币改成 `gold - n_gold` ⇒ ②红。
    #[test]
    fn cm_dropgold_deep_body_draws_zero_rng_and_emits_goldchanged() {
        const SEED: i32 = 20_261_025;
        let (
            mut world,
            _hero,
            _corpse,
            mut sessions,
            online,
            gates,
            mut rx,
            cfg,
            displays,
            mut pwd,
        ) = dropgold_butch_rig(SEED, false);
        let mut probe = world.rng.clone();

        handle_inbound_cmd(
            &CommandMessage {
                recog: 300, // nGold（wire：recog = nParam1）
                ident: mir2_protocol::messages::CM_DROPGOLD,
                param: 7,  // 不参与（三值互异，防字段错位假绿）
                tag: 8,    // 不参与
                series: 9, // 不参与
            },
            None,
            "hero",
            901,
            &online,
            &mut world,
            &mut sessions,
            &gates,
            None,
            None,
            &mut pwd,
            &cfg,
            &displays,
            &test_frames_ctx(&game_svr::ability::StdItemCatalog::new()),
        );

        let frames = drain_frames(&mut rx);
        assert_eq!(frames.len(), 1, "过门 ⇒ 恰好一条 SM_GOLDCHANGED");
        let f = &frames[0];
        assert_eq!(
            u16::from_le_bytes([f[4], f[5]]),
            mir2_protocol::messages::SM_GOLDCHANGED
        );
        assert_eq!(
            i32::from_le_bytes([f[0], f[1], f[2], f[3]]),
            1_000,
            "Recog = 净金币（BUG-REPLICA 2：减了又加回 ⇒ 不变，牙=改成真扣则红）"
        );
        assert_eq!(sessions["hero"].state.gold, 1_000, "会话金币净不变");

        let after = rng_probe(&mut world.rng, 16);
        let expect = rng_probe(&mut probe, 16);
        assert_eq!(after, expect, "CM_DROPGOLD 深体必须零抽数（流位逐位相同）");
    }

    /// **判据 B**：`CM_DROPGOLD` 的另两道门同样零抽数、零金币副作用——
    /// `nGold >= Gold` ⇒ 静默 return（零帧）；`ControlDropItem && nGold < CanDropGold`
    /// ⇒ `SM_MENU_OK(767)` 拒绝且金币不变。
    ///
    /// 牙（实测）：删 `client_drop_gold` 的 `nGold >= Gold` 门 ⇒ 第一段红（多一条 653）。
    #[test]
    fn cm_dropgold_gates_draw_zero_rng() {
        const SEED: i32 = 20_261_026;
        // ① nGold == Gold ⇒ 零帧、零抽数。
        let (mut world, _hero, _c, mut sessions, online, gates, mut rx, cfg, displays, mut pwd) =
            dropgold_butch_rig(SEED, false);
        let mut probe = world.rng.clone();
        handle_inbound_cmd(
            &CommandMessage {
                recog: 1_000,
                ident: mir2_protocol::messages::CM_DROPGOLD,
                param: 0,
                tag: 0,
                series: 0,
            },
            None,
            "hero",
            901,
            &online,
            &mut world,
            &mut sessions,
            &gates,
            None,
            None,
            &mut pwd,
            &cfg,
            &displays,
            &test_frames_ctx(&game_svr::ability::StdItemCatalog::new()),
        );
        assert!(drain_frames(&mut rx).is_empty(), "nGold >= Gold ⇒ 零出帧");
        assert_eq!(rng_probe(&mut world.rng, 8), rng_probe(&mut probe, 8));

        // ② ControlDropItem ⇒ 500 < 1000 被拒 ⇒ SM_MENU_OK(767)，金币不变、零抽数。
        let (mut world, _hero, _c, mut sessions, online, gates, mut rx, mut cfg, displays, mut pwd) =
            dropgold_butch_rig(SEED, false);
        cfg.control_drop_item = true;
        let mut probe = world.rng.clone();
        handle_inbound_cmd(
            &CommandMessage {
                recog: 500,
                ident: mir2_protocol::messages::CM_DROPGOLD,
                param: 0,
                tag: 0,
                series: 0,
            },
            None,
            "hero",
            901,
            &online,
            &mut world,
            &mut sessions,
            &gates,
            None,
            None,
            &mut pwd,
            &cfg,
            &displays,
            &test_frames_ctx(&game_svr::ability::StdItemCatalog::new()),
        );
        let frames = drain_frames(&mut rx);
        assert_eq!(frames.len(), 1, "拒绝 ⇒ 一条 SM_MENU_OK");
        assert_eq!(
            u16::from_le_bytes([frames[0][4], frames[0][5]]),
            mir2_protocol::messages::SM_MENU_OK
        );
        // 卡 `openmir2-menu-ok-text`（第 4 个生产者）：拒绝帧**带尾**，文案 = `CanotDropGoldMsg`。
        assert_eq!(
            mir2_protocol::edcode::decode(&frames[0][12..]),
            game_svr::downlink::gbk(crate::strings::DEFAULT_CANOT_DROP_GOLD_MSG),
            "CM_DROPGOLD 拒绝文案 = MessageSettings.CanotDropGoldMsg"
        );
        assert_eq!(sessions["hero"].state.gold, 1_000);
        assert_eq!(rng_probe(&mut world.rng, 8), rng_probe(&mut probe, 8));
    }

    /// **判据 C（ButchEffect RNG，与 DROPGOLD 同一条 `M2Share.RandomNumber` 流）**：
    /// `ClientGetButchItem` 效果体（`PlayObject.Operate.cs:722-723`）**先 `Random(16)+5`、
    /// 后 `Random(201)+100`**；本仓 `World::butch_effect_now` 已按该序接线（`CM_BUTCH` ⇒
    /// `Command::ButchEffect` ⇒ tick 结算）。本用例从**生产派发面**钉：同 seed 的抽数逐位一致、
    /// 恰两次、状态落值正确、流位停在第二抽之后。
    ///
    /// 牙（实测）：把两抽对调 ⇒ 状态断言红；删第二抽（常量顶替）⇒ 流位断言红。
    #[test]
    fn cm_butch_effect_two_draw_sequence_is_bit_exact() {
        const SEED: i32 = 20_261_027;
        let (mut world, hero, corpse, mut sessions, online, gates, _rx, cfg, displays, mut pwd) =
            dropgold_butch_rig(SEED, true);
        {
            let e = world.entities.get_mut(corpse).unwrap();
            e.ai.body_leathery = 255;
            e.ai.meat_quality = 2_000;
        }
        let mut probe = world.rng.clone();
        let d1 = u8::try_from(probe.random_below(16) + 5).unwrap();
        let d2 = u16::try_from(probe.random_below(201) + 100).unwrap();
        let tail = rng_probe(&mut probe, 8);

        handle_inbound_cmd(
            &CommandMessage {
                recog: corpse,
                ident: mir2_protocol::messages::CM_BUTCH,
                param: 12,
                tag: 9,
                series: 4,
            },
            None,
            "hero",
            901,
            &online,
            &mut world,
            &mut sessions,
            &gates,
            None,
            None,
            &mut pwd,
            &cfg,
            &displays,
            &test_frames_ctx(&game_svr::ability::StdItemCatalog::new()),
        );
        assert_eq!(world.entities.get(hero).unwrap().ai.dir, 4);
        let rec = world.tick();
        assert_eq!(rec.skeletons.len(), 0, "255-d1 > 0 ⇒ 不出骨架");

        let e = world.entities.get(corpse).unwrap();
        assert_eq!(
            e.ai.body_leathery,
            255u8.wrapping_sub(d1),
            "第 1 抽 = Random(16)+5"
        );
        assert_eq!(
            e.ai.meat_quality,
            2_000u16.wrapping_sub(d2),
            "第 2 抽 = Random(201)+100"
        );
        assert_eq!(
            rng_probe(&mut world.rng, 8),
            tail,
            "恰好两次抽数：流位停在第二抽之后（逐位）"
        );
    }

    /// **判据 D**：`CM_BUTCH` 的门未过（`|Δ|>2`）⇒ 效果体不执行 ⇒ **零抽数**（流位不变），
    /// `RM_BUTCH` 仍发（`Operate.cs:749` 无条件）。
    #[test]
    fn cm_butch_gate_fail_draws_zero_rng() {
        const SEED: i32 = 20_261_028;
        let (mut world, _hero, corpse, mut sessions, online, gates, _rx, cfg, displays, mut pwd) =
            dropgold_butch_rig(SEED, true);
        let before = world.entities.get(corpse).unwrap().ai.body_leathery;
        let mut probe = world.rng.clone();
        handle_inbound_cmd(
            &CommandMessage {
                recog: corpse,
                ident: mir2_protocol::messages::CM_BUTCH,
                param: 20, // |20-10| = 10 > 2
                tag: 9,
                series: 4,
            },
            None,
            "hero",
            901,
            &online,
            &mut world,
            &mut sessions,
            &gates,
            None,
            None,
            &mut pwd,
            &cfg,
            &displays,
            &test_frames_ctx(&game_svr::ability::StdItemCatalog::new()),
        );
        let rec = world.tick();
        assert_eq!(rec.butches.len(), 1, "RM_BUTCH 无条件发");
        assert_eq!(
            world.entities.get(corpse).unwrap().ai.body_leathery,
            before,
            "门未过 ⇒ 效果体不执行"
        );
        assert_eq!(
            rng_probe(&mut world.rng, 8),
            rng_probe(&mut probe, 8),
            "零抽数"
        );
    }

    // ---- handler 级 MsgQueue 统一（卡 `openmir2-script-handler-msgqueue`，tier R） ----------

    /// **判据（M-3，review f215e887）**：`RM_USERGETBACKITEM` → `SendSaveItemList` 一次调用
    /// **顺序发多页**（`PlayObject.Base.cs:1600-1622` 的 `for page ... SendSocket`）⇒ 队列里是
    /// **一条消息**，出队时按页序连发，绝不被四叉堆按同优先级（163）打散。
    ///
    /// 牙（实测）：去掉 `atomic_batch` 分组合并（逐页单独入堆）⇒ 3 页同优先级会按堆序出队
    /// `[0,2,1]`，本用例红。
    #[test]
    fn handler_msgqueue_getback_pages_keep_page_order_as_one_message() {
        let (tx, mut rx) = mpsc::unbounded_channel::<SimToGate>();
        let mut q = HandlerMsgQueue::new(Some(tx), 7);
        let mk = |page: u16| game_svr::shop::ShopFrame {
            ident: mir2_protocol::messages::SM_SAVEITEMLIST,
            recog: 1,
            param: 0,
            tag: page,
            series: 2,
            tail: Vec::new(),
            tail_encoded: true,
            queue_priority: Some((mir2_protocol::messages::RM_USERGETBACKITEM & 0xFF) as u8),
            atomic_batch: true,
        };
        emit_shop_frames_into(&mut q, &[mk(0), mk(1), mk(2)]);
        q.flush();
        let mut pages = Vec::new();
        while let Ok(SimToGate::SendFrame { body, .. }) = rx.try_recv() {
            pages.push(u16::from_le_bytes([body[8], body[9]]));
        }
        assert_eq!(
            pages,
            vec![0u16, 1, 2],
            "多页必须按页序连发（一条队列消息）"
        );
    }

    /// 本卡判据用的 rig：`T142Rig` + 预置 `@buy` 可跳（`LableIsCanJmp` 账本）。
    fn handler_msgqueue_rig(records: Vec<mir2_script::SayingRecord>) -> T142Rig {
        let mut rig = T142Rig::new(records);
        rig.shop_sessions
            .entry("hero".to_string())
            .or_default()
            .can_jmp_labels = game_svr::shop::get_script_label("<确定/@buy>");
        rig
    }

    fn ident_of(body: &[u8]) -> u16 {
        u16::from_le_bytes([body[4], body[5]])
    }

    /// **判据 ③（等价保持）**：只有说词 + 脚本帧、没有面板帧时，合并前后帧序**完全一致**：
    /// 说词优先级 0/1 恒先于脚本帧（`RM_MENU_OK` = 10309 & 0xFF = 69）。
    ///
    /// 牙（实测）：让 says 直连绕队（在 `emit_merchant_goto_result` 里直接 `tx.send`）⇒
    /// 说词会排到脚本帧之后（本用例红）。
    #[test]
    fn handler_msgqueue_says_plus_script_order_is_unchanged_by_merge() {
        let mut rig = handler_msgqueue_rig(vec![t142_record(
            "@main",
            "hello",
            vec![t142_act(234, "m", 0, "")],
        )]);
        rig.dlg_select("@main");
        let frames = drain_frames(&mut rig.rx);
        let idents: Vec<u16> = frames.iter().map(|b| ident_of(b)).collect();
        assert_eq!(
            idents,
            vec![
                mir2_protocol::messages::SM_MERCHANTSAY,
                mir2_protocol::messages::SM_MENU_OK
            ],
            "说词(1) 恒先于脚本帧(69)；合并前后一致"
        );
    }

    /// **判据 ②（核心：面板 + 脚本帧同 handler）**：`@buy` 走 `GotoLable(@buy)`（说词 + 脚本帧
    /// `RM_MENU_OK`=69 / `RM_GAMEGOLDCHANGED`=148）后 `UserSelectBuyItem` 产出
    /// `RM_SENDGOODSLIST`=144；另加 `CHANGEEXP` ⇒ `RM_WINEXP`=139（落在 133 与 144 之间，
    /// 用于把「错用 SM ident 低字节」的变异打红）⇒ **同一堆按 `(byte)RM` 升序**：
    /// 643(say,1) → 767(69) → 44(139) → 645(144) → 5008(148)。
    ///
    /// 旧实现（直连 `out`）给的是 643 → 767 → **5008 → 645**；本用例同时断言它与旧序不同，
    /// 证明「合并改变帧序」只发生在 oracle 要求的组合上。
    ///
    /// 牙（实测）：① 把面板帧改回直连（`emit_shop_frames_into` 里 `None => direct` 改成全部
    /// 直连）⇒ 面板被提前到堆前，本用例红；② 面板优先级用 SM ident 低字节而非 `(byte)RM` ⇒ 红。
    #[test]
    fn handler_msgqueue_panel_and_script_interleave_by_rm_priority() {
        let mut rig = handler_msgqueue_rig(vec![
            t142_record("@main", "@buy", vec![]),
            t142_record(
                "@buy",
                "hi",
                vec![
                    t142_act(234, "m", 0, ""),
                    t142_act(185, "+", 0, "5"),
                    t142_act(191, "+", 0, "5"),
                ],
            ),
        ]);
        rig.dlg_select("@main"); // 让 `@buy` 进 `can_jmp_labels`（说词含 @buy）
        let _ = drain_frames(&mut rig.rx);
        rig.dlg_select("@buy");
        let frames = drain_frames(&mut rig.rx);
        let idents: Vec<u16> = frames.iter().map(|b| ident_of(b)).collect();
        assert_eq!(
            idents,
            vec![
                mir2_protocol::messages::SM_MERCHANTSAY,
                mir2_protocol::messages::SM_MENU_OK,
                mir2_protocol::messages::SM_WINEXP,
                mir2_protocol::messages::SM_SENDGOODSLIST,
                mir2_protocol::messages::SM_GAMEGOLDNAME,
            ],
            "同一 MsgQueue：说词(1) → MENU_OK(69) → WINEXP(139) → SENDGOODSLIST(144) → GAMEGOLD(148)"
        );
        assert_ne!(
            idents,
            vec![
                mir2_protocol::messages::SM_MERCHANTSAY,
                mir2_protocol::messages::SM_MENU_OK,
                mir2_protocol::messages::SM_WINEXP,
                mir2_protocol::messages::SM_GAMEGOLDNAME,
                mir2_protocol::messages::SM_SENDGOODSLIST,
            ],
            "旧实现（out 直连）是 5008 在 645 之前；合并后必须不同"
        );
    }

    /// **同优先级仍走 .NET 四叉堆序**（并入同一队后不得退化成稳定排序）：3 条 `MESSAGEBOX`
    /// （同 `RM_MENU_OK`=69）出队 `[0,2,1]` ⇒ 文本序 a, c, b。
    ///
    /// 牙（实测）：把 `HandlerMsgQueue` 的堆换成 `sort_by_key`/FIFO ⇒ 本用例红（a, b, c）。
    #[test]
    fn handler_msgqueue_ties_keep_four_ary_heap_order() {
        let mut rig = handler_msgqueue_rig(vec![t142_record(
            "@main",
            "",
            vec![
                t142_act(234, "a", 0, ""),
                t142_act(234, "b", 0, ""),
                t142_act(234, "c", 0, ""),
            ],
        )]);
        rig.dlg_select("@main");
        let frames = drain_frames(&mut rig.rx);
        assert_eq!(frames.len(), 3, "3 条 SM_MENU_OK");
        let tails: Vec<Vec<u8>> = frames.iter().map(|b| b[12..].to_vec()).collect();
        let enc = |s: &[u8]| mir2_protocol::edcode::encode(s);
        assert_eq!(
            tails,
            vec![enc(b"a"), enc(b"c"), enc(b"b")],
            "同优先级 3 条 ⇒ 四叉堆序 [0,2,1]"
        );
    }

    /// **卡 `openmir2-butch-rng-contract-hardening`（L；review `e26812b48` R-4）**：`CM_BUTCH` 效果体
    /// 的**逐位** RNG 合同改**硬编码字面量**（不再用同实现反推），并加第二个 seed：
    /// 两个 seed 都满足 `next_max(16) ≠ next_max(15)` 且 `next_max(201) ≠ next_max(200)`，
    /// 因此把 `random_below(16)` 改成 `(15)` 或 `(201)` 改成 `(200)` 必红。
    ///
    /// oracle：`PlayObject.Operate.cs:722-723` 先 `Random(16)+5`、后 `Random(201)+100`；
    /// 本文的 d1/d2 是 `with_seed` 下**前两抽**的字面量（seed 20261015: 13/166 ⇒ 18/266；
    /// seed 20261028: 10/129 ⇒ 15/229）。
    ///
    /// 牙（实测）：模数 16→15 ⇒ 本用例红（d1 少 1）；201→200 ⇒ 红（d2 少 1）；两抽对调 ⇒ 红。
    #[test]
    fn butch_effect_draw_values_are_hardcoded_for_two_seeds() {
        // (seed, 第 1 抽 Random(16)+5, 第 2 抽 Random(201)+100, 其后 3 抽的硬编码值)
        const CASES: [(i32, u8, u16, [i32; 3]); 2] = [
            (20_261_015, 18, 266, [927_908, 976_396, 551_707]),
            (20_261_028, 15, 229, [14_752, 751_154, 421_021]),
        ];
        for (seed, draw1, draw2, tail) in CASES {
            let (
                mut world,
                _hero,
                corpse,
                mut sessions,
                online,
                gates,
                _rx,
                cfg,
                displays,
                mut pwd,
            ) = dropgold_butch_rig(seed, true);
            {
                let e = world.entities.get_mut(corpse).unwrap();
                e.ai.body_leathery = 255;
                e.ai.meat_quality = 2_000;
            }
            handle_inbound_cmd(
                &CommandMessage {
                    recog: corpse,
                    ident: mir2_protocol::messages::CM_BUTCH,
                    param: 12,
                    tag: 9,
                    series: 4,
                },
                None,
                "hero",
                901,
                &online,
                &mut world,
                &mut sessions,
                &gates,
                None,
                None,
                &mut pwd,
                &cfg,
                &displays,
                &test_frames_ctx(&game_svr::ability::StdItemCatalog::new()),
            );
            let rec = world.tick();
            assert!(
                rec.skeletons.is_empty(),
                "seed={seed}: 皮革未归零 ⇒ 不出骨架"
            );

            let e = world.entities.get(corpse).unwrap();
            assert_eq!(
                e.ai.body_leathery,
                255u8.wrapping_sub(draw1),
                "seed={seed}：第 1 抽必须是 Random(16)+5 = {draw1}（硬编码；模数 15 会给 {}）",
                draw1 - 1
            );
            assert_eq!(
                e.ai.meat_quality,
                2_000u16.wrapping_sub(draw2),
                "seed={seed}：第 2 抽必须是 Random(201)+100 = {draw2}（硬编码；模数 200 会给 {}）",
                draw2 - 1
            );
            // 区间合同（`Random(16)+5 ∈ [5,20]`、`Random(201)+100 ∈ [100,300]`）。
            let got1 = 255u8 - e.ai.body_leathery;
            let got2 = 2_000u16 - e.ai.meat_quality;
            assert!(
                (5..=20).contains(&got1),
                "seed={seed}: 第 1 抽 {got1} 越界 [5,20]"
            );
            assert!(
                (100..=300).contains(&got2),
                "seed={seed}: 第 2 抽 {got2} 越界 [100,300]"
            );

            // 流位：恰好两次抽数；其后 3 抽与硬编码字面量逐位相同。
            let got_tail: Vec<i32> = (0..3).map(|_| world.rng.random_below(1_000_000)).collect();
            assert_eq!(
                got_tail,
                tail.to_vec(),
                "seed={seed}：流位必须恰停在第 2 抽之后（后续抽数逐位硬编码）"
            );
        }
    }

    /// **模数边界合同（review R-4 ③）**：把 15/16 与 200/201 两侧的字面量都钉死，
    /// 使「模数选错」在**同一断言面**上可见。
    ///
    /// 牙（实测）：把 `random_below(16)` 改成 `(15)` ⇒ 第一条红；`(201)`→`(200)` ⇒ 第二条红。
    #[test]
    fn butch_draw_modulus_boundaries_are_pinned() {
        const SEED: i32 = 20_261_015;
        let mut a = mir2_shared::rng::RandomNumber::with_seed(SEED);
        assert_eq!(
            a.random_below(16),
            13,
            "第 1 抽模数 = 16（模数 15 会给 12）"
        );
        assert_eq!(
            a.random_below(201),
            166,
            "第 2 抽模数 = 201（模数 200 会给 165）"
        );
        assert_eq!(
            mir2_shared::rng::RandomNumber::with_seed(SEED).random_below(15),
            12,
            "15 侧字面量（对照）"
        );
        let mut c = mir2_shared::rng::RandomNumber::with_seed(SEED);
        let _ = c.random_below(16);
        assert_eq!(c.random_below(200), 165, "200 侧字面量（对照）");
    }
    // ==================== 脚本 GMEXECUTE 桥宿主通道（卡 `openmir2-gmexe-bridge-channels`）====================

    /// 脚本桥夹具：32×32 全零地图（逻辑名 `map` ⇒ map_id 0）+ 刷怪宿主（`mob`）+ 玩家
    /// `hero`（ActorId=1，`ai.dir=2` ⇒ 面前格 (6,5)）+ 前方活人 `victim` + 会话/存档/收帧
    /// 通道 + 进程级全局单元（`FilterWord`/`Mission`/`SpiritMutinyTick`）。
    struct ScriptBridgeRig {
        fx: ClearMapRegistry,
        world: mir2_world_bevy::World,
        mon_host: game_svr::mongen::MonGenHost,
        table: game_svr::mongen::MonsterTable,
        displays: downlink::DisplayTable,
        sessions: HashMap<String, SessionGround>,
        saves: HashMap<String, SavedHuman>,
        online: OnlineRegistry,
        gates: HashMap<u8, mpsc::UnboundedSender<SimToGate>>,
        rx: mpsc::UnboundedReceiver<SimToGate>,
        guilds: mir2_world_bevy::GuildManager,
        guild_cfg: mir2_world_bevy::GuildConfig,
        colors: MsgColors,
        enter_cfg: EnterConfig,
        filter_word: std::cell::Cell<bool>,
        mission: std::cell::RefCell<gmcmd::GmMissionState>,
        spirit_mutiny_tick: std::cell::Cell<i64>,
        actor: i32,
        victim: i32,
        item_number: std::sync::atomic::AtomicI32,
    }

    impl ScriptBridgeRig {
        fn new() -> Self {
            let fx = clear_map_registry("map");
            let mut world = mir2_world_bevy::World::new(32, 32);
            world.rng = mir2_shared::rng::RandomNumber::with_seed(2026_1031);
            let mut hero = mir2_world_bevy::EntitySpawn::new(1, "hero", 5, 5);
            hero.race = mir2_world_bevy::ACTOR_RACE_PLAY;
            hero.ai.dir = 2; // `Direction.Right` ⇒ 面前格 (x+1, y) = (6,5)
            let actor = world.add_entity(hero);
            let mut victim = mir2_world_bevy::EntitySpawn::new(2, "victim", 6, 5);
            victim.race = mir2_world_bevy::ACTOR_RACE_PLAY;
            let victim = world.add_entity(victim);
            let table =
                game_svr::mongen::MonsterTable::new(vec![m_monster_row("mob", 80, 5, 10, 100)]);
            let entries = vec![mir2_world_bevy::mongen::MonGenEntry::new(
                "map", 5, 5, "mob", 1, 1, 0, 0,
            )];
            let mon_host = game_svr::mongen::MonGenHost::start(
                entries,
                &table,
                false,
                mir2_world_bevy::mongen::MonGenConfig::default(),
                &mut world.rng,
            );
            let mut sessions = HashMap::new();
            let mut sg = test_session_ground(actor);
            sg.gm.permission = 10;
            sg.state.wabil.weight = 0;
            sg.state.wabil.max_weight = 10_000;
            sessions.insert("hero".to_string(), sg);
            let mut saves = HashMap::new();
            for (name, account) in [("hero", "h"), ("victim", "v")] {
                saves.insert(
                    name.to_string(),
                    SavedHuman {
                        account: account.to_string(),
                        record: record::PlayerRecord::default(),
                        enter_map: "0".to_string(),
                        derived: None,
                    },
                );
            }
            let mut online: OnlineRegistry = OnlineRegistry::new();
            online_set(&mut online, entry("h", "hero", 1, 0, 901, actor));
            online_set(&mut online, entry("v", "victim", 2, 0, 902, victim));
            let (tx, rx) = mpsc::unbounded_channel::<SimToGate>();
            let mut gates = HashMap::new();
            gates.insert(0, tx);
            // `@Level0` 的 `HasLevelUp` 读 `Config.NeedExps[nLevel]`（`get_level_exp` 直接下标）
            // ⇒ 夹具必须给足长度（生产来自 `Exps.conf`）。
            let mut enter_cfg = EnterConfig::for_test(strings::parse(b"[String]\n"));
            enter_cfg.need_exps = vec![1000; mir2_data::models::MAX_LEVEL as usize + 1];
            Self {
                fx,
                world,
                mon_host,
                table,
                displays: downlink::DisplayTable::new(),
                sessions,
                saves,
                online,
                gates,
                rx,
                guilds: mir2_world_bevy::GuildManager::new(),
                guild_cfg: mir2_world_bevy::GuildConfig::default(),
                colors: w_colors(),
                enter_cfg,
                filter_word: std::cell::Cell::new(true),
                mission: std::cell::RefCell::new(gmcmd::GmMissionState::default()),
                spirit_mutiny_tick: std::cell::Cell::new(0),
                actor,
                victim,
                item_number: std::sync::atomic::AtomicI32::new(1000),
            }
        }

        /// 经**脚本桥**执行一行 `@…`：等价 `ActionOfGmExecute` → `ProcessUserLineMsg`
        /// （脚本动作把 `Permission` 临时抬到 10，`NpcGm.GmWorld` 由 [`ScriptGmEnv::bridge`]
        /// 装配）。`wired=false` ⇒ 用未装配的 [`ScriptGmHost::default`]（退化兜底形态）。
        fn run_with_host(&mut self, line: &str, wired: bool) -> gmcmd::GmResult {
            let cfg = gmcmd::GmConfig::default();
            let pwd: HashMap<String, game_svr::inbound::PwdSession> = HashMap::new();
            let host = if wired {
                ScriptGmHost::for_event(
                    &self.filter_word,
                    &self.mission,
                    &self.spirit_mutiny_tick,
                    &self.saves,
                    &self.sessions,
                    &self.world,
                    "hero",
                )
            } else {
                ScriptGmHost::default()
            };
            let env = ScriptGmEnv {
                guilds: &self.guilds,
                maps: Some(&self.fx.registry),
                cfg: &cfg,
                pwd_sessions: &pwd,
                host,
            };
            let mut sess = std::mem::take(&mut self.sessions.get_mut("hero").unwrap().gm);
            sess.permission = 10; // `ActionOfGmExecute` 的 `PermissionGuard`
            let r = {
                let bridge = env.bridge(&mut sess, &self.world, "hero", self.actor);
                gmcmd::execute(bridge.sess, bridge.cfg, &bridge.world, line)
            };
            self.sessions.get_mut("hero").unwrap().gm = sess;
            r
        }

        fn run(&mut self, line: &str) -> gmcmd::GmResult {
            self.run_with_host(line, true)
        }

        /// 命令事件末尾的宿主收口（与 `sim_loop` 调用的**同一个入口函数**）。
        /// 返回重连队列/城堡广播正文（构造级用例按需断言）。
        fn drain(&mut self) -> ScriptDrainOutcome {
            let mut pwd_sessions: HashMap<String, game_svr::inbound::PwdSession> = HashMap::new();
            let mut reconnect_pending = Vec::new();
            let mut castle_broadcasts = Vec::new();
            let castle_war_states = HashMap::new();
            command_event_tail_gm_drain(
                &mut self.sessions,
                &mut pwd_sessions,
                &mut self.saves,
                &mut self.world,
                &mut self.displays,
                &self.online,
                &self.gates,
                Some(&mut self.mon_host),
                Some(&self.fx.registry),
                &self.table,
                &castle_war_states,
                &mut self.guilds,
                &self.guild_cfg,
                None,
                &self.colors,
                &self.enter_cfg,
                "hero",
                &mut reconnect_pending,
                &mut castle_broadcasts,
                &self.item_number,
            );
            ScriptDrainOutcome {
                reconnect: reconnect_pending,
            }
        }

        /// 取本夹具网关通道里的所有帧（按发出顺序）。
        fn frames(&mut self) -> Vec<Vec<u8>> {
            let mut out = Vec::new();
            while let Ok(msg) = self.rx.try_recv() {
                match msg {
                    SimToGate::SendFrame { body, .. } => out.push(body),
                    other => panic!("脚本 GM 收口不得发非帧消息：{other:?}"),
                }
            }
            out
        }
    }

    /// 事件末收口的可观察产物（构造级用例读重连队列）。
    #[derive(Debug, Default)]
    struct ScriptDrainOutcome {
        reconnect: Vec<ReconnectPending>,
    }

    /// **A1/A2（六组通道之一：全局单元）**：脚本桥注入 `FilterWord`/`Mission`/`SpiritMutinyTick`
    /// 后，`@DisableFilter`/`@Mission`/`@祈祷生效`/`@停止叛变` 经 `GMEXECUTE` 路径产生**真副作用**
    /// （进程级单元被写），而不是 `log_note` 退化零帧。
    ///
    /// 变异红：删 `for_event` 的任一全局单元注入 ⇒ 对应用例段 `log_note.is_some()` 红。
    #[test]
    fn script_bridge_injects_global_units_filter_mission_spirit() {
        let mut rig = ScriptBridgeRig::new();
        // @DisableFilter：`SystemShare.FilterWord` 翻转（部署启动 true）。
        assert!(rig.filter_word.get());
        let r = rig.run("@DisableFilter");
        assert!(r.found, "命令必须命中");
        assert!(r.log_note.is_none(), "装配后不得走退化：{:?}", r.log_note);
        assert!(!rig.filter_word.get(), "脚本桥必须真翻转全局 FilterWord");
        let _ = rig.run("@DisableFilter");
        assert!(rig.filter_word.get(), "第二敲翻回 true");
        // @Mission：写全局四元（图名取说话者当前图）+ 绿字。
        let r = rig.run("@Mission 100 200");
        assert!(r.log_note.is_none(), "装配后不得退化：{:?}", r.log_note);
        assert_eq!(r.msgs.len(), 1, "足参 ⇒ 一条绿字");
        {
            let m = rig.mission.borrow();
            assert!(m.bo_mission, "BoMission 必须置真");
            assert_eq!(m.mission_map, "map", "地图名取说话者当前图");
            assert_eq!((m.mission_x, m.mission_y), (100, 200));
        }
        // @祈祷生效 / @停止叛变：写 `SystemShare.SpiritMutinyTick`。
        let r = rig.run("@祈祷生效 30");
        assert!(r.log_note.is_none(), "装配后不得退化：{:?}", r.log_note);
        assert_eq!(
            rig.spirit_mutiny_tick.get(),
            rig.world.clock_ms + 30_000,
            "tick = now + 参数秒*1000"
        );
        let r = rig.run("@停止叛变");
        assert!(r.log_note.is_none(), "装配后不得退化：{:?}", r.log_note);
        assert_eq!(rig.spirit_mutiny_tick.get(), 0, "停止叛变清零");
    }

    /// **A3（退化兜底必须保留）**：同一批命令在**未装配** [`ScriptGmHost`] 时仍走原退化形态
    /// （`log_note` 登记、零帧、不写全局）——脚本桥未接线/测试夹具的行为不回归。
    ///
    /// 变异红：删命令体的 `None` 退化分支（改成按全零伪造写）⇒ 本用例红。
    #[test]
    fn script_bridge_unwired_keeps_degenerate_fallbacks() {
        let mut rig = ScriptBridgeRig::new();
        let mission_before = rig.mission.borrow().clone();
        let r = rig.run_with_host("@Mission 100 200", false);
        assert!(r.msgs.is_empty(), "未装配 ⇒ 退化零帧");
        assert!(r.log_note.is_some(), "退化必须留痕（不静默伪造写）");
        assert_eq!(*rig.mission.borrow(), mission_before, "不得写全局四元");
        let r = rig.run_with_host("@DisableFilter", false);
        assert!(r.log_note.is_some(), "退化必须留痕");
        assert!(rig.filter_word.get(), "未装配 ⇒ 不得翻转全局位");
        let r = rig.run_with_host("@祈祷生效 30", false);
        assert!(r.log_note.is_some(), "退化必须留痕");
        assert_eq!(rig.spirit_mutiny_tick.get(), 0, "未装配 ⇒ 不得写 tick");
        let r = rig.run_with_host("@setflag victim 5 1", false);
        assert!(r.log_note.is_some(), "quests 未装配 ⇒ 退化留痕");
        assert!(
            rig.sessions["hero"].gm.pending_quest.is_none(),
            "未装配 ⇒ 不得装 pending（防陈旧写）"
        );
        let r = rig.run_with_host("@MobPlace 3 4 mob 1", false);
        assert!(r.log_note.is_some(), "m_host=false ⇒ 退化留痕");
        assert!(
            rig.sessions["hero"].gm.pending_spawn.is_none(),
            "未装配 ⇒ 不得装刷怪 pending"
        );
    }

    /// **A2（quests 通道）**：脚本桥注入会话任务位阵快照后，`@setflag` 经 `GMEXECUTE` 走真
    /// 路径（命令体装 `pending_quest`）⇒ 宿主收口把**调用者**位阵落进 `saves`（oracle 怪癖：
    /// 写调用者，不写目标）。
    #[test]
    fn script_bridge_quests_write_caller_flags_through_host_drain() {
        let mut rig = ScriptBridgeRig::new();
        let r = rig.run("@setflag victim 5 1");
        assert!(r.found, "命令必须命中");
        assert!(r.log_note.is_none(), "装配后不得退化：{:?}", r.log_note);
        assert!(
            rig.sessions["hero"].gm.pending_quest.is_some(),
            "命令体必须装 pending_quest（真路径）"
        );
        rig.drain();
        assert!(
            rig.sessions["hero"].gm.pending_quest.is_none(),
            "落地即清（一次性）"
        );
        let flag = rig.saves["hero"]
            .record
            .data
            .quest_flag
            .as_ref()
            .expect("写后必须建 128B 位阵");
        assert_eq!(flag.len(), 128, "oracle `new byte[128]`");
        let mut arr = [0u8; 128];
        arr.copy_from_slice(flag);
        let bits = mir2_script::engine::quest_state::QuestBitmap::from_bytes(arr);
        assert_eq!(bits.get(5), 1, "调用者 hero 的 QuestFlag 位 5 = ON");
        assert!(
            rig.saves["victim"].record.data.quest_flag.is_none(),
            "写调用者，不写目标（oracle 怪癖）"
        );
    }

    /// **A2（m_host + mission 通道）**：脚本桥注入 `mission` + `m_host` 后，`@MobPlace` 经
    /// `GMEXECUTE` 走真路径（命令体装 `pending_spawn`）⇒ 宿主收口**真刷出怪**。
