        assert_eq!(per.get(&(904, struck)), None, "|Δ|=12：31 被挡");
        assert_eq!(per.get(&(904, name)), None, "|Δ|=12：656 被挡");
        assert_eq!(per.get(&(905, nc)), None, "+13：零帧");
