    /// **M1c-3a 静态牙 `make_drug_local_arm_has_no_process_state`**：本地臂/执行体**不得**出现
    /// 进程态符号（`npc_vars`/`npc_host`/`merchant_book`/`script_world`/`sell_off_book`/`proc_svc!`）。
    #[test]
    fn make_drug_local_arm_has_no_process_state() {
        let src = include_str!("lib.rs");
        let prod = &src[..src.find("mod tests {").expect("生产面边界")];
        let f = prod.find("fn make_drug_zone_local(").expect("执行体定义");
        let f_end = prod[f..].find("\n}\n").map_or(prod.len(), |k| f + k + 3);
        let body = &prod[f..f_end];
        for sym in [
            "npc_vars",
            "npc_host",
            "merchant_book",
            "script_world",
            "sell_off_book",
            "proc_svc!",
        ] {
            assert!(
                !body.contains(sym),
                "药物合成执行体不得引用进程态符号 `{sym}`"
            );
        }
    }

    #[test]
    fn post_transfer_move_drop_is_counted() {
        let (mut state, actor) = landed("cmd_transfer", zone::ZoneId::new(1));
        let (gates, _rx) = gates_and_rx();
        let (x, y) = pos_of(&state, actor);
        // 模拟「handoff 已提升、源区已释放实体」：在线表仍有条目（区域路由未随迁，④b）。
        assert!(
            state.host.world.release_entity(actor),
            "夹具先摘实体（模拟源区已 release）"
        );
        let before = perf_counters::handoff_move_after_transfer_dropped();
        handle_zone_command(
            &mut state,
            &gates,
            "hero",
            7,
            &cmd(mir2_protocol::messages::CM_WALK, x + 1, y, 2),
        );
        assert!(
            perf_counters::handoff_move_after_transfer_dropped() > before,
            "提升后源区丢走位必须计入 handoff_move_after_transfer_dropped"
        );
        assert!(
            state.host.world.entities.get(actor).is_none(),
            "丢弃后实体仍不在世界"
        );
    }

    /// **两侧判据**（纯谓词，不依赖全局计数器并发状态）：无注册表**且**本批有换图事件才计。
    /// 红检：把 `counts_as_map_change_unsupported` 改成只看 `changes > 0` ⇒ 本用例红。
    #[test]
    fn map_change_count_predicate_needs_missing_registry_and_events() {
        assert!(
            counts_as_map_change_unsupported(true, 1),
            "无注册表 + 有事件 ⇒ 计"
        );
        assert!(
            !counts_as_map_change_unsupported(false, 1),
            "有注册表 ⇒ 不计（降级只属于缺注册表路径）"
        );
        assert!(
            !counts_as_map_change_unsupported(true, 0),
            "无事件 ⇒ 不计（空批不是降级）"
        );
    }

    /// **集成正向**：`drain_map_change` 走 `registry=None` 的真路径 ⇒ `move_map_change_unsupported`
    /// 必须增长。红检：删掉 `drain_map_change_at_time` 里的计数调用 ⇒ 本用例红。
    #[test]
    fn map_change_without_registry_is_counted() {
        let mut world = mir2_world_bevy::World::with_maps(vec![(20, 20), (20, 20)]);
        world.open_session("hero");
        let _hero = world
            .enter_map(
                "hero",
                mir2_world_bevy::EntitySpawn::new(0, "hero", 5, 5),
                0,
            )
            .expect("进图");
        let online: OnlineRegistry = OnlineRegistry::new();
        let gates: std::collections::HashMap<u8, mpsc::UnboundedSender<SimToGate>> =
            std::collections::HashMap::new();
        let displays = downlink::DisplayTable::new();
        world
            .switch_map_space("hero", 1, 5, 5, false)
            .expect("换图落地");
        let before = perf_counters::move_map_change_unsupported();
        drain_map_change(&mut world, &online, &gates, &displays, None);
        assert!(
            perf_counters::move_map_change_unsupported() > before,
            "无注册表的换图批次必须计入 move_map_change_unsupported"
        );
    }

    #[test]
    fn zone_k_move_across_zone_bounds_marks_handoff_pending() {
        let (mut state, actor) = landed("cmd_handoff", zone::ZoneId::new(1));
        let (x, y) = pos_of(&state, actor);
        // 本区 rect = 落点左侧 5 格到落点本身 ⇒ 向右一格即出界（跨界判定只看 rect）。
        state
            .host
            .world
            .set_zone_bounds(Some((0, (x - 5, 0, x, 19))));
        let (gates, _rx) = gates_and_rx();
        handle_zone_command(
            &mut state,
            &gates,
            "hero",
            7,
            &cmd(mir2_protocol::messages::CM_WALK, x + 1, y, 2),
        );
        let e = state
            .host
            .world
            .entities
            .get(actor)
            .expect("跨界后实体仍在源区（源从不放手）");
        assert_eq!((e.x, e.y), (x + 1, y), "跨界移动必须成功落格");
        assert!(
            e.handoff_pending,
            "跨出本区 rect 必须置 handoff_pending（④a 的命令 ⇒ ③ 的 handoff 衔接）"
        );
    }

    // ============ A34 片 3：交易 6 + 组队 4（区 k 本地、仅同区） ============

    /// 片 3 夹具：`a34_ready` 之上放一个同区玩家 `peer` 在 hero **正前方**并回指（dir=6 左）。
    /// 世界时钟抬到 1e6（越过 `try_deal_time` 门）。
    #[allow(clippy::type_complexity)]
    fn a34_slice3_ready(
        tag: &str,
    ) -> (
        ZoneState,
        i32,
        i32,
        std::collections::HashMap<u8, mpsc::UnboundedSender<SimToGate>>,
        mpsc::UnboundedReceiver<SimToGate>,
    ) {
        let (mut state, hero, gates, rx) = a34_ready(tag);
        state.host.world.clock_ms = 1_000_000;
        let (hx, hy) = pos_of(&state, hero);
        let (fx, fy) = game_svr::attackwire::front_position(2, hx, hy, 20, 20);
        let peer = state
            .host
            .world
            .add_entity(mir2_world_bevy::EntitySpawn::new(0, "peer", fx, fy));
        state.host.world.entities.get_mut(hero).unwrap().ai.dir = 2; // 右
        state.host.world.entities.get_mut(peer).unwrap().ai.dir = 6; // 左（回指 hero）
        state
            .host
            .ground_sessions
            .insert("peer".to_string(), test_session_ground(peer));
        online_set(
            &mut state.host.online,
            OnlineEntry {
                account: "ub".to_string(),
                chr_name: "peer".to_string(),
                session_id: 2,
                gate_idx: 0,
                socket: 902,
                actor_id: peer,
            },
        );
        // 双方各一条交易会话态（生产按玩家惰性建立；`handle_deal_cmd` 只回写已有条目，
        // 缺条目的一方状态不落地 ⇒ 夹具按真实会话表形态预置两条）。
        state
            .host
            .trade_sessions
            .insert("hero".to_string(), game_svr::trade::DealState::default());
        state
            .host
            .trade_sessions
            .insert("peer".to_string(), game_svr::trade::DealState::default());
        (state, hero, peer, gates, rx)
    }

    fn a34_recog(body: &[u8]) -> i32 {
        i32::from_le_bytes([body[0], body[1], body[2], body[3]])
    }

    fn a34_count(frames: &[Vec<u8>], ident: u16) -> usize {
        frames.iter().filter(|b| a34_id(b) == ident).count()
    }

    /// **A34 片 3 · 分类器**：10 个 ident 必须归 `Local`（区 k 本区执行）。
    ///
    /// 变异：从 `zone_cmd_class` 删任一 ident ⇒ 该 ident 落 `Unsupported` ⇒ 红。
    #[test]
    fn a34_slice3_classifier_marks_ten_idents_local() {
        use mir2_protocol::messages as m;
        for ident in [
            m::CM_DEALTRY,
            m::CM_DEALADDITEM,
            m::CM_DEALDELITEM,
            m::CM_DEALCANCEL,
            m::CM_DEALCHGGOLD,
            m::CM_DEALEND,
            m::CM_GROUPMODE,
            m::CM_CREATEGROUP,
            m::CM_ADDGROUPMEMBER,
            m::CM_DELGROUPMEMBER,
        ] {
            assert_eq!(
                zone_cmd_class(ident, None),
                ZoneCmdClass::Local,
                "ident={ident} 必须归 Local（区 k 本区执行）"
            );
        }
    }

    /// **A34 片 3 · 交易 TRY（同区成功）**：互指的前排 ⇒ 双方各一条 `SM_DEALMENU`、双向 dealing。
    #[test]
    fn a34_slice3_deal_try_same_zone_opens_both() {
        let (mut state, _hero, _peer, gates, mut rx) = a34_slice3_ready("s3_try");
        let out = handle_zone_command(
            &mut state,
            &gates,
            "hero",
            901,
            &a34_msg(mir2_protocol::messages::CM_DEALTRY, 0, 0, 0),
        );
        assert_eq!(out, ZoneCmdOutcome::Dispatched);
        assert!(
            state
                .host
                .trade_sessions
                .get("hero")
                .is_some_and(|s| s.dealing),
            "同区互指 ⇒ hero 进入交易"
        );
        assert!(
            state
                .host
                .trade_sessions
                .get("peer")
                .is_some_and(|s| s.dealing),
            "同区互指 ⇒ peer 进入交易"
        );
        let frames = a34_frames(&mut rx);
        assert_eq!(
            a34_count(&frames, mir2_protocol::messages::SM_DEALMENU),
            2,
            "双方各一条 SM_DEALMENU：{frames:?}"
        );
    }

    /// **A34 片 3 · 交易 TRY（对方不在本区 ⇒ 拒）**：前排是他区玩家的**镜像** ⇒ 恰一条
    /// `SM_DEALTRY_FAIL`、不建交易（**不**用默认 DealState 误开窗）。
    ///
    /// 变异：删 `handle_deal_cmd` 的 local-online 守卫 ⇒ 镜像被当普通玩家开窗 ⇒ 红。
    #[test]
    fn a34_slice3_deal_try_facing_mirror_refused() {
        let (mut state, hero, peer, gates, mut rx) = a34_slice3_ready("s3_mirror");
        let (hx, hy) = pos_of(&state, hero);
        let (fx, fy) = game_svr::attackwire::front_position(2, hx, hy, 20, 20);
        // 前排只能有镜像（把夹具的 peer 挪开，否则 `front_target` 先命中真实玩家）。
        let peer_off = (hx, hy + 3);
        if let Some(t) = state.host.world.entities.transform_mut(peer) {
            t.x = peer_off.0;
            t.y = peer_off.1;
        }
        let mirror = state
            .host
            .world
            .add_entity(mir2_world_bevy::EntitySpawn::new(0, "faraway", fx, fy));
        {
            let e = state.host.world.entities.get_mut(mirror).unwrap();
            e.ai.dir = 6;
            e.flags.mirror = true; // 他区玩家的世界侧投影（无本区 online 项）
        }
        let out = handle_zone_command(
            &mut state,
            &gates,
            "hero",
            901,
            &a34_msg(mir2_protocol::messages::CM_DEALTRY, 0, 0, 0),
        );
        assert_eq!(out, ZoneCmdOutcome::Dispatched);
        let frames = a34_frames(&mut rx);
        assert_eq!(
            a34_count(&frames, mir2_protocol::messages::SM_DEALTRY_FAIL),
            1,
            "前排是镜像 ⇒ 恰一条 SM_DEALTRY_FAIL：{frames:?}"
        );
        assert_eq!(
            a34_count(&frames, mir2_protocol::messages::SM_DEALMENU),
            0,
            "不得开窗"
        );
        assert!(
            !state
                .host
                .trade_sessions
                .get("hero")
                .is_some_and(|s| s.dealing),
            "不得建立交易（删 local-online 守卫 ⇒ 本断言红）"
        );
    }

    /// **A34 片 3 · 交易 ADD/DEL（同区）**：入交易栏 ⇒ 回包；退回 ⇒ 物品回包。
    #[test]
    fn a34_slice3_deal_add_and_del_item_roundtrip() {
        // 现网 `CanNotGetBackDeal=1` 时退回会被拒（oracle 原样）；本条测「允许退回」配置。
        let mut shared = SharedServices::for_test();
        shared.enter_cfg.trade.can_not_get_back_deal = false;
        let (mut state, hero, _peer, gates, mut rx) = a34_slice3_ready("s3_additem");
        state
            .host
            .ground_sessions
            .get_mut("hero")
            .unwrap()
            .state
            .item_list
            .push(game_svr::bag::BagItem::new(4242, 1));
        assert_eq!(
            handle_zone_command_with_tail_and_shared(
                &mut state,
                &gates,
                "hero",
                901,
                &a34_msg(mir2_protocol::messages::CM_DEALTRY, 0, 0, 0),
                None,
                &shared
            ),
            ZoneCmdOutcome::Dispatched
        );
        let _ = a34_frames(&mut rx); // 丢弃 TRY 帧
        assert_eq!(
            handle_zone_command_with_tail_and_shared(
                &mut state,
                &gates,
                "hero",
                901,
                &a34_msg(mir2_protocol::messages::CM_DEALADDITEM, 4242, 0, 0),
                None,
                &shared
            ),
            ZoneCmdOutcome::Dispatched
        );
        let frames = a34_frames(&mut rx);
        assert_eq!(
            a34_count(&frames, mir2_protocol::messages::SM_DEALADDITEM_OK),
            1,
            "ADD 成功恰一条 OK：{frames:?}"
        );
        assert!(
            state.host.ground_sessions["hero"]
                .state
                .item_list
                .is_empty(),
            "物品已移入交易栏"
        );
        assert_eq!(
            state.host.trade_sessions["hero"].deal_item_list.len(),
            1,
            "交易栏 1 件"
        );
        assert_eq!(
            handle_zone_command_with_tail_and_shared(
                &mut state,
                &gates,
                "hero",
                901,
                &a34_msg(mir2_protocol::messages::CM_DEALDELITEM, 4242, 0, 0),
                None,
                &shared
            ),
            ZoneCmdOutcome::Dispatched
        );
        let frames = a34_frames(&mut rx);
        assert_eq!(
            a34_count(&frames, mir2_protocol::messages::SM_DEALDELITEM_OK),
            1,
            "DEL 成功恰一条 OK：{frames:?}"
        );
        assert_eq!(
            state.host.ground_sessions["hero"].state.item_list.len(),
            1,
            "物品退回背包"
        );
        assert!(state.host.trade_sessions["hero"].deal_item_list.is_empty());
        let _ = hero;
    }

    /// **A34 片 3 · 交易 CANCEL（同区）**：恰两条 `SM_DEALCANCEL`（每侧一条），双方 dealing 复位。
