    /// **A35-b · D2（2026-11-24 裁决二）**：交易取消帧 `SM_DEALCANCEL` **先于**会话 detach
    /// （设计 §2.1「帧先发」）。用 `cfg(test)` 测试缝 `a35b_order` 记录两个真实调用点的相对序，
    /// 断言 `["cancel", "detach"]`，且 tick 返回时 `gates` 里已有恰一条 `SM_DEALCANCEL`。
    ///
    /// 变异：把取消调用挪到 detach **之后** ⇒ 序变 `["detach","cancel"]` ⇒ 红。
    #[test]
    fn a35b_cancel_frames_precede_session_detach() {
        let _guard = super::l2_handoff_prod_tests::PROD_LOCK
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let _counters = perf_counters::test_zone_counters_scope();
        perf_counters::reset_zone_handoff_counters_for_tests();
        crate::a35b_order::reset();
        let layout = std::sync::Arc::new(layout());
        let boxes = crate::handoff::new_mailboxes(2);
        let counter = std::sync::Arc::new(std::sync::atomic::AtomicI32::new(0));
        let mut host = HostLoop::for_zone(zone(1), &[(20, 10)], Some(0), &counter);
        host.handoff_runtime = Some(crate::handoff::HandoffRuntime::new(
            zone(1),
            std::sync::Arc::clone(&layout),
            boxes.clone(),
        ));
        let chr = "mover";
        let id = seed_full_session_for_host(&mut host, chr, 901);
        host.trade_sessions.insert(
            chr.to_string(),
            game_svr::trade::DealState {
                dealing: true,
                ..game_svr::trade::DealState::default()
            },
        );
        let (g_tx, mut g_rx) = mpsc::unbounded_channel::<SimToGate>();
        host.gates.insert(0, g_tx);
        host.world
            .entities
            .get_mut(id)
            .expect("实体在")
            .flags
            .handoff_pending = true;
        host.handoff_runtime
            .as_mut()
            .expect("运行时在")
            .after_phase2(&mut host.world, 0);
        {
            let mut m = boxes[1].lock().unwrap_or_else(|e| e.into_inner());
            m.1.push(crate::handoff::HandoffAck {
                to: zone(1),
                from: zone(0),
                id,
                ok: true,
            });
        }
        let (shared, _process) = (SharedServices::for_test(), ProcessServices::for_test());
        let (_tx, ev_rx) = std::sync::mpsc::channel();
        let (_ctx, ev_ctl_rx) = std::sync::mpsc::channel();
        let mut io = TickIo {
            ev_rx,
            ev_ctl_rx,
            shutdown: ShutdownSignal::Flag(std::sync::Arc::new(
                std::sync::atomic::AtomicBool::new(false),
            )),
            inbound_local_buffer: std::collections::VecDeque::new(),
            inbound_local_carry_prefix: 0,
            inbound_local_filled: 0,
            inbound_local_fill_hit: false,
            inbound_outstanding: None,
            control_inbox: None,
        };
        let mut shared = shared;
        let mut process = None;
        let mut scratch = TickScratch::default();
        let outcome = host.tick_phase_a(
            &mut shared,
            &mut process,
            &mut io,
            PhaseSet(PhaseSet::WORLD_HEAD | PhaseSet::WORLD_TAIL),
            &mut scratch,
            &mut None,
        );
        assert_eq!(outcome, TickOutcome::Continue);
        assert_eq!(
            crate::a35b_order::taken(),
            vec!["cancel", "detach"],
            "取消阶段必须在 detach 之前（帧先发）"
        );
        let mut cancels = 0u32;
        while let Ok(SimToGate::SendFrame { body, .. }) = g_rx.try_recv() {
            if CommandMessage::from_bytes(&body)
                .is_some_and(|cm| cm.ident == mir2_protocol::messages::SM_DEALCANCEL)
            {
                cancels += 1;
            }
        }
        assert_eq!(cancels, 1, "tick 返回时取消帧已发出（恰一条）");
    }

    /// **A35-b · D3（2026-11-24 裁决二）**：目标区展示项由**镜像路径**保证
    /// （`region_loop::apply_mirrors` 的 display 同步；`promote_mirror_to_real` 不写 displays）
    /// ⇒ `attach_session` 的 `is_none()` 是**防御性检查**：缺失 ⇒ 计数 + WRN + **拒收整包回滚**。
    ///
    /// 本牙造"实体已提升但展示项缺失"⇒ 断言失败计数、source 逐表恢复、目标区无会话。
    /// 变异：把拒收改回「计数后继续搬」⇒ 目标区有会话 / failed==0 ⇒ 红。
    #[test]
    fn a35b_missing_target_display_rejects_and_rolls_back() {
        let _guard = super::l2_handoff_prod_tests::PROD_LOCK
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let _counters = perf_counters::test_zone_counters_scope();
        perf_counters::reset_zone_handoff_counters_for_tests();
        mir2_world_bevy::mirror_metrics::reset_handoff_refused_for_tests();
        let counter = std::sync::Arc::new(std::sync::atomic::AtomicI32::new(0));
        let chr = "mover";
        let mut src = two_zone_state(1, &counter);
        let id = seed_full_session(&mut src, chr, 901);
        assert!(src.host.world.release_entity(id));
        let m = src
            .host
            .take_session_for_migration(id, zone(1), zone(0))
            .expect("应摘下");
        let mut dst = two_zone_state(0, &counter);
        seed_target_world(&mut dst, id, chr);
        dst.host.displays.remove(id); // 造「实体已提升但展示项缺失」
        let dst = std::sync::Arc::new(std::sync::Mutex::new(dst));
        let router = zone_router::ZoneRouter::new();
        let missing0 = perf_counters::zone_handoff_target_display_missing();
        deliver_session_migrations(
            |z| (z == zone(0)).then(|| std::sync::Arc::clone(&dst)),
            Some(&router),
            vec![m],
            |m| src.host.restore_session(m),
        );
        assert_eq!(
            perf_counters::zone_handoff_target_display_missing() - missing0,
            1,
            "缺失必须计 zone_handoff_target_display_missing +1"
        );
        assert_eq!(perf_counters::zone_handoff_session_failed(), 1);
        assert_eq!(mirror_world_refused(), 1);
        assert!(src.host.ground_sessions.contains_key(chr), "源区整包恢复");
        assert!(
            src.host
                .world
                .session(chr)
                .is_some_and(|s| s.stage == mir2_world_bevy::WorldStage::InWorld),
            "源区 World 会话写回 InWorld"
        );
        {
            let dst = dst.lock().unwrap_or_else(|e| e.into_inner());
            assert!(
                !dst.host.ground_sessions.contains_key(chr),
                "目标区不得留半份（拒收）"
            );
        }
    }

    /// `handoff_refused` 的读取缝（`mirror_metrics` 的模块名较长，集中一处）。
    fn mirror_world_refused() -> u64 {
        mir2_world_bevy::mirror_metrics::handoff_refused()
    }

    /// **A35-b · T3**：交易中跨区 ⇒ 走既有 `deal_cancel_between`，**恰好一条** `SM_DEALCANCEL`
    /// （不丢不重）；两表不搬（条目在源区清掉）。
    ///
    /// 变异：不取消直接搬 ⇒ 0 帧红；取消两遍 ⇒ 2 帧红。
    #[test]
    fn cross_zone_trade_cancel_emits_exactly_one_dealcancel() {
        let _guard = super::l2_handoff_prod_tests::PROD_LOCK
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let _counters = perf_counters::test_zone_counters_scope();
        perf_counters::reset_zone_handoff_counters_for_tests();
        let counter = std::sync::Arc::new(std::sync::atomic::AtomicI32::new(0));
        let mut st = two_zone_state(1, &counter);
        let _id = seed_full_session(&mut st, "dealer", 901);
        st.host.trade_sessions.insert(
            "dealer".into(),
            game_svr::trade::DealState {
                dealing: true,
                ..game_svr::trade::DealState::default()
            },
        );
        let shared = SharedServices::for_test();
        let (tx, mut rx) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates = std::collections::HashMap::new();
        gates.insert(0u8, tx);
        let displays = downlink::DisplayTable::new();
        let mut sell_off = std::collections::HashMap::new();
        let canceled = cancel_cross_zone_trade_and_selloff(
            "dealer",
            &st.host.online,
            &st.host.world,
            &displays,
            &mut st.host.ground_sessions,
            &mut st.host.trade_sessions,
            &mut sell_off,
            &gates,
            &shared.enter_cfg.trade,
            &shared.enter_cfg.catalog,
            &shared.enter_cfg.sell_off,
            None,
        );
        assert!(canceled, "dealing ⇒ 必须发生取消");
        assert!(
            !st.host.trade_sessions.contains_key("dealer"),
            "交易表不搬（残条在源区清掉）"
        );
        let mut dealcancel = 0u32;
        while let Ok(SimToGate::SendFrame { body, .. }) = rx.try_recv() {
            let cm = CommandMessage::from_bytes(&body).expect("SM_* 至少 12B");
            if cm.ident == mir2_protocol::messages::SM_DEALCANCEL {
                dealcancel += 1;
            }
        }
        assert_eq!(dealcancel, 1, "恰好一条 SM_DEALCANCEL（不丢不重）");
    }

    /// **A35-b · T3b**：寄售中跨区 ⇒ 取消帧先发，**恰好一条** `SM_SellOffCANCEL`；`SellOffBook`
    /// 的该卖家条目被取消（不搬）。区 k（`book=None`）只丢弃空表、不产帧。
    #[test]
    fn cross_zone_selloff_cancel_emits_one_selloffcancel() {
        let _guard = super::l2_handoff_prod_tests::PROD_LOCK
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let counter = std::sync::Arc::new(std::sync::atomic::AtomicI32::new(0));
        let mut st = two_zone_state(1, &counter);
        let _id = seed_full_session(&mut st, "seller", 901);
        st.host.sell_off_sessions.insert(
            "seller".into(),
            game_svr::selloff::SellOffState {
                sell_off_confirm: true,
                ..game_svr::selloff::SellOffState::default()
            },
        );
        let mut book = game_svr::selloff::SellOffBook {
            entries: vec![game_svr::selloff::DealOffInfo {
                deal_chr_name: "seller".into(),
                flag: 0,
                ..game_svr::selloff::DealOffInfo::new_with_slots()
            }],
        };
        let shared = SharedServices::for_test();
        let (tx, mut rx) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates = std::collections::HashMap::new();
        gates.insert(0u8, tx);
        let displays = downlink::DisplayTable::new();
        let mut trade = std::collections::HashMap::new();
        let canceled = cancel_cross_zone_trade_and_selloff(
            "seller",
            &st.host.online,
            &st.host.world,
            &displays,
            &mut st.host.ground_sessions,
            &mut trade,
            &mut st.host.sell_off_sessions,
            &gates,
            &shared.enter_cfg.trade,
            &shared.enter_cfg.catalog,
            &shared.enter_cfg.sell_off,
            Some(&mut book),
        );
        assert!(canceled, "寄售中 ⇒ 必须发生取消");
        assert!(
            book.entries.is_empty(),
            "该卖家的寄售条目必须被取消（不搬）"
        );
        assert!(!st.host.sell_off_sessions.contains_key("seller"));
        let mut cancel_frames = 0u32;
        while let Ok(SimToGate::SendFrame { body, .. }) = rx.try_recv() {
            let cm = CommandMessage::from_bytes(&body).expect("SM_* 至少 12B");
            if cm.ident == mir2_protocol::messages::SM_SellOffCANCEL {
                cancel_frames += 1;
            }
        }
        assert_eq!(cancel_frames, 1, "恰好一条 SM_SellOffCANCEL");
        // 区 k（无进程态 book）：空态 no-op、不产帧、不报 canceled。
        let (tx2, mut rx2) = mpsc::unbounded_channel::<SimToGate>();
        let mut gates2 = std::collections::HashMap::new();
        gates2.insert(0u8, tx2);
        let canceled_k = cancel_cross_zone_trade_and_selloff(
            "seller",
            &st.host.online,
            &st.host.world,
            &displays,
            &mut st.host.ground_sessions,
            &mut trade,
            &mut st.host.sell_off_sessions,
            &gates2,
            &shared.enter_cfg.trade,
            &shared.enter_cfg.catalog,
            &shared.enter_cfg.sell_off,
            None,
        );
        assert!(!canceled_k, "区 k 空态 ⇒ 不取消");
        assert!(rx2.try_recv().is_err(), "区 k 不得产帧");
    }

    /// **A35-b · Q1「活尸牙」**：迁移后目标区收到 `Closed` ⇒ `world.disconnect` 能摘掉实体
    /// （不出现活尸），且源区 World 会话为 `Left`。
    ///
    /// 变异：`attach_session` 不写回 `world.session` ⇒ 目标区 `disconnect` 命中 `NoSession` ⇒
    /// 实体仍在 ⇒ 红。
    #[test]
    fn migrated_session_disconnects_on_target_without_entity_leak() {
        let _guard = super::l2_handoff_prod_tests::PROD_LOCK
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let counter = std::sync::Arc::new(std::sync::atomic::AtomicI32::new(0));
        let mut src = two_zone_state(1, &counter);
        let chr = "mover";
        let id = seed_full_session(&mut src, chr, 901);
        assert!(src.host.world.release_entity(id));
        let m = src
            .host
            .take_session_for_migration(id, zone(1), zone(0))
            .expect("应摘下");
        let mut dst = two_zone_state(0, &counter);
        seed_target_world(&mut dst, id, chr);
        dst.host
            .attach_session(m)
            .unwrap_or_else(|_| panic!("attach 必须成功"));
        assert!(
            dst.host
                .world
                .session(chr)
                .is_some_and(|s| s.stage == mir2_world_bevy::WorldStage::InWorld),
            "前置：目标区 World 会话在"
        );
        let handled = handle_zone_closed(&mut dst, chr, 0, 901, &[]);
        assert!(handled, "目标区在线项在 ⇒ Closed 必须被处理");
        assert!(
            dst.host.world.entities.get(id).is_none(),
            "迁移后断线必须摘实体（活尸牙：World 会话没随迁时本断言红）"
        );
        assert!(
            dst.host
                .world
                .session(chr)
                .is_some_and(|s| s.stage == mir2_world_bevy::WorldStage::Left),
            "目标区会话应置 Left"
        );
        assert!(
            src.host
                .world
                .session(chr)
                .is_some_and(|s| s.stage == mir2_world_bevy::WorldStage::Left),
            "源区会话应保持 Left"
        );
    }

    /// **A35-b · 接线牙**：`tick_phase_a` 的 WORLD_HEAD 消费 `tick_top` 的 committed ids ⇒
    /// （夹具是裸会话：本用例只跑 `WORLD_HEAD|WORLD_TAIL`，**不跑 rest 段**——理由见
    /// [`seed_full_session`] 的注释。）
    /// 源区七表当场摘空、搬迁包进入 `pending_session_migrations`（供驱动锁外 attach）。
    ///
    /// 变异：删 WORLD_HEAD 里的消费循环 ⇒ 包为空、源区仍有会话 ⇒ 红。
    #[test]
    fn tick_phase_a_detaches_committed_session_into_pending() {
        let _guard = super::l2_handoff_prod_tests::PROD_LOCK
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let _counters = perf_counters::test_zone_counters_scope();
        perf_counters::reset_zone_handoff_counters_for_tests();
        let layout = Arc::new(layout());
        let boxes = crate::handoff::new_mailboxes(2);
        let counter = std::sync::Arc::new(std::sync::atomic::AtomicI32::new(0));
        let mut host = HostLoop::for_zone(zone(1), &[(20, 10)], Some(0), &counter);
        host.handoff_runtime = Some(crate::handoff::HandoffRuntime::new(
            zone(1),
            Arc::clone(&layout),
            boxes.clone(),
        ));
        let chr = "mover";
        let id = seed_full_session_for_host(&mut host, chr, 901);
        {
            let e = host.world.entities.get_mut(id).expect("实体在");
            e.group.allow_group = true;
            e.group.group_owner = id;
            e.group.group_members = vec![id, id + 1];
        }
        // 跨界时正在交易 ⇒ WORLD_HEAD 必须先取消（帧先发）再 detach。
        host.trade_sessions.insert(
            chr.to_string(),
            game_svr::trade::DealState {
                dealing: true,
                ..game_svr::trade::DealState::default()
            },
        );
        let (g_tx, mut g_rx) = mpsc::unbounded_channel::<SimToGate>();
        host.gates.insert(0, g_tx);
        // 实体跨到区 0 的 rect ⇒ 标记 pending，after_phase2 投 offer 给区 0。
        host.world
            .entities
            .get_mut(id)
            .expect("实体在")
            .flags
            .handoff_pending = true;
        host.handoff_runtime
            .as_mut()
            .expect("运行时在")
            .after_phase2(&mut host.world, 0);
        // 目标区（区 0）收下并回执。
        {
            let mut m = boxes[1].lock().unwrap_or_else(|e| e.into_inner());
            m.1.push(crate::handoff::HandoffAck {
                to: zone(1),
                from: zone(0),
                id,
                ok: true,
            });
        }
        let (shared, _process) = (SharedServices::for_test(), ProcessServices::for_test());
        let (_tx, ev_rx) = std::sync::mpsc::channel();
        let (_ctx, ev_ctl_rx) = std::sync::mpsc::channel();
        let io = TickIo {
            ev_rx,
            ev_ctl_rx,
            shutdown: ShutdownSignal::Flag(std::sync::Arc::new(
                std::sync::atomic::AtomicBool::new(false),
            )),
            inbound_local_buffer: std::collections::VecDeque::new(),
            inbound_local_carry_prefix: 0,
            inbound_local_filled: 0,
            inbound_local_fill_hit: false,
            inbound_outstanding: None,
            control_inbox: None,
        };
        let mut shared = shared;
        let mut process = None;
        let mut io = io;
        let mut scratch = TickScratch::default();
        let outcome = host.tick_phase_a(
            &mut shared,
            &mut process,
            &mut io,
            PhaseSet(PhaseSet::WORLD_HEAD | PhaseSet::WORLD_TAIL),
            &mut scratch,
            &mut None,
        );
        assert_eq!(outcome, TickOutcome::Continue);
        assert_eq!(
            host.pending_session_migrations.len(),
            1,
            "已提交的跨界必须摘成搬迁包（WORLD_HEAD 消费循环被删 ⇒ 本断言红）"
        );
        let m = &host.pending_session_migrations[0];
        assert_eq!(
            (m.chr_name.as_str(), m.id, m.line, m.socket, m.target),
            (chr, id, 0, 901, zone(0))
        );
        assert_eq!(
            (
                m.group.allow_group,
                m.group.group_owner,
                m.group.group_members.clone()
            ),
            (true, id, vec![id, id + 1]),
            "A38：组关系必须随搬迁包带走（接线路径）"
        );
        assert!(host.ground_sessions.is_empty(), "源区 ground 必须当场摘空");
        assert!(host.online.find_by_chr(chr).is_none());
        assert!(host.saves.is_empty() && host.login_tails.is_empty());
        assert_eq!(perf_counters::zone_handoff_session_failed(), 0);
        // 取消接线：dealing ⇒ 计数 1、交易表不搬、恰一条 SM_DEALCANCEL。
        assert_eq!(perf_counters::zone_handoff_canceled_trades(), 1);
        assert!(!host.trade_sessions.contains_key(chr), "交易表不搬");
        let mut cancels = 0u32;
        while let Ok(SimToGate::SendFrame { body, .. }) = g_rx.try_recv() {
            if CommandMessage::from_bytes(&body)
                .is_some_and(|cm| cm.ident == mir2_protocol::messages::SM_DEALCANCEL)
            {
                cancels += 1;
            }
        }
        assert_eq!(cancels, 1, "接线路径恰好一条 SM_DEALCANCEL");
    }

    /// **A38**：捕获点必须在 `release_entity` **之前**——实体释放后 `GroupState` 组件随之消失。
    ///
    /// 红检：把 `handoff.rs` 的捕获行挪到 `release_entity` 之后 ⇒ 拿到 `default()`（空组）⇒ 红。
    #[test]
    fn handoff_tick_top_captures_group_state_before_release() {
        let _guard = super::l2_handoff_prod_tests::PROD_LOCK
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let layout = Arc::new(layout());
        let boxes = crate::handoff::new_mailboxes(2);
        let mut world = World::with_maps(vec![(20, 10)]);
        let mut rt =
            crate::handoff::HandoffRuntime::new(zone(0), Arc::clone(&layout), boxes.clone());
        let mut spawn = mir2_world_bevy::EntitySpawn::new(0, "P", 12, 5);
        spawn.race = 0;
        let id = world.add_entity(spawn);
        {
            let e = world.entities.get_mut(id).expect("刚插入");
            e.flags.handoff_pending = true;
            e.group.allow_group = true;
            e.group.group_owner = id;
            e.group.group_members = vec![id, id + 1];
        }
        rt.after_phase2(&mut world, 0);
        {
            let mut m = boxes[0].lock().unwrap_or_else(|e| e.into_inner());
            m.1.push(crate::handoff::HandoffAck {
                to: zone(0),
                from: zone(1),
                id,
                ok: true,
            });
        }
        let committed = rt.tick_top(&mut world, 1);
        assert_eq!(committed.len(), 1);
        assert_eq!(committed[0].id, id);
        assert!(
            committed[0].group.allow_group,
            "allow_group 必须随实体捕获（放到 release 之后 ⇒ default ⇒ 红）"
        );
        assert_eq!(committed[0].group.group_owner, id);
        assert_eq!(committed[0].group.group_members, vec![id, id + 1]);
        assert!(world.entities.get(id).is_none(), "捕获之后实体才被释放");
    }

    /// A38 公共夹具：源区种好带组关系的实体并走到「已提交 + 已 detach」，
    /// 返回 `(源区, 搬迁包, 期望的 GroupState)`。
    fn committed_group_migration(
        chr: &str,
        group_owner: i32,
        members: Vec<i32>,
    ) -> (
        ZoneState,
        PendingSessionMigration,
        mir2_world_bevy::GroupState,
    ) {
        let layout = std::sync::Arc::new(layout());
        let boxes = crate::handoff::new_mailboxes(2);
        let counter = std::sync::Arc::new(std::sync::atomic::AtomicI32::new(0));
        let mut src = two_zone_state(1, &counter);
        let id = seed_full_session(&mut src, chr, 901);
        {
            let e = src.host.world.entities.get_mut(id).expect("实体在");
            e.flags.handoff_pending = true;
            e.group.allow_group = true;
            e.group.group_owner = group_owner;
            e.group.group_members = members;
        }
        let mut rt = crate::handoff::HandoffRuntime::new(
            zone(1),
            std::sync::Arc::clone(&layout),
            boxes.clone(),
        );
        rt.after_phase2(&mut src.host.world, 0);
        {
            let mut m = boxes[1].lock().unwrap_or_else(|e| e.into_inner());
            m.1.push(crate::handoff::HandoffAck {
                to: zone(1),
                from: zone(0),
                id,
                ok: true,
            });
        }
        let committed = rt.tick_top(&mut src.host.world, 1);
        assert_eq!(committed.len(), 1, "前置：恰一条已提交");
        let expected = committed[0].group.clone();
        let tail = committed.into_iter().next().expect("一条");
        let m = detach_session_for_migration(
            &mut src.host.world,
            &mut src.host.displays,
            &mut src.host.online,
            &mut src.host.ground_sessions,
            &mut src.host.saves,
            &mut src.host.login_tails,
            &mut src.host.aoi_frames_total,
            &mut src.host.shop_sessions,
            &mut src.host.pending_local,
            zone(1),
            zone(0),
            id,
            tail.group,
        )
        .expect("detach");
        (src, m, expected)
    }

    /// **A38 · 牙①（团长跨区）**：目标区实体带同一份组关系（owner + 成员列表）；
    /// 源区实体已释放 ⇒ 源区不再有该组项。
    ///
    /// 变异：① attach 不写 `GroupState` ⇒ 目标区空组 ⇒ 红；② 只写 owner 不写 members ⇒ 红。
    #[test]
    fn party_group_survives_leader_crossing() {
        let _guard = super::l2_handoff_prod_tests::PROD_LOCK
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let (src, m, expected) = committed_group_migration("leader", 9001, vec![9001, 9002]);
        let id = m.id;
        assert_eq!(m.group, expected, "搬迁包必须携带捕获到的组关系");
        let counter = std::sync::Arc::new(std::sync::atomic::AtomicI32::new(0));
        let mut dst = two_zone_state(0, &counter);
        seed_target_world(&mut dst, id, "leader");
        dst.host
            .attach_session(m)
            .unwrap_or_else(|_| panic!("attach 必须成功"));
        assert_eq!(
            dst.host.world.entities.group(id),
            Some(&expected),
            "目标区实体必须带同一份组关系（不搬 ⇒ 空组 ⇒ 红）"
        );
        assert_eq!(
            expected.group_members.len(),
            2,
            "成员表完整随迁（只搬 owner ⇒ 红）"
        );
        assert!(
            src.host.world.entities.get(id).is_none(),
            "源区实体已释放 ⇒ 无该组项"
        );
        assert!(
            src.host.ground_sessions.is_empty(),
            "会话已摘（A35-b 语义不变）"
        );
    }

    /// **A38 · 牙①（成员跨区）**：成员侧的 `group_owner` 必须随迁（成员自己的
    /// `group_members` 本来为空）。
    ///
    /// 变异：只搬 `group_members` 不搬 `group_owner` ⇒ 目标区 owner=0 ⇒ 红。
    #[test]
    fn party_group_survives_member_crossing() {
        let _guard = super::l2_handoff_prod_tests::PROD_LOCK
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let (src, m, expected) = committed_group_migration("member", 9001, Vec::new());
        let id = m.id;
        let counter = std::sync::Arc::new(std::sync::atomic::AtomicI32::new(0));
        let mut dst = two_zone_state(0, &counter);
        seed_target_world(&mut dst, id, "member");
        dst.host
            .attach_session(m)
            .unwrap_or_else(|_| panic!("attach 必须成功"));
        assert_eq!(
            dst.host.world.entities.group(id),
            Some(&expected),
            "成员的 owner=9001 必须随迁（不搬 owner ⇒ 0 ⇒ 红）"
        );
        assert_eq!(expected.group_owner, 9001);
        assert!(src.host.world.entities.get(id).is_none());
    }

    /// **A40①（迁移）**：`attach_session` 在目标区建默认交易条目；被拒回滚时源区恢复条目、
    /// 目标区不留孤儿。
    ///
    /// 变异：删 attach 的 `trade_sessions.insert` ⇒ 目标区缺条目红；删 restore/take 的
    /// 配套清理 ⇒ 源区缺条目或目标区孤儿 ⇒ 红。
    #[test]
    fn a40_migration_attach_creates_trade_entry_and_rollback_no_orphan() {
        let _guard = super::l2_handoff_prod_tests::PROD_LOCK
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let _counters = perf_counters::test_zone_counters_scope();
        perf_counters::reset_zone_handoff_counters_for_tests();
        mir2_world_bevy::mirror_metrics::reset_handoff_refused_for_tests();
        // (a) 成功 attach：目标区有默认条目。
        let (src, m, _g) = committed_group_migration("a40mig", 9001, Vec::new());
        let id = m.id;
        let chr = m.chr_name.clone();
        let counter = std::sync::Arc::new(std::sync::atomic::AtomicI32::new(0));
        let mut dst = two_zone_state(0, &counter);
        seed_target_world(&mut dst, id, &chr);
        dst.host
            .attach_session(m)
            .unwrap_or_else(|_| panic!("attach"));
        assert!(
            dst.host.trade_sessions.contains_key(&chr),
            "目标区必须有默认交易条目（删 attach 初始化 ⇒ 红）"
        );
        assert!(!dst.host.trade_sessions[&chr].dealing);
        assert!(!src.host.trade_sessions.contains_key(&chr));
        // (b) 被拒回滚：源区恢复默认条目；目标区不留 attach 之前不存在的孤儿。
        let (mut src2, m2, _g2) = committed_group_migration("a40rb", 9001, Vec::new());
        let chr2 = m2.chr_name.clone();
        let id2 = m2.id;
        let counter2 = std::sync::Arc::new(std::sync::atomic::AtomicI32::new(0));
        let mut dst2 = two_zone_state(0, &counter2);
        let _ = seed_full_session(&mut dst2, &chr2, 902); // 冲突源（目标区自己的同名会话）
        seed_target_world(&mut dst2, id2, &chr2);
        let dst2_arc = std::sync::Arc::new(std::sync::Mutex::new(dst2));
        let lookup = std::sync::Arc::clone(&dst2_arc);
        let router = zone_router::ZoneRouter::new();
        deliver_session_migrations(
            |z| (z == zone(0)).then(|| std::sync::Arc::clone(&lookup)),
            Some(&router),
            vec![m2],
            |m| src2.host.restore_session(m),
        );
        assert!(
            src2.host.trade_sessions.contains_key(&chr2),
            "回滚必须恢复源区的默认交易条目"
        );
        {
            let dst2 = dst2_arc.lock().unwrap_or_else(|e| e.into_inner());
            assert!(
                !dst2.host.trade_sessions.contains_key(&chr2),
                "被拒路径不得在目标区留下孤儿条目"
            );
        }
    }

    /// **A38 · 牙②（card/handoff-release-leak 修订，2026-11-26 裁决 A）**：attach 被拒
    /// （同 chr 冲突）⇒ 会话整包回源，**目标区已提升的真实体必须回收**（`release_entity`）。
    ///
    /// A38 原口径「组关系仍留在目标区实体上、恰一份」以实体保留为前提；b1 卡确认无会话的
    /// 真实体会永久扫描并刷 `missing_online`，因此实体必须回收，**组关系随实体消失是已知
    /// 代价**——由 `DEV-HANDOFF-GROUP` 追踪（源区实体的组关系是否还在、失败迁移是否静默
    /// 退组），此处不表示"这样是对的"。
    ///
    /// 变异：删掉 `deliver_session_migrations` Err 分支的 `release_entity` ⇒ 本牙红。
    #[test]
    fn refused_attach_releases_target_entity() {
        let _guard = super::l2_handoff_prod_tests::PROD_LOCK
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let _counters = perf_counters::test_zone_counters_scope();
        perf_counters::reset_zone_handoff_counters_for_tests();
        mir2_world_bevy::mirror_metrics::reset_handoff_refused_for_tests();
        let (mut src, m, _expected) = committed_group_migration("leader", 9001, vec![9001, 9002]);
        let id = m.id;
        let counter = std::sync::Arc::new(std::sync::atomic::AtomicI32::new(0));
        let mut dst = two_zone_state(0, &counter);
        // 目标区自己的同名会话（冲突源）+ 实体已晋升。
        let _ = seed_full_session(&mut dst, "leader", 902);
        seed_target_world(&mut dst, id, "leader");
        let dst_arc = std::sync::Arc::new(std::sync::Mutex::new(dst));
        let lookup = std::sync::Arc::clone(&dst_arc);
        let router = zone_router::ZoneRouter::new();
        deliver_session_migrations(
            |z| (z == zone(0)).then(|| std::sync::Arc::clone(&lookup)),
            Some(&router),
            vec![m],
            |m| src.host.restore_session(m),
        );
        assert_eq!(perf_counters::zone_handoff_session_failed(), 1);
        assert_eq!(mirror_world_refused(), 1);
        assert!(
            src.host.ground_sessions.contains_key("leader"),
            "会话七表必须整包回源"
        );
        assert_eq!(router.len(), 0, "失败路径不得 assign");
        let dst = dst_arc.lock().unwrap_or_else(|e| e.into_inner());
        assert!(
            dst.host.world.entities.get(id).is_none(),
            "attach 被拒 ⇒ 目标区实体必须被回收（组关系随实体消失是已知代价，登记 DEV-HANDOFF-GROUP）"
        );
    }

    /// **A35-b · 静态牙（接线提示，非行为证据）**：两个驱动点必须夹在「A 段之后、barrier1
    /// 之前」——区 0：`tick_phase_a(` < `A35-b 驱动点（区 0）` < `await_neighbors(self.ticks)`；
    /// 区 k：`tick_phase_a(` < `A35-b 驱动点（区 k）` < `await_neighbors(tick)`。
    ///
    /// 为什么钉顺序：源区 detach 在 A 的 WORLD_HEAD（持本区锁）完成，attach 只能持目标区一把锁
    /// （A9）⇒ 必须等 A 返回；又不得跨过 barrier1，否则迁移窗口从亚 tick 级扩到跨屏障/跨 tick。
    ///
    /// 红检：把区 0 的搬迁块整体挪到 `await_neighbors` 之后 ⇒ 断言红。
    #[test]
    fn session_migration_drivers_sit_between_phase_a_and_barrier1() {
        let src = include_str!("lib.rs");
        let d0 = src
            .find("A35-b 驱动点（区 0）")
            .expect("区 0 驱动点标记必须在源码里");
        let a0 = src[..d0]
            .rfind("let outcome = self.tick_phase_a(")
            .expect("区 0 的 tick_phase_a 调用");
        // **从 `a0` 起找**（不是从 `d0`）：本测试自身的源码文本里也含该字面量，从 `d0` 起找
        // 会变成自指（『源码文本牙可绕过』）；`a0` 起的第一处就是真实的 barrier1。
        let b0 = a0
            + src[a0..]
                .find("ops.await_neighbors(self.ticks)")
                .expect("区 0 的 barrier1");
        assert!(a0 < d0, "区 0 驱动点必须在 A 段之后");
        assert!(d0 < b0, "区 0 驱动点必须在 barrier1 之前");
        let dk = src
            .find("A35-b 驱动点（区 k）")
            .expect("区 k 驱动点标记必须在源码里");
        let ak = src[..dk]
            .rfind("st.host.tick_phase_a(")
            .expect("区 k 的 tick_phase_a 调用");
        // 同区 0：从 `ak` 起找，避开本测试源码里的字面量。
        let bk = ak
            + src[ak..]
                .find("ops.await_neighbors(tick)")
                .expect("区 k 的 barrier1");
        assert!(ak < dk, "区 k 驱动点必须在锁1（A 段）之后");
        assert!(dk < bk, "区 k 驱动点必须在 barrier1 之前");
    }

    /// [`seed_full_session`] 的 `HostLoop` 版（接线牙在 `HostLoop` 上跑 `tick_phase_a`）。
    fn seed_full_session_for_host(host: &mut HostLoop, chr: &str, socket: i32) -> i32 {
        let id = host
            .world
            .add_entity(mir2_world_bevy::EntitySpawn::new(0, chr, 5, 5));
        host.ground_sessions
            .insert(chr.to_string(), super::tests::test_session_ground(id));
        host.online.set(OnlineEntry {
            account: "acct".into(),
            chr_name: chr.to_string(),
            session_id: 1,
            gate_idx: 0,
            socket,
            actor_id: id,
        });
        host.saves.insert(
            chr.to_string(),
            SavedHuman {
                account: "acct".into(),
                record: record::PlayerRecord::default(),
                enter_map: "0".into(),
                derived: None,
            },
        );
        host.login_tails
            .insert(chr.to_string(), smframe::EnterWorldInputs::default());
        host.aoi_frames_total.insert(chr.to_string(), 7);
        host.shop_sessions
            .insert(chr.to_string(), ShopSession::default());
        let _ = host.world.open_session(chr);
        if let Some(sess) = host.world.sessions.get_mut(chr) {
            sess.actor_id = Some(id);
            sess.map_id = 0;
            sess.stage = mir2_world_bevy::WorldStage::InWorld;
        }
        id
    }

    // ------------------------------------------------------------------
    // 4：outgoing 镜像追加格尾、忽略 cell_pos；普通镜像仍按 cell_pos
    // ------------------------------------------------------------------
    #[test]
    fn outgoing_mirror_appends_to_cell_tail_ignoring_cell_pos() {
        let mut world = World::with_maps(vec![(20, 10)]);
        // 目标区本地真实体（先占该格；`tick` 处理 `Command::Enter` 才真正落格）。
        let local = add(&mut world, "L", 5, 5, false);
        let _ = world.tick();
        let base = |id: i32, name: &str, outgoing: bool, cell_pos: usize| HaloEntity {
            actor_id: id,
            map_id: 0,
            x: 5,
            y: 5,
            view_range: 5,
            name: name.into(),
            race: 80,
            race_img: 0,
            appr: 0,
            light: 0,
            name_color: 255,
            cell_type: mir2_world_bevy::CellType::Monster,
            dir: 0,
            death: false,
            invisible: false,
            ghost: false,
            fixed_hide_mode: false,
            ob_mode: false,
            master: None,
            cell_pos,
            display: None,
            route: None,
            outgoing,
        };
        // 普通镜像 cell_pos=1（应在 L 之后）；outgoing 镜像 cell_pos=0（假装最前，但必须排最后）。
        let snap = HaloSnapshot {
            tick: 0,
            entities: vec![base(42, "O", true, 0), base(41, "N", false, 1)],
        };
        let stats = apply_mirrors(&mut world, &[snap], None).expect("镜像应用");
        assert_eq!(stats.inserted, 2);
        let (cell, _) = world.map(0).get_cell_info(5, 5);
        let order: Vec<i32> = cell
            .obj_list
            .iter()
            .filter(|o| o.actor_object)
            .map(|o| o.cell_obj_id)
            .collect();
        assert_eq!(
            order,
            vec![local, 41, 42],
            "outgoing 镜像必须追加格尾（忽略 cell_pos=0）；普通镜像按 cell_pos"
        );
    }

    /// **段 4 裁决（2026-11-22）**：镜像落格失败（`RefusedCell`）⇒ **丢弃该条 + 计数**，
